    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall own exclusively, in perpetuity, throughout the universe, all right, title and interest in and to the Program and all elements thereof, including without limitation all Materials, in all media whether now known or hereafter devised.', ARRAY['exclusive ownership','perpetuity','universe','all right title interest','Program','Materials','all media']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Standard Amazon position - complete ownership grant", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "This is Amazon''s standard position establishing complete, exclusive, perpetual ownership throughout the universe in all media. No qualifications or limitations that would require escalation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All right, title and interest of every kind and nature in and to the Program, including all Materials created in connection therewith, shall vest exclusively in Amazon in perpetuity and throughout the universe, free and clear of any claims, liens or encumbrances.', ARRAY['vest exclusively','perpetuity','universe','free and clear','no encumbrances','Program','Materials']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Alternative acceptable formulation with anti-encumbrance language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Achieves same result as standard position with additional protective language regarding encumbrances. Fully acceptable without approval."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall be the sole and exclusive owner in perpetuity throughout the universe of all right, title and interest in the Program, all versions and iterations thereof, and all Materials, for exploitation in any and all media and by any and all means.', ARRAY['sole exclusive owner','perpetuity','universe','all versions iterations','all media','all means']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Expanded language covering versions/iterations explicitly", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly addresses versions and iterations which strengthens Amazon''s position. Standard acceptable formulation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The Program and all Materials shall be owned exclusively by Amazon Content Services LLC and its successors and assigns, in perpetuity, throughout the universe, in all media now known or hereafter developed.', ARRAY['owned exclusively','successors assigns','perpetuity','universe','all media','hereafter developed']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Includes successors/assigns language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit inclusion of successors and assigns is consistent with Amazon''s assignment flexibility. Standard acceptable position."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall own in perpetuity and throughout the universe, exclusively and without limitation, all right, title and interest in and to: (a) the Program; (b) all Materials; (c) all ancillary and subsidiary rights therein; and (d) all proceeds and income therefrom.', ARRAY['perpetuity','universe','exclusive','Program','Materials','ancillary subsidiary rights','proceeds income']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Detailed enumeration format with proceeds", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerated format provides additional clarity and explicitly captures proceeds/income. Acceptable variation of standard position."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'From the commencement of production and continuing in perpetuity throughout the universe, Amazon shall exclusively own all right, title and interest in and to the Program and Materials for all purposes and in all media whether now existing or later created.', ARRAY['commencement of production','perpetuity','universe','exclusive','all purposes','all media','later created']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Specifies timing of ownership vesting", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that ownership vests from commencement rather than delivery. This is favorable to Amazon and acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall be entitled to the exclusive ownership throughout the universe in perpetuity of all right, title and interest of whatsoever nature in the Programme and all Materials, including all copyrights, database rights, and intellectual property rights therein.', ARRAY['exclusive ownership','universe','perpetuity','Programme','Materials','copyrights','database rights','intellectual property']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "UK spelling and additional IP enumeration for UK productions", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK variant with appropriate spelling and explicit database rights reference (relevant under UK/EU law). Acceptable for UK productions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own exclusively, in perpetuity, throughout the universe, all right, title and interest in and to the Program and Materials, excluding only ProdCo''s pre-existing intellectual property contributed to the Program which shall be licensed to Amazon on an exclusive, perpetual, royalty-free basis.', ARRAY['exclusive ownership','perpetuity','universe','excluding pre-existing IP','perpetual license','royalty-free']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "ProdCo carveout for pre-existing IP with back-license", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for pre-existing IP is a common ProdCo request. Acceptable if the license grant is truly perpetual, exclusive, and royalty-free, but requires Legal review to verify scope of pre-existing IP."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own all right, title and interest in and to the Program and Materials exclusively, in perpetuity, throughout the universe; provided that Amazon acknowledges ProdCo''s retained trademark rights in ProdCo''s corporate name and logo.', ARRAY['exclusive ownership','perpetuity','universe','retained trademark','corporate name logo']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "ProdCo trademark retention for corporate identity", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Retention of ProdCo''s own corporate name/logo trademarks is generally acceptable as these don''t relate to Program content, but requires Legal confirmation that carveout is appropriately narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own exclusively, in perpetuity, throughout the universe, all right, title and interest in the Program and Materials, provided that upon termination of Amazon''s exploitation of the Program for a continuous period of ten (10) years, all such rights shall revert to ProdCo.', ARRAY['exclusive ownership','perpetuity','universe','reversion','ten years','cessation of exploitation']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Turnaround/reversion provision", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Reversion clauses fundamentally undermine perpetual ownership. Requires senior Legal approval and likely pushback, but may be negotiable for limited scope or extended timeframe."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own exclusively, in perpetuity and throughout the universe, all right, title and interest in the Program, subject to any customary residual or reuse payment obligations to guilds and unions as may be applicable.', ARRAY['exclusive ownership','perpetuity','universe','residual obligations','guild union','reuse payments']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Guild residual carveout", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledgment of guild residuals is standard industry practice and doesn''t affect ownership. Business Affairs should confirm specific guild applicability."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own all right, title and interest in the Program and Materials exclusively, in perpetuity, throughout the universe, except that ProdCo shall retain the exclusive right to produce theatrical sequel and prequel motion pictures.', ARRAY['exclusive ownership','perpetuity','universe','sequel prequel carveout','theatrical motion pictures']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Sequel/prequel theatrical carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Sequel/prequel carveouts significantly limit Amazon''s ability to expand the franchise. Requires Legal approval and is likely to be heavily negotiated or rejected."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall own exclusively all right, title and interest in the Programme and Materials in perpetuity throughout the universe. ProdCo shall retain moral rights in the Programme to the extent such rights are not waivable under applicable law, but covenants not to enforce or exercise such rights.', ARRAY['exclusive ownership','perpetuity','universe','moral rights','non-waivable','covenant not to enforce']::text[], '{"doc": "PSA_Fallbacks", "section": "Rights/Ownership", "note": "EU/UK moral rights acknowledgment with non-exercise covenant", "approval": "AMAZON_LEGAL", "jurisdiction": "EU", "risk_level": "MEDIUM", "reasoning": "In jurisdictions where moral rights cannot be waived (France, Germany), a covenant not to exercise is the standard fallback. Requires Legal confirmation of jurisdiction-specific requirements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall own exclusively, in perpetuity, throughout the universe, all right, title and interest in and to the Program and Materials, provided that ProdCo shall retain ownership of all underlying intellectual property, formats, characters, and storylines for use in any medium.', ARRAY['exclusive ownership','perpetuity','universe','retained underlying IP','formats','characters','storylines']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "ProdCo attempts to retain core underlying rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Retention of underlying IP, formats, characters and storylines would eviscerate Amazon''s ownership of the Program. This creates significant sequel/spinoff risk and is fundamentally incompatible with Amazon''s position."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall own all right, title and interest in the Program and Materials, and hereby grants to Amazon an exclusive license throughout the universe for a period of fifteen (15) years from initial delivery.', ARRAY['ProdCo ownership','exclusive license','fifteen years','limited term']::text[], '{"doc": "Counterparty_Proposal", "section": "Rights/Ownership", "note": "Complete inversion - license model instead of ownership", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "This fundamentally inverts the ownership structure. Amazon requires ownership, not a license. A 15-year term is wholly inadequate for content investment. Reject outright."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall own exclusively all right, title and interest in the Program in perpetuity throughout the Territory, defined as North America and the United Kingdom only.', ARRAY['exclusive ownership','perpetuity','limited territory','North America','UK']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Territorial limitation on ownership", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Amazon requires universe-wide ownership. Territorial limitations are incompatible with global streaming distribution model and would create significant exploitation complications."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon and ProdCo shall jointly own all right, title and interest in the Program and Materials, with each party having the right to exploit the Program independently without accounting to the other.', ARRAY['joint ownership','independent exploitation','no accounting']::text[], '{"doc": "Counterparty_Proposal", "section": "Rights/Ownership", "note": "Joint ownership proposal", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Joint ownership creates deadlock risk, complicates chain of title, and allows ProdCo to license to competitors. Amazon must be sole owner. Not acceptable under any circumstances."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall own all right, title and interest in the Program, provided that such ownership shall terminate and revert to ProdCo upon the earlier of (i) Amazon''s material breach of this Agreement, or (ii) Amazon''s failure to produce a second season within twenty-four (24) months.', ARRAY['ownership','termination','reversion','material breach','second season trigger']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Conditional ownership with reversion triggers", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Ownership conditioned on production commitments or breach is fundamentally unacceptable. Amazon cannot have ownership that can be lost through operational decisions. This creates unacceptable risk exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall own the Program exclusively throughout the universe during the License Period, which shall commence on First Exploitation and continue for a period of seven (7) years, renewable at Amazon''s option for successive one (1) year periods.', ARRAY['exclusive','limited license period','seven years','renewal option']::text[], '{"doc": "Counterparty_Proposal", "section": "Rights/Ownership", "note": "Term ownership with renewal structure", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Seven-year term with renewals is a license structure, not ownership in perpetuity. Renewal options create uncertainty. Amazon requires perpetual ownership without conditions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall own all right, title and interest in the Program exclusively, in perpetuity, throughout the universe, subject to ProdCo''s reserved right to produce up to two (2) additional seasons for any third party distributor if Amazon does not exercise its option for such additional seasons within twelve (12) months.', ARRAY['exclusive ownership','perpetuity','universe','reserved right','additional seasons','third party distributor']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Third party production carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "This allows ProdCo to take the show to a competitor if Amazon doesn''t greenlight additional seasons. Fundamentally incompatible with exclusive ownership and creates competitive exposure."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The Program and all Materials shall be considered a ''work made for hire'' for Amazon within the meaning of the U.S. Copyright Act. To the extent any element does not qualify as a work made for hire, ProdCo hereby irrevocably assigns to Amazon all right, title and interest therein.', ARRAY['work made for hire','Copyright Act','irrevocable assignment','backstop','all right title interest']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Standard US WMFH with assignment backstop", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "This is Amazon''s standard formulation combining WMFH status with an assignment backstop to capture any elements that might not qualify as WMFH under the Copyright Act''s enumerated categories."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All Materials and the Program are created as works made for hire for Amazon, and Amazon is deemed the author thereof for all purposes. In the event any Materials or the Program do not qualify as works made for hire under applicable law, ProdCo assigns and agrees to assign to Amazon in perpetuity all right, title and interest therein, including all copyrights.', ARRAY['works made for hire','Amazon as author','assignment','perpetuity','copyrights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Includes authorship acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly designates Amazon as author for copyright purposes and includes present and future assignment language. Standard acceptable position."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges and agrees that: (a) all Materials and the Program are specially ordered or commissioned works made for hire for Amazon; (b) Amazon is and shall be considered the author and owner thereof; and (c) to the extent any element is determined not to be a work made for hire, ProdCo hereby assigns, transfers and conveys all right, title and interest in such element to Amazon.', ARRAY['specially ordered commissioned','works made for hire','author owner','assigns transfers conveys']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Detailed acknowledgment format", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive language addressing multiple WMFH requirements under the Copyright Act. The acknowledgment of ''specially ordered or commissioned'' supports WMFH status for certain categories."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The Program and Materials are works made for hire owned by Amazon. Without limiting the foregoing, ProdCo irrevocably assigns to Amazon all right, title and interest in the Program and Materials throughout the universe in perpetuity, including all renewals and extensions of copyright.', ARRAY['works made for hire','irrevocable assignment','universe','perpetuity','renewals extensions copyright']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Includes renewal/extension language for pre-1978 works considerations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes copyright renewal and extension language which provides additional protection. Standard acceptable formulation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The Programme and all Materials constitute works created by ProdCo at Amazon''s request pursuant to a commission for the purposes of section 9(2)(aa) of the Copyright, Designs and Patents Act 1988. ProdCo hereby assigns to Amazon by way of present assignment of future copyright all right, title and interest in the Programme and Materials in perpetuity throughout the universe.', ARRAY['commission','CDPA 1988','present assignment future copyright','perpetuity','universe']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "UK commissioned works formulation", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate language referencing CDPA 1988 commissioned works provisions. Present assignment of future copyright ensures chain of title vests upon creation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All Materials and the Program are works made for hire. ProdCo irrevocably assigns to Amazon now and in the future all right, title and interest in the Program and Materials, including all copyrights, neighboring rights, and all other intellectual property rights, in all languages, for all purposes, throughout the universe, in perpetuity.', ARRAY['works made for hire','irrevocable assignment','copyrights','neighboring rights','all languages','universe','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Expanded IP coverage including neighboring rights", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes neighboring rights (relevant for performers, broadcasters in civil law jurisdictions) and multi-language coverage. Comprehensive and acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'To the fullest extent permitted by applicable law, the Program and Materials shall be deemed works made for hire. To the extent that any jurisdiction does not recognize the work made for hire doctrine, or to the extent any Materials or elements thereof are not works made for hire, ProdCo hereby absolutely and irrevocably assigns to Amazon all right, title and interest therein in perpetuity throughout the universe.', ARRAY['fullest extent','works made for hire','jurisdiction','irrevocable assignment','perpetuity','universe']::text[], '{"doc": "PSA_Principal_Terms", "section": "Work-Made-For-Hire", "note": "Multi-jurisdiction protective language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledges jurisdictional variations in WMFH doctrine and ensures assignment backstop covers all scenarios. Appropriate for international productions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The Program and Materials shall be works made for hire for Amazon. To the extent any element does not qualify as a work made for hire, ProdCo assigns all right, title and interest therein to Amazon, subject to ProdCo''s receipt of the applicable portion of the Production Fee for such element.', ARRAY['works made for hire','assignment','subject to payment','production fee']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Assignment conditioned on payment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Conditioning assignment on payment introduces chain of title risk. Legal should confirm whether this is acceptable given payment structure and timing."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The Program and Materials are works made for hire for Amazon. ProdCo assigns to Amazon all right, title and interest therein, provided that ProdCo shall have a perpetual, non-exclusive, royalty-free license to use clips from the Program (not exceeding thirty seconds) for portfolio and self-promotional purposes only.', ARRAY['works made for hire','assignment','back-license','clips','portfolio','self-promotion']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Promotional clip license for ProdCo", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited promotional clip license is commonly requested by production companies for portfolio purposes. Requires Legal approval to ensure appropriate restrictions (timing, context, no competitive use)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All Materials and the Program shall be works made for hire for Amazon. ProdCo assigns all right, title and interest therein to Amazon, except that any music composed specifically for the Program shall be subject to a separate music agreement between Amazon and the applicable composer.', ARRAY['works made for hire','assignment','music carveout','separate agreement','composer']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Music rights carved out to separate agreement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Music rights often require separate treatment due to publishing, sync, and performance royalty considerations. Acceptable if separate agreement exists and is on Amazon-favorable terms."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo acknowledges that the Programme and Materials constitute commissioned works under applicable EU law. ProdCo hereby assigns and transfers to Amazon all economic rights in the Programme and Materials throughout the universe in perpetuity, to the extent permitted by applicable law.', ARRAY['commissioned works','EU law','economic rights','universe','perpetuity','extent permitted']::text[], '{"doc": "PSA_Fallbacks", "section": "Work-Made-For-Hire", "note": "EU-compliant economic rights transfer", "approval": "AMAZON_LEGAL", "jurisdiction": "EU", "risk_level": "MEDIUM", "reasoning": "EU jurisdictions distinguish between economic and moral rights. ''To the extent permitted'' qualifier may require Legal review to confirm comprehensive coverage in applicable EU member state."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The Program and Materials are works made for hire. ProdCo assigns all right, title and interest therein to Amazon, provided that any pre-existing materials owned by ProdCo prior to commencement of services and incorporated into the Program shall be licensed to Amazon on exclusive, perpetual, royalty-free terms as set forth in Schedule B.', ARRAY['works made for hire','assignment','pre-existing materials','exclusive license','Schedule B']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Pre-existing materials license structure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Schedule B must be reviewed to ensure license terms are truly perpetual, exclusive, and include all necessary rights. Chain of title for pre-existing materials requires diligence."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The Program and Materials shall be considered works made for hire for Amazon. To the extent any element does not so qualify, ProdCo hereby assigns all right, title and interest therein to Amazon. This assignment is effective upon execution of this Agreement and is not subject to any termination rights under 17 U.S.C. § 203.', ARRAY['works made for hire','assignment','Section 203','termination rights','waiver']::text[], '{"doc": "PSA_Fallbacks", "section": "Work-Made-For-Hire", "note": "Section 203 termination waiver language", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Section 203 termination rights can''t be waived prospectively under US law, but acknowledgment of WMFH status helps avoid 203 applying. Legal should confirm language effectiveness."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall own all right, title and interest in the Program and Materials as works made for hire, and hereby grants Amazon an exclusive license to exploit the Program during the Term.', ARRAY['ProdCo ownership','works made for hire','exclusive license','Term']::text[], '{"doc": "Counterparty_Proposal", "section": "Work-Made-For-Hire", "note": "Inverted WMFH - ProdCo as commissioning party", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Fundamentally inverts the WMFH relationship. Amazon must be the commissioning party and owner. This is legally and commercially unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The Program shall be a work made for hire for Amazon. However, any Materials created by ProdCo employees or independent contractors shall remain the property of ProdCo, and ProdCo grants Amazon a non-exclusive license to use such Materials solely in connection with the Program.', ARRAY['works made for hire','Materials excluded','ProdCo property','non-exclusive license']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Carveout for ProdCo-created materials", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding Materials from the WMFH/assignment structure creates significant chain of title problems. Non-exclusive license is wholly inadequate. Amazon must own all Materials."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The Program and Materials are works made for hire. To the extent any element does not qualify as a work made for hire, ProdCo shall assign such rights to Amazon upon Amazon''s written request and payment of additional consideration to be negotiated in good faith.', ARRAY['works made for hire','conditional assignment','written request','additional consideration']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Assignment conditioned on request and additional payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Assignment backstop must be automatic and unconditional. Requiring additional consideration or written request creates gap in chain of title and exposes Amazon to ransom risk."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo acknowledges the Program is a work made for hire. ProdCo assigns to Amazon all right, title and interest therein for the Initial Term of five (5) years, after which all rights shall revert to ProdCo.', ARRAY['work made for hire','assignment','limited term','five years','reversion']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Term-limited assignment with reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Assignment must be perpetual. Term-limited assignment with reversion contradicts WMFH status and creates unacceptable rights uncertainty. Reject."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The Program shall be a work made for hire for Amazon. ProdCo assigns all right, title and interest therein, subject to ProdCo''s retained right to terminate this assignment if Amazon fails to release the Program within eighteen (18) months of Delivery.', ARRAY['work made for hire','assignment','termination right','release deadline','eighteen months']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Assignment subject to release obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Assignment subject to termination for failure to release creates unacceptable operational constraint and rights uncertainty. Amazon must have unfettered ownership regardless of release decisions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo agrees the Program is a work made for hire. In the alternative, ProdCo assigns all right, title and interest therein to Amazon, provided that Amazon shall not have the right to create derivative works, sequels, prequels, or spinoffs without ProdCo''s prior written consent.', ARRAY['work made for hire','assignment','derivative works restriction','consent required']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "Derivative works consent requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Restricting derivative work rights contradicts full ownership. Amazon must have unfettered ability to create sequels, prequels, spinoffs. This limitation is commercially unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'To the extent the Program qualifies as a work made for hire, Amazon shall be deemed the author. To the extent it does not so qualify, the parties shall negotiate in good faith regarding the allocation of rights therein.', ARRAY['work made for hire','if qualifies','good faith negotiation','rights allocation']::text[], '{"doc": "Counterparty_Markup", "section": "Work-Made-For-Hire", "note": "No automatic assignment backstop", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Future negotiation is not an acceptable backstop to WMFH. Creates gap in chain of title and potential deadlock. Assignment backstop must be automatic and comprehensive."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s ownership and exploitation rights shall extend to all media, formats, platforms and technologies now known or hereafter devised, invented or developed, throughout the universe, in perpetuity.', ARRAY['all media','formats','platforms','technologies','now known','hereafter devised','universe','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Standard future media language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive future media language ensuring Amazon can exploit the Program on platforms and in formats that don''t exist yet. Standard industry language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The rights granted herein include the right to exhibit, distribute, market and otherwise exploit the Program by any and all means and media, whether now known or hereafter devised, including without limitation theatrical, home video, television, streaming, mobile, interactive, and any technology developed in the future.', ARRAY['all means media','now known hereafter devised','theatrical','home video','television','streaming','mobile','interactive','future technology']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Enumerated media with future catch-all", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Combines specific enumeration of current media with catch-all future language. Provides additional clarity while maintaining comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have the exclusive right to exploit the Program in all media and formats of every kind and nature, whether now existing or hereafter created, including all linear and non-linear platforms, over-the-top services, SVOD, AVOD, TVOD, EST, and any successor or analogous technologies.', ARRAY['all media formats','linear non-linear','OTT','SVOD','AVOD','TVOD','EST','successor technologies']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Streaming-specific enumeration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates current streaming business models (SVOD, AVOD, etc.) while capturing future analogous technologies. Appropriate for streaming-first content."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s rights extend to exhibition, distribution and exploitation in any and all media and by any and all means, methods and devices now or hereafter known, discovered, devised, developed or invented anywhere in the universe.', ARRAY['all media','all means methods devices','now or hereafter','known discovered devised developed invented','universe']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Expansive verb coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Multiple synonymous verbs (known, discovered, devised, developed, invented) provide maximum coverage against potential future challenges based on unforeseen technologies."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Without limiting Amazon''s ownership, Amazon shall have the sole and exclusive right to exploit the Program throughout the universe in perpetuity in and by means of all media, whether now in existence or later invented, including without limitation cinema, broadcast, cable, satellite, internet, wireless, virtual reality, augmented reality, and all future technologies.', ARRAY['all media','now existing','later invented','cinema','broadcast','cable','satellite','internet','wireless','VR','AR','future technologies']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Includes emerging tech (VR/AR)", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly includes VR and AR which are increasingly relevant for content exploitation. Comprehensive enumeration with future catch-all."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may exploit the Programme by all means and in all media and formats of audiovisual and sound recording exploitation, whether now known or hereafter devised, including all forms of digital distribution, electronic sell-through and any analogous future technology throughout the world in perpetuity.', ARRAY['all means media formats','audiovisual','sound recording','digital distribution','electronic sell-through','future technology','world','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "UK production language", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate language with comprehensive media coverage. ''World'' can be used interchangeably with ''universe'' in UK agreements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The rights herein shall include the right to exploit the Program in all audiovisual and audio-only media, all interactive and non-interactive formats, and by all means and methods of delivery and distribution, whether analog or digital, now existing or later developed.', ARRAY['audiovisual','audio-only','interactive','non-interactive','analog','digital','now existing','later developed']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Format-agnostic language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Captures both audiovisual and audio-only exploitation, and interactive/non-interactive distinction. Comprehensive and future-proof."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program in all media now known or hereafter devised, provided that exploitation in any media not currently contemplated by the parties shall be subject to good faith consultation with ProdCo.', ARRAY['all media','now known hereafter devised','good faith consultation','future media']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Consultation requirement for future media", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation (as opposed to consent) may be acceptable if it doesn''t create a blocking right. Legal should confirm ''consultation'' doesn''t operate as consent requirement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s exploitation rights extend to all media now known or hereafter devised, except that exploitation via direct neural interface or similar brain-computer interface technology shall require mutual agreement of the parties.', ARRAY['all media','now known hereafter devised','neural interface','BCI','mutual agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Carveout for speculative future tech", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for extremely speculative technology (neural interfaces) may be negotiable as a ProdCo compromise. Legal should assess whether carveout is appropriately narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program in all media now known or hereafter devised throughout the universe, provided that Amazon shall pay to ProdCo additional compensation as separately agreed for exploitation in any media not existing as of the date hereof and generating material revenue.', ARRAY['all media','now known hereafter devised','additional compensation','future media','material revenue']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Future media compensation requirement", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Additional compensation for future media is a ProdCo ask. Business Affairs should determine whether this is acceptable and, if so, define ''material revenue'' threshold."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s rights include exploitation in all media now known or hereafter devised, including virtual reality and augmented reality. For the avoidance of doubt, Amazon may create immersive, interactive and gaming experiences based on the Program without additional compensation.', ARRAY['all media','VR','AR','immersive','interactive','gaming','no additional compensation']::text[], '{"doc": "PSA_Fallbacks", "section": "Rights/Ownership", "note": "Explicit VR/AR/gaming clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly addresses emerging exploitation modes that are sometimes disputed. May preempt future VR/gaming compensation claims. Legal should confirm language adequacy."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have the exclusive right to exploit the Program in all media now known or hereafter devised; provided that any theatrical release shall be subject to Amazon''s separate theatrical distribution agreement then in effect.', ARRAY['all media','now known hereafter devised','theatrical release','separate agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Theatrical subject to separate terms", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Reference to separate theatrical agreement may be appropriate for productions with theatrical component. Business Affairs should confirm standard theatrical terms are acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The rights granted herein extend to all media now known or hereafter devised, provided that Amazon''s exploitation rights in respect of the soundtrack album shall be limited to promotional use only, with commercial soundtrack rights reserved to ProdCo''s affiliated music company.', ARRAY['all media','soundtrack','promotional use only','music company','commercial rights reserved']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Soundtrack carveout for music affiliate", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Soundtrack carveout is significant but may be negotiable depending on music component value. Requires Legal assessment of impact on ancillary exploitation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program via streaming platforms only. All other media rights, including theatrical, broadcast, home video and physical media, are expressly reserved to ProdCo.', ARRAY['streaming only','reserved rights','theatrical','broadcast','home video','physical media']::text[], '{"doc": "Counterparty_Proposal", "section": "Rights/Ownership", "note": "Streaming-only license with reserved rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting Amazon to streaming-only rights is fundamentally incompatible with ownership model. Amazon must have all media rights to fully exploit and monetize the Program."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s exploitation rights shall be limited to media existing as of the Effective Date of this Agreement. Rights to exploit the Program in any media developed after the Effective Date shall require separate negotiation and additional compensation.', ARRAY['limited to existing media','future media excluded','separate negotiation','additional compensation']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Future media exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding future media entirely defeats the purpose of perpetual ownership. Technology evolution is certain; Amazon cannot be held hostage to future negotiations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program in all media now known or hereafter devised, subject to ProdCo''s prior written consent for any exploitation not specifically enumerated in Exhibit C.', ARRAY['all media','ProdCo consent','enumerated rights','Exhibit C']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Consent requirement for non-enumerated media", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Prior consent requirement for non-enumerated media creates blocking right that undermines ownership. ProdCo cannot have approval rights over Amazon''s exploitation decisions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s media rights shall include streaming, download-to-own, and linear broadcast. Amazon shall not have the right to exploit the Program in theatrical exhibition, gaming, merchandise, theme parks or location-based entertainment without ProdCo''s separate consent and payment of additional fees.', ARRAY['limited media','no theatrical','no gaming','no merchandise','no theme parks','consent required','additional fees']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Significant ancillary rights carveouts", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Carving out theatrical, gaming, merchandise and theme parks represents massive value leakage. These ancillary rights are essential components of full ownership."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program in the English language in all media now known or hereafter devised. Rights to exploit dubbed or subtitled versions in other languages shall be subject to separate agreement.', ARRAY['English language only','dubbed subtitled','other languages','separate agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Language restriction on media rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Language restrictions fundamentally undermine global exploitation. Amazon requires rights in all languages as part of its worldwide streaming model."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have the right to exploit the Program in all media now known. The parties shall meet annually to discuss in good faith the allocation of rights to any new media technologies developed during the preceding year.', ARRAY['now known only','annual meeting','good faith discussion','new media allocation']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Future media subject to annual negotiation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Annual negotiation structure creates perpetual uncertainty and potential deadlock. Amazon must have automatic rights to all future media without ongoing consent requirements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s exploitation rights extend to all media now known or hereafter devised; provided that Amazon shall share equally with ProdCo all revenue generated from exploitation in any media category not specifically identified in Exhibit D.', ARRAY['all media','revenue sharing','fifty percent','unidentified media','Exhibit D']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "50/50 revenue share on future media", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Revenue sharing on future media is inconsistent with fee-based PSA structure where Amazon pays production fee for full ownership. This introduces profit participation through back door."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall execute and deliver such further documents and instruments, and take such further actions, as Amazon may reasonably request to evidence, perfect or protect Amazon''s ownership of the Program and Materials, including execution of copyright assignments and any documents required for registration with applicable copyright offices.', ARRAY['further documents','instruments','reasonably request','evidence','perfect','protect','ownership','copyright assignments','registration']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Standard further assurances language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard further assurances provision ensuring ProdCo will provide any documentation needed to perfect Amazon''s ownership. Essential for chain of title."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon Amazon''s request, ProdCo shall promptly execute, acknowledge and deliver to Amazon any and all documents, instruments and assignments that Amazon deems necessary or desirable to confirm, establish or protect Amazon''s exclusive ownership of the Program and all Materials in any jurisdiction.', ARRAY['promptly execute','acknowledge','deliver','documents instruments assignments','necessary desirable','exclusive ownership','any jurisdiction']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Expanded further assurances with jurisdictional coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Multi-jurisdictional coverage is important for international productions and registrations. Standard acceptable language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo agrees to sign, execute and deliver any documents, certificates, assignments or instruments of conveyance as may be required by Amazon to transfer, assign, register or otherwise evidence Amazon''s ownership of the Program and Materials, including short-form copyright assignments suitable for recording with the U.S. Copyright Office.', ARRAY['sign execute deliver','documents certificates assignments','transfer assign register','short-form copyright assignments','Copyright Office']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Specific Copyright Office reference", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly references short-form assignments for Copyright Office recording, which is standard practice for evidencing chain of title. Acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall cooperate fully with Amazon in connection with the registration or recordation of the Program or any component thereof with any governmental agency, guild, performing rights organization, or collective management organization, and shall execute all documents reasonably required therefor.', ARRAY['cooperate fully','registration recordation','governmental agency','guild','PRO','collective management organization','execute documents']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Expanded registration scope including guilds/PROs", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes guild and PRO registrations which are necessary for proper rights administration. Comprehensive and acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'At any time and from time to time, upon Amazon''s request, ProdCo shall do, execute, acknowledge and deliver, or cause to be done, executed, acknowledged and delivered, all such further acts, deeds, assignments, conveyances, powers of attorney and assurances as may be required to carry out the intent of this Agreement and to vest in Amazon all right, title and interest in the Program and Materials.', ARRAY['at any time','further acts deeds','assignments conveyances','powers of attorney','assurances','vest','right title interest']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Comprehensive further assurances with POA reference", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive language covering full range of potential documentation needs. Reference to powers of attorney anticipates potential execution issues."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo undertakes to execute and deliver to Amazon all deeds of assignment and other documents as Amazon may reasonably require to perfect or evidence Amazon''s title to the Programme and Materials in any part of the world, and to enable Amazon to register such title with all relevant collecting societies and copyright registries.', ARRAY['deeds of assignment','reasonably require','perfect evidence title','any part of world','collecting societies','copyright registries']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "UK formulation with collecting societies", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate language addressing collecting society registrations (PRS, PPL, etc.) which are important for proper UK rights administration."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall procure that each contributor to the Program executes such documents as Amazon may require to confirm the assignment of rights to Amazon, and ProdCo shall deliver to Amazon copies of all executed contributor agreements upon request.', ARRAY['procure','contributor','executed documents','confirm assignment','contributor agreements','deliver copies']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Contributor agreement procurement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends further assurances to underlying contributors, ensuring complete chain of title documentation. Essential for proper rights clearance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall execute and deliver such further documents as Amazon may reasonably request to evidence Amazon''s ownership, provided that (i) Amazon shall bear all costs of registration and recording fees, and (ii) Amazon shall provide ProdCo with copies of all filed documents.', ARRAY['further documents','reasonably request','Amazon bears costs','registration fees','copies to ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Cost allocation and copy requirements", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Cost allocation for registrations is reasonable and often assumed. Copy provision is administrative. Business Affairs should confirm acceptability."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall execute such further instruments as Amazon may reasonably request, provided that Amazon''s requests shall not require ProdCo to make any representation or warranty beyond those set forth in this Agreement or to incur any unreimbursed expense.', ARRAY['further instruments','reasonably request','no additional reps warranties','no unreimbursed expense']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Limitations on further assurances scope", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limitations on additional reps/warranties may be acceptable if Agreement reps are comprehensive. Legal should confirm existing reps are adequate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon reasonable advance notice, ProdCo shall execute documents to evidence Amazon''s ownership and to enable registration with copyright offices. ProdCo shall have five (5) business days to review and execute such documents; Amazon shall consider in good faith any reasonable comments from ProdCo.', ARRAY['reasonable advance notice','five business days','review period','good faith','reasonable comments']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Review period for further assurances", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Five-day review period is short and may be acceptable. ''Good faith consideration'' of comments is not a consent right. Legal should confirm this doesn''t create blocking opportunity."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall execute further documents reasonably requested by Amazon. In the event ProdCo fails to do so within fifteen (15) business days of Amazon''s written request, ProdCo hereby appoints Amazon as its attorney-in-fact to execute such documents on ProdCo''s behalf.', ARRAY['further documents','fifteen business days','attorney-in-fact','execute on behalf']::text[], '{"doc": "PSA_Fallbacks", "section": "Rights/Ownership", "note": "POA with fifteen-day cure period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Fifteen-day period before POA activates is longer than ideal (standard is immediate or shorter). Legal should confirm acceptable timing."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall provide reasonable cooperation and execute documents as Amazon may request for registration purposes, subject to the availability of appropriate personnel. ProdCo shall use commercially reasonable efforts to ensure such personnel are available.', ARRAY['reasonable cooperation','registration','subject to availability','commercially reasonable efforts']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Availability qualification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Availability qualification could create delays, but ''commercially reasonable efforts'' standard provides some comfort. Legal should assess whether this is acceptable given POA backup."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall execute such documents as Amazon may reasonably request for registration purposes, provided that Amazon shall not register the Program with any government agency or copyright office that ProdCo reasonably believes would require ProdCo to disclose confidential business information unrelated to the Program.', ARRAY['reasonably request','registration','confidential business information','unrelated to Program']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Confidential information carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Narrow carveout for truly confidential unrelated information may be reasonable. Legal should assess scope and ensure it doesn''t impede necessary registrations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall execute such further documents as Amazon may reasonably request, provided that ProdCo shall have the right to approve the form and content of any such documents, which approval shall not be unreasonably withheld.', ARRAY['further documents','ProdCo approval right','form and content','not unreasonably withheld']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Approval right over documentation form", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Approval right over document form creates potential blocking mechanism. Standard registration forms should not require ProdCo consent. This impedes chain of title perfection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall execute further documents upon Amazon''s request, provided that ProdCo shall not be obligated to execute any document that ProdCo believes, in its sole discretion, contains terms inconsistent with this Agreement or is otherwise objectionable to ProdCo.', ARRAY['further documents','ProdCo sole discretion','inconsistent terms','objectionable']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "ProdCo sole discretion to refuse", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo''s ''sole discretion'' to determine consistency or objectionability creates absolute blocking right. This fundamentally undermines the further assurances obligation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Upon receipt of additional compensation to be agreed by the parties, ProdCo shall execute such further documents as Amazon may request to evidence Amazon''s ownership rights.', ARRAY['additional compensation','to be agreed','further documents']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Further assurances conditioned on additional payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Conditioning further assurances on additional payment creates ransom situation. Chain of title perfection is included in the Production Fee and cannot require further consideration."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall execute further documents reasonably requested by Amazon, limited to documents required by the U.S. Copyright Office only. ProdCo shall have no obligation to execute documents for registration in any foreign jurisdiction.', ARRAY['US Copyright Office only','no foreign jurisdiction','limited obligation']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "US-only further assurances", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting further assurances to US only fails to support Amazon''s worldwide exploitation. Foreign registrations are essential for international rights protection and enforcement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall execute further documents requested by Amazon, provided that such requests shall be made only once per calendar year, and ProdCo shall have sixty (60) days to comply with each such request.', ARRAY['once per year','sixty days','limited requests']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Frequency and timing limitations", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Annual request limitation and 60-day response period are wholly inadequate for business needs. Amazon must be able to obtain documentation as needed for transactions and registrations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This Agreement constitutes the entire agreement between the parties regarding assignment of rights. ProdCo shall have no obligation to execute any further documents, assignments, or instruments, and Amazon expressly waives any right to require further assurances.', ARRAY['entire agreement','no further documents','waiver of further assurances']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Elimination of further assurances obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating the further assurances obligation entirely leaves Amazon without ability to perfect chain of title or respond to future registration requirements. This is fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall, subject to ProdCo''s legal counsel''s approval in each instance, execute such documents as Amazon may request. ProdCo''s counsel shall have sole authority to determine whether any requested document is appropriate.', ARRAY['ProdCo counsel approval','each instance','sole authority']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "ProdCo counsel gatekeeping", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring ProdCo counsel approval for each document creates blocking mechanism and potential for endless delay. Amazon cannot be subject to opposing counsel gatekeeping for routine registrations."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo hereby irrevocably appoints Amazon as its attorney-in-fact, coupled with an interest, with full power of substitution, to execute, acknowledge, deliver, file and record any and all documents that Amazon deems necessary or desirable to evidence, establish, protect or enforce Amazon''s rights in the Program and Materials, if ProdCo fails to do so within five (5) business days of Amazon''s request.', ARRAY['irrevocably appoints','attorney-in-fact','coupled with interest','power of substitution','five business days']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Standard POA with short cure period", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard irrevocable POA coupled with an interest, which survives any attempt by ProdCo to revoke. Five-day cure period is appropriate and protects Amazon''s ability to perfect chain of title."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If ProdCo fails or refuses to execute any document required hereunder, Amazon is hereby granted an irrevocable power of attorney, coupled with an interest, to sign such documents in ProdCo''s name and on ProdCo''s behalf. This power of attorney shall survive any termination of this Agreement.', ARRAY['irrevocable power of attorney','coupled with interest','sign in ProdCo''s name','survives termination']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "POA with survival language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit survival provision ensures POA remains effective after Agreement termination. Essential for post-termination chain of title needs."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo hereby constitutes and appoints Amazon and its designees as ProdCo''s true and lawful attorney-in-fact, irrevocably and coupled with an interest, to execute in ProdCo''s name and behalf any documents necessary to effectuate the purposes of this Agreement, including short-form copyright assignments, certificates of engagement, chain of title documents, and registration applications.', ARRAY['true and lawful attorney-in-fact','irrevocable','coupled with interest','designees','copyright assignments','certificates of engagement','chain of title','registration applications']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Detailed POA with specific document types", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific document types covered by POA, providing additional clarity. Inclusion of designees allows Amazon to delegate execution authority."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon is hereby appointed as ProdCo''s irrevocable attorney-in-fact with full authority to execute on ProdCo''s behalf any instruments in writing in the name of ProdCo and to take any actions necessary to vest in Amazon, or any third party authorized by Amazon, all rights contemplated herein, in the event that ProdCo is unable, unwilling or unavailable to do so.', ARRAY['irrevocable attorney-in-fact','unable unwilling unavailable','third party authorized','vest rights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "POA covering inability/unwillingness/unavailability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers multiple scenarios (unable, unwilling, unavailable) ensuring POA is effective regardless of reason for ProdCo''s non-execution. Allows assignment-related executions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The power of attorney granted herein is coupled with an interest and shall be irrevocable. This power shall not be affected by the subsequent disability, incapacity, dissolution, bankruptcy or insolvency of ProdCo. Amazon may exercise this power at any time without notice to ProdCo.', ARRAY['coupled with interest','irrevocable','disability','incapacity','dissolution','bankruptcy','insolvency','no notice']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "POA surviving corporate events", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly addresses corporate events (dissolution, bankruptcy) that might otherwise impair POA effectiveness. No notice requirement provides maximum flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo irrevocably appoints Amazon as its attorney-in-fact to do all acts and execute all documents that may be necessary or desirable to give full effect to the assignment of rights herein, including to register or record such assignment with any governmental authority, copyright office, trademark office, or collecting society anywhere in the world.', ARRAY['irrevocably appoints','attorney-in-fact','register record','governmental authority','copyright office','trademark office','collecting society','anywhere in world']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "Global registration authority", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Worldwide scope for registrations ensures Amazon can perfect chain of title in any jurisdiction. Includes collecting societies which are essential for certain territories."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo grants Amazon an irrevocable power of attorney, coupled with an interest, to execute any document in ProdCo''s name as may be required to confirm, secure, evidence, maintain, enforce or protect Amazon''s ownership of the Programme and Materials, including execution of deeds of assignment, waiver of moral rights, and applications for registration.', ARRAY['irrevocable power of attorney','coupled with interest','confirm secure evidence','maintain enforce protect','deeds of assignment','waiver moral rights','registration']::text[], '{"doc": "PSA_Principal_Terms", "section": "Rights/Ownership", "note": "UK-style POA with moral rights coverage", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate formulation including deeds of assignment and moral rights waivers. Comprehensive authority for UK chain of title needs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo grants Amazon an irrevocable power of attorney to execute documents in ProdCo''s name, which Amazon may exercise only after providing ten (10) business days'' written notice to ProdCo and ProdCo''s failure to respond or execute during such period.', ARRAY['irrevocable power of attorney','ten business days','written notice','failure to respond']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "POA with extended notice period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Ten-day notice period is longer than standard five days but still workable. Legal should confirm this doesn''t unduly delay time-sensitive registrations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo grants Amazon a power of attorney to execute documents on ProdCo''s behalf if ProdCo fails to do so within five (5) business days. Amazon shall provide ProdCo with copies of any documents so executed within ten (10) days of execution.', ARRAY['power of attorney','five business days','copies','ten days']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "POA with copy requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Copy requirement is administrative and does not limit Amazon''s rights. Legal should confirm this is acceptable tracking obligation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon is appointed as ProdCo''s irrevocable attorney-in-fact. Amazon shall exercise this power only through its duly authorized officers or legal counsel, and not through any third party designee without ProdCo''s prior consent.', ARRAY['irrevocable attorney-in-fact','duly authorized officers','legal counsel','no third party','prior consent']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Limitation on POA delegation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting exercise to officers and counsel may be workable but restricts flexibility. Legal should confirm operational acceptability."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo grants Amazon power of attorney to execute chain of title documents. In jurisdictions where powers of attorney must be notarized or authenticated for validity, Amazon shall comply with such formalities, and ProdCo shall reasonably cooperate in any required notarization or authentication.', ARRAY['power of attorney','chain of title','notarization','authentication','ProdCo cooperation']::text[], '{"doc": "PSA_Fallbacks", "section": "Rights/Ownership", "note": "Jurisdiction-specific POA formalities", "approval": "AMAZON_LEGAL", "jurisdiction": "EU", "risk_level": "LOW", "reasoning": "Acknowledges civil law notarization requirements while maintaining ProdCo cooperation obligation. Legal should confirm formality requirements for applicable jurisdictions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo hereby grants Amazon an irrevocable power of attorney, coupled with an interest, to execute documents in ProdCo''s name. This power shall be exercised reasonably and in good faith, and Amazon shall not use this power to modify or expand ProdCo''s substantive obligations under this Agreement.', ARRAY['irrevocable power of attorney','coupled with interest','reasonably','good faith','no expansion of obligations']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "POA with good faith qualifier", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Good faith limitation on POA exercise is reasonable and doesn''t substantively limit Amazon''s chain of title needs. Legal should confirm this doesn''t create dispute opportunity."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon is hereby granted power of attorney to execute documents on ProdCo''s behalf. To the extent permitted by applicable law, this power is coupled with an interest and irrevocable; however, in jurisdictions where such coupling is not recognized, ProdCo covenants not to revoke this power during the Term or thereafter.', ARRAY['power of attorney','coupled with interest','irrevocable','to extent permitted','covenant not to revoke']::text[], '{"doc": "PSA_Fallbacks", "section": "Rights/Ownership", "note": "Jurisdictional fallback for POA", "approval": "AMAZON_LEGAL", "jurisdiction": "EU", "risk_level": "MEDIUM", "reasoning": "Addresses jurisdictions where ''coupled with an interest'' concept may not apply. Covenant not to revoke provides contractual protection. Legal should confirm enforceability in applicable jurisdictions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If ProdCo fails to execute documents within thirty (30) days, Amazon may exercise its power of attorney upon providing ProdCo an additional fifteen (15) days'' cure notice, which ProdCo may extend for an additional fifteen (15) days for good cause.', ARRAY['thirty days','fifteen days cure','extension','good cause']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Extended cure periods with extensions", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Total potential delay of 60+ days before POA can be exercised is commercially unworkable. Amazon needs ability to act promptly on chain of title matters."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s power of attorney shall be revocable by ProdCo upon written notice, provided that revocation shall not be effective if Amazon has already initiated the relevant registration process.', ARRAY['revocable','written notice','exception for initiated process']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Revocable POA", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Revocable POA defeats entire purpose of the provision. Amazon must have irrevocable authority that cannot be withdrawn at ProdCo''s discretion."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo grants Amazon power of attorney to execute documents, limited to applications for copyright registration in the United States only. ProdCo expressly withholds authority to execute any other documents or to make any filings in jurisdictions outside the United States.', ARRAY['limited POA','copyright registration only','US only','no foreign filings']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Geographically and substantively limited POA", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "POA limited to US copyright registration is wholly inadequate for global exploitation model. Amazon needs worldwide authority for all relevant documents."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall not have power of attorney or any authority to execute documents on ProdCo''s behalf. ProdCo shall execute all required documents within a reasonable time following Amazon''s written request.', ARRAY['no power of attorney','no authority','reasonable time']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Complete elimination of POA", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating POA entirely leaves Amazon dependent on ProdCo''s good faith execution. ''Reasonable time'' is undefined and unenforceable. This is fundamentally unacceptable for chain of title."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo grants Amazon power of attorney to execute documents, subject to ProdCo''s right to review and object to any document within fifteen (15) days. If ProdCo objects, the matter shall be submitted to binding arbitration before Amazon may exercise the power of attorney.', ARRAY['power of attorney','ProdCo review','right to object','fifteen days','binding arbitration']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "POA subject to objection and arbitration", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Right to object with arbitration requirement defeats purpose of POA entirely. Amazon would need to arbitrate every document execution, causing massive delays and expense."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s power of attorney shall automatically terminate upon the earlier of (i) three (3) years from the date hereof, or (ii) termination of this Agreement for any reason. Following such termination, Amazon shall have no authority to execute documents on ProdCo''s behalf.', ARRAY['automatic termination','three years','termination of agreement','no authority']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Time-limited POA", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Time-limited or Agreement-termination-limited POA fails to support perpetual ownership. Amazon needs ongoing authority for chain of title maintenance in perpetuity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may, in its sole discretion, grant Amazon a limited power of attorney for specific documents on a case-by-case basis. Any such grant shall be documented in a separate written instrument signed by both parties.', ARRAY['sole discretion','limited POA','case-by-case','separate instrument']::text[], '{"doc": "Counterparty_Markup", "section": "Rights/Ownership", "note": "Discretionary case-by-case POA", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Case-by-case POA subject to ProdCo discretion is essentially no POA at all. Amazon requires standing irrevocable authority, not repeated negotiations."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'To the fullest extent permitted by applicable law, ProdCo hereby irrevocably waives and agrees not to assert any and all moral rights, droit moral, or similar rights of authors (including rights of attribution, integrity, disclosure and withdrawal) in and to the Program and Materials in favor of Amazon and its licensees, assignees and successors.', ARRAY['irrevocably waives','not assert','moral rights','droit moral','attribution','integrity','disclosure','withdrawal','licensees assignees successors']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Standard comprehensive moral rights waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive waiver covering all moral rights categories with extension to licensees and successors. Standard Amazon position for US agreements where moral rights are limited."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo waives any moral rights in the Program and Materials to the maximum extent permitted by law, and to the extent such rights cannot be waived, ProdCo agrees not to enforce or exercise such rights against Amazon or any party authorized by Amazon to exploit the Program.', ARRAY['waives moral rights','maximum extent','cannot be waived','not enforce','not exercise','authorized party']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Waiver with non-exercise fallback", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Two-tier approach addresses jurisdictions where waiver is valid and those where only non-exercise covenant is enforceable. Standard protective language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo irrevocably and unconditionally waives all moral rights under the Copyright, Designs and Patents Act 1988 and any similar rights under the laws of any jurisdiction, including the right to be identified as author and the right to object to derogatory treatment of the Programme.', ARRAY['irrevocably unconditionally waives','CDPA 1988','right to be identified','derogatory treatment']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "UK-specific CDPA waiver", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-specific reference to CDPA 1988 moral rights provisions. Explicit waiver is valid and enforceable under UK law. Standard for UK productions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo hereby waives, and shall procure that all contributors to the Program waive, all moral rights in the Program and Materials. ProdCo shall include appropriate moral rights waiver provisions in all agreements with cast, crew, writers, directors and other contributors.', ARRAY['waives','procure contributors waive','cast crew writers directors','contributor agreements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Waiver with contributor procurement obligation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends moral rights waiver obligation to underlying contributors through ProdCo''s procurement obligation. Essential for complete chain of title clearance."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'To the extent moral rights exist under applicable law and are capable of waiver, ProdCo waives such rights. To the extent such rights exist but cannot be waived (including under French, German, Spanish or other civil law jurisdictions), ProdCo covenants not to exercise such rights and consents to any act or omission that would otherwise infringe such rights.', ARRAY['capable of waiver','waives','cannot be waived','French German Spanish','civil law','covenants not to exercise','consents']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Multi-jurisdiction moral rights provision", "approval": null, "jurisdiction": "EU", "risk_level": "LOW", "reasoning": "Explicitly addresses civil law jurisdictions where moral rights are inalienable. Covenant not to exercise plus consent provides maximum protection available under such laws."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo agrees that Amazon may edit, modify, adapt, translate, dub, subtitle, cut, add to, rearrange, or otherwise alter the Program without limitation and without any obligation to consult with or obtain consent from ProdCo or any other person, and ProdCo waives any right to object to such treatment of the Program.', ARRAY['edit modify adapt','translate dub subtitle','cut add rearrange alter','without limitation','no consent','waives right to object']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Operational waiver framing", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Frames moral rights waiver in operational terms, explicitly permitting specific types of modifications. Useful for addressing integrity right concerns."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo permanently and irrevocably waives any and all moral rights or analogous rights recognized under the laws of any country or jurisdiction, including but not limited to rights of paternity, integrity, divulgation, and withdrawal, and agrees that this waiver shall inure to the benefit of Amazon, its affiliates, licensees, assignees, and successors in perpetuity.', ARRAY['permanently irrevocably waives','any country jurisdiction','paternity integrity divulgation withdrawal','inure to benefit','affiliates licensees assignees successors','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Moral Rights", "note": "Perpetual worldwide waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive perpetual waiver explicitly extending to all Amazon-related parties worldwide. Enumerates civil law moral rights categories (paternity, divulgation, withdrawal)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo waives all moral rights in the Program to the extent permitted by applicable law. In jurisdictions where such waiver is not recognized, ProdCo agrees not to exercise moral rights, provided that Amazon shall use reasonable efforts to provide credit to the principal creative contributors in accordance with industry custom.', ARRAY['waives moral rights','not exercise','reasonable efforts','credit','principal creative contributors','industry custom']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Non-exercise tied to credit commitment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Ties non-exercise covenant to Amazon credit commitment. ''Reasonable efforts'' and ''industry custom'' qualifiers provide flexibility but require Legal review to ensure no binding credit obligation is created."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo waives moral rights to the maximum extent permitted by law. To the extent moral rights cannot be waived under applicable law, ProdCo shall not assert such rights except in the case of material distortion or mutilation of the Program that is prejudicial to ProdCo''s honor or reputation.', ARRAY['waives maximum extent','cannot be waived','not assert','except material distortion mutilation','prejudicial','honor reputation']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Limited integrity right reservation", "approval": "AMAZON_LEGAL", "jurisdiction": "EU", "risk_level": "MEDIUM", "reasoning": "Reserves integrity right for extreme cases only. This aligns with some civil law formulations of integrity rights. Legal should assess whether ''material distortion or mutilation prejudicial to honor/reputation'' creates operational risk."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo waives all moral rights in the Program. ProdCo shall procure waivers from all contributors; provided that to the extent any contributor refuses to provide such waiver despite ProdCo''s commercially reasonable efforts, ProdCo shall promptly notify Amazon and the parties shall consult in good faith regarding how to proceed.', ARRAY['waives','procure waivers','contributor refuses','commercially reasonable efforts','notify','consult good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Contributor waiver with consultation fallback", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledges practical reality that some contributors may refuse moral rights waiver. Consultation mechanism provides flexibility but Legal should confirm ProdCo remains responsible for contributor clearance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'En la medida permitida por la ley aplicable, el Productor renuncia a todos los derechos morales sobre el Programa. En jurisdicciones donde dicha renuncia no sea válida, el Productor se compromete a no ejercer tales derechos contra Amazon ni sus cesionarios, licenciatarios o sublicenciatarios.', ARRAY['renuncia','derechos morales','no ejercer','cesionarios','licenciatarios','sublicenciatarios']::text[], '{"doc": "PSA_Fallbacks", "section": "Moral Rights", "note": "Spanish-language moral rights provision for LATAM", "approval": "AMAZON_LEGAL", "jurisdiction": "LATAM", "risk_level": "MEDIUM", "reasoning": "Spanish-language formulation for Latin American productions. Non-exercise covenant is appropriate fallback for civil law jurisdictions. Legal should confirm local counsel review for specific country."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo waives and agrees not to assert moral rights in the Program. This waiver and non-assertion agreement is given in consideration of the fees payable hereunder and ProdCo acknowledges such consideration is adequate. ProdCo further agrees to execute any documents reasonably required to evidence this waiver in any jurisdiction.', ARRAY['waives','not assert','consideration','fees','adequate consideration','execute documents','any jurisdiction']::text[], '{"doc": "PSA_Fallbacks", "section": "Moral Rights", "note": "Moral rights waiver with consideration acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "Explicit consideration acknowledgment may strengthen enforceability in certain jurisdictions. Further assurances obligation for moral rights documentation is helpful. Legal should confirm adequacy."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo irrevocably waives moral rights in the Program. To the extent any contributor to the Program has moral rights that have not been waived, Amazon may, in its discretion, either (a) require ProdCo to obtain such waiver as a condition to final payment, or (b) proceed without such waiver at ProdCo''s risk and indemnification.', ARRAY['irrevocably waives','contributor moral rights','not waived','condition to payment','ProdCo risk','indemnification']::text[], '{"doc": "PSA_Fallbacks", "section": "Moral Rights", "note": "Payment condition for contributor waivers", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Provides Amazon flexibility to condition payment on contributor waivers or proceed at ProdCo''s risk. Shifts moral rights clearance risk appropriately. Legal should confirm indemnity coverage is adequate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo retains all moral rights in the Program, including rights of attribution and integrity. Amazon shall not make any changes, alterations, edits or modifications to the Program without ProdCo''s prior written approval.', ARRAY['retains moral rights','attribution','integrity','no changes','prior written approval']::text[], '{"doc": "Counterparty_Proposal", "section": "Moral Rights", "note": "Full moral rights retention with approval requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Full retention of moral rights with approval requirement for modifications fundamentally undermines Amazon''s control over the Program. Incompatible with standard exploitation needs."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo agrees not to assert moral rights against Amazon, except that ProdCo reserves the right to receive credit as producer of the Program in all exploitation, and Amazon shall not release the Program without such credit in a form approved by ProdCo.', ARRAY['not assert','except credit','producer credit','all exploitation','form approved by ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Moral rights reserved for credit control", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Reservation of moral rights for credit control with ProdCo approval creates operational blocking right. Amazon must have sole discretion over credits per standard position."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo waives moral rights only for the purpose of Amazon''s exhibition of the Program on streaming platforms. All moral rights are reserved for any theatrical, broadcast, physical media or other non-streaming exploitation.', ARRAY['waives','streaming only','reserved','theatrical','broadcast','physical media','non-streaming']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Platform-limited moral rights waiver", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Moral rights waiver limited to streaming defeats multi-platform exploitation model. Amazon requires waiver for all media, not just primary streaming platform."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall waive moral rights in the Program upon Amazon''s payment of a separate moral rights buyout fee in the amount of [___] to be negotiated in good faith.', ARRAY['waive','separate fee','moral rights buyout','negotiate good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Separate moral rights fee requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Moral rights waiver is included in Production Fee. Requiring separate payment creates ransom situation and is inconsistent with ownership model."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo agrees not to exercise moral rights for a period of five (5) years from initial release of the Program. Following such period, ProdCo may exercise all moral rights, including requiring restoration of original version and attribution.', ARRAY['not exercise','five years','following period','exercise moral rights','restoration','original version','attribution']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Time-limited moral rights non-exercise", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Time-limited moral rights arrangement creates future liability and operational risk after five years. Amazon requires perpetual waiver/non-exercise consistent with perpetual ownership."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo waives moral rights in the Program, except that Amazon shall not colorize any black-and-white footage, add commercial interruptions, or alter the Program''s aspect ratio without ProdCo''s prior written consent.', ARRAY['waives','except','colorize','commercial interruptions','aspect ratio','prior written consent']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Operational restrictions dressed as moral rights", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Specific operational restrictions requiring consent undermine waiver. While framed as protecting artistic integrity, these create approval requirements for standard exploitation decisions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'In recognition of the importance of moral rights under international law, ProdCo does not waive any moral rights in the Program, and Amazon acknowledges that it shall exploit the Program in a manner consistent with ProdCo''s artistic vision as determined by ProdCo in its reasonable discretion.', ARRAY['does not waive','moral rights','artistic vision','ProdCo reasonable discretion']::text[], '{"doc": "Counterparty_Proposal", "section": "Moral Rights", "note": "No waiver with artistic vision standard", "approval": null, "jurisdiction": "EU", "risk_level": "CRITICAL", "reasoning": "Explicit refusal to waive moral rights combined with ''artistic vision'' standard gives ProdCo ongoing control over exploitation. Fundamentally incompatible with Amazon''s operational needs."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo waives moral rights solely with respect to ProdCo itself. ProdCo makes no representation or warranty regarding moral rights of directors, writers, composers or other contributors, and Amazon shall be solely responsible for obtaining any such waivers.', ARRAY['waives','ProdCo only','no representation warranty','contributors','Amazon responsible']::text[], '{"doc": "Counterparty_Markup", "section": "Moral Rights", "note": "Waiver limited to ProdCo with contributor carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Shifting contributor moral rights clearance to Amazon is contrary to ProdCo''s production responsibility. ProdCo must procure all necessary waivers from its personnel and contributors."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All fees payable to ProdCo hereunder are subject to and conditioned upon ProdCo not being in uncured, material breach of this Agreement at the time such payment is due.', ARRAY['fees','conditioned upon','not in','uncured material breach','time payment due']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Standard breach condition on fees", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position conditioning payment on absence of uncured material breach. Both ''uncured'' and ''material'' qualifiers are appropriate and industry-standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Payment of any fees or other amounts to ProdCo is expressly conditioned on ProdCo not being in uncured, material breach of any of its obligations under this Agreement or any related agreement between the parties.', ARRAY['payment conditioned','uncured material breach','obligations','related agreement']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Extended to related agreements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends breach condition to related agreements (e.g., development agreements, option agreements), which is appropriate for integrated deal structures."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s right to receive fees is subject to and contingent upon ProdCo not being in uncured, material breach of this Agreement. For the avoidance of doubt, Amazon''s obligation to pay shall be suspended during any period in which ProdCo is in such breach.', ARRAY['right to receive','contingent','uncured material breach','obligation suspended','during breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Explicit suspension language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly states suspension of payment obligation during breach period, providing additional clarity on Amazon''s rights. Standard acceptable position."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Each installment of the Production Fee is conditioned upon ProdCo not being in uncured, material breach of this Agreement as of the date such installment is due. Amazon may withhold any payment pending cure of any such breach.', ARRAY['each installment','Production Fee','conditioned','uncured material breach','withhold','pending cure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Installment-specific conditioning", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Applies breach condition to each installment, with explicit withholding right. Standard for milestone-based payment structures."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All compensation payable by Amazon to ProdCo pursuant to this Agreement or Exhibit A attached hereto shall be subject to and conditioned upon ProdCo''s compliance with its obligations hereunder and ProdCo not being in uncured, material breach hereof.', ARRAY['all compensation','Exhibit A','conditioned','compliance','obligations','uncured material breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Covers Exhibit A compensation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly references Exhibit A (typically the detailed fee schedule) ensuring all compensation categories are covered by the breach condition."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The fees set forth in Exhibit A are payable subject to ProdCo not being in uncured, material breach of this Agreement. In the event of such breach, Amazon may, in its sole discretion, either withhold payment until the breach is cured or terminate this Agreement in accordance with the termination provisions hereof.', ARRAY['fees','Exhibit A','uncured material breach','sole discretion','withhold','terminate']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Alternative remedies for breach", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Provides Amazon with election between withholding and termination in event of breach. Preserves flexibility while maintaining standard breach condition."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Payment of fees hereunder is conditioned upon ProdCo not being in uncured, material breach of this Agreement. Notice of any such breach shall be provided in writing, and ProdCo shall have ten (10) business days following receipt of such notice to cure any curable breach before Amazon may exercise its withholding rights.', ARRAY['conditioned','uncured material breach','notice in writing','ten business days','cure','curable breach','withholding rights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Includes notice and cure period", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Incorporates procedural protections (notice, cure period) while maintaining breach condition. Ten business days is reasonable and industry-standard."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Payment of fees is conditioned upon ProdCo not being in uncured, material breach of this Agreement, provided that ''material breach'' shall mean a breach that has a material adverse effect on the production, delivery or exploitation of the Program.', ARRAY['conditioned','uncured material breach','material breach defined','material adverse effect','production delivery exploitation']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Definition of material breach", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "ProdCo attempt to define ''material breach'' narrowly. Definition focuses on Program impact which is reasonable, but Legal should confirm it doesn''t exclude other significant breaches (e.g., confidentiality, IP assignments)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All fees are conditioned upon ProdCo not being in uncured, material breach. Prior to withholding any payment, Amazon shall provide written notice to ProdCo specifying the alleged breach in reasonable detail, and ProdCo shall have fifteen (15) business days to cure such breach or to dispute the existence of such breach in writing.', ARRAY['conditioned','uncured material breach','written notice','reasonable detail','fifteen business days','cure or dispute']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Extended cure period with dispute mechanism", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Fifteen-day cure period is longer than standard ten days. Dispute mechanism could create delay but may be acceptable if it doesn''t prevent withholding. Legal should review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Payment of fees is subject to ProdCo not being in uncured, material breach. Notwithstanding the foregoing, Amazon shall not withhold any payment on account of an alleged breach that is the subject of a good faith dispute between the parties.', ARRAY['subject to','uncured material breach','not withhold','alleged breach','good faith dispute']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Good faith dispute carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Good faith dispute carveout could limit Amazon''s withholding right during disputes. Legal should assess whether this unduly restricts Amazon''s leverage during breach situations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Fees are conditioned upon ProdCo not being in uncured, material breach. In the event Amazon withholds any payment pursuant to this provision, Amazon shall pay interest on any withheld amounts at the rate of [Prime + 2%] per annum from the original due date if it is subsequently determined that no breach occurred.', ARRAY['conditioned','uncured material breach','withholds','interest','Prime plus 2%','no breach occurred']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Interest on wrongfully withheld amounts", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Interest on wrongfully withheld amounts provides ProdCo protection against improper withholding. May be acceptable at reasonable rate. Legal and Finance should approve rate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Payment of the Production Fee is conditioned upon ProdCo not being in uncured, material breach, provided that amounts due for actual third-party production costs already incurred shall not be subject to withholding and shall be paid as scheduled.', ARRAY['Production Fee','conditioned','uncured material breach','third-party production costs','not subject to withholding']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Carveout for third-party costs", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for third-party costs already incurred is reasonable to avoid disrupting production vendors. Business Affairs should confirm scope is appropriately limited to documented third-party costs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All fees are subject to ProdCo not being in uncured, material breach. For purposes of this provision, a breach shall not be considered ''material'' if ProdCo is using commercially reasonable efforts to remedy such breach and such breach does not materially impair Amazon''s rights or the Program.', ARRAY['uncured material breach','commercially reasonable efforts','remedy','materially impair','Amazon''s rights','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Efforts-based materiality carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Efforts-based carveout could reduce Amazon''s leverage if ProdCo claims to be working on cure. Legal should assess whether this is acceptable given other protections."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'All fees payable to ProdCo hereunder are unconditional and shall be paid when due regardless of any breach or alleged breach by ProdCo. Amazon''s sole remedy for any breach shall be a claim for damages.', ARRAY['unconditional','paid when due','regardless of breach','sole remedy','damages']::text[], '{"doc": "Counterparty_Proposal", "section": "Fees/Payment", "note": "Unconditional payment obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Removing breach condition entirely eliminates Amazon''s primary leverage to ensure ProdCo performance. Unconditional payment obligation is fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Payment of fees is conditioned upon ProdCo not being in material breach, as determined by final, non-appealable judgment of a court of competent jurisdiction.', ARRAY['conditioned','material breach','final non-appealable judgment','court']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Judicial determination required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring judicial determination before withholding renders the breach condition meaningless. Litigation could take years, eliminating Amazon''s operational leverage."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Fees are conditioned upon ProdCo not being in uncured, material breach of this Agreement. For purposes of this provision, ''material breach'' shall mean only a breach resulting in ProdCo''s failure to deliver the completed Program.', ARRAY['conditioned','uncured material breach','material breach means','only','failure to deliver']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Extremely narrow materiality definition", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Defining material breach as only delivery failure excludes all other significant breaches (IP, confidentiality, compliance, reps/warranties). This gutting of the breach condition is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Fees are payable subject to ProdCo not being in uncured, material breach. Notwithstanding the foregoing, if Amazon withholds any payment and ProdCo disputes such withholding, ProdCo may suspend all services and Amazon shall continue to pay all crew and vendor costs during such suspension.', ARRAY['uncured material breach','withholds','ProdCo disputes','suspend services','Amazon pays costs']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "ProdCo suspension right with cost allocation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Allowing ProdCo to suspend services while Amazon pays costs in response to disputed withholding inverts the leverage structure entirely. This is fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Payment is conditioned upon ProdCo not being in uncured, material, willful, persistent breach of this Agreement that has been the subject of at least three (3) prior written notices from Amazon.', ARRAY['uncured','material','willful','persistent','three prior notices']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Stacked qualifiers on breach", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Adding ''willful,'' ''persistent,'' and three-notice requirement to already-qualified ''uncured, material'' makes it nearly impossible to invoke the breach condition. This accumulation of qualifiers is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Payment of fees is conditioned upon ProdCo not being in material breach. ProdCo shall have one hundred eighty (180) days following written notice to cure any breach, and Amazon may not withhold payment during such cure period.', ARRAY['conditioned','material breach','180 days','cure','no withholding during cure']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Excessive cure period with no withholding", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "180-day cure period is grossly excessive (standard is 10-15 business days), and prohibition on withholding during cure eliminates Amazon''s leverage entirely."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'All fees shall be paid as and when due. Amazon acknowledges that ProdCo''s cash flow depends on timely payment and agrees that any withholding of fees, regardless of reason, shall constitute a material breach by Amazon entitling ProdCo to terminate this Agreement.', ARRAY['paid when due','cash flow','withholding','material breach by Amazon','ProdCo terminate']::text[], '{"doc": "Counterparty_Proposal", "section": "Fees/Payment", "note": "Withholding as Amazon breach", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Characterizing any withholding as Amazon breach with ProdCo termination right completely inverts the commercial relationship. Amazon must retain withholding right for ProdCo breach."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All fees payable to ProdCo pursuant to this Agreement are subject to and conditioned upon all other terms and conditions of this Agreement, including without limitation the representations, warranties and indemnities set forth herein.', ARRAY['fees','subject to','conditioned upon','all other terms','representations','warranties','indemnities']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Standard terms and conditions conditioning", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard language ensuring fee payment is integrated with all Agreement obligations. Prevents argument that fees are independent of other terms."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Payment of the Production Fee and all other amounts hereunder is expressly subject to and conditioned upon ProdCo''s full compliance with all terms, conditions, representations, warranties, covenants and obligations set forth in this Agreement and any exhibits or schedules hereto.', ARRAY['Production Fee','all amounts','expressly subject to','full compliance','terms conditions','exhibits schedules']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Comprehensive conditioning including exhibits", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly includes exhibits and schedules, ensuring fee conditions apply to all components of the integrated agreement. Standard Amazon position."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The fees set forth in Exhibit A are subject to all terms and conditions of this Agreement. Without limiting the foregoing, payment is conditioned upon timely delivery of all Materials, execution of all required documentation, and ProdCo not being in breach of any provision hereof.', ARRAY['fees','Exhibit A','subject to all terms','timely delivery','execution of documentation','not in breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Specific operational conditions enumerated", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates key operational conditions (delivery, documentation) in addition to general terms conditioning. Provides additional clarity on payment prerequisites."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Fees hereunder are subject to all other terms and conditions of this Agreement. Amazon''s obligation to pay any installment is further conditioned upon Amazon''s approval of the applicable deliverable and receipt of all chain of title documentation required hereunder.', ARRAY['subject to all terms','Amazon approval','deliverable','chain of title documentation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Approval and documentation conditions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Ties payment to deliverable approval and chain of title documentation, which are standard production payment conditions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All compensation payable to ProdCo is subject to and conditioned upon all other terms of this Agreement. ProdCo acknowledges that the fees set forth herein are the total compensation for all rights granted and services rendered, and no additional compensation shall be due except as expressly provided.', ARRAY['compensation','subject to','conditioned','total compensation','all rights','services','no additional compensation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Total compensation acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes important acknowledgment that stated fees are total compensation, preventing later claims for additional payment. Standard protective language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Payment of fees is subject to all other terms and conditions hereof, including without limitation ProdCo''s compliance with all applicable laws, Amazon policies and guidelines, and the production schedule set forth in Exhibit B.', ARRAY['subject to','compliance','applicable laws','Amazon policies','guidelines','production schedule','Exhibit B']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Includes policy and schedule compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly references compliance with laws, Amazon policies, and production schedule as payment conditions. Comprehensive and acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The fees payable pursuant to Exhibit A are subject to and contingent upon all terms, conditions and covenants of this Agreement. In the event of any conflict between Exhibit A and this Agreement, the terms of this Agreement shall control.', ARRAY['fees','Exhibit A','subject to','contingent','terms conditions covenants','conflict','Agreement controls']::text[], '{"doc": "PSA_Principal_Terms", "section": "Fees/Payment", "note": "Hierarchy provision for exhibit conflicts", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Establishes hierarchy with main Agreement controlling over Exhibit A in case of conflicts. Prevents Exhibit A carveouts from overriding principal terms."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Fees are subject to all other terms and conditions of this Agreement, provided that Amazon shall not condition payment on compliance with any term or condition that was not disclosed to ProdCo in writing prior to commencement of production.', ARRAY['subject to','all terms','not condition','not disclosed','writing','prior to commencement']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Disclosure limitation on conditioning", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limitation to disclosed terms is reasonable as it prevents post-hoc creation of payment conditions. Legal should confirm all relevant terms are in fact disclosed in the Agreement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Payment is subject to all terms of this Agreement. If Amazon believes ProdCo has failed to satisfy any condition to payment, Amazon shall notify ProdCo in writing with reasonable specificity, and ProdCo shall have ten (10) business days to cure or provide evidence of compliance.', ARRAY['subject to all terms','notify','reasonable specificity','ten business days','cure','evidence of compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Notice and cure mechanism for conditions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notice and cure mechanism is reasonable and provides procedural fairness without eliminating conditions. Ten-day period is acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Fees are subject to all other terms and conditions hereof. Notwithstanding the foregoing, Amazon shall not withhold or delay payment based on immaterial or technical non-compliance with Agreement terms that does not affect the Program or Amazon''s rights therein.', ARRAY['subject to all terms','not withhold','immaterial','technical non-compliance','does not affect','Program','Amazon''s rights']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Immaterial non-compliance carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for truly immaterial non-compliance may be reasonable but could be subject to dispute. Legal should assess whether this creates interpretive issues."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Payment is subject to all terms and conditions of this Agreement. If Amazon determines that any condition to payment has not been satisfied, Amazon shall provide prompt written notice to ProdCo, and the parties shall meet within five (5) business days to resolve the matter in good faith.', ARRAY['subject to all terms','condition not satisfied','prompt notice','meet','five business days','resolve','good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Meet and confer requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Meet and confer requirement adds procedural step but doesn''t eliminate conditions. Legal should confirm this doesn''t unduly delay Amazon''s ability to withhold."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All fees are subject to the terms and conditions of this Agreement. ProdCo acknowledges that certain fees are conditioned upon specific deliverable approvals as set forth in Exhibit A, and that the parties shall work together in good faith to resolve any approval issues promptly.', ARRAY['subject to terms','deliverable approvals','Exhibit A','work together','good faith','resolve','promptly']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Good faith resolution for approval issues", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Good faith resolution language for approval issues is acceptable if it doesn''t limit Amazon''s ultimate approval discretion. Legal should review Exhibit A approval provisions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Fees are subject to all terms of this Agreement, except that fees for services already performed by ProdCo as of the date of any alleged non-compliance shall not be subject to forfeiture or clawback.', ARRAY['subject to all terms','except','services performed','alleged non-compliance','no forfeiture','no clawback']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Anti-clawback for earned fees", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Anti-clawback for services already performed may be reasonable from equity standpoint but limits Amazon''s remedies. Legal should assess interaction with indemnity and set-off rights."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The fees set forth in Exhibit A are payable unconditionally and are not subject to any terms, conditions, or other provisions of this Agreement. Payment obligations shall be independent of all other covenants herein.', ARRAY['unconditionally','not subject to','any terms','independent','all other covenants']::text[], '{"doc": "Counterparty_Proposal", "section": "Fees/Payment", "note": "Unconditional independent payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Making payment unconditional and independent of Agreement terms eliminates Amazon''s ability to enforce compliance through payment leverage. Fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Fees are subject to the payment schedule in Exhibit A only and shall not be conditioned upon, reduced by, or offset against any other terms, conditions, claims or obligations arising under this Agreement.', ARRAY['Exhibit A only','not conditioned','reduced','offset','claims','obligations']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "No set-off or offset rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating set-off rights removes a critical Amazon remedy. Payment must be subject to set-off for claims, damages, and other amounts owed by ProdCo."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Payment of fees is subject to all terms of this Agreement. Notwithstanding the foregoing, if ProdCo disputes any Amazon determination that a condition has not been satisfied, ProdCo may submit the dispute to expedited arbitration, and Amazon shall pay the disputed amount into escrow pending resolution.', ARRAY['subject to all terms','disputes','expedited arbitration','pay into escrow','pending resolution']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Escrow requirement for disputes", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring Amazon to pay disputed amounts into escrow eliminates withholding leverage and forces payment despite ProdCo non-compliance. This is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'While fees are generally subject to the terms of this Agreement, ProdCo shall be entitled to full payment of all fees if ProdCo has substantially performed its obligations, even if technical breaches or minor non-compliance exist.', ARRAY['generally subject','full payment','substantially performed','technical breaches','minor non-compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Substantial performance standard", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Substantial performance'' standard borrowed from construction law is inappropriate for media production agreements. Creates ambiguity about what constitutes sufficient compliance."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Fees are subject to all terms and conditions hereof. If Amazon withholds any fee based on alleged non-satisfaction of any condition, ProdCo may elect to suspend all production activities until payment is made, and any resulting delays shall extend the delivery schedule day-for-day.', ARRAY['subject to all terms','withholds','ProdCo suspend production','delays extend schedule']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "ProdCo suspension right", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Giving ProdCo suspension rights in response to withholding (even for legitimate non-compliance) inverts the contractual leverage structure and is commercially unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Payment of fees shall be subject only to those specific conditions expressly enumerated in Exhibit A. No other term, condition, representation, warranty, covenant or obligation in this Agreement shall constitute a condition to payment.', ARRAY['subject only to','Exhibit A','no other term','representation warranty','not condition to payment']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Limited conditioning to Exhibit A only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting payment conditions to Exhibit A only excludes critical Agreement provisions (reps/warranties, indemnities, IP assignment) from payment leverage. Fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Fees are subject to all terms of this Agreement, provided that Amazon must exercise any withholding right within thirty (30) days of becoming aware of the applicable non-compliance. Failure to withhold within such period shall constitute waiver of such right.', ARRAY['subject to all terms','withhold within 30 days','aware of non-compliance','waiver']::text[], '{"doc": "Counterparty_Markup", "section": "Fees/Payment", "note": "Time-limited withholding with waiver", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "30-day waiver provision is unreasonably short and could result in loss of withholding rights before full scope of non-compliance is discovered. Amazon needs ongoing right to condition payment."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All entitlements set forth in this Agreement or Exhibit A are subject to and conditioned upon (i) completion of ProdCo''s services hereunder, and (ii) ProdCo not being in uncured, material breach of this Agreement.', ARRAY['entitlements','conditioned','completion of services','not in','uncured material breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Standard entitlements condition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard conditioning of entitlements on completion and no breach. Entitlements (perks, residuals, bonuses) require these baseline conditions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s entitlement to credit, bonus compensation, profit participation or any other benefits described herein is expressly conditioned upon ProdCo''s full performance and completion of all services and ProdCo not being in uncured, material breach of this Agreement at any time during or after production.', ARRAY['entitlement','credit','bonus','profit participation','benefits','full performance','completion','uncured material breach','during or after production']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Comprehensive entitlements enumeration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly enumerates credit, bonus, and profit participation as conditioned entitlements. ''During or after production'' extends condition appropriately."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Entitlements are conditioned upon completion of services and ProdCo not being in uncured, material breach. For purposes of this provision, ''completion'' means ProdCo has rendered all services required hereunder through final delivery and acceptance of the Program by Amazon.', ARRAY['entitlements conditioned','completion','uncured material breach','completion means','final delivery','acceptance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Defined completion standard", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Defines ''completion'' as including final delivery and acceptance, ensuring entitlements don''t vest until Amazon has accepted all deliverables."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All entitlements, including without limitation any residual or reuse payments, sequel/spinoff fees, or passive payments, shall be subject to and conditioned upon completion of ProdCo''s obligations and ProdCo not being in uncured, material breach of this Agreement.', ARRAY['entitlements','residual','reuse payments','sequel spinoff fees','passive payments','conditioned','completion','uncured material breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Extended to all contingent payments", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly covers residuals, sequel fees, and passive payments under entitlement conditions. Comprehensive coverage of contingent compensation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Entitlements are conditioned upon (a) ProdCo completing all services, (b) delivery of all required Materials to Amazon''s satisfaction, and (c) ProdCo not being in uncured, material breach of this Agreement or any other agreement between ProdCo and Amazon or its affiliates.', ARRAY['entitlements conditioned','completing services','delivery','Amazon''s satisfaction','uncured material breach','any other agreement','affiliates']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Cross-default with affiliates", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes cross-default to other Amazon/affiliate agreements, preventing ProdCo from maintaining entitlements despite breach of related deals."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s entitlements under this Agreement shall vest only upon completion of services and absence of uncured, material breach. Prior to vesting, Amazon may suspend or terminate any entitlement if ProdCo is in breach or has failed to perform.', ARRAY['entitlements','vest','completion','absence of breach','prior to vesting','suspend','terminate','failed to perform']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Vesting concept with suspension right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Uses vesting concept common in employment context, with clear Amazon rights to suspend or terminate pre-vesting. Standard acceptable approach."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All entitlements are subject to completion and no uncured, material breach. If ProdCo is removed or replaced prior to completion for any reason other than Amazon''s convenience, ProdCo shall forfeit all entitlements, and Amazon shall have no obligation to pay any amounts other than fees earned through the date of removal.', ARRAY['entitlements','completion','uncured material breach','removed replaced','forfeit','no obligation','fees earned','date of removal']::text[], '{"doc": "PSA_Principal_Terms", "section": "Entitlements", "note": "Forfeiture upon removal", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear forfeiture consequence for removal, with carveout only for Amazon convenience removal. Provides appropriate Amazon protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Entitlements are conditioned upon completion and no uncured, material breach. If ProdCo is terminated by Amazon for cause, entitlements shall be forfeited; however, if ProdCo is terminated for Amazon''s convenience, ProdCo shall receive a pro-rata portion of entitlements based on services performed.', ARRAY['entitlements conditioned','completion','uncured material breach','terminated for cause','forfeited','convenience','pro-rata','services performed']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Pro-rata entitlements on convenience termination", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Pro-rata entitlement for convenience termination is a common ProdCo ask. May be acceptable for major producers. Legal should assess specific entitlements subject to pro-rata treatment."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Entitlements are subject to completion and no uncured, material breach. Notwithstanding the foregoing, if ProdCo completes principal photography but is removed prior to post-production, ProdCo shall retain credit entitlements (but not financial entitlements) earned through principal photography.', ARRAY['entitlements','completion','uncured material breach','principal photography','removed','retain credit entitlements','not financial entitlements']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Credit retention post-principal photography", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Retaining credit (but not financial) entitlements after principal photography may be reasonable where ProdCo has made substantial contribution. Legal should assess specific credits affected."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All entitlements are conditioned upon completion and no uncured, material breach; provided that ProdCo shall receive written notice of any alleged breach and shall have twenty (20) business days to cure such breach before forfeiture of any entitlement.', ARRAY['entitlements conditioned','completion','uncured material breach','written notice','twenty business days','cure','forfeiture']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Extended cure period for entitlement forfeiture", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Twenty-day cure period is longer than standard but may be acceptable given severity of entitlement forfeiture. Legal should confirm adequacy."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Entitlements are conditioned upon completion and no uncured, material breach. In the event of a disputed breach, entitlements shall be held in abeyance pending resolution; if the dispute is resolved in ProdCo''s favor, entitlements shall be reinstated retroactively.', ARRAY['entitlements conditioned','completion','uncured material breach','disputed breach','abeyance','resolution','reinstated retroactively']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Abeyance for disputed breaches", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Abeyance mechanism for disputed breaches preserves entitlements pending resolution. Retroactive reinstatement is reasonable if no breach occurred. Legal should review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Entitlements are subject to completion of services and absence of uncured, material breach. For the avoidance of doubt, ''completion'' shall include substantial completion, meaning performance of at least ninety percent (90%) of required services, with remaining services being immaterial to the Program.', ARRAY['entitlements','completion','uncured material breach','substantial completion','ninety percent','remaining services','immaterial']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Substantial completion standard", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Substantial completion (90%) standard may be acceptable depending on what services could be excluded. Legal should confirm this doesn''t allow key deliverables to be incomplete."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s entitlements are conditioned upon completion and no uncured, material breach. If ProdCo is unable to complete services due to disability, death, or force majeure affecting ProdCo''s key personnel, entitlements shall be prorated based on services actually rendered.', ARRAY['entitlements conditioned','completion','uncured material breach','disability','death','force majeure','key personnel','prorated','services rendered']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Proration for force majeure/disability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Proration for disability, death, or force majeure affecting key personnel is reasonable equity-based protection. Legal should confirm scope of ''key personnel.''"}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s entitlements shall vest immediately upon execution of this Agreement and shall not be subject to any conditions, including completion of services or absence of breach.', ARRAY['entitlements vest','immediately','execution','not subject','conditions','completion','breach']::text[], '{"doc": "Counterparty_Proposal", "section": "Entitlements", "note": "Unconditional immediate vesting", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Immediate unconditional vesting eliminates Amazon''s ability to condition entitlements on performance. This is fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Entitlements are conditioned upon completion, but shall not be conditioned upon absence of breach. ProdCo''s entitlements shall be payable regardless of any breach of this Agreement, subject only to Amazon''s right to pursue damages separately.', ARRAY['entitlements conditioned','completion','not conditioned','absence of breach','payable regardless','damages separately']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Breach condition removed", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Removing breach condition from entitlements eliminates Amazon''s leverage for compliance. Entitlements must remain subject to no-breach condition."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Entitlements are conditioned upon completion and no material breach. If Amazon alleges a breach, ProdCo may contest such allegation in binding arbitration, and entitlements shall continue to be paid pending final arbitration award.', ARRAY['entitlements conditioned','completion','material breach','contest','binding arbitration','continue to be paid','pending award']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Payment during arbitration", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring continued entitlement payment pending arbitration eliminates Amazon''s leverage and creates potential for unrecoverable payments. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Entitlements shall vest upon completion of principal photography and shall not be affected by any subsequent breach or failure to complete post-production services.', ARRAY['entitlements vest','principal photography','not affected','subsequent breach','failure','post-production']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Early vesting at principal photography", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Vesting entitlements at principal photography with no subsequent breach condition leaves Amazon without leverage for post-production compliance. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Entitlements are conditioned upon completion and no uncured, material breach, provided that any breach must be (i) adjudicated by a court of competent jurisdiction, (ii) have caused damages exceeding $1,000,000, and (iii) not be subject to insurance coverage.', ARRAY['entitlements conditioned','completion','uncured material breach','adjudicated','court','damages exceeding','one million','insurance coverage']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Stacked requirements for breach finding", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring adjudication, $1M+ damages, and no insurance coverage makes breach condition nearly impossible to invoke. These stacked requirements are unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s credit entitlements shall be unconditional. All other entitlements are conditioned upon completion and no uncured, material breach. Amazon shall not withhold or condition credit on any basis.', ARRAY['credit entitlements','unconditional','other entitlements','conditioned','completion','not withhold','credit','any basis']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Credit entitlements carved out", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Making credit unconditional conflicts with Amazon''s sole discretion over credits. Credit must remain within Amazon''s control like other entitlements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Entitlements are subject to completion only. The concept of ''uncured, material breach'' is deleted. ProdCo shall be entitled to all entitlements upon rendering substantially all services regardless of any alleged breach or non-compliance.', ARRAY['entitlements','completion only','uncured material breach','deleted','entitled','substantially all services','regardless','alleged breach']::text[], '{"doc": "Counterparty_Markup", "section": "Entitlements", "note": "Breach condition deleted entirely", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Complete deletion of breach condition is unacceptable. Amazon must maintain ability to withhold entitlements for material breach."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Any credit to be accorded to ProdCo or any other person in connection with the Program shall be determined by Amazon in its sole discretion.', ARRAY['credit','ProdCo','any other person','determined','Amazon','sole discretion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Standard sole discretion language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position reserving absolute discretion over all credits. This is essential for maintaining creative and business control over the Program."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All matters relating to credit, including form, size, placement, duration and order of credits, shall be within Amazon''s sole and absolute discretion.', ARRAY['credit','form','size','placement','duration','order','sole and absolute discretion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Comprehensive credit elements enumerated", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific credit elements (form, size, placement, duration, order) all within sole discretion. Comprehensive and clear."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Credit, if any, shall be accorded in Amazon''s sole discretion, including whether to accord credit at all, the form and manner of any credit, and the media in which credit may appear.', ARRAY['credit if any','sole discretion','whether to accord','form manner','media']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Explicit ''if any'' language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''If any'' makes clear that credit itself is discretionary, not just its form. Important for maximum flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have sole discretion with respect to all credit decisions, including without limitation credits for producers, executive producers, directors, writers, cast, crew and all other contributors to the Program.', ARRAY['sole discretion','credit decisions','producers','executive producers','directors','writers','cast','crew','contributors']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Applies to all contributor categories", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly extends sole discretion to all contributor categories, preventing arguments that discretion applies only to ProdCo credit."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Credit shall be determined by Amazon in its sole discretion, consistent with Amazon''s then-current credit policies and any applicable guild requirements. Subject to the foregoing, Amazon shall have no obligation to accord credit to any person.', ARRAY['sole discretion','Amazon credit policies','guild requirements','no obligation','any person']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Acknowledges guild requirements only", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Appropriately acknowledges that guild requirements may impose minimum credit obligations while preserving sole discretion for all other matters."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s decisions regarding credit shall be final, binding and non-appealable, and shall be made in Amazon''s sole discretion. ProdCo hereby waives any right to challenge, dispute or seek review of any credit determination.', ARRAY['decisions','credit','final binding non-appealable','sole discretion','waives','challenge dispute review']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Finality and waiver language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Adds finality and waiver language to prevent credit disputes. Strong protection of Amazon''s discretion."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All credit determinations are within Amazon''s sole discretion and shall be subject to change at any time without notice to or consent from ProdCo or any other party.', ARRAY['credit determinations','sole discretion','subject to change','any time','without notice','without consent']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Right to change without notice", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Preserves Amazon''s right to modify credits at any time without process, which is important for responding to changed circumstances or creative decisions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit shall be determined by Amazon in its sole discretion; provided that Amazon shall accord ProdCo an ''Executive Producer'' credit in the main titles of the Program if ProdCo completes all services and is not in uncured material breach.', ARRAY['sole discretion','provided that','Executive Producer','main titles','completes services','not in breach']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Specific credit commitment for ProdCo", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Specific EP credit commitment for ProdCo may be acceptable for major producers if conditioned on completion and no breach. Legal should confirm this is negotiated outcome."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit shall be within Amazon''s sole discretion, except that Amazon agrees to use good faith efforts to provide ProdCo an on-screen producer credit consistent with industry custom for comparable productions.', ARRAY['sole discretion','except','good faith efforts','producer credit','industry custom','comparable productions']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Good faith efforts for producer credit", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "''Good faith efforts'' standard for producer credit is softer than absolute commitment. May be acceptable if ''industry custom'' provides flexibility. Legal should review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit is within Amazon''s sole discretion. Notwithstanding the foregoing, if Amazon accords any producer credit to any third party, Amazon shall also accord a comparable producer credit to ProdCo.', ARRAY['sole discretion','notwithstanding','producer credit','third party','comparable','ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Most favored nations for producer credit", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "MFN for producer credit relative to other producers. May be acceptable depending on other producer arrangements. Legal should assess impact on credit flexibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have sole discretion over all credit matters, provided that Amazon shall consult with ProdCo regarding producer credits prior to finalizing the credit block, though Amazon shall retain final decision-making authority.', ARRAY['sole discretion','consult','producer credits','prior to finalizing','credit block','final decision-making authority']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Consultation right without approval", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Consultation (without approval right) before finalizing credits is minimally intrusive. Legal should confirm ''final decision-making authority'' language is clear."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit shall be in Amazon''s sole discretion. In exercising such discretion, Amazon shall consider in good faith any reasonable credit requests submitted by ProdCo in writing, but Amazon shall have no obligation to honor any such request.', ARRAY['sole discretion','consider in good faith','reasonable credit requests','in writing','no obligation','honor request']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Good faith consideration without obligation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Agreeing to ''consider'' requests without obligation to honor them is relatively low risk. May be acceptable as relationship gesture."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit is in Amazon''s sole discretion. If Amazon removes or reduces ProdCo''s credit after initial determination, Amazon shall provide ProdCo written notice and a brief explanation of the reason for such change.', ARRAY['sole discretion','removes reduces','initial determination','written notice','brief explanation','reason']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Notice for credit reduction", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notice and brief explanation for credit changes doesn''t limit Amazon''s discretion but provides courtesy to ProdCo. May be acceptable for relationship purposes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall receive an ''Executive Producer'' credit in the main titles of the Program, in first position among all producer credits, in a size and style no less prominent than any other credit.', ARRAY['Executive Producer','main titles','first position','no less prominent','any other credit']::text[], '{"doc": "Counterparty_Proposal", "section": "Credit", "note": "Guaranteed position and prominence", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Guaranteed credit position and prominence eliminates Amazon''s discretion and creates potential conflicts with other credit commitments. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon and ProdCo shall mutually agree upon all credits to be accorded in connection with the Program. Neither party shall finalize credits without the written approval of the other.', ARRAY['mutually agree','all credits','neither party','finalize','written approval','other']::text[], '{"doc": "Counterparty_Proposal", "section": "Credit", "note": "Mutual approval requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mutual approval requirement gives ProdCo blocking power over all credits. This fundamentally undermines Amazon''s creative and business control."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Credit shall be in Amazon''s reasonable discretion, and Amazon shall not unreasonably withhold, condition or delay any credit reasonably requested by ProdCo.', ARRAY['reasonable discretion','not unreasonably withhold','condition','delay','reasonably requested']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Reasonable discretion standard", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Reasonable discretion'' with ''not unreasonably withhold'' standard exposes Amazon to disputes about what is reasonable. Amazon requires sole discretion."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall have the right to approve all credits relating to ProdCo and its personnel. Amazon shall submit proposed credits to ProdCo for approval at least thirty (30) days prior to the scheduled initial release date.', ARRAY['right to approve','credits','ProdCo personnel','submit','thirty days','prior to release']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "ProdCo approval over its credits", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo approval right over credits is contrary to Amazon''s sole discretion requirement. Creates potential delays and disputes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall accord credit in accordance with the credit schedule attached hereto as Exhibit D. Amazon may not deviate from Exhibit D without ProdCo''s prior written consent.', ARRAY['credit schedule','Exhibit D','may not deviate','prior written consent']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Fixed credit schedule with no deviation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Fixed credit schedule with no deviation right locks Amazon into commitments that may become problematic. Amazon must retain flexibility."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Credit decisions shall be made by a committee consisting of one representative from Amazon and one representative from ProdCo. In the event of disagreement, the matter shall be submitted to binding arbitration.', ARRAY['committee','representative','Amazon','ProdCo','disagreement','binding arbitration']::text[], '{"doc": "Counterparty_Proposal", "section": "Credit", "note": "Joint credit committee", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Joint credit committee with arbitration creates unacceptable operational complexity and eliminates Amazon''s unilateral control. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Credit is within Amazon''s discretion. However, if Amazon fails to accord ProdCo a producer credit in the main titles, ProdCo shall be entitled to additional compensation equal to 10% of the Production Fee as liquidated damages.', ARRAY['discretion','fails to accord','producer credit','main titles','additional compensation','10%','liquidated damages']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Liquidated damages for no credit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Liquidated damages for credit decisions effectively monetizes what should be discretionary. Creates pressure to accord credit regardless of merit."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No casual or inadvertent failure to comply with any credit obligation, nor any failure by third parties to comply with their credit obligations, shall constitute a breach of this Agreement. Amazon''s sole obligation shall be to prospectively cure any such failure on future copies or broadcasts, to the extent commercially practicable.', ARRAY['casual inadvertent failure','third parties','not breach','sole obligation','prospectively cure','future copies','broadcasts','commercially practicable']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Standard inadvertent failure language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard protection against credit errors becoming breach claims. Prospective cure only, with commercial practicability qualifier. Industry-standard language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Any inadvertent failure to accord credit in accordance with this Agreement shall not be a breach hereof, and ProdCo''s sole remedy shall be prospective correction on a going-forward basis when and if such correction is reasonably practicable.', ARRAY['inadvertent failure','not breach','sole remedy','prospective correction','going-forward','reasonably practicable']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Sole remedy limitation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly limits remedy to prospective correction, preventing damages claims for credit errors. ''Sole remedy'' language is important."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall not be in breach of any credit obligation due to any inadvertent omission or error, or any act or omission of third parties including distributors, licensees, broadcasters or exhibitors. Amazon agrees to use reasonable efforts to correct any credit error on prospective copies or broadcasts.', ARRAY['not in breach','inadvertent omission error','third parties','distributors licensees broadcasters exhibitors','reasonable efforts','correct','prospective']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Third party and distributor coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly covers third-party errors (distributors, broadcasters) which are common sources of credit issues and outside Amazon''s direct control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No failure to comply with credit provisions, whether inadvertent, casual or otherwise, shall constitute a breach or default under this Agreement. ProdCo waives any claim, cause of action or remedy arising from any credit failure, and agrees that prospective cure shall be the exclusive remedy for any such failure.', ARRAY['failure','inadvertent casual otherwise','not breach default','waives','claim cause of action remedy','prospective cure','exclusive remedy']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Broad waiver with exclusive remedy", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Expands beyond ''inadvertent'' to cover all credit failures, with explicit waiver of claims. Very strong protection for Amazon."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Inadvertent credit failures shall not constitute breach. Amazon shall have no obligation to recall, remaster or re-release any materials to correct credit errors, and prospective correction shall be limited to new production runs or newly-created digital assets.', ARRAY['inadvertent','not breach','no obligation','recall remaster re-release','prospective correction','new production runs','digital assets']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "No recall or remastering obligation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly excludes recall, remastering, or re-release obligations which could be extremely costly. Limits prospective cure to new materials."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Credit errors or omissions, whether by Amazon or any third party, shall not be deemed a breach of this Agreement, and Amazon shall have no liability therefor. Amazon''s sole obligation, upon written notice from ProdCo identifying a specific credit error, shall be to use commercially reasonable efforts to correct such error prospectively.', ARRAY['credit errors omissions','Amazon','third party','not breach','no liability','sole obligation','written notice','commercially reasonable efforts','prospectively']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Notice requirement for cure", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Adds notice requirement, shifting burden to ProdCo to identify errors before cure obligation triggers. Reasonable procedural protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Failure to accord credit as contemplated herein shall not constitute a breach if such failure is inadvertent and is corrected prospectively within a commercially reasonable time after Amazon receives written notice thereof from ProdCo.', ARRAY['failure','not breach','inadvertent','corrected prospectively','commercially reasonable time','written notice']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Time-based prospective cure", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''Commercially reasonable time'' provides flexibility for cure while still requiring action after notice. Standard acceptable formulation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Inadvertent credit failures shall not be a breach. Amazon shall use best efforts to correct any credit error prospectively within thirty (30) days after receiving written notice from ProdCo.', ARRAY['inadvertent','not breach','best efforts','correct','thirty days','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Best efforts with 30-day timeline", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "''Best efforts'' is higher standard than ''reasonable efforts.'' 30-day timeline may be acceptable if limited to new materials. Legal should confirm ''best efforts'' is workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Inadvertent credit failures shall not constitute a breach, and Amazon''s sole obligation shall be prospective cure. If the same credit error occurs on more than three (3) separate occasions after written notice, such repeated failure shall no longer be deemed inadvertent.', ARRAY['inadvertent','not breach','prospective cure','three occasions','written notice','no longer inadvertent']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Repeated failure carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for repeated errors after notice is reasonable as truly inadvertent errors shouldn''t recur. Legal should confirm ''three occasions'' threshold is workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit failures shall not be a breach, and prospective cure shall be the sole remedy; provided that this limitation shall not apply to willful or intentional failure to accord credit that was expressly agreed upon in writing.', ARRAY['not breach','prospective cure','sole remedy','not apply','willful intentional','expressly agreed','writing']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Carveout for willful failures", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for ''willful or intentional'' failure of expressly agreed credits may be reasonable. Legal should assess whether any credits are ''expressly agreed'' under the agreement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Inadvertent credit failures shall not be a breach, and prospective cure shall be the exclusive remedy. For the avoidance of doubt, this provision shall not limit ProdCo''s right to seek specific performance of credit obligations for future exploitation.', ARRAY['inadvertent','not breach','prospective cure','exclusive remedy','not limit','specific performance','future exploitation']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Specific performance carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Preserving specific performance for future exploitation is consistent with prospective cure concept but uses different legal mechanism. Legal should assess whether this is problematic."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit failures shall not constitute breach, and Amazon shall correct prospectively. If any credit failure is not corrected within sixty (60) days after written notice, ProdCo may, at ProdCo''s expense, place a corrective notice on ProdCo''s website regarding the correct credit.', ARRAY['not breach','correct prospectively','sixty days','written notice','ProdCo expense','corrective notice','website']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Self-help corrective notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Self-help website notice at ProdCo''s expense is minimal impact and allows ProdCo to address reputational concerns without imposing costs on Amazon. May be acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Inadvertent or casual credit failures by Amazon shall not be a breach, provided that failures caused by Amazon''s licensees or distributors shall not be deemed Amazon''s failure, and Amazon shall have no responsibility for third-party credit errors.', ARRAY['inadvertent casual','not breach','licensees distributors','not Amazon''s failure','no responsibility','third-party errors']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Express third-party disclaimer", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Express disclaimer of responsibility for licensee/distributor errors is protective and consistent with standard position. Legal should confirm this is adequately covered."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Any failure to accord credit as required by this Agreement shall constitute a material breach. ProdCo shall be entitled to damages, injunctive relief and termination of this Agreement for any credit failure, whether inadvertent or otherwise.', ARRAY['failure','material breach','damages','injunctive relief','termination','inadvertent or otherwise']::text[], '{"doc": "Counterparty_Proposal", "section": "Credit", "note": "Credit failure as material breach", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Making all credit failures (including inadvertent) material breach with full remedies is wholly inconsistent with industry standard and operationally unworkable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Inadvertent credit failures shall not be a breach, but Amazon shall pay ProdCo liquidated damages of $10,000 for each credit failure that is not corrected within fifteen (15) days after written notice.', ARRAY['inadvertent','not breach','liquidated damages','$10,000','each failure','fifteen days','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Liquidated damages for uncured failures", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Liquidated damages for credit failures is inconsistent with prospective-cure-only remedy. Creates significant financial exposure for operational issues."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Credit failures shall not be a breach, but Amazon shall indemnify ProdCo against any reputational harm, loss of business opportunities, or other damages suffered by ProdCo as a result of any credit omission or error.', ARRAY['not breach','indemnify','reputational harm','loss of business','damages','credit omission error']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Indemnity for credit errors", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Indemnification for ''reputational harm'' and ''loss of business opportunities'' from credit errors is speculative, potentially unlimited, and inconsistent with sole-remedy limitation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Credit failures shall be subject to prospective cure only; provided that Amazon shall recall and replace all physical media and re-issue all digital files to correct any credit error affecting ProdCo''s producer credit.', ARRAY['prospective cure','recall','replace','physical media','re-issue','digital files','producer credit']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Recall and replacement obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Recall and replacement obligation for credit errors is extremely costly and impractical. Prospective cure must mean new copies only, not retrofitting existing distribution."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Inadvertent credit failures shall not be a breach, provided that Amazon notifies ProdCo of any credit failure within five (5) business days of Amazon becoming aware of such failure, and corrects the failure within fifteen (15) business days.', ARRAY['inadvertent','not breach','provided','Amazon notifies','five business days','aware','corrects','fifteen business days']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Notice and cure timeline on Amazon", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Imposing notice and cure timelines on Amazon inverts the standard arrangement. Amazon should not have affirmative obligation to discover and report credit errors."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This inadvertent failure provision shall apply only to credit failures affecting minor contributors. Any failure to accord proper credit to ProdCo, the showrunner, or principal cast members shall constitute a material breach regardless of intent.', ARRAY['inadvertent','minor contributors only','ProdCo','showrunner','principal cast','material breach','regardless of intent']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Carveout for key credits", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Carving out key credits from inadvertent failure protection creates disproportionate exposure for the most visible (and error-prone) credits. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Inadvertent credit failures shall not be a breach. However, if Amazon fails to correct any credit error within ninety (90) days after notice, ProdCo may terminate this Agreement and retain all rights in the Program.', ARRAY['inadvertent','not breach','fails to correct','ninety days','terminate','retain all rights']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Termination right for uncured credit error", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination with rights retention for credit errors is grossly disproportionate remedy. Credit issues cannot result in loss of Program rights."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include in its agreements with third-party distributors and licensees a requirement that such parties accord credit to talent in accordance with their contractual entitlements. Amazon shall have no liability for any third party''s failure to comply with credit obligations.', ARRAY['reasonable efforts','third-party distributors','licensees','accord credit','talent','contractual entitlements','no liability','third party failure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "Standard reasonable efforts with no liability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position requiring only reasonable efforts to include credit provisions in third-party agreements, with explicit disclaimer of liability for third-party failures."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon agrees to use reasonable efforts to cause its licensees and sub-distributors to comply with applicable credit requirements. ProdCo acknowledges that Amazon has no privity of contract with such third parties and shall have no responsibility for their actions or omissions regarding credit.', ARRAY['reasonable efforts','licensees','sub-distributors','credit requirements','no privity','no responsibility','actions omissions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "Privity acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes explicit acknowledgment of no privity, reinforcing that Amazon cannot guarantee third-party compliance. Standard protective language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'With respect to third-party exploitation of the Program, Amazon shall use reasonable efforts to include credit provisions in its license agreements. Amazon does not warrant or guarantee that any third party will comply with such provisions and shall not be liable for any third party''s failure to do so.', ARRAY['third-party exploitation','reasonable efforts','credit provisions','license agreements','no warrant guarantee','not liable','failure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "No warranty of compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly disclaims warranty or guarantee of third-party compliance. ''Reasonable efforts to include'' is the appropriate standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include provisions in its distribution agreements requiring compliance with credit obligations. ProdCo agrees that Amazon shall not be required to police, monitor or enforce such provisions, and shall have no liability for any distributor''s failure to accord proper credit.', ARRAY['reasonable efforts','distribution agreements','credit obligations','not required to police','monitor','enforce','no liability','distributor failure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "No policing obligation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly disclaims policing, monitoring, and enforcement obligations, which is essential as Amazon cannot practically oversee all third-party credit compliance."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon will use reasonable efforts to include credit requirements in agreements with third parties exploiting the Program. ProdCo''s sole recourse for any third party''s credit failure shall be directly against such third party, and not against Amazon.', ARRAY['reasonable efforts','credit requirements','third parties','sole recourse','directly against third party','not against Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "Directs recourse to third party", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly directs ProdCo''s recourse to the breaching third party rather than Amazon. Important for avoiding Amazon as intermediary in credit disputes."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall include in its standard license agreements a provision requiring licensees to accord credit consistent with the Program''s credit block. Amazon shall have no liability for any licensee''s failure to comply, and ProdCo waives any claim against Amazon arising from such failure.', ARRAY['standard license agreements','licensees','credit block','no liability','waives claim','arising from failure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "Includes waiver of claims", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Adds explicit waiver of claims against Amazon for third-party credit failures, providing additional protection beyond simple no-liability statement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s obligations with respect to third-party credit compliance shall be limited to using reasonable efforts to include appropriate credit provisions in its license agreements. Amazon shall not be deemed in breach of this Agreement due to any act or omission of any third party regarding credit.', ARRAY['obligations limited','reasonable efforts','credit provisions','license agreements','not deemed in breach','act omission','third party']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "Limitation on Amazon''s obligation scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clearly limits scope of Amazon''s obligation to inclusion of provisions, explicitly stating third-party failures don''t constitute Amazon breach."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall use commercially reasonable efforts to include credit provisions in its third-party agreements and to notify such third parties of credit requirements. Amazon shall have no liability for third-party failures, but shall notify ProdCo if Amazon becomes aware of any material credit violation by a major licensee.', ARRAY['commercially reasonable efforts','credit provisions','notify third parties','no liability','notify ProdCo','material credit violation','major licensee']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Notice of material violations", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Notice requirement for material violations by major licensees adds obligation but is limited in scope. Legal should confirm this doesn''t create monitoring duty."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in third-party agreements. If ProdCo notifies Amazon of a third party''s credit failure and provides reasonable evidence thereof, Amazon shall use reasonable efforts to communicate with such third party regarding correction.', ARRAY['reasonable efforts','credit provisions','ProdCo notifies','reasonable evidence','communicate','third party','correction']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Communication upon ProdCo notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Obligation to communicate with third party upon ProdCo notice is additional but limited. ''Reasonable efforts'' standard and evidence requirement provide protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in distribution agreements. Amazon shall have no liability for third-party failures; provided that Amazon shall not affirmatively instruct any third party to omit or reduce credits that are required under this Agreement.', ARRAY['reasonable efforts','distribution agreements','no liability','not affirmatively instruct','omit reduce credits','required']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "No affirmative instruction to omit", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Prohibition on affirmatively instructing credit omission is reasonable and shouldn''t limit Amazon''s flexibility. Legal should confirm this is operationally acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall include credit provisions in its material third-party license agreements (excluding short-form licenses, promotional licenses, and agreements with total value under $50,000). Amazon shall have no liability for any third party''s credit failure.', ARRAY['material third-party license agreements','excluding','short-form','promotional','under $50,000','no liability']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Carveouts for minor licenses", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Carveouts for minor licenses are reasonable as including credit provisions in every small deal is impractical. Legal should confirm thresholds are appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in third-party agreements. If Amazon enters into any license agreement that does not contain credit provisions, Amazon shall notify ProdCo of such omission within thirty (30) days.', ARRAY['reasonable efforts','credit provisions','license agreement','does not contain','notify ProdCo','omission','thirty days']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Notice of agreements without credit provisions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Notice requirement for agreements lacking credit provisions adds tracking burden. Legal should assess operational feasibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in its third-party agreements and shall provide ProdCo with copies of credit-related provisions from major distribution agreements (with financial terms redacted) upon reasonable request.', ARRAY['reasonable efforts','credit provisions','copies','credit-related provisions','major distribution agreements','redacted','reasonable request']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Copies of credit provisions upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Providing copies of credit provisions (with financial terms redacted) upon request is additional but limited burden. Legal should confirm confidentiality concerns are addressed."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall ensure that all third-party distributors and licensees comply with credit obligations. Amazon shall be responsible for any third party''s failure to accord proper credit and shall indemnify ProdCo against any claims arising from such failure.', ARRAY['ensure','third-party distributors','licensees','comply','responsible','indemnify','claims','failure']::text[], '{"doc": "Counterparty_Proposal", "section": "Third-Party Credit", "note": "Amazon guarantee of third-party compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Ensure'' creates guarantee obligation, and indemnification for third-party failures is unacceptable. Amazon cannot control third-party behavior."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall use best efforts to cause all third parties exploiting the Program to comply with credit requirements. Amazon shall be liable for any third party''s failure to accord credit as if such failure were Amazon''s own breach of this Agreement.', ARRAY['best efforts','cause','third parties','comply','liable','third party failure','Amazon''s own breach']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Best efforts with liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Best efforts'' is higher than reasonable efforts, and treating third-party failures as Amazon breach creates unacceptable liability exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall include credit provisions in all third-party agreements and shall actively monitor and enforce such provisions. Amazon shall terminate any licensee that fails to comply with credit requirements after written notice.', ARRAY['include','all third-party agreements','actively monitor','enforce','terminate','fails to comply','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Active monitoring and enforcement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Active monitoring and enforcement obligation is operationally impractical. Termination requirement for credit non-compliance is grossly disproportionate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in third-party agreements. If any third party fails to accord proper credit, Amazon shall pursue legal action against such third party at Amazon''s expense to enforce credit compliance.', ARRAY['reasonable efforts','credit provisions','third party fails','pursue legal action','Amazon''s expense','enforce credit compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Litigation obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Obligation to pursue legal action against third parties for credit failures is unreasonable, costly, and disproportionate to the credit interest at stake."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall include credit provisions in third-party agreements and shall be jointly and severally liable with any third party that fails to comply with credit requirements. ProdCo may pursue claims against Amazon or the third party, or both.', ARRAY['credit provisions','jointly and severally liable','third party','fails to comply','pursue claims','Amazon or third party']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Joint and several liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Joint and several liability with third parties for credit failures is completely unacceptable. Amazon cannot be liable for entities it doesn''t control."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall include credit provisions in third-party agreements. Amazon''s no-liability protection shall not apply if Amazon failed to include such provisions or if Amazon approved any third-party materials that contained credit errors prior to distribution.', ARRAY['credit provisions','no-liability','not apply','failed to include','approved','credit errors','prior to distribution']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Exceptions to no-liability", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Creating exceptions to no-liability for approval of materials or inclusion failures significantly undermines protection. Amazon cannot review all third-party materials for credit accuracy."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in third-party agreements. If any third party fails to accord proper credit, Amazon shall pay ProdCo liquidated damages of $25,000 per occurrence, regardless of whether Amazon bears fault for such failure.', ARRAY['reasonable efforts','third party fails','liquidated damages','$25,000','per occurrence','regardless of fault']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Liquidated damages for third-party failures", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Liquidated damages for third-party credit failures regardless of Amazon fault is completely unacceptable. Amazon cannot be penalized for conduct it doesn''t control."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually require its distributors and licensees to accord credit in accordance with the Program''s credit block. Notwithstanding the foregoing, Amazon shall have no obligation to police or monitor such compliance and shall have no liability for any distributor''s or licensee''s failure to comply.', ARRAY['contractually require','distributors','licensees','credit block','no obligation','police','monitor','no liability','failure to comply']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Contractual bind with no police/no liability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Upgrade from ''reasonable efforts'' to ''contractually require'' is a give that requires Legal approval. No-police and no-liability protections remain essential."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon agrees to include binding credit provisions in its license agreements with third parties. ProdCo acknowledges that Amazon shall not be required to enforce such provisions or to monitor third-party compliance, and Amazon shall not be liable for any third party''s credit failure.', ARRAY['binding credit provisions','license agreements','not required to enforce','monitor','not liable','third party credit failure']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Binding provisions with enforcement disclaimer", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Binding provisions language is stronger than reasonable efforts but paired with appropriate enforcement and liability disclaimers. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall include in its distribution agreements a contractual requirement that distributors provide credit consistent with talent agreements. Amazon shall have no responsibility for policing such agreements, and ProdCo''s sole recourse for any credit violation shall be against the violating distributor.', ARRAY['contractual requirement','distributors','credit','talent agreements','no responsibility','policing','sole recourse','violating distributor']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Sole recourse against distributor", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Directs recourse exclusively to violating distributor, maintaining Amazon''s protection despite contractual-bind obligation. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually bind its major territorial licensees to accord credit in accordance with this Agreement. ''Major territorial licensees'' means licensees with rights in territories generating at least 5% of worldwide Program revenue. Amazon shall have no policing obligation and no liability for non-compliance.', ARRAY['contractually bind','major territorial licensees','5%','worldwide revenue','no policing obligation','no liability','non-compliance']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Limited to major licensees", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting contractual-bind obligation to major licensees (defined by revenue threshold) is reasonable scope limitation. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'With respect to third-party exploitation, Amazon shall include credit requirements in its license agreements as contractual provisions. Amazon expressly disclaims any duty to police, monitor, audit or enforce such provisions, and shall have no liability whatsoever for any licensee''s failure to comply with credit requirements.', ARRAY['credit requirements','contractual provisions','disclaims duty','police','monitor','audit','enforce','no liability','licensee failure']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Comprehensive disclaimer of duties", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Comprehensive disclaimer covering police, monitor, audit, and enforce provides robust protection alongside contractual-bind commitment. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually require third-party distributors to accord credit. If Amazon becomes aware of a material credit violation and ProdCo requests in writing, Amazon shall send a single written notice to the violating distributor requesting correction. Amazon shall have no further obligation and no liability regardless of whether correction occurs.', ARRAY['contractually require','becomes aware','material credit violation','written request','single written notice','requesting correction','no further obligation','no liability']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Single notice upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Commitment to send single notice upon request is limited additional obligation that doesn''t create enforcement duty. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon agrees to contractually bind its licensees to credit compliance obligations. ProdCo acknowledges that: (a) Amazon cannot guarantee third-party compliance; (b) Amazon has no duty to police or enforce such provisions; (c) Amazon shall have no liability for third-party credit failures; and (d) ProdCo''s sole remedy is against the non-compliant third party.', ARRAY['contractually bind','licensees','cannot guarantee','no duty','police','enforce','no liability','sole remedy','non-compliant third party']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Enumerated acknowledgments", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Enumerated acknowledgments reinforce that contractual-bind commitment doesn''t expand Amazon''s liability or enforcement obligations. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually require its licensees to comply with credit requirements. Upon ProdCo''s written request identifying a specific credit violation with supporting evidence, Amazon shall forward ProdCo''s complaint to the relevant licensee. Amazon shall have no further obligation and no liability.', ARRAY['contractually require','written request','specific violation','supporting evidence','forward complaint','no further obligation','no liability']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Complaint forwarding upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Complaint forwarding is ministerial act that doesn''t create enforcement obligation. Evidence requirement provides protection against frivolous requests. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually bind licensees to credit obligations and shall have no policing duty or liability. If Amazon terminates or does not renew any licensee agreement for any reason, Amazon shall use reasonable efforts to require the successor licensee to correct any known credit deficiencies.', ARRAY['contractually bind','no policing','no liability','terminates','does not renew','successor licensee','correct','known credit deficiencies']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Successor licensee obligation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Successor licensee credit correction is limited obligation triggered only by licensee transition. ''Known deficiencies'' limits scope. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall include binding credit provisions in third-party agreements. Amazon shall have no policing obligation or liability; provided that if Amazon exercises any contractual remedy against a licensee for material breach unrelated to credit, Amazon shall consider in good faith including credit violations in any such enforcement action if raised by ProdCo.', ARRAY['binding credit provisions','no policing','no liability','exercises remedy','material breach','consider in good faith','credit violations','enforcement action']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Piggyback on other enforcement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Considering credit issues when already pursuing other enforcement is limited obligation that doesn''t create independent enforcement duty. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually require credit compliance by third parties. Amazon shall not be required to police such agreements; however, Amazon shall include in its form license agreements a provision allowing ProdCo (as third-party beneficiary for credit provisions only) to enforce credit requirements directly against the licensee.', ARRAY['contractually require','not required to police','form license agreements','third-party beneficiary','credit provisions only','enforce directly','licensee']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Third-party beneficiary rights", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Third-party beneficiary status for ProdCo on credit provisions shifts enforcement burden from Amazon to ProdCo but creates privity concerns. Requires careful Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually bind licensees to accord credit. If any licensee persistently fails to accord proper credit after multiple notices (three or more) and ProdCo requests in writing, Amazon shall consider in good faith whether to include such failure as a factor in future license renewal decisions.', ARRAY['contractually bind','persistently fails','multiple notices','three or more','written request','consider in good faith','license renewal']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Consideration in renewal decisions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Good faith consideration of credit failures in renewal decisions is weak commitment that preserves Amazon discretion. ''Persistent'' and ''multiple notices'' thresholds provide protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually require credit compliance. Amazon shall have no policing obligation or liability for third-party failures. Notwithstanding the foregoing, Amazon shall provide ProdCo upon written request with contact information for the person responsible for credit matters at any major licensee, so ProdCo may communicate directly.', ARRAY['contractually require','no policing','no liability','provide upon request','contact information','credit matters','major licensee','communicate directly']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Contact information sharing", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Providing contact information for direct ProdCo communication is minimal burden that empowers ProdCo without creating Amazon enforcement obligations. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually require all third parties to comply with credit provisions and shall actively enforce such provisions. If any third party fails to accord proper credit, Amazon shall pursue all available legal remedies at Amazon''s cost to compel compliance.', ARRAY['contractually require','actively enforce','fails','pursue','legal remedies','Amazon''s cost','compel compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Active enforcement obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Active enforcement and litigation obligation is unacceptable regardless of contractual-bind commitment. Amazon cannot be required to sue third parties over credit."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually bind all third parties to credit compliance. Amazon shall monitor all third-party exploitation for credit compliance on an ongoing basis and shall notify ProdCo within seven (7) days of any credit violation discovered.', ARRAY['contractually bind','monitor','all third-party exploitation','ongoing basis','notify ProdCo','seven days','violation discovered']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Ongoing monitoring obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Ongoing monitoring obligation is operationally impractical and directly contradicts the no-police protection that is essential to the contractual-bind give."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually require credit compliance. If any third party materially violates credit requirements, Amazon shall terminate such licensee''s agreement within thirty (30) days of written notice from ProdCo, or Amazon shall be liable to ProdCo for the third party''s continuing violations.', ARRAY['contractually require','materially violates','terminate','thirty days','written notice','liable','continuing violations']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Mandatory termination or liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mandatory termination for credit violations or assumption of liability is grossly disproportionate and unacceptable. Credit issues cannot dictate major business relationships."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually bind licensees to credit provisions. Amazon shall be deemed to have policing and enforcement obligations with respect to credit provisions, and any third party''s credit failure shall be deemed Amazon''s failure for purposes of this Agreement.', ARRAY['contractually bind','deemed','policing','enforcement obligations','third party failure','deemed Amazon''s failure']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Third-party failures imputed to Amazon", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deeming third-party failures as Amazon failures directly contradicts the no-liability protection and creates unacceptable exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually require credit compliance. Amazon''s no-policing and no-liability protections shall apply only to immaterial credit errors. For material credit violations (affecting main titles or key creative credits), Amazon shall actively enforce and shall be liable if enforcement is not pursued.', ARRAY['contractually require','no-policing','no-liability','immaterial only','material violations','main titles','key creative','actively enforce','liable']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Carveout for material violations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Carving out ''material'' violations from no-liability protection creates significant exposure for the most visible credits and is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall include credit provisions in third-party agreements as binding obligations. If Amazon fails to include such provisions in any agreement, Amazon shall indemnify ProdCo against any losses arising from that third party''s failure to accord proper credit.', ARRAY['credit provisions','binding obligations','fails to include','indemnify','losses','third party failure']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Indemnity for failure to include provisions", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Indemnification for failing to include credit provisions creates disproportionate exposure. The remedy for inclusion failure shouldn''t be full liability for third-party conduct."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually require credit compliance and shall audit all major licensees annually for credit compliance. Amazon shall share audit results with ProdCo and shall withhold a portion of license fees from any non-compliant licensee until compliance is achieved.', ARRAY['contractually require','audit','major licensees','annually','credit compliance','share audit results','withhold','license fees','non-compliant']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Annual audit and fee withholding", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Annual credit audits and fee withholding obligations are operationally burdensome and disproportionate to credit interests. Completely unacceptable."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have sole and final control over all aspects of the development, production, post-production, marketing, distribution and exploitation of the Program, including without limitation all creative, editorial, technical and business decisions.', ARRAY['sole and final control','all aspects','development','production','post-production','marketing','distribution','exploitation','creative','editorial','technical','business decisions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Standard comprehensive control provision", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position establishing complete control over all Program-related decisions. Essential for maintaining creative and business autonomy over the content."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All decisions regarding the Program shall be made by Amazon in its sole discretion, including decisions relating to casting, scripting, directing, producing, editing, marketing, release timing, platforms, territories and any other matter affecting the Program.', ARRAY['all decisions','sole discretion','casting','scripting','directing','producing','editing','marketing','release timing','platforms','territories']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Enumerated control elements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific control elements to provide additional clarity. Comprehensive list reinforces Amazon''s unilateral decision-making authority."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have the sole right to determine the final form and content of the Program. Amazon may edit, modify, add to, subtract from, rearrange, adapt or otherwise alter the Program in any manner without limitation and without any requirement to consult with or obtain approval from ProdCo.', ARRAY['sole right','final form content','edit','modify','add','subtract','rearrange','adapt','alter','without limitation','no consultation','no approval']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Editorial control specifics", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly addresses editorial modifications without consultation or approval, ensuring Amazon can make any changes needed for creative, regulatory, or commercial reasons."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges and agrees that Amazon shall exercise sole and final control over the Program and that ProdCo shall have no approval, consultation or veto rights with respect to any decision relating to the Program.', ARRAY['acknowledges agrees','sole and final control','no approval','no consultation','no veto rights','any decision']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Explicit waiver of ProdCo rights", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit acknowledgment that ProdCo has no approval, consultation, or veto rights reinforces Amazon''s control and prevents future disputes about implied rights."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s control over the Program shall be absolute and unfettered. Amazon shall not be required to produce, complete, release, distribute or continue to exploit the Program, and all such decisions shall be within Amazon''s sole discretion.', ARRAY['absolute unfettered','not required','produce','complete','release','distribute','exploit','sole discretion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Includes no-release discretion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly includes discretion not to produce, release, or exploit the Program, which is essential for avoiding any implied commitment to release."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have sole and final control over all Program matters. ProdCo shall render services strictly in accordance with Amazon''s instructions and directions, and shall implement all changes, revisions or modifications requested by Amazon promptly and without objection.', ARRAY['sole and final control','render services','Amazon''s instructions','directions','implement changes','revisions','modifications','promptly','without objection']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Service delivery subject to control", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Connects Amazon''s control to ProdCo''s service obligations, ensuring ProdCo must follow Amazon direction without resistance or delay."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall exercise sole and final creative and business control over the Programme. Without limiting the foregoing, Amazon shall have the exclusive right to determine all matters relating to format, length, rating, language versions, accessibility features, territorial release strategy and platform prioritisation.', ARRAY['sole and final','creative','business control','format','length','rating','language versions','accessibility','territorial release','platform prioritisation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "UK production with platform specifics", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate spelling with specific streaming platform considerations (accessibility, platform prioritization). Comprehensive control provision."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have sole and final control over the Program. Notwithstanding the foregoing, Amazon shall consult with ProdCo regarding key creative decisions, including selection of director and principal cast, provided that Amazon shall retain final decision-making authority.', ARRAY['sole and final control','consult','key creative decisions','director','principal cast','final decision-making authority']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Consultation on key creative", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation (without approval) on key creative decisions may be acceptable for major producers if Amazon retains final authority. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have sole and final control over the Program in all respects. If Amazon contemplates a material change to the approved production budget or shooting schedule, Amazon shall provide ProdCo reasonable advance notice of such change.', ARRAY['sole and final control','material change','approved production budget','shooting schedule','reasonable advance notice']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Notice for budget/schedule changes", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notice (not approval) for budget/schedule changes is minimal impact on control and may be operationally reasonable. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall exercise sole and final control over the Program. Amazon agrees to consider in good faith any creative input provided by ProdCo, though Amazon shall have no obligation to accept or incorporate such input and shall retain final authority over all decisions.', ARRAY['sole and final control','consider in good faith','creative input','no obligation','accept incorporate','final authority']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Good faith consideration of input", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''Consider in good faith'' with explicit disclaimer of obligation to accept is low-impact accommodation. May be appropriate for relationship purposes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have sole and final control over the Program. If Amazon decides not to proceed with production of the Program after commencement of pre-production, Amazon shall notify ProdCo in writing and pay any documented wind-down costs reasonably incurred by ProdCo.', ARRAY['sole and final control','decides not to proceed','commencement of pre-production','notify','writing','wind-down costs','reasonably incurred']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Wind-down costs on cancellation", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Wind-down costs for post-pre-production cancellation is a commercial term that doesn''t affect control. Business Affairs should assess scope and caps."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have sole and final control over the Program, subject to compliance with applicable laws and regulations, guild and union requirements, and any third-party agreements to which Amazon has consented in writing.', ARRAY['sole and final control','subject to','applicable laws','regulations','guild union','third-party agreements','consented in writing']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Subject to laws/guilds/consented agreements", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Carveouts for laws, regulations, and Amazon-consented agreements are inherent limitations that don''t expand ProdCo rights. Legal should confirm scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall exercise sole and final control over the Program. ProdCo may request Amazon''s reconsideration of any creative decision by written notice setting forth ProdCo''s concerns; Amazon shall respond to any such request within five (5) business days but shall not be obligated to change any decision.', ARRAY['sole and final control','request reconsideration','creative decision','written notice','concerns','respond','five business days','not obligated']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Reconsideration request process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Formal reconsideration process is additional procedure but doesn''t limit Amazon''s decision authority. Requires Legal assessment of operational impact."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon and ProdCo shall jointly exercise control over the Program. All material creative and business decisions shall require the mutual written approval of both parties.', ARRAY['jointly','control','material creative','business decisions','mutual written approval','both parties']::text[], '{"doc": "Counterparty_Proposal", "section": "Control", "note": "Joint control proposal", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Joint control fundamentally undermines Amazon''s position as sole owner and decision-maker. Creates potential for deadlock and is completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have control over distribution and marketing of the Program. ProdCo shall have creative control over the Program, including final cut authority, and Amazon shall not make any creative changes without ProdCo''s prior written consent.', ARRAY['Amazon distribution marketing','ProdCo creative control','final cut','no creative changes','prior written consent']::text[], '{"doc": "Counterparty_Proposal", "section": "Control", "note": "Split control with ProdCo final cut", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Splitting control gives ProdCo creative authority that conflicts with Amazon''s ownership. Final cut authority for ProdCo is completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have sole and final control over the Program, except that ProdCo shall have approval rights over the following: (a) selection of director; (b) selection of principal cast; (c) final script; (d) final cut; and (e) any material changes to the approved budget.', ARRAY['sole and final control','except','ProdCo approval rights','director','principal cast','final script','final cut','budget changes']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Major approval rights reserved to ProdCo", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo approval over director, cast, script, final cut, and budget represents near-total creative control. These carveouts eviscerate Amazon''s control."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall exercise control over the Program in a manner consistent with ProdCo''s creative vision for the series as set forth in the Series Bible attached hereto. Amazon shall not deviate materially from the Series Bible without ProdCo''s consent.', ARRAY['control','consistent with','ProdCo''s creative vision','Series Bible','not deviate','materially','ProdCo''s consent']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Bound by Series Bible", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Binding Amazon to ProdCo''s ''creative vision'' in a Series Bible with consent requirement for deviations gives ProdCo effective creative control. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have control over the Program. However, ProdCo shall have the right to remove ProdCo''s name and any credit from the Program if Amazon makes creative decisions that ProdCo, in its reasonable judgment, determines are inconsistent with ProdCo''s professional reputation.', ARRAY['control','however','remove name','credit','creative decisions','reasonable judgment','inconsistent','professional reputation']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Reputation-based removal right", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Reputation-based removal right creates implicit pressure on Amazon''s creative decisions. While not a formal approval right, it functions as a constraint on Amazon''s control."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s control over the Program shall be subject to the oversight of a Creative Committee consisting of two representatives from Amazon and two representatives from ProdCo. Decisions of the Creative Committee shall be made by majority vote.', ARRAY['control subject to','oversight','Creative Committee','two representatives','Amazon','ProdCo','majority vote']::text[], '{"doc": "Counterparty_Proposal", "section": "Control", "note": "Creative Committee oversight", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Creative Committee with equal representation creates deadlock risk and shared control. Majority vote structure cannot function with 2-2 composition. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall exercise reasonable control over the Program in accordance with industry-standard production practices. ProdCo shall have the right to dispute any Amazon decision that deviates from such practices, with disputes to be resolved by an independent production consultant.', ARRAY['reasonable control','industry-standard','production practices','right to dispute','deviates','disputes resolved','independent consultant']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Industry standard limitation with disputes", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable control'' with industry-standard limitation and dispute resolution undermines sole control. Independent consultant decisions would override Amazon authority."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not issue or authorize any press release, publicity, announcement or other public statement regarding the Program, this Agreement or ProdCo''s relationship with Amazon without Amazon''s prior written approval.', ARRAY['not issue','authorize','press release','publicity','announcement','public statement','Program','Agreement','relationship','prior written approval']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Standard publicity restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position requiring prior written approval for all publicity. Essential for controlling messaging around the Program and Amazon relationship."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All publicity, marketing, promotion and advertising relating to the Program shall be controlled exclusively by Amazon. ProdCo shall not make any public statement or disclosure about the Program without Amazon''s prior written consent, which may be withheld in Amazon''s sole discretion.', ARRAY['publicity','marketing','promotion','advertising','controlled exclusively','Amazon','no public statement','disclosure','prior written consent','sole discretion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Comprehensive marketing control", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive language covering all forms of public communication with explicit sole discretion standard for consent."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain strict confidentiality regarding the Program and shall not disclose any information about the Program to any third party, including media outlets, without Amazon''s prior written approval. This restriction applies during production and in perpetuity thereafter.', ARRAY['strict confidentiality','not disclose','information','third party','media outlets','prior written approval','during production','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Perpetual publicity restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Perpetual restriction ensures ProdCo cannot make unauthorized statements even after production or release. Essential for long-term control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not issue any publicity without Amazon''s prior written approval. Without limiting the foregoing, ProdCo shall not post any content relating to the Program on any social media platform, website, blog or other digital medium without Amazon''s express authorization.', ARRAY['no publicity','prior written approval','not post','content','social media','website','blog','digital medium','express authorization']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Includes social media restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly covers social media and digital platforms, which are increasingly important channels that require Amazon control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All publicity relating to the Program requires Amazon''s prior written approval. ProdCo shall submit any proposed publicity materials to Amazon at least ten (10) business days in advance, and Amazon shall have the right to approve, reject or require modifications to such materials.', ARRAY['all publicity','prior written approval','submit','proposed materials','ten business days','advance','approve','reject','require modifications']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Submission and review process", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Establishes clear submission and review process with adequate lead time for Amazon review. Right to require modifications ensures complete control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not make any public statement regarding the Program without Amazon''s prior approval. ProdCo shall ensure that all of its employees, contractors, agents and representatives comply with this restriction and shall be responsible for any unauthorized publicity by such persons.', ARRAY['no public statement','prior approval','ensure','employees','contractors','agents','representatives','comply','responsible','unauthorized publicity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Extends to ProdCo personnel", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends publicity restriction to all ProdCo personnel and makes ProdCo responsible for their compliance. Essential for practical enforcement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No publicity shall be issued without Amazon''s prior written approval. For the avoidance of doubt, this restriction covers interviews, panel appearances, podcasts, trade publication articles, industry event presentations, award campaign materials and any other form of public communication relating to the Program.', ARRAY['no publicity','prior written approval','interviews','panel appearances','podcasts','trade publications','industry events','award campaigns','public communication']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Comprehensive enumeration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Detailed enumeration of publicity formats prevents arguments that certain types of communication fall outside the restriction."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not issue publicity without Amazon''s prior written approval, except that ProdCo may include a brief, factual reference to the Program in ProdCo''s corporate communications (e.g., investor reports, company website bio) describing ProdCo''s slate of productions.', ARRAY['no publicity','prior written approval','except','brief factual reference','corporate communications','investor reports','website bio','slate']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Corporate communications carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited carveout for factual corporate communications may be acceptable for established production companies. Legal should review to ensure scope is narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo requires Amazon''s prior approval for all publicity. Notwithstanding the foregoing, after the Program''s initial public release, ProdCo may make general statements acknowledging ProdCo''s involvement with the Program without disclosing confidential information or plot details.', ARRAY['prior approval','all publicity','notwithstanding','after initial release','general statements','acknowledging involvement','no confidential information','plot details']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Post-release acknowledgment carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Post-release acknowledgment of involvement without confidential/plot disclosure may be acceptable. Legal should define ''general statements'' more precisely."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall obtain Amazon''s prior approval for all publicity. Amazon shall respond to ProdCo''s approval requests within five (5) business days; failure to respond shall be deemed approval for purposes of this provision only.', ARRAY['prior approval','all publicity','respond','five business days','failure to respond','deemed approval']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Deemed approval for non-response", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Deemed approval on non-response creates risk of inadvertent approval. Legal should assess whether 5-day window is adequate for review and whether this is operationally workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'No publicity without Amazon''s prior approval. ProdCo may respond to direct media inquiries by referring the inquiry to Amazon''s publicity department; provided that ProdCo shall not provide any substantive response without Amazon''s approval.', ARRAY['no publicity','prior approval','respond','media inquiries','referring','Amazon''s publicity','no substantive response']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Referral of media inquiries", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Allowing ProdCo to refer inquiries to Amazon (without substantive response) is procedurally helpful and doesn''t undermine control. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo requires Amazon''s prior written approval for publicity. If ProdCo is nominated for or receives an industry award relating to the Program, ProdCo may make acceptance speeches and participate in press events customary for such awards, provided ProdCo does not disclose NPI.', ARRAY['prior written approval','publicity','nominated','industry award','acceptance speeches','press events','customary','no NPI disclosure']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Award ceremony carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Award ceremony participation is expected and blocking it could damage relationships. NPI protection is maintained. Legal should confirm scope of ''customary'' activities."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All publicity requires Amazon''s prior approval. Amazon hereby grants ongoing approval for ProdCo to use the approved Program logline and key art provided by Amazon in ProdCo''s portfolio and website, subject to Amazon''s right to revoke such approval upon written notice.', ARRAY['prior approval','ongoing approval','approved logline','key art','portfolio','website','revoke','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Pre-approved portfolio use", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Pre-approval for specific approved materials in portfolio with revocation right is limited grant that may be acceptable. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may issue publicity regarding the Program at any time without Amazon''s approval, provided such publicity does not contain false or misleading information. ProdCo shall provide Amazon with copies of any publicity materials within five (5) business days of release.', ARRAY['may issue','without approval','not false misleading','provide copies','five business days','after release']::text[], '{"doc": "Counterparty_Proposal", "section": "Publicity", "note": "No prior approval required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating prior approval requirement gives ProdCo complete publicity freedom. After-the-fact copies are useless for controlling messaging. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo requires Amazon''s approval for publicity, which approval shall not be unreasonably withheld, conditioned or delayed. Amazon shall be deemed to have acted unreasonably if it fails to approve factually accurate publicity within three (3) business days.', ARRAY['approval','not unreasonably withheld','conditioned','delayed','deemed unreasonable','factually accurate','three business days']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Reasonableness standard with deemed approval", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Not unreasonably withheld'' with 3-day deemed approval effectively eliminates Amazon''s publicity control. Amazon needs sole discretion over all publicity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s approval is required for ProdCo publicity. However, ProdCo''s principals may discuss the Program freely on their personal social media accounts and in personal interviews, as such statements are personal expression and not official ProdCo communications.', ARRAY['approval required','however','principals','personal social media','personal interviews','personal expression','not official']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Personal social media carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Carveout for principals'' ''personal'' social media and interviews creates massive loophole. Personal/official distinction is unworkable and defeats publicity control."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not issue publicity without Amazon''s approval. If Amazon denies approval, Amazon shall provide ProdCo a written explanation of the denial and ProdCo shall have the right to appeal the denial to Amazon''s Head of Communications for final determination.', ARRAY['not issue','without approval','denies','written explanation','right to appeal','Head of Communications','final determination']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Appeal process for denials", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Appeal process for publicity denials undermines Amazon''s control by creating escalation mechanism. Written explanations for denials create unnecessary burden."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Publicity requires Amazon''s approval, except for communications required by law, regulation, or court order. ProdCo may also issue publicity if necessary to protect ProdCo''s business reputation from material harm, with notice to Amazon concurrent with release.', ARRAY['approval','except','required by law','court order','protect reputation','material harm','notice concurrent']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Reputation protection carveout", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Reputation protection'' carveout is subjective and could be invoked to justify any self-serving publicity. This exception is too broad."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo requires Amazon''s prior approval for formal press releases. All other publicity, including social media posts, interviews, industry event appearances and behind-the-scenes content, shall be at ProdCo''s discretion with contemporaneous notice to Amazon.', ARRAY['prior approval','formal press releases','all other publicity','social media','interviews','events','BTS','ProdCo discretion','contemporaneous notice']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Limited to formal press releases only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting approval to ''formal press releases'' only while freeing everything else defeats the purpose of publicity control. Most modern publicity occurs outside formal press releases."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Publicity approval is required. Amazon agrees not to deny approval for any publicity that is substantially similar in tone and content to publicity previously approved by Amazon for this Program or other similar Amazon productions.', ARRAY['approval required','not deny','substantially similar','tone content','previously approved','similar productions']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Precedent-based approval obligation", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Substantially similar'' standard based on prior approvals creates precedent-lock that limits Amazon''s ability to evolve publicity strategy or respond to changing circumstances."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not use any Amazon trademarks, service marks, trade names, logos or other proprietary designations without Amazon''s prior written approval in each instance.', ARRAY['not use','Amazon trademarks','service marks','trade names','logos','proprietary designations','prior written approval','each instance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Standard trademark restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position requiring prior approval for each use of Amazon marks. Essential for trademark protection and brand control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Use of Amazon''s trademarks, including without limitation the Amazon logo, Prime Video logo, and any Program-specific marks created by Amazon, requires Amazon''s prior written approval. Any approved use must comply with Amazon''s then-current trademark guidelines.', ARRAY['Amazon''s trademarks','Amazon logo','Prime Video logo','Program-specific marks','prior written approval','trademark guidelines']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Includes guidelines compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly references specific Amazon marks and requires compliance with trademark guidelines. Comprehensive trademark protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not use any Amazon marks without prior written approval. All goodwill arising from any approved use of Amazon marks shall inure solely to Amazon''s benefit. ProdCo shall not register or attempt to register any mark confusingly similar to Amazon''s marks.', ARRAY['not use','Amazon marks','prior written approval','goodwill','inure','Amazon''s benefit','not register','confusingly similar']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Goodwill and registration protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes essential goodwill inurement and anti-registration provisions to prevent ProdCo from claiming rights in Amazon marks."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Prior written approval is required for use of Amazon marks. ProdCo acknowledges that Amazon is the sole owner of all Amazon trademarks and that ProdCo has no rights in such marks except as expressly authorized in writing by Amazon. Such authorization may be revoked at any time.', ARRAY['prior written approval','Amazon marks','sole owner','no rights','except expressly authorized','writing','revoked','any time']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Ownership acknowledgment with revocability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit ownership acknowledgment and revocability provision ensures Amazon maintains complete control over its marks."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s prior written approval is required for any use of Amazon trademarks. ProdCo shall submit proposed uses to Amazon for approval at least fifteen (15) business days in advance, including mock-ups or samples showing the proposed use in context.', ARRAY['prior written approval','Amazon trademarks','submit proposed uses','fifteen business days','advance','mock-ups','samples','context']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Submission process with mock-ups", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Establishes clear submission process with adequate lead time and requires contextual mock-ups for proper review."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Use of Amazon marks requires prior written approval. If Amazon approves any use, such approval shall be limited to the specific use, medium, territory and time period approved, and shall not constitute approval for any other or extended use.', ARRAY['prior written approval','Amazon marks','limited','specific use','medium','territory','time period','not constitute','other','extended use']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Narrow scope of approval", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Limits each approval to specific parameters, preventing ProdCo from extrapolating one approval to cover other uses."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not use Amazon trademarks without prior written approval. ProdCo shall not use Amazon marks in any manner that suggests Amazon endorses, sponsors or is affiliated with ProdCo''s other business activities or productions not covered by this Agreement.', ARRAY['not use','Amazon trademarks','prior written approval','not suggest','endorses','sponsors','affiliated','other business','other productions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "No implied endorsement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Prevents ProdCo from leveraging Amazon relationship to imply endorsement of unrelated activities. Important brand protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s prior written approval is required for use of Amazon marks. Amazon hereby grants ongoing approval for ProdCo to use the standard ''An Amazon Original'' credit block provided by Amazon, in the format and placement specified by Amazon, in connection with the Program only.', ARRAY['prior written approval','ongoing approval','Amazon Original','credit block','format','placement','specified','Program only']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Pre-approved credit block use", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Pre-approval for standard Amazon-provided credit block in specified format is controlled, limited use that may be acceptable. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Prior approval required for Amazon marks. Amazon shall respond to approval requests within ten (10) business days. If Amazon does not respond within such period, ProdCo may send a reminder notice, and if Amazon does not respond within five (5) additional business days, approval shall be deemed granted for the specific requested use only.', ARRAY['prior approval','ten business days','respond','reminder notice','five additional days','deemed granted','specific use only']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Deemed approval with reminder", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Deemed approval with reminder requirement and 15-day total window provides some protection. Legal should assess whether this is operationally acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Use of Amazon marks requires prior approval. Notwithstanding the foregoing, ProdCo may use Amazon marks in factual descriptions of ProdCo''s relationship with Amazon (e.g., ''produced for Amazon'') in ProdCo''s corporate materials, provided such use is textual only and does not incorporate Amazon logos.', ARRAY['prior approval','notwithstanding','factual descriptions','relationship','produced for Amazon','corporate materials','textual only','no logos']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Textual reference carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited carveout for textual references (no logos) in corporate materials may be acceptable. Legal should confirm ''factual descriptions'' is sufficiently narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s prior written approval is required for trademark use. For any use in connection with the Program''s marketing or distribution, Amazon shall not unreasonably withhold approval of uses that comply with Amazon''s brand guidelines, provided ProdCo submits such uses with adequate lead time.', ARRAY['prior written approval','marketing','distribution','not unreasonably withhold','brand guidelines','adequate lead time']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Not unreasonably withheld for guideline-compliant use", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "''Not unreasonably withheld'' for guideline-compliant uses in Program marketing context may be acceptable given the guideline compliance requirement. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Prior written approval is required for Amazon marks. If ProdCo requests approval for a specific use and Amazon does not respond within the specified review period, ProdCo may escalate the request to Amazon''s designated trademark contact, who shall respond within three (3) business days.', ARRAY['prior written approval','does not respond','review period','escalate','designated trademark contact','three business days']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Escalation for non-response", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Escalation process for non-response doesn''t create deemed approval but provides procedural pathway. May be acceptable for operational purposes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s approval is required for use of Amazon trademarks. Upon termination of this Agreement for any reason, ProdCo shall immediately cease all use of Amazon marks and shall remove or cover Amazon marks from any materials in ProdCo''s possession within thirty (30) days.', ARRAY['approval required','termination','immediately cease','all use','remove','cover','materials','possession','thirty days']::text[], '{"doc": "PSA_Fallbacks", "section": "Trademarks", "note": "Post-termination cessation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Post-termination cessation requirement reinforces Amazon''s trademark control. 30-day removal period may be acceptable for practical purposes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may use Amazon trademarks in connection with the Program without prior approval, provided such use complies with Amazon''s publicly available brand guidelines. Amazon may request corrections for non-compliant uses.', ARRAY['may use','without prior approval','publicly available','brand guidelines','request corrections','non-compliant']::text[], '{"doc": "Counterparty_Proposal", "section": "Trademarks", "note": "Self-policing guideline compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Self-policing compliance with brand guidelines eliminates Amazon''s prior approval control. Request for corrections after the fact is inadequate protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s prior approval is required for trademark use, which approval shall not be unreasonably withheld. Approval shall be deemed granted if Amazon fails to respond within five (5) business days of ProdCo''s request.', ARRAY['prior approval','not unreasonably withheld','deemed granted','fails to respond','five business days']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Short deemed approval window", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Five-day deemed approval is too short for proper trademark review, and ''not unreasonably withheld'' undermines Amazon''s discretion. Creates unacceptable trademark exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Prior written approval is required for Amazon marks. Amazon hereby grants ProdCo a perpetual, irrevocable, royalty-free license to use Amazon marks in connection with the Program and any derivative works, spinoffs or franchises based thereon.', ARRAY['prior written approval','grants','perpetual','irrevocable','royalty-free license','Program','derivative works','spinoffs','franchises']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Perpetual irrevocable license", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Perpetual, irrevocable trademark license eliminates Amazon''s ongoing control over its marks. Amazon must retain ability to revoke trademark permissions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s approval is required for use of Amazon marks. In connection with any approved use, Amazon shall reimburse ProdCo for costs incurred in implementing Amazon''s brand requirements, including costs of producing materials featuring Amazon marks.', ARRAY['approval required','approved use','reimburse','costs','brand requirements','producing materials']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Cost reimbursement for brand compliance", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Requiring Amazon to reimburse costs of trademark use inverts the relationship. ProdCo should bear costs of using Amazon marks for its benefit."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Use of Amazon marks requires approval. If Amazon revokes any previously granted approval, Amazon shall provide ProdCo ninety (90) days'' notice and shall reimburse ProdCo for any non-recoverable costs incurred in reliance on such approval.', ARRAY['requires approval','revokes','ninety days notice','reimburse','non-recoverable costs','reliance']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Revocation limitations", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Extended notice period and reimbursement for revocation significantly limits Amazon''s ability to protect its marks. Amazon needs unfettered revocation right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s approval is required for use of Amazon trademarks. Amazon grants ProdCo a co-exclusive license to use Amazon marks in connection with the Program, and Amazon shall not license any third party to use such marks in connection with the Program without ProdCo''s consent.', ARRAY['approval required','co-exclusive license','Amazon marks','Program','not license','third party','ProdCo consent']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Co-exclusive trademark license", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Co-exclusive license with restriction on Amazon''s ability to license its own marks to others is completely unacceptable. Amazon must retain full control over its trademarks."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Prior approval required for Amazon marks. ProdCo shall have the right to create and register Program-specific marks that incorporate Amazon trademarks (e.g., ''Amazon''s [Program Title]''), with ownership of such combined marks to be jointly held by Amazon and ProdCo.', ARRAY['prior approval','right to create','register','Program-specific marks','incorporate','joint ownership','combined marks']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Joint ownership of combined marks", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Joint ownership of marks incorporating Amazon trademarks is completely unacceptable. Amazon must be sole owner of all marks featuring Amazon branding."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain in strict confidence and shall not disclose to any third party any Non-Public Information (''NPI'') of Amazon, including without limitation the terms of this Agreement, information about the Program, Amazon''s business plans, strategies, financial information, technology, and any other information designated as confidential by Amazon.', ARRAY['strict confidence','not disclose','third party','NPI','Non-Public Information','terms of Agreement','Program','business plans','strategies','financial','technology','designated confidential']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Standard NPI obligation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive NPI protection covering Agreement terms, Program information, and business information. Designation language provides flexibility for identifying additional NPI."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All Non-Public Information disclosed by Amazon to ProdCo, or otherwise obtained by ProdCo in connection with this Agreement, shall be held in strict confidence. ProdCo shall use NPI solely for the purpose of performing its obligations hereunder and for no other purpose.', ARRAY['Non-Public Information','disclosed','obtained','strict confidence','use solely','performing obligations','no other purpose']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Use limitation included", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes both confidentiality and use limitation, ensuring NPI is protected and used only for Agreement purposes. Essential dual protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges that the existence and terms of this Agreement, all information relating to the Program (including scripts, treatments, casting, creative elements, release plans and marketing strategies), and all Amazon business information constitute NPI. ProdCo shall protect such NPI using at least the same degree of care it uses to protect its own confidential information, but in no event less than reasonable care.', ARRAY['existence terms Agreement','Program information','scripts','treatments','casting','creative','release plans','marketing','business information','NPI','same degree of care','reasonable care']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Enumerated NPI with care standard", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific categories of NPI and establishes care standard with reasonable care floor. Comprehensive and clear."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall keep confidential all NPI and shall not, without Amazon''s prior written consent, disclose NPI to any person or entity, or use NPI for any purpose other than as expressly authorized by this Agreement. This obligation shall survive termination or expiration of this Agreement indefinitely.', ARRAY['keep confidential','NPI','prior written consent','not disclose','any person entity','not use','except authorized','survive termination','indefinitely']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Indefinite survival", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Indefinite survival of confidentiality obligation ensures protection extends beyond Agreement term. Standard and appropriate for entertainment industry NPI."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall treat as strictly confidential all NPI, including any information that Amazon identifies as confidential or that ProdCo should reasonably understand to be confidential given its nature or the circumstances of disclosure. ProdCo shall implement appropriate administrative, technical and physical safeguards to protect NPI.', ARRAY['strictly confidential','NPI','identifies as confidential','reasonably understand','nature','circumstances','administrative','technical','physical safeguards']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Includes safeguards requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes objective ''reasonably understand'' standard and requires implementation of safeguards, providing robust protection mechanism."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of all NPI and shall be responsible for any breach of this confidentiality obligation by its employees, contractors, agents or representatives. ProdCo shall ensure that all such persons are bound by confidentiality obligations no less protective than those set forth herein.', ARRAY['maintain confidentiality','NPI','responsible','breach','employees','contractors','agents','representatives','bound by','no less protective']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Extends to ProdCo personnel", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Makes ProdCo responsible for personnel breaches and requires binding personnel to equivalent confidentiality obligations. Essential for practical enforcement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All NPI shall be and remain the exclusive property of Amazon. ProdCo''s confidentiality obligations hereunder shall apply to all NPI regardless of the form in which it is disclosed (oral, written, electronic or otherwise) and regardless of whether it is marked or identified as confidential at the time of disclosure.', ARRAY['NPI','exclusive property','Amazon','confidentiality obligations','regardless of form','oral','written','electronic','regardless','marked','identified']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Form-agnostic protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Protects NPI regardless of disclosure form and without requiring marking, eliminating potential loopholes based on formalities."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of all NPI. Notwithstanding the foregoing, information shall not be considered NPI to the extent it: (a) is or becomes publicly available through no fault of ProdCo; (b) was rightfully in ProdCo''s possession prior to disclosure; or (c) is independently developed by ProdCo without use of NPI.', ARRAY['maintain confidentiality','NPI','notwithstanding','not considered NPI','publicly available','no fault','prior possession','independently developed','without use']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Standard confidentiality exceptions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard confidentiality exceptions (public domain, prior possession, independent development) are industry-standard and generally acceptable. Legal should confirm formulation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall keep all NPI strictly confidential. For purposes of this Agreement, ''NPI'' means information that is (a) designated as confidential by Amazon in writing, or (b) would reasonably be understood to be confidential given its nature, excluding information that is publicly available or independently known to ProdCo.', ARRAY['strictly confidential','NPI means','designated','writing','reasonably understood','nature','excluding','publicly available','independently known']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "NPI definition with exclusions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Written designation requirement for some NPI may be acceptable if paired with ''reasonably understood'' standard. Legal should confirm public availability exclusion is properly scoped."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI for a period of five (5) years following disclosure. After such period, ProdCo''s confidentiality obligations shall terminate except with respect to trade secrets, which shall remain confidential indefinitely.', ARRAY['maintain confidentiality','NPI','five years','following disclosure','terminate','except','trade secrets','indefinitely']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Time-limited confidentiality with trade secret carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Five-year term with trade secret exception may be acceptable for general business information but Legal should confirm Program-related NPI is protected (ideally indefinitely)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall protect NPI with at least the same level of care it applies to its own confidential information. Upon Amazon''s request, ProdCo shall provide reasonable evidence of its confidentiality safeguards, including security policies and access controls.', ARRAY['protect NPI','same level of care','own confidential information','upon request','reasonable evidence','safeguards','security policies','access controls']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Evidence of safeguards upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Right to request evidence of safeguards is helpful for Amazon but may be viewed as additional burden by ProdCo. Requires Legal confirmation this is mutual benefit."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI. In the event of any actual or suspected breach of this confidentiality obligation, ProdCo shall immediately notify Amazon in writing and cooperate fully with Amazon''s investigation and remediation efforts.', ARRAY['maintain confidentiality','NPI','actual','suspected breach','immediately notify','writing','cooperate','investigation','remediation']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Breach notification and cooperation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Breach notification and cooperation requirements strengthen Amazon''s ability to respond to confidentiality incidents. Standard data protection practice."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party shall maintain the confidentiality of the other party''s confidential information. Amazon''s NPI includes Agreement terms, Program information, and business information. ProdCo''s confidential information includes its personnel information and proprietary production methodologies.', ARRAY['each party','other party''s','confidential information','Amazon NPI','Agreement','Program','business','ProdCo confidential','personnel','production methodologies']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Mutual confidentiality", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual confidentiality is commonly requested by ProdCo. Acceptable if scope of Amazon''s obligations is limited and doesn''t restrict Amazon''s use of Materials or Program information."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI that is disclosed in writing and marked ''CONFIDENTIAL'' at the time of disclosure. Oral disclosures shall not be considered NPI unless confirmed in writing within thirty (30) days.', ARRAY['maintain confidentiality','NPI','disclosed in writing','marked CONFIDENTIAL','oral disclosures','not NPI','confirmed in writing','thirty days']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Marking and confirmation requirements", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Requiring written marking and confirmation creates significant gaps in protection. Program discussions, creative conversations, and business meetings generate NPI that may not be formally documented."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use reasonable efforts to maintain the confidentiality of NPI. ProdCo shall not be liable for any disclosure of NPI that occurs despite ProdCo''s reasonable efforts to prevent such disclosure.', ARRAY['reasonable efforts','maintain confidentiality','NPI','not liable','disclosure','despite reasonable efforts']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Reasonable efforts with liability cap", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' with liability exclusion for failed efforts essentially eliminates accountability for NPI breaches. ProdCo must be strictly liable for breaches regardless of effort."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI for a period of one (1) year following the initial release of the Program. After such date, all NPI shall be deemed non-confidential.', ARRAY['maintain confidentiality','NPI','one year','initial release','deemed non-confidential']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "One-year post-release limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "One-year post-release confidentiality is wholly inadequate. Business strategies, financial terms, and future plans remain sensitive indefinitely. This limitation is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI, except that ProdCo may disclose NPI to potential investors, lenders, or acquirers in connection with financing or sale transactions involving ProdCo, provided such recipients agree to keep the information confidential.', ARRAY['maintain confidentiality','NPI','except','disclose','investors','lenders','acquirers','financing','sale transactions','recipients','confidential']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "M&A and financing carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Broad carveout for investors, lenders, and acquirers without Amazon approval creates uncontrolled disclosure risk. Amazon NPI could be shared with competitors or leaked through transaction processes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI. Notwithstanding the foregoing, the financial terms of this Agreement shall not be considered NPI and may be disclosed by ProdCo to third parties.', ARRAY['maintain confidentiality','NPI','notwithstanding','financial terms','not NPI','may be disclosed','third parties']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Financial terms excluded from NPI", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding financial terms from NPI allows ProdCo to disclose deal terms publicly or to competitors. Financial terms are core NPI that must be protected."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The parties shall maintain the confidentiality of each other''s NPI on a mutual and equivalent basis. Neither party shall have greater confidentiality obligations than the other, and any confidentiality protection afforded to Amazon''s NPI shall equally apply to ProdCo''s confidential information.', ARRAY['mutual','equivalent basis','neither party','greater obligations','confidentiality protection','equally apply']::text[], '{"doc": "Counterparty_Proposal", "section": "Confidentiality", "note": "Forced mutuality and equivalence", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Forced equivalence ignores asymmetry of information flows. Amazon discloses far more valuable NPI than ProdCo. Mutual obligations are acceptable but cannot be forced to equivalence."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI. In the event of any breach of confidentiality by ProdCo, Amazon''s sole remedy shall be injunctive relief, and ProdCo shall not be liable for any monetary damages resulting from such breach.', ARRAY['maintain confidentiality','NPI','breach','sole remedy','injunctive relief','not liable','monetary damages']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "No monetary damages for breach", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting remedies to injunctive relief only eliminates accountability for NPI breaches. Amazon must have full remedies including monetary damages for confidentiality violations."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to its employees, contractors and professional advisors who have a need to know such information for purposes of performing ProdCo''s obligations under this Agreement, provided such persons are bound by confidentiality obligations at least as protective as those set forth herein.', ARRAY['may disclose','NPI','employees','contractors','professional advisors','need to know','performing obligations','bound by','confidentiality obligations','as protective']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Standard need-to-know exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard need-to-know exception limited to persons performing Agreement obligations, with requirement for binding confidentiality. Appropriate and necessary for practical performance."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the confidentiality obligations above, ProdCo may disclose NPI to: (a) ProdCo''s employees with a bona fide need to know; (b) ProdCo''s legal counsel and accountants; and (c) contractors engaged in connection with the Program, in each case subject to binding confidentiality obligations no less restrictive than this Agreement.', ARRAY['notwithstanding','may disclose','NPI','employees','bona fide need to know','legal counsel','accountants','contractors','Program','binding confidentiality','no less restrictive']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Enumerated permitted recipients", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific categories of permitted recipients with appropriate confidentiality binding requirement. Clear and appropriately limited."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may share NPI with its affiliates, employees and contractors on a need-to-know basis for purposes of this Agreement, provided that ProdCo shall remain fully responsible for any breach of confidentiality by such persons and shall ensure they are bound by appropriate confidentiality obligations prior to any disclosure.', ARRAY['may share','NPI','affiliates','employees','contractors','need-to-know','purposes','remain responsible','breach','ensure bound','prior to disclosure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "ProdCo responsibility for recipients", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Expressly preserves ProdCo''s responsibility for recipient breaches and requires pre-disclosure binding. Strong protective language within permitted disclosure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to cast, crew and production personnel as necessary for production of the Program, provided such persons execute confidentiality agreements in a form approved by Amazon or containing terms substantially similar to those in Amazon''s standard confidentiality agreement.', ARRAY['may disclose','NPI','cast','crew','production personnel','necessary','production','execute confidentiality agreements','approved by Amazon','substantially similar']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Production personnel with approved NDAs", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses practical need to share NPI with production personnel while requiring Amazon-approved or equivalent NDAs. Appropriate for production context."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Disclosure of NPI is permitted to ProdCo''s professional advisors (legal, accounting, tax) who are subject to professional duties of confidentiality, and to ProdCo''s employees and contractors who need the information to perform services for the Program and who have executed Amazon''s standard NDA or equivalent.', ARRAY['disclosure permitted','professional advisors','legal','accounting','tax','professional duties','employees','contractors','need information','executed NDA','equivalent']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Professional duty recognition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Recognizes that professional advisors are bound by professional duties, while still requiring executed NDAs for employees and contractors."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to permitted recipients who have a need to know, subject to confidentiality binding. For the avoidance of doubt, ''need to know'' means a genuine business need directly related to performing obligations under this Agreement, and not mere curiosity or general business interest.', ARRAY['may disclose','NPI','permitted recipients','need to know','confidentiality binding','genuine business need','directly related','performing obligations','not curiosity','general business interest']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Need-to-know definition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Defines ''need to know'' to prevent over-broad interpretation. Clarifies that casual interest doesn''t qualify, limiting disclosure scope."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Permitted disclosures to need-to-know recipients shall be limited to the minimum amount of NPI necessary for the relevant purpose. ProdCo shall not disclose the complete Agreement or comprehensive Program information when a summary or excerpt would suffice.', ARRAY['permitted disclosures','need-to-know','limited','minimum amount','NPI','necessary','relevant purpose','not disclose','complete Agreement','summary','excerpt']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Minimum necessary principle", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Minimum necessary principle further limits disclosure even to permitted recipients. Prevents wholesale sharing when targeted disclosure would suffice."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI to its parent company and wholly-owned subsidiaries on a need-to-know basis, provided such affiliates are bound by confidentiality obligations. ProdCo shall provide Amazon with a list of affiliates to whom NPI has been disclosed upon Amazon''s reasonable request.', ARRAY['may disclose','NPI','parent company','wholly-owned subsidiaries','need-to-know','affiliates','bound','confidentiality','provide list','upon request']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Affiliate disclosure with list upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Affiliate disclosure with list-upon-request provides transparency. Legal should confirm ''wholly-owned'' limitation is maintained and parent company disclosure is acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI to its employees and contractors who need to know, provided that before any such disclosure, ProdCo shall: (a) inform such persons of the confidential nature of the NPI; (b) obtain their written agreement to protect such NPI; and (c) maintain records of such disclosures for Amazon''s audit purposes.', ARRAY['may disclose','NPI','employees','contractors','need to know','before disclosure','inform','confidential nature','written agreement','maintain records','audit purposes']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Disclosure records for audit", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Record-keeping for audit purposes provides Amazon visibility into NPI disclosures. May be helpful for compliance monitoring. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may share NPI with need-to-know recipients. In addition, ProdCo may disclose general, non-specific information about its relationship with Amazon (e.g., that ProdCo is producing a series for a major streaming platform) without identifying Amazon by name, for ProdCo''s general business development purposes.', ARRAY['may share','NPI','need-to-know','general non-specific','relationship','without identifying Amazon','business development']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Anonymized general disclosure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Anonymized general disclosure for business development may be acceptable if truly non-identifying. Legal should assess whether ''major streaming platform'' language is sufficiently anonymized in context."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI to its attorneys, accountants, and bankers in connection with legal, financial, and lending matters, provided such advisors are bound by professional duties of confidentiality or have executed appropriate NDAs, and provided further that ProdCo shall not disclose more information than reasonably necessary.', ARRAY['may disclose','NPI','attorneys','accountants','bankers','legal','financial','lending','professional duties','NDAs','not disclose more','reasonably necessary']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Bankers added to advisors", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Adding bankers for lending matters is reasonable business need but expands disclosure beyond typical professional advisors. Legal should confirm scope is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'NPI may be disclosed to guild and union representatives to the extent required by applicable collective bargaining agreements. ProdCo shall use reasonable efforts to limit such disclosures to information actually required and to obtain confidential treatment where possible.', ARRAY['NPI','disclosed','guild','union representatives','required','collective bargaining agreements','limit disclosures','actually required','confidential treatment']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Guild/union disclosure carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Guild/union disclosure may be required by CBA obligations. Limitation to required information and confidential treatment efforts provide protection. Legal should confirm CBA obligations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI to its employees and contractors on a need-to-know basis. If any such employee or contractor''s engagement terminates, ProdCo shall take reasonable steps to ensure the return or destruction of any NPI in such person''s possession.', ARRAY['may disclose','NPI','employees','contractors','need-to-know','engagement terminates','reasonable steps','return','destruction','possession']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Return/destruction on termination", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Return/destruction requirement upon personnel termination is good practice that enhances protection. Requires Legal confirmation this is operationally enforceable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to any person or entity that ProdCo reasonably believes has a need to receive such information, provided ProdCo uses reasonable efforts to bind such recipients to confidentiality.', ARRAY['may disclose','NPI','any person entity','reasonably believes','need to receive','reasonable efforts','bind','confidentiality']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Unlimited discretion on recipients", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Unlimited ProdCo discretion to determine recipients based on ''reasonable belief'' and only ''reasonable efforts'' to bind is far too broad. Amazon has no control over NPI distribution."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to its employees, contractors, advisors, affiliates, investors, prospective investors, acquirers, prospective acquirers, and business partners, in each case on a need-to-know basis and subject to confidentiality obligations.', ARRAY['may disclose','NPI','employees','contractors','advisors','affiliates','investors','prospective investors','acquirers','prospective acquirers','business partners','need-to-know','confidentiality']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Overly broad recipient list", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Including investors, prospective investors, acquirers, and ''business partners'' in permitted recipients is far too broad. M&A and investment disclosures require Amazon''s specific approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to need-to-know recipients. ProdCo shall not be required to execute confidentiality agreements with such recipients if ProdCo reasonably believes such recipients will maintain confidentiality based on the nature of their relationship with ProdCo.', ARRAY['may disclose','NPI','need-to-know','not required','confidentiality agreements','reasonably believes','maintain confidentiality','relationship']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "No binding requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating requirement to bind recipients to confidentiality based on ProdCo''s ''reasonable belief'' provides no enforceable protection. All recipients must be bound by confidentiality obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to its entire workforce on a company-wide basis, as ProdCo believes that transparency with employees enhances morale and productivity. ProdCo shall include confidentiality reminders in its employee handbook.', ARRAY['may disclose','NPI','entire workforce','company-wide','transparency','employees','morale','productivity','confidentiality reminders','handbook']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Company-wide disclosure", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Company-wide disclosure with only handbook reminders is completely unacceptable. NPI must be limited to need-to-know personnel with binding confidentiality obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may share NPI with need-to-know recipients. Any breach of confidentiality by such recipients shall be the responsibility of the recipient, not ProdCo, and Amazon shall pursue remedies directly against the breaching party.', ARRAY['may share','NPI','need-to-know','breach','responsibility of recipient','not ProdCo','pursue remedies','directly','breaching party']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "ProdCo not responsible for recipient breaches", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Releasing ProdCo from responsibility for recipient breaches eliminates accountability for NPI protection. ProdCo must remain responsible for all disclosures it makes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to co-producers, co-financiers, completion bond companies, errors and omissions insurers, and distribution partners in connection with the production and distribution of the Program, without Amazon''s prior approval.', ARRAY['may disclose','NPI','co-producers','co-financiers','completion bond','E&O insurers','distribution partners','without Amazon approval']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Industry partners without approval", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Disclosure to co-producers, financiers, and distribution partners without Amazon approval creates uncontrolled NPI dissemination. These disclosures require Amazon''s specific consent."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If ProdCo is required by law, regulation, court order or governmental authority to disclose any NPI, ProdCo shall, to the extent legally permitted, provide Amazon with prompt written notice of such requirement prior to disclosure, and shall cooperate with Amazon in seeking protective treatment for such NPI.', ARRAY['required by law','regulation','court order','governmental authority','disclose NPI','legally permitted','prompt written notice','prior to disclosure','cooperate','protective treatment']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Standard compelled disclosure provision", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard provision requiring advance notice where legally permitted and cooperation in seeking protective orders. Provides Amazon opportunity to protect NPI in legal proceedings."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If ProdCo receives a subpoena, court order, or other legal process requiring disclosure of NPI, ProdCo shall: (a) notify Amazon immediately and in any event within two (2) business days; (b) provide Amazon copies of the relevant demand; (c) cooperate with any effort by Amazon to obtain protective orders; and (d) disclose only such NPI as is legally required.', ARRAY['subpoena','court order','legal process','notify Amazon','immediately','two business days','copies of demand','cooperate','protective orders','disclose only','legally required']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Detailed compelled disclosure process", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Detailed procedural requirements including specific timing, document sharing, and minimum-disclosure principle. Comprehensive protection for compelled disclosure scenarios."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Compelled disclosure of NPI pursuant to legal process shall not constitute a breach of this Agreement, provided that ProdCo: (i) gives Amazon prompt advance notice to the extent not prohibited by law; (ii) reasonably cooperates with Amazon''s efforts to limit or prevent disclosure; and (iii) limits disclosure to what is strictly required.', ARRAY['compelled disclosure','legal process','not breach','prompt advance notice','not prohibited','reasonably cooperates','limit prevent disclosure','strictly required']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Not-a-breach framing with conditions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies compelled disclosure is not a breach while imposing protective conditions. Appropriate balance between legal compliance and NPI protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI if required by applicable law, regulation, or valid legal process. Prior to any such disclosure, ProdCo shall provide Amazon with sufficient notice to allow Amazon to seek a protective order or other appropriate remedy, and ProdCo shall cooperate fully with such efforts at Amazon''s expense.', ARRAY['may disclose','NPI','required by law','regulation','legal process','prior to disclosure','sufficient notice','protective order','appropriate remedy','cooperate fully','Amazon''s expense']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Cooperation at Amazon expense", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Places cooperation costs on Amazon, which is reasonable since Amazon is the beneficiary of protective efforts. Otherwise standard compelled disclosure language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If legally compelled to disclose NPI, ProdCo shall provide Amazon notice within twenty-four (24) hours of receiving such legal demand, unless prohibited by law. ProdCo shall assert all available privileges and protections and shall not waive any such protections without Amazon''s written consent.', ARRAY['legally compelled','disclose NPI','notice','twenty-four hours','unless prohibited','assert privileges','protections','not waive','written consent']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "24-hour notice with privilege protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Tight 24-hour notice window and requirement to assert privileges without waiver provides strong protection. Appropriate for high-sensitivity NPI."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the confidentiality obligations herein, ProdCo may disclose NPI to the extent required by law, provided that: (a) ProdCo provides Amazon maximum possible notice; (b) ProdCo limits disclosure to the minimum required; (c) ProdCo seeks confidential treatment; and (d) ProdCo coordinates with Amazon on the disclosure.', ARRAY['notwithstanding','may disclose','required by law','maximum possible notice','minimum required','confidential treatment','coordinates with Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Four-prong protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Four protective requirements (notice, minimum disclosure, confidential treatment, coordination) provide comprehensive safeguards for compelled disclosure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If ProdCo is required to disclose NPI in connection with securities filings, regulatory requirements, or governmental investigations, ProdCo shall notify Amazon promptly and shall work with Amazon to limit such disclosure and obtain confidential treatment under applicable rules.', ARRAY['required to disclose','NPI','securities filings','regulatory requirements','governmental investigations','notify promptly','work with Amazon','limit disclosure','confidential treatment']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Securities and regulatory context", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses specific securities and regulatory disclosure contexts with appropriate notice and limitation requirements."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI if required by law, regulation, or court order, provided that ProdCo gives Amazon notice as soon as reasonably practicable and cooperates with protective efforts. If ProdCo is prohibited by law from providing advance notice, ProdCo shall notify Amazon promptly after such prohibition expires.', ARRAY['may disclose','NPI','required by law','court order','notice','reasonably practicable','cooperates','prohibited','advance notice','notify after','prohibition expires']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Post-prohibition notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Post-prohibition notice requirement is reasonable addition that ensures Amazon learns of disclosure even when advance notice was prohibited. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If compelled to disclose NPI, ProdCo shall notify Amazon promptly. ProdCo shall not be required to take any action that would expose ProdCo to sanctions for contempt of court or violation of law, but shall use commercially reasonable efforts to enable Amazon to seek protective treatment.', ARRAY['compelled','disclose NPI','notify promptly','not required','contempt of court','violation of law','commercially reasonable efforts','protective treatment']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Contempt protection", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Contempt/violation protection is reasonable practical limitation. ProdCo should not be required to violate court orders. Requires Legal confirmation of scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI if legally required, with prompt notice to Amazon. If Amazon wishes to challenge the disclosure requirement, Amazon shall bear all costs and expenses of such challenge, and ProdCo shall cooperate as reasonably requested.', ARRAY['may disclose','NPI','legally required','prompt notice','Amazon challenge','bear costs expenses','ProdCo cooperate','reasonably requested']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Amazon bears challenge costs", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Placing challenge costs on Amazon is reasonable since Amazon benefits from protective efforts. Reasonable cooperation standard is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Compelled disclosures of NPI shall be permitted with prompt notice to Amazon. For disclosures required by routine securities filings (10-K, 10-Q, proxy statements), ProdCo shall notify Amazon at least ten (10) business days in advance of the filing deadline to allow review and comment.', ARRAY['compelled disclosures','NPI','prompt notice','securities filings','10-K','10-Q','proxy','ten business days','advance','filing deadline','review comment']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Securities filing advance notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Ten-day advance notice for routine securities filings provides Amazon opportunity to review and seek confidential treatment. Requires Legal confirmation this is operationally workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI as required by law. If Amazon disputes that disclosure is legally required, the parties shall promptly meet and confer. If the dispute is not resolved within three (3) business days, ProdCo may proceed with disclosure as it reasonably determines is required.', ARRAY['may disclose','NPI','required by law','Amazon disputes','meet and confer','three business days','not resolved','proceed with disclosure','reasonably determines']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Meet-and-confer with resolution timeline", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Meet-and-confer process with defined timeline provides structure for disputes. Three-day resolution period may be tight. Requires Legal assessment."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If legally compelled to disclose NPI, ProdCo shall notify Amazon and disclose only the minimum NPI required. Both parties acknowledge that applicable law may require disclosure of certain information (e.g., material contracts for SEC filings) and agree to work together in good faith to address such requirements.', ARRAY['legally compelled','disclose NPI','notify','minimum NPI','applicable law','material contracts','SEC filings','work together','good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "SEC material contract acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledges SEC material contract disclosure requirements which may be applicable. Good faith cooperation commitment is reasonable. Requires Legal confirmation of SEC treatment."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI if required by law, regulation, or legal process. ProdCo shall use reasonable efforts to notify Amazon of such disclosure but shall not be required to delay disclosure or seek protective treatment.', ARRAY['may disclose','NPI','required by law','reasonable efforts','notify','not required','delay disclosure','seek protective treatment']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "No delay or protective treatment requirement", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Eliminating requirements to delay disclosure and seek protective treatment provides no meaningful opportunity for Amazon to protect NPI. These protective measures are essential."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to the extent ProdCo reasonably believes such disclosure is required by applicable law or regulation. ProdCo shall not be required to provide advance notice to Amazon of any such disclosure.', ARRAY['may disclose','NPI','reasonably believes','required by law','not required','advance notice']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Subjective legal requirement, no notice", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Subjective ''reasonably believes'' standard without notice requirement gives ProdCo unfettered discretion to disclose NPI without any opportunity for Amazon to object or seek protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI as required by law. Notwithstanding the foregoing, if Amazon does not respond to ProdCo''s notice of compelled disclosure within forty-eight (48) hours, ProdCo may proceed with full disclosure without limitation.', ARRAY['may disclose','NPI','required by law','Amazon does not respond','forty-eight hours','full disclosure','without limitation']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Short response window, unlimited disclosure", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "48-hour response window is too short for Amazon to obtain protective orders, and ''full disclosure without limitation'' exceeds what is legally required. Both elements are problematic."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI if required by law, court order, or government request. ProdCo shall also have the right to disclose NPI if ProdCo believes in good faith that such disclosure is necessary to protect ProdCo''s legal rights or business interests.', ARRAY['may disclose','NPI','required by law','court order','government request','right to disclose','good faith','protect legal rights','business interests']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Self-help legal/business disclosure", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Adding subjective ''business interests'' exception goes far beyond compelled disclosure. ProdCo could justify almost any disclosure as protecting its interests. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If compelled to disclose NPI by legal process, ProdCo shall notify Amazon. However, if the disclosure request is from a governmental authority in connection with an investigation, ProdCo may comply immediately without notice to Amazon to avoid obstructing such investigation.', ARRAY['compelled','disclose NPI','legal process','notify','governmental authority','investigation','comply immediately','without notice','avoid obstructing']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Government investigation exception", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Blanket exception for government investigations without notice allows ProdCo to disclose NPI without any Amazon awareness. Many investigation disclosures permit notice unless explicitly prohibited."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI as required by law. For purposes of this provision, ''required by law'' includes any disclosure that ProdCo''s legal counsel advises is required or advisable to comply with applicable law or regulation.', ARRAY['may disclose','NPI','required by law','includes','legal counsel advises','required or advisable','comply']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Advisable disclosure included", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Expanding ''required by law'' to include ''advisable'' disclosures creates enormous loophole. Legal counsel could advise many disclosures as ''advisable'' that are not actually required."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not input, upload, transmit or otherwise provide any NPI, Program information, Materials, scripts, treatments, or any other confidential information into any artificial intelligence tool, machine learning system, large language model, or similar technology, whether or not such technology is publicly available, without Amazon''s prior written approval.', ARRAY['not input','upload','transmit','provide','NPI','Program information','Materials','scripts','treatments','confidential','artificial intelligence','machine learning','large language model','prior written approval']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Comprehensive AI input prohibition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive prohibition on inputting any Amazon confidential information into AI tools. Covers all forms of AI technology and requires prior written approval for any exception. Post-2023 critical provision."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo and its personnel shall not use any generative AI tool, including without limitation ChatGPT, Claude, Gemini, Midjourney, DALL-E, or any similar technology, in connection with the Program or to process any NPI, Materials, or Amazon confidential information. This prohibition applies regardless of whether the AI tool retains or trains on inputted data.', ARRAY['not use','generative AI','ChatGPT','Claude','Gemini','Midjourney','DALL-E','Program','NPI','Materials','confidential','regardless','retains','trains']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Named tools prohibition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Names specific AI tools while including catch-all. Addresses both retention and training concerns. Extends to all ProdCo personnel. Comprehensive protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Without Amazon''s prior written consent, ProdCo shall not: (a) input any NPI, Program content, or Materials into any AI system; (b) use AI tools to generate any content for the Program; (c) use AI tools to analyze, summarize, or process any Amazon information; or (d) permit any third party to perform any of the foregoing.', ARRAY['without prior consent','not input','NPI','Program content','Materials','AI system','use AI','generate content','analyze','summarize','process','permit third party']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Enumerated prohibitions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific prohibited uses including input, generation, analysis, and third-party activities. Comprehensive coverage of AI-related risks."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges that AI tools may retain, train on, or otherwise process inputted data in ways that could compromise confidentiality. ProdCo therefore agrees not to input any NPI, Materials, or Program information into any AI tool and shall include equivalent restrictions in all agreements with its personnel and contractors.', ARRAY['acknowledges','AI tools','retain','train','process','compromise confidentiality','not input','NPI','Materials','Program','equivalent restrictions','personnel','contractors']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Acknowledgment with flow-down", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes acknowledgment of AI training risks and requires flow-down to personnel and contractors. Addresses practical enforcement concerns."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The AI restriction in this Agreement applies to all forms of artificial intelligence, including generative AI, predictive AI, machine learning models, neural networks, and any successor or similar technologies. ProdCo shall not input NPI or Program information into any such technology without Amazon''s express prior authorization.', ARRAY['AI restriction','all forms','generative AI','predictive AI','machine learning','neural networks','successor','similar technologies','not input','NPI','Program','express prior authorization']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Technology-agnostic AI definition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Broad technology-agnostic definition ensures restriction covers current and future AI technologies. Prevents arguments based on narrow AI definitions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall implement reasonable technical and administrative controls to prevent unauthorized input of NPI or Program Materials into AI systems, including blocking access to public AI tools on production networks and providing training to personnel on this prohibition.', ARRAY['implement','technical','administrative controls','prevent','unauthorized input','NPI','Program Materials','AI systems','blocking access','public AI tools','training','personnel']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Controls and training requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Requires affirmative implementation of controls and training, going beyond mere prohibition to address practical compliance mechanisms."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No NPI, Materials, scripts, or Program information shall be inputted into any AI tool. This restriction survives termination of this Agreement and applies in perpetuity. ProdCo shall be strictly liable for any breach of this provision by ProdCo or any of its personnel, contractors, or agents.', ARRAY['no NPI','Materials','scripts','Program','inputted','AI tool','survives termination','perpetuity','strictly liable','breach','personnel','contractors','agents']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Perpetual restriction with strict liability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Perpetual survival appropriate given permanent nature of AI training data. Strict liability ensures accountability regardless of intent or negligence level."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not input NPI or Program Materials into any AI tool without Amazon''s prior written approval. Notwithstanding the foregoing, ProdCo may use AI tools that have been expressly approved by Amazon in writing, subject to any conditions specified in such approval.', ARRAY['not input','NPI','Program Materials','AI tool','prior written approval','notwithstanding','expressly approved','writing','conditions specified']::text[], '{"doc": "PSA_Fallbacks", "section": "AI Restrictions", "note": "Approved tools exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Allows for approved-tools exception which may be necessary for certain production workflows. Approval must be express, written, and conditional. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not input NPI or Materials into public AI tools. ProdCo may use enterprise AI solutions that are deployed on-premises or in a private cloud environment and that do not transmit data externally, provided ProdCo notifies Amazon in advance and such solutions meet Amazon''s security requirements.', ARRAY['not input','NPI','Materials','public AI tools','enterprise AI','on-premises','private cloud','do not transmit externally','notifies Amazon','advance','security requirements']::text[], '{"doc": "PSA_Fallbacks", "section": "AI Restrictions", "note": "Enterprise/private AI exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Private/enterprise AI exception with security requirements may be acceptable for sophisticated ProdCos. Requires advance notice and security compliance. Legal approval required."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not input NPI or Program Materials into any AI tool without approval. If ProdCo wishes to use AI tools for administrative purposes unrelated to Program content (e.g., scheduling, budget tracking), ProdCo shall submit a request describing the proposed use, and Amazon shall not unreasonably withhold approval.', ARRAY['not input','NPI','Program Materials','AI tool','approval','administrative purposes','unrelated to Program','scheduling','budget tracking','submit request','not unreasonably withhold']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Administrative use exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Administrative-use exception for non-content purposes may be reasonable if truly divorced from NPI. ''Not unreasonably withhold'' provides Amazon flexibility. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not input NPI, Materials, or Program content into AI tools. ProdCo shall include equivalent AI restrictions in all agreements with cast, crew, and production personnel. Upon Amazon''s request, ProdCo shall provide certification that such restrictions have been included.', ARRAY['not input','NPI','Materials','Program','AI tools','equivalent restrictions','cast','crew','production personnel','upon request','certification','included']::text[], '{"doc": "PSA_Fallbacks", "section": "AI Restrictions", "note": "Flow-down with certification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Flow-down requirement with certification mechanism ensures AI restrictions extend to all production personnel. Certification provides verification. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not use AI tools to process NPI or generate Program content. If ProdCo inadvertently inputs NPI into an AI tool, ProdCo shall immediately notify Amazon, take all available steps to delete such data from the AI system, and provide Amazon a detailed incident report within forty-eight (48) hours.', ARRAY['not use','AI tools','process NPI','generate Program content','inadvertently inputs','immediately notify','delete data','AI system','incident report','forty-eight hours']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Incident response procedure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Incident response procedure for inadvertent inputs is practical addition. Deletion and reporting requirements are appropriate. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo agrees to comply with Amazon''s AI Usage Policy as provided by Amazon from time to time. ProdCo shall not input NPI or Materials into any AI tool except as expressly permitted by such policy. ProdCo acknowledges receipt of the current version of such policy.', ARRAY['comply','Amazon''s AI Usage Policy','from time to time','not input','NPI','Materials','except as permitted','policy','acknowledges receipt','current version']::text[], '{"doc": "PSA_Fallbacks", "section": "AI Restrictions", "note": "Reference to Amazon AI policy", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Reference to Amazon policy provides flexibility to update AI restrictions as technology evolves. Policy acknowledgment creates compliance baseline. Requires Legal review of policy terms."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use reasonable efforts to prevent input of NPI into public AI tools. ProdCo shall not be liable for any inadvertent or unauthorized input of NPI into AI systems by its employees or contractors.', ARRAY['reasonable efforts','prevent input','NPI','public AI tools','not liable','inadvertent','unauthorized','employees','contractors']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Reasonable efforts with liability exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' standard with liability exclusion for employee/contractor actions is completely inadequate. ProdCo must be strictly liable for all AI input regardless of intent."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not input NPI into public AI tools. ProdCo may use AI tools for creative development of the Program, including script drafting, character development, and plot analysis, provided any AI-generated content is reviewed and modified by human personnel before use.', ARRAY['not input','NPI','public AI tools','may use','creative development','script drafting','character development','plot analysis','AI-generated content','reviewed','modified','human']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Creative development AI exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Allowing AI for creative development (scripts, characters, plots) creates massive content and ownership risks. AI-generated content raises fundamental copyright and originality issues. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not input NPI into AI tools that are known to retain or train on user data. ProdCo may use AI tools that contractually commit not to retain or use inputted data for training purposes.', ARRAY['not input','NPI','AI tools','known to retain','train on user data','may use','contractually commit','not retain','not use','training']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Non-training AI exception", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Distinction based on AI training practices is difficult to verify and evolves constantly. Contractual commitments by AI providers may not be enforceable or reliable. Creates unacceptable compliance uncertainty."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The AI restriction herein shall apply only during principal photography and post-production. After delivery of the Program, ProdCo shall be free to use AI tools to analyze and discuss the Program for portfolio, educational, and marketing purposes.', ARRAY['AI restriction','only during','principal photography','post-production','after delivery','free to use','AI tools','analyze','discuss','portfolio','educational','marketing']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Time-limited restriction", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Time-limited AI restriction fails to protect NPI and Materials in perpetuity. Post-delivery AI use for ''portfolio'' and ''marketing'' could expose Program content and trade secrets permanently."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not input NPI into AI tools. Notwithstanding the foregoing, this restriction shall not apply to AI tools that are industry-standard in the entertainment production sector, as ProdCo determines in good faith.', ARRAY['not input','NPI','AI tools','notwithstanding','not apply','industry-standard','entertainment production','ProdCo determines','good faith']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Industry-standard exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo discretion to determine ''industry-standard'' AI tools eliminates meaningful restriction. The entertainment industry is rapidly adopting AI tools, making this exception effectively unlimited."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon acknowledges that AI tools are increasingly essential to modern production workflows. ProdCo may use AI tools as it deems appropriate in its professional judgment, provided ProdCo takes reasonable precautions to protect NPI confidentiality.', ARRAY['acknowledges','AI tools','essential','modern production','may use','deems appropriate','professional judgment','reasonable precautions','protect NPI']::text[], '{"doc": "Counterparty_Proposal", "section": "AI Restrictions", "note": "ProdCo discretion with precautions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Complete ProdCo discretion with only ''reasonable precautions'' provides no meaningful protection. This essentially negates any AI restriction. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not input NPI or Materials into AI tools without Amazon''s approval. Amazon shall approve or deny any such request within five (5) business days; failure to respond shall constitute approval. Amazon shall not unreasonably withhold approval for commonly-used AI productivity tools.', ARRAY['not input','NPI','Materials','AI tools','approval','approve or deny','five business days','failure to respond','constitute approval','not unreasonably withhold','productivity tools']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Deemed approval and reasonableness standard", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deemed approval on non-response and ''not unreasonably withhold'' standard eliminate Amazon''s ability to control AI use. Given irreversible nature of AI training, Amazon must have absolute discretion."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and all Materials are and shall be wholly original with ProdCo and its personnel, are fully protected by copyright under applicable law, and do not and shall not infringe upon or violate any copyright, trademark, patent or other intellectual property right of any third party.', ARRAY['represents warrants','Program','Materials','wholly original','ProdCo','personnel','fully protected','copyright','applicable law','not infringe','violate','intellectual property','third party']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Standard originality and copyright representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard unqualified representation of originality and copyright protection. Covers Program and Materials with appropriate breadth. No knowledge qualifiers that would weaken the representation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that: (a) all literary, dramatic, musical and artistic elements of the Program are original works of authorship created by ProdCo or its employees and contractors; (b) all such works are protected by copyright; and (c) ProdCo has the full right and authority to grant all rights contemplated herein.', ARRAY['represents warrants','literary','dramatic','musical','artistic','original works','authorship','created by ProdCo','employees','contractors','protected by copyright','full right','authority','grant rights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Enumerated elements with authority representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific types of copyrightable elements and includes authority representation. Comprehensive coverage of creative elements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials are original and were independently created without copying or derivation from any pre-existing work not owned or fully licensed by ProdCo. All copyrightable elements of the Program shall be entitled to full copyright protection under the laws of the United States and all other applicable jurisdictions.', ARRAY['represents warrants','Program','Materials','original','independently created','without copying','derivation','pre-existing work','owned','licensed','copyrightable elements','full copyright protection','United States','jurisdictions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Independent creation with multi-jurisdiction protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Emphasizes independent creation and addresses pre-existing works carveout for owned/licensed materials. Multi-jurisdiction copyright protection representation is appropriate for global exploitation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that all elements of the Program, including without limitation the screenplay, teleplay, dialogue, characters, storylines, music, and visual elements, are original creations fully protected by copyright, and that ProdCo owns or controls all rights necessary for Amazon''s exploitation of the Program as contemplated herein.', ARRAY['represents warrants','elements','Program','screenplay','teleplay','dialogue','characters','storylines','music','visual elements','original','copyright','ProdCo owns','controls','rights','exploitation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Detailed enumeration of Program elements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Detailed enumeration of specific Program elements covered by originality representation. Includes both creation and rights control aspects."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that: (i) the Program and all Materials constitute original works of authorship; (ii) the Program and Materials are copyrightable under the Copyright Act of 1976, as amended; (iii) no portion of the Program or Materials is in the public domain; and (iv) no AI-generated content is included in the Program or Materials.', ARRAY['represents warrants','original works','authorship','copyrightable','Copyright Act 1976','no public domain','no AI-generated content']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Includes AI-generated content representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes important post-2023 representation regarding AI-generated content, addressing copyrightability concerns. Public domain exclusion protects against unprotectable elements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program is an original audiovisual work created by human authors and is entitled to full copyright protection. ProdCo further represents that all creative contributions to the Program were made by natural persons and not by artificial intelligence or machine learning systems.', ARRAY['represents warrants','original audiovisual work','human authors','full copyright protection','creative contributions','natural persons','not artificial intelligence','machine learning']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Human authorship representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit human authorship representation addresses US Copyright Office position that AI-generated works lack human authorship for copyright purposes. Critical for protecting Program copyrightability."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Programme and all Materials are original works fully protected by copyright under the Copyright, Designs and Patents Act 1988 and all applicable international copyright conventions. ProdCo has caused all necessary assignments and waivers to be executed to vest full copyright ownership in Amazon.', ARRAY['represents warrants','Programme','Materials','original','copyright','CDPA 1988','international conventions','assignments','waivers','vest','ownership','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "UK-specific copyright representation", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate reference to CDPA 1988 and international conventions. Includes representation regarding assignments and waivers necessary for UK copyright vesting."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials are original and copyrightable, except for any third-party materials that have been cleared for use in the Program pursuant to licenses listed in Exhibit C, which licenses grant rights sufficient for Amazon''s contemplated exploitation.', ARRAY['represents warrants','original','copyrightable','except','third-party materials','cleared','licenses','Exhibit C','sufficient','exploitation']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Exception for scheduled licensed materials", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Exception for Exhibit C licensed materials is reasonable if Exhibit C is properly reviewed. Legal must verify that scheduled licenses provide sufficient rights for exploitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program is original and protected by copyright. Notwithstanding the foregoing, this representation shall not apply to any stock footage, music, or visual effects elements sourced from third-party libraries, which ProdCo represents have been properly licensed for use in the Program.', ARRAY['represents warrants','original','copyright','notwithstanding','not apply','stock footage','music','visual effects','third-party libraries','properly licensed']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Stock and library material carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for stock and library materials with licensing representation is practical for productions using licensed elements. Legal should verify licensing is adequate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials are original works protected by copyright. ProdCo shall provide Amazon with a complete chain of title package evidencing all rights, and Amazon''s acceptance of such package shall not diminish ProdCo''s representations hereunder.', ARRAY['represents warrants','original','copyright','chain of title package','evidencing','rights','acceptance','not diminish','representations']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Chain of title delivery with preservation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Chain of title delivery obligation is standard. Clarification that Amazon''s acceptance doesn''t diminish representations preserves Amazon''s recourse. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program is original and copyrightable. This representation is made as of the Effective Date and as of the date of final delivery of the Program to Amazon, but does not extend to any period thereafter.', ARRAY['represents warrants','original','copyrightable','as of Effective Date','as of final delivery','does not extend','thereafter']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Time-limited representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Time-limited representation through delivery may be acceptable as originality is primarily a creation-time issue. Legal should assess whether post-delivery limitation creates gap."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials are original and protected by copyright. In the event any third party asserts a claim challenging the originality of any Program element, ProdCo shall immediately notify Amazon and cooperate fully in the defense of such claim.', ARRAY['represents warrants','original','copyright','third party','asserts claim','challenging originality','immediately notify','cooperate','defense']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Claim notification and cooperation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notification and cooperation obligations enhance Amazon''s ability to respond to claims. These are reasonable procedural additions that don''t weaken the substantive representation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program is original, copyrightable, and was created without the use of generative AI tools for substantive creative content. For clarity, this prohibition does not apply to AI-assisted tools used solely for administrative or technical purposes (e.g., scheduling, color correction presets).', ARRAY['represents warrants','original','copyrightable','without','generative AI','substantive creative','prohibition','not apply','AI-assisted','administrative','technical']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "AI carveout for administrative/technical", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Distinction between creative AI (prohibited) and administrative/technical AI may be reasonable. Legal should define boundary precisely and confirm examples are appropriately narrow."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'To the best of ProdCo''s knowledge, the Program and Materials are original and protected by copyright. ProdCo has not received any notice of any claim challenging the originality of the Program.', ARRAY['to the best of knowledge','Program','Materials','original','copyright','not received notice','claim','challenging originality']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Knowledge qualifier on originality", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Knowledge qualifier on originality representation is completely unacceptable. ProdCo creates the content and must warrant originality absolutely, not merely to its knowledge."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program is believed to be original but makes no warranty regarding copyright protection or the absence of infringement claims. Amazon acknowledges that content creation involves inherent risks of inadvertent similarity to existing works.', ARRAY['represents','believed to be original','no warranty','copyright protection','absence of claims','acknowledges','inherent risks','inadvertent similarity']::text[], '{"doc": "Counterparty_Proposal", "section": "Representations and Warranties", "note": "Disclaimer of originality warranty", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Disclaiming warranty on originality and copyright shifts all creation risk to Amazon. Acknowledgment of ''inherent risks'' undermines entire chain of title protection. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program is original and copyrightable, provided that this representation shall not apply to any element that ProdCo in good faith believed was in the public domain or otherwise available for use.', ARRAY['represents','original','copyrightable','provided','not apply','good faith believed','public domain','available for use']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Good faith belief exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Good faith belief exception allows ProdCo to avoid representation based on subjective belief. Public domain determinations require proper clearance, not good faith assumptions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that, except as disclosed in the attached Schedule of Known Issues, the Program is original and protected by copyright. Amazon has reviewed the Schedule of Known Issues and accepts the risks identified therein.', ARRAY['represents warrants','except as disclosed','Schedule of Known Issues','original','copyright','reviewed','accepts risks']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Carveout for known issues", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Open-ended carveout for ''Known Issues'' schedule could exclude significant problems. Amazon cannot ''accept risks'' of undisclosed scope. Issues must be resolved, not scheduled."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program is substantially original. Minor similarities to existing works that do not constitute actionable infringement shall not be deemed a breach of this representation.', ARRAY['represents','substantially original','minor similarities','existing works','not actionable infringement','not deemed breach']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Substantial originality with similarities carveout", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Substantially original'' with carveout for ''minor similarities'' waters down the representation. Determining what is ''minor'' or ''actionable'' creates litigation risk."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program is original to the extent practicable given industry realities. ProdCo acknowledges that certain genre conventions, stock characters, and common plot elements may appear in multiple works and do not constitute lack of originality.', ARRAY['represents','original','to the extent practicable','industry realities','genre conventions','stock characters','common plot elements','not constitute','lack of originality']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Industry realities qualification", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''To the extent practicable'' qualification and broad carveouts for genre conventions significantly weaken originality representation. Creates ambiguity that could excuse infringement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program is original. This representation shall survive for a period of three (3) years following delivery, after which it shall expire and be of no further force or effect.', ARRAY['represents','original','survive','three years','following delivery','expire','no further force effect']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Three-year survival limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Three-year survival limit on originality representation is completely inadequate given perpetual exploitation. Originality claims can surface decades after release. Must survive indefinitely."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials do not and shall not: (a) infringe any copyright, trademark, patent or other intellectual property right; (b) violate any right of privacy or publicity; (c) constitute defamation, libel or slander; or (d) violate any other right of any third party.', ARRAY['represents warrants','Program','Materials','not infringe','copyright','trademark','patent','intellectual property','privacy','publicity','defamation','libel','slander','violate','third party']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Comprehensive non-infringement representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive representation covering IP infringement, privacy/publicity, and defamation. Catch-all for other third-party rights provides complete coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that neither the Program nor any Materials infringe, violate or misappropriate any intellectual property rights, rights of privacy, rights of publicity, moral rights, or any contractual or other rights of any person or entity anywhere in the world.', ARRAY['represents warrants','Program','Materials','not infringe','violate','misappropriate','intellectual property','privacy','publicity','moral rights','contractual rights','anywhere in world']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Worldwide scope with misappropriation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes misappropriation (relevant for trade secrets and right of publicity in some states) and worldwide scope. Comprehensive protection for global exploitation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that: (i) the Program does not defame any person; (ii) the Program does not invade any person''s right of privacy or publicity; (iii) the Program does not infringe any copyright, trademark or other intellectual property right; and (iv) ProdCo has obtained all necessary consents, releases and clearances from any living person depicted or referred to in the Program.', ARRAY['represents warrants','not defame','not invade','privacy','publicity','not infringe','copyright','trademark','intellectual property','obtained','consents','releases','clearances','living person','depicted','referred to']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Includes consent/release representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes representation regarding obtaining consents and releases from depicted persons, addressing practical clearance requirements for documentaries and biopics."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not contain any material that is defamatory, libelous, slanderous, obscene, or that violates any right of privacy, right of publicity, or any other personal or proprietary right of any third party. This representation extends to all territories in which Amazon may exploit the Program.', ARRAY['represents warrants','Program','not contain','defamatory','libelous','slanderous','obscene','privacy','publicity','personal','proprietary','third party','all territories','exploit']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Territorial scope with obscenity", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes obscenity in addition to standard claims and explicitly extends to all exploitation territories. Comprehensive territorial coverage is essential for global streaming."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that neither the development, production, nor exploitation of the Program will infringe any third-party rights, including copyrights, trademarks, trade secrets, rights of privacy, rights of publicity, moral rights, or any contractual rights, and will not result in defamation of any person or entity.', ARRAY['represents warrants','development','production','exploitation','not infringe','third-party rights','copyrights','trademarks','trade secrets','privacy','publicity','moral rights','contractual','defamation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Covers development through exploitation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers entire lifecycle from development through exploitation, ensuring representation applies to all phases. Includes trade secrets which is important for format and idea protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any rights and does not contain any material that is false, misleading, defamatory or that invades any right of privacy or publicity. ProdCo has conducted appropriate legal review of the Program for defamation and privacy concerns and has addressed all issues identified in such review.', ARRAY['represents warrants','not infringe','not contain','false','misleading','defamatory','privacy','publicity','legal review','defamation','privacy concerns','addressed issues']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Legal review representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes representation regarding legal review (script clearance) and issue resolution. Important for documentary or fact-based content where defamation risk is elevated."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any intellectual property rights or violate any privacy, publicity, or defamation laws of any jurisdiction. Without limiting the foregoing, ProdCo represents that it has obtained valid written releases from all recognizable persons appearing in the Program.', ARRAY['represents warrants','not infringe','intellectual property','not violate','privacy','publicity','defamation','any jurisdiction','valid written releases','recognizable persons','appearing']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Written releases for appearing persons", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Requires valid written releases from all recognizable persons, providing documented protection against privacy and publicity claims from on-screen talent."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any rights or constitute defamation. Notwithstanding the foregoing, ProdCo does not represent or warrant that the Program will not be the subject of claims; ProdCo represents only that any such claims would be without merit.', ARRAY['represents warrants','not infringe','defamation','notwithstanding','not represent','not be subject of claims','claims without merit']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "No claim-free representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Distinction between meritless claims and no-claims is technically accurate but may create interpretive issues. Legal should assess whether this affects indemnity coverage."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any rights. With respect to documentary content, ProdCo represents that it has conducted standard script clearance review and has implemented recommendations of clearance counsel, but acknowledges that documentary content inherently carries elevated clearance risk.', ARRAY['represents warrants','not infringe','documentary content','script clearance review','implemented recommendations','clearance counsel','acknowledges','elevated clearance risk']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Documentary clearance acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Documentary-specific acknowledgment of elevated risk may be acceptable if combined with clearance process representation. Legal should confirm indemnity remains fully applicable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe or violate any third-party rights. This representation is made subject to the E&O Insurance Coverage Exclusions set forth in Exhibit E, which Amazon has reviewed and accepted.', ARRAY['represents warrants','not infringe','violate','third-party rights','subject to','E&O Insurance','Coverage Exclusions','Exhibit E','reviewed','accepted']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "E&O exclusions incorporated", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Incorporating E&O exclusions may be acceptable if Amazon has actually reviewed and accepted specific exclusions. Legal must confirm Exhibit E contents are appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any intellectual property right or constitute defamation, libel, slander, or invasion of privacy. If the Program is based on or inspired by true events, ProdCo has taken reasonable steps to verify factual accuracy and to fictionalize appropriately.', ARRAY['represents warrants','not infringe','intellectual property','defamation','libel','slander','invasion of privacy','based on true events','reasonable steps','verify accuracy','fictionalize']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "True events verification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Reasonable steps for true-events content is pragmatic acknowledgment of fact-based production realities. Legal should confirm this doesn''t weaken substantive representation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any third-party rights, defame any person, or violate any privacy or publicity right. ProdCo shall maintain errors and omissions insurance with coverage of not less than $3,000,000 per occurrence covering claims arising from the Program.', ARRAY['represents warrants','not infringe','defame','privacy','publicity','E&O insurance','$3,000,000','per occurrence','claims','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "E&O insurance requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "E&O insurance requirement provides additional protection layer. $3M per occurrence is reasonable minimum. Legal should confirm coverage terms are adequate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents that the Program does not infringe any rights or violate defamation laws. With respect to any real persons referenced in the Program, ProdCo has obtained appropriate life story rights, name and likeness rights, and releases as required under applicable law.', ARRAY['represents','not infringe','defamation','real persons','referenced','life story rights','name and likeness','releases','applicable law']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Life story rights representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Life story rights representation is appropriate for biographical content. ''As required under applicable law'' provides some flexibility. Legal should confirm for specific production."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'To the best of ProdCo''s knowledge, after reasonable inquiry, the Program does not infringe any copyright or trademark, defame any person, or violate any right of privacy or publicity.', ARRAY['to the best of knowledge','reasonable inquiry','not infringe','copyright','trademark','defame','privacy','publicity']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Knowledge qualifier on non-infringement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Knowledge qualifier on non-infringement representation is fundamentally unacceptable. ProdCo creates the content and must warrant non-infringement absolutely, not merely based on its knowledge or inquiry."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program does not, to ProdCo''s knowledge, infringe any intellectual property rights or defame any living person. ProdCo makes no representation regarding deceased persons or regarding rights under laws of jurisdictions outside the United States.', ARRAY['represents','to knowledge','not infringe','intellectual property','defame','living person','no representation','deceased persons','outside United States']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Knowledge qualifier with deceased/foreign carveouts", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Knowledge qualifier combined with exclusion of deceased persons and foreign jurisdictions creates massive gaps. Deceased persons'' estates have rights; international exploitation requires worldwide protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program does not infringe any rights. However, given the creative nature of content production, ProdCo cannot guarantee that no third party will ever assert a claim, and Amazon agrees to share equally in the defense costs of any such claim.', ARRAY['represents','not infringe','creative nature','cannot guarantee','no claim','Amazon','share equally','defense costs']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Shared defense costs", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring Amazon to share defense costs for claims arising from ProdCo''s content inverts the indemnity structure. ProdCo must bear full defense costs for its representations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program does not infringe any rights, except that this representation shall not apply to any claim based on (i) matters of public record, (ii) statements of opinion, or (iii) fair use or fair dealing.', ARRAY['represents','not infringe','except','not apply','public record','statements of opinion','fair use','fair dealing']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Broad exceptions to representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exceptions for public record, opinion, and fair use are legal defenses that should be asserted, not carveouts from the representation. These exceptions could justify almost any infringement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program does not infringe any intellectual property rights. ProdCo does not represent or warrant that the Program does not defame any person, as defamation is a matter of legal interpretation and factual analysis that ProdCo cannot definitively determine.', ARRAY['represents','not infringe','intellectual property','does not represent','warrant','defame','legal interpretation','factual analysis','cannot determine']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Defamation representation excluded", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding defamation from the representation creates enormous exposure for fact-based or commentary content. ProdCo must warrant against defamation regardless of interpretive challenges."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program does not infringe any rights. Any claim asserted more than two (2) years after initial release of the Program shall be deemed waived for purposes of this representation, and ProdCo shall have no liability for such late-arising claims.', ARRAY['represents','not infringe','claim','two years','initial release','deemed waived','no liability','late-arising claims']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Two-year claim cutoff", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Two-year claim cutoff is completely inadequate. Infringement and defamation claims can surface years after release and may have longer statutes of limitation. Must survive indefinitely."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and all Materials are free and clear of any and all liens, claims, encumbrances, restrictions, or rights of any third party, and that no third party has any right, title, interest, claim or lien in or to the Program or Materials.', ARRAY['represents warrants','Program','Materials','free and clear','liens','claims','encumbrances','restrictions','rights','third party','no right','title','interest','lien']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Standard no-encumbrance representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard unqualified representation that Program and Materials are unencumbered. Essential for ensuring Amazon receives clean chain of title without third-party claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that: (a) ProdCo has full right and authority to enter into this Agreement and grant all rights herein; (b) no third party has any right, title, interest or claim in or to the Program or Materials; (c) the Program and Materials are not subject to any lien, charge, security interest or encumbrance; and (d) ProdCo has not granted and will not grant any rights inconsistent with the rights granted to Amazon.', ARRAY['represents warrants','full right','authority','enter into','grant rights','no third party','right title interest claim','not subject to','lien','charge','security interest','encumbrance','not granted','inconsistent rights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Comprehensive authority and encumbrance representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive representation covering authority, third-party claims, encumbrances, and inconsistent grants. Essential protection against competing claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the rights granted hereunder are free of any adverse claim, lien, or encumbrance. No person or entity other than Amazon has or shall have any right to exploit the Program in any manner or to receive any proceeds from such exploitation.', ARRAY['represents warrants','rights granted','free of','adverse claim','lien','encumbrance','no person entity','other than Amazon','right to exploit','receive proceeds']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Exploitation and proceeds protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses both exploitation rights and proceeds, protecting against revenue claims from third parties. Important for clean ownership."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that no option, first-look, first-negotiation, or other preferential right has been granted to any third party with respect to the Program, the underlying rights, or any sequel, prequel, spinoff, or derivative thereof. ProdCo has the unencumbered right to grant Amazon all rights contemplated herein.', ARRAY['represents warrants','no option','first-look','first-negotiation','preferential right','third party','Program','underlying rights','sequel','prequel','spinoff','derivative','unencumbered','grant','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "No preferential rights", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specifically addresses preferential rights (options, first-looks) which could encumber sequel/derivative rights. Essential for franchise protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and Materials are not subject to any agreement, commitment, or understanding with any third party that would in any way restrict, limit, or impair Amazon''s rights hereunder or Amazon''s ability to fully exploit the Program throughout the universe in perpetuity.', ARRAY['represents warrants','Program','Materials','not subject to','agreement','commitment','understanding','third party','restrict','limit','impair','Amazon''s rights','exploit','universe','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "No restrictive agreements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses any form of restrictive agreement, not just formal encumbrances. Protects Amazon against informal commitments that could impair exploitation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that it has not assigned, pledged, hypothecated, or otherwise encumbered any rights in the Program or Materials, and that it shall not do so during the term of this Agreement or at any time thereafter. Any purported assignment or encumbrance in violation of this provision shall be void.', ARRAY['represents warrants','not assigned','pledged','hypothecated','encumbered','rights','Program','Materials','shall not','purported','void']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Anti-encumbrance with void provision", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes forward-looking covenant and void provision for violations. Provides strong protection against future encumbrances."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program and all underlying rights are free from all defects in chain of title. ProdCo has valid and complete documentation evidencing ProdCo''s ownership or control of all necessary rights, which documentation shall be delivered to Amazon upon request.', ARRAY['represents warrants','Program','underlying rights','free from','defects','chain of title','valid','complete documentation','ownership','control','delivered','upon request']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Chain of title documentation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Representation regarding complete chain of title documentation with delivery requirement enables Amazon verification of clean title."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents and warrants that the Program is free and clear of all encumbrances, except for customary guild and union residual obligations which are standard in the industry and do not affect Amazon''s exploitation rights.', ARRAY['represents warrants','Program','free and clear','encumbrances','except','guild','union','residual obligations','industry standard','not affect','exploitation rights']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Guild residuals carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Guild residual carveout is industry-standard and doesn''t affect exploitation rights. Legal should confirm residual obligations are truly standard and non-interfering."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents that the Program is free of encumbrances. The parties acknowledge that certain talent agreements may contain standard provisions regarding credit, compensation adjustments, and approval rights that are customary in the entertainment industry and have been disclosed to Amazon.', ARRAY['represents','free of encumbrances','acknowledge','talent agreements','standard provisions','credit','compensation adjustments','approval rights','customary','disclosed']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Talent agreement acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledgment of disclosed talent agreement provisions may be acceptable if disclosures are complete and provisions are truly customary. Legal must verify disclosures."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents that the Program is free of liens and encumbrances. Any contingent compensation, profit participation, or backend obligations owed to talent or other participants are set forth in Exhibit D and shall be satisfied by ProdCo without reducing or encumbering Amazon''s rights.', ARRAY['represents','free of liens','encumbrances','contingent compensation','profit participation','backend','Exhibit D','satisfied by ProdCo','without reducing','encumbering','Amazon''s rights']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Scheduled participations", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Scheduling participations in Exhibit D with ProdCo satisfaction obligation is acceptable if Exhibit D is comprehensive. Legal must review scheduled obligations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents that the Program is free of encumbrances. In the event any lien or encumbrance arises after the date hereof, ProdCo shall immediately notify Amazon and take all steps necessary to remove such lien or encumbrance at ProdCo''s sole cost and expense.', ARRAY['represents','free of encumbrances','lien','encumbrance','arises','after date','immediately notify','Amazon','remove','ProdCo''s cost','expense']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Future encumbrance removal obligation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Future encumbrance notification and removal obligation is helpful additional protection. Confirms ProdCo''s ongoing responsibility for clean title."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents the Program is free of encumbrances. With respect to underlying literary material, ProdCo has acquired all necessary rights from the author pursuant to the acquisition agreement attached as Exhibit B, which grants rights coextensive with those granted to Amazon herein.', ARRAY['represents','free of encumbrances','underlying literary material','acquired','necessary rights','author','acquisition agreement','Exhibit B','rights coextensive','granted to Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Underlying rights acquisition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Reference to scheduled acquisition agreement provides transparency. Legal must verify Exhibit B agreement actually grants coextensive rights."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents that the Program is not subject to any lien or encumbrance. If the Program is based on pre-existing intellectual property, ProdCo represents that it has obtained all necessary rights from the rights holder and shall provide Amazon with evidence of such rights upon request.', ARRAY['represents','not subject to','lien','encumbrance','pre-existing intellectual property','obtained','necessary rights','rights holder','provide evidence','upon request']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Pre-existing IP evidence requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Evidence-upon-request provision for pre-existing IP rights is appropriate verification mechanism. Legal should confirm evidence is obtained proactively."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'To ProdCo''s knowledge, after reasonable inquiry, the Program and Materials are free of liens, encumbrances, and third-party claims.', ARRAY['to knowledge','reasonable inquiry','Program','Materials','free of liens','encumbrances','third-party claims']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Knowledge qualifier on encumbrances", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Knowledge qualifier on encumbrance representation is completely unacceptable. ProdCo knows what agreements it has entered and what rights it has granted. No knowledge qualifier is appropriate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that the Program is free of material encumbrances. Minor encumbrances that do not significantly impair Amazon''s exploitation rights shall not constitute a breach of this representation.', ARRAY['represents','free of material encumbrances','minor encumbrances','do not significantly impair','exploitation rights','not constitute breach']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Materiality qualifier on encumbrances", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Material'' and ''minor'' qualifiers create ambiguity about what encumbrances are acceptable. Any encumbrance could affect Amazon''s rights and must be disclosed and addressed."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program is free of encumbrances, except for any customary industry encumbrances and except for any matters disclosed in ProdCo''s chain of title opinion, which Amazon acknowledges having received.', ARRAY['represents','free of encumbrances','except','customary industry encumbrances','except','chain of title opinion','acknowledges','received']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Chain of title opinion carveout", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Carveout for chain of title opinion issues shifts risk of disclosed defects to Amazon. Encumbrance issues identified in opinion should be resolved, not carved out."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program is currently free of encumbrances as of the Effective Date. ProdCo makes no representation regarding encumbrances that may arise after the Effective Date or during production.', ARRAY['represents','currently free','encumbrances','as of Effective Date','no representation','after Effective Date','during production']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Point-in-time only representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Point-in-time representation provides no protection against encumbrances arising during production. Representation must be continuous and cover the full term."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents the Program is free of encumbrances. However, ProdCo has entered into financing arrangements that create a security interest in ProdCo''s accounts receivable, which may include amounts payable under this Agreement. Such arrangements shall not be deemed an encumbrance on the Program itself.', ARRAY['represents','free of encumbrances','however','financing arrangements','security interest','accounts receivable','amounts payable','not deemed','encumbrance on Program']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Financing security interest carveout", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Security interest in receivables under the Agreement could create lender claims or UCC issues. While not directly on Program, creates complications that should be addressed."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that, as between ProdCo and Amazon, the Program is free of encumbrances. ProdCo''s representations hereunder are made without prejudice to any rights of third parties that may exist under applicable law.', ARRAY['represents','as between ProdCo and Amazon','free of encumbrances','without prejudice','rights of third parties','applicable law']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Limited inter-party representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''As between ProdCo and Amazon'' and ''without prejudice to third parties'' creates representation that is meaningless against actual third-party claims. Representation must be absolute."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The representations and warranties in this Section shall not apply to any materials supplied by Amazon or to any materials incorporated into the Program at Amazon''s express written direction.', ARRAY['representations warranties','not apply','materials supplied by Amazon','incorporated','Program','Amazon''s express written direction']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Standard Amazon-supplied exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard carveout for Amazon-supplied materials and Amazon-directed inclusions. Appropriate since ProdCo cannot warrant Amazon''s own materials."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations and warranties shall not apply to: (a) materials provided by Amazon for inclusion in the Program; (b) materials incorporated at Amazon''s written request or instruction; or (c) changes made by Amazon to the Program after delivery, provided that ProdCo''s representations shall continue to apply to the underlying delivered Program.', ARRAY['representations warranties','not apply','materials provided by Amazon','incorporated','written request','instruction','changes made by Amazon','after delivery','underlying delivered Program']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Post-delivery changes carveout", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes post-delivery changes by Amazon while preserving representation for underlying delivered Program. Clear allocation of responsibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the foregoing representations and warranties, ProdCo shall not be responsible for any claims arising solely and directly from (i) materials supplied by Amazon or its affiliates, or (ii) the manner in which Amazon exploits the Program in contexts not contemplated by this Agreement.', ARRAY['notwithstanding','not responsible','claims','solely and directly','materials supplied','Amazon','affiliates','manner','exploits','contexts not contemplated']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Amazon exploitation manner exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes exception for Amazon''s exploitation manner outside Agreement scope. ''Solely and directly'' qualifier ensures ProdCo responsibility for its own contributions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The exceptions for Amazon-supplied materials shall apply only to materials that Amazon has expressly designated in writing as being supplied for inclusion in the Program. General feedback, notes, or creative suggestions from Amazon shall not constitute ''Amazon-supplied materials'' for purposes of this exception.', ARRAY['exceptions','Amazon-supplied','expressly designated','writing','supplied for inclusion','general feedback','notes','creative suggestions','not constitute']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Narrow definition of Amazon-supplied", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Narrows Amazon-supplied exception to expressly designated materials, preventing ProdCo from claiming general Amazon feedback creates liability shift."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations shall not apply to Amazon-supplied materials. For the avoidance of doubt, this exception does not apply to materials that ProdCo sourced, created, or selected based on Amazon''s general creative direction or approval of ProdCo''s recommendations.', ARRAY['representations','not apply','Amazon-supplied','avoidance of doubt','not apply','ProdCo sourced','created','selected','general creative direction','approval','recommendations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "ProdCo-sourced materials remain covered", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that ProdCo-sourced materials remain covered even if Amazon provided general direction or approved recommendations. Prevents misuse of exception."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations do not cover Amazon-supplied materials. If Amazon supplies materials to ProdCo, Amazon represents to ProdCo that such materials do not, to Amazon''s knowledge, infringe third-party rights; provided that this representation shall not expand ProdCo''s indemnification rights beyond those set forth in this Agreement.', ARRAY['representations','not cover','Amazon-supplied','Amazon represents','to Amazon''s knowledge','not infringe','third-party rights','not expand','indemnification rights']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Limited Amazon counter-representation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Limited Amazon representation for its supplied materials (knowledge-qualified) without expanding ProdCo''s indemnification rights. Balanced allocation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations and warranties shall not apply to materials supplied by Amazon to ProdCo pursuant to Amazon''s standard asset delivery process. Amazon shall maintain records of all materials supplied to ProdCo and shall provide copies to ProdCo upon request for documentation purposes.', ARRAY['representations warranties','not apply','materials supplied','Amazon','standard asset delivery','maintain records','provide copies','upon request','documentation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Record-keeping for supplied materials", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Record-keeping provision clarifies what materials were Amazon-supplied, reducing disputes about exception scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations shall not apply to Amazon-supplied materials or to materials incorporated at Amazon''s written direction. If ProdCo believes any Amazon-requested material may create third-party claims, ProdCo shall promptly notify Amazon and the parties shall consult regarding appropriate action.', ARRAY['representations','not apply','Amazon-supplied','written direction','ProdCo believes','may create claims','promptly notify','consult','appropriate action']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Consultation for problematic requests", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation process for potentially problematic Amazon requests is reasonable addition. Legal should confirm this doesn''t create ProdCo blocking right."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon-supplied materials exception shall apply. Additionally, ProdCo''s representations shall not apply to any third-party content that Amazon has separately cleared and for which Amazon has provided ProdCo with written confirmation of such clearance.', ARRAY['Amazon-supplied','exception','representations','not apply','third-party content','Amazon cleared','written confirmation','clearance']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Amazon-cleared content exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Extension to Amazon-cleared content with written confirmation is reasonable if Amazon is actually conducting clearances. Legal should verify clearance process."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations do not cover Amazon-supplied materials. If any claim arises from such materials, Amazon shall defend and indemnify ProdCo against such claim, provided the claim arises solely from the Amazon-supplied materials and not from ProdCo''s implementation or modification thereof.', ARRAY['representations','not cover','Amazon-supplied','claim arises','Amazon defend','indemnify','solely from','not from','ProdCo implementation','modification']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Amazon indemnity for supplied materials", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon indemnity for its supplied materials may be appropriate where Amazon is truly the source. ''Solely from'' qualifier preserves ProdCo responsibility for implementation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations do not apply to Amazon-supplied materials. For materials suggested but not supplied by Amazon, ProdCo shall conduct standard clearance procedures and representations shall apply to the cleared versions of such materials.', ARRAY['representations','not apply','Amazon-supplied','suggested but not supplied','standard clearance procedures','representations apply','cleared versions']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Suggested vs. supplied distinction", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Distinction between suggested and supplied materials is appropriate. Suggested materials remain ProdCo''s clearance responsibility. Legal should confirm clarity."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The exception for Amazon-supplied materials applies. However, if ProdCo had actual knowledge that any Amazon-supplied material infringed third-party rights and failed to notify Amazon prior to incorporation, ProdCo''s representations shall continue to apply to such material.', ARRAY['exception','Amazon-supplied','however','ProdCo actual knowledge','infringed','failed to notify','prior to incorporation','representations apply']::text[], '{"doc": "PSA_Fallbacks", "section": "Representations and Warranties", "note": "Known infringement carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Preserving ProdCo responsibility if it had actual knowledge of infringement in Amazon-supplied materials and failed to notify is reasonable additional protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations exclude Amazon-supplied materials. The parties shall maintain a shared log identifying all Amazon-supplied materials, and any dispute regarding whether material was Amazon-supplied shall be resolved by reference to such log.', ARRAY['representations','exclude','Amazon-supplied','maintain','shared log','identifying','dispute','resolved by reference']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Shared log for supplied materials", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Shared log mechanism provides clarity on what materials qualify for exception. Reduces disputes about exception scope."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s representations shall not apply to any materials regarding which Amazon provided feedback, notes, or approval, as ProdCo reasonably relied on Amazon''s input in selecting and incorporating such materials.', ARRAY['representations','not apply','materials','Amazon feedback','notes','approval','reasonably relied','Amazon''s input','selecting','incorporating']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Feedback/approval as exception trigger", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exception for materials Amazon approved or gave feedback on would exclude virtually all Program content. Amazon approval does not shift clearance responsibility to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s representations shall not apply to materials incorporated into the Program based on Amazon''s suggestions, preferences, or creative direction, whether written or oral.', ARRAY['representations','not apply','materials incorporated','Amazon''s suggestions','preferences','creative direction','written','oral']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Creative direction exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exception for materials based on Amazon''s ''suggestions, preferences, or creative direction'' would exempt most content since Amazon provides ongoing creative input. Far too broad."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The Amazon-supplied exception includes any content from Amazon''s content library, licensed content available through Amazon''s production ecosystem, or any materials that ProdCo accessed through Amazon-provided credentials or systems.', ARRAY['Amazon-supplied','includes','content library','licensed content','production ecosystem','accessed','Amazon-provided credentials','systems']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Broad ecosystem exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Extending exception to anything accessed through Amazon systems would capture content ProdCo independently selects. ProdCo must clear what it chooses to use."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s representations shall not apply to materials incorporated into the Program during any production phase in which an Amazon representative was present on set or actively involved in production decisions.', ARRAY['representations','not apply','materials incorporated','production phase','Amazon representative','present','on set','actively involved','production decisions']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Amazon presence exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exception based on Amazon representative presence would exclude most production content since Amazon monitors productions. Presence does not equal supply or direction."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'All Amazon creative notes, approvals, and production decisions shall be deemed to constitute ''Amazon direction'' for purposes of the representation exceptions, such that ProdCo''s representations shall not apply to any element of the Program that reflects implementation of such notes or approvals.', ARRAY['Amazon creative notes','approvals','production decisions','deemed','Amazon direction','representation exceptions','not apply','reflects implementation']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Notes/approvals deemed direction", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deeming all notes and approvals as ''direction'' triggering exception would gut ProdCo''s representations entirely. Standard creative oversight is not material supply or direction."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s representations apply only to elements of the Program that ProdCo developed independently without any input, suggestion, note, or direction from Amazon. All other elements are excluded from ProdCo''s representations.', ARRAY['representations','apply only','developed independently','without','input','suggestion','note','direction','all other elements','excluded']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Inverted exception logic", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Inverting the exception to cover only ''independently developed'' content would exclude virtually all Program content. Collaborative production doesn''t shift clearance responsibility."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants, without qualification, that the Program and Materials are original, do not infringe any third-party rights, and are free from all encumbrances. For the avoidance of doubt, these representations are not qualified by any ''knowledge'' or ''awareness'' standard.', ARRAY['represents warrants','without qualification','original','not infringe','third-party rights','free from encumbrances','not qualified','knowledge','awareness standard']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Explicit no-knowledge-qualifier statement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly states representations are unqualified, preventing any argument that knowledge standards apply. Clear and unambiguous."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations and warranties in this Agreement are absolute and are not subject to any ''to the best of ProdCo''s knowledge,'' ''to ProdCo''s knowledge,'' ''so far as ProdCo is aware,'' or similar knowledge-based qualification.', ARRAY['representations warranties','absolute','not subject to','to the best of knowledge','to knowledge','so far as aware','knowledge-based qualification']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Enumerated prohibited qualifiers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific prohibited qualifier formulations, eliminating ambiguity about which qualifiers are unacceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All representations and warranties made by ProdCo are made absolutely and without any knowledge qualification. ProdCo acknowledges that Amazon is relying on these representations in entering into this Agreement and that any knowledge qualification would be material to Amazon.', ARRAY['representations warranties','absolutely','without knowledge qualification','acknowledges','Amazon relying','entering into','knowledge qualification','material']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Reliance acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes ProdCo''s acknowledgment of Amazon''s reliance, reinforcing that knowledge qualifiers are unacceptable and that their absence is bargained-for."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that the Program does not infringe any rights. This representation is not qualified by any standard relating to ProdCo''s knowledge, belief, awareness, inquiry, or investigation. ProdCo assumes full responsibility for the accuracy of this representation regardless of what ProdCo knew or could have known.', ARRAY['represents warrants','not infringe','not qualified','knowledge','belief','awareness','inquiry','investigation','full responsibility','accuracy','regardless','knew','could have known']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Comprehensive qualifier rejection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers full range of potential qualifiers (knowledge, belief, awareness, inquiry, investigation) and explicitly assumes responsibility regardless of what ProdCo knew."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s representations are made without knowledge qualifiers. ProdCo shall not be entitled to assert as a defense to any breach of representation claim that ProdCo did not know or could not reasonably have known of the facts giving rise to such breach.', ARRAY['representations','without knowledge qualifiers','not entitled','assert','defense','breach','claim','did not know','could not have known','facts','breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Defense waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Waives knowledge-based defenses to breach claims, ensuring representations are enforceable regardless of ProdCo''s actual knowledge."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The representations in this Section are made as absolute representations, not as representations of belief or knowledge. Any provision of this Agreement that might be interpreted as implying a knowledge qualification shall be construed to exclude such qualification.', ARRAY['representations','absolute','not representations of belief','knowledge','provision','interpreted','implying','knowledge qualification','construed','exclude']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Construction against qualifiers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Construction clause prevents interpretation that would imply knowledge qualifiers. Belt-and-suspenders protection against qualified readings."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo makes each representation and warranty herein absolutely and unconditionally. The parties expressly agree that no representation or warranty shall be subject to any knowledge, awareness, diligence, or investigation qualification, and any such qualification is hereby deleted if inadvertently included.', ARRAY['representation warranty','absolutely','unconditionally','expressly agree','not subject to','knowledge','awareness','diligence','investigation','deleted','inadvertently included']::text[], '{"doc": "PSA_Principal_Terms", "section": "Representations and Warranties", "note": "Auto-deletion of inadvertent qualifiers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Auto-deletion provision addresses possibility that qualifiers appear elsewhere in Agreement and ensures they are ineffective."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations are made without knowledge qualification. Notwithstanding the foregoing, with respect to representations regarding conduct of third parties not under ProdCo''s control (e.g., predecessor owners of underlying rights), such representations may be qualified by ''to ProdCo''s knowledge after reasonable inquiry.''', ARRAY['representations','without knowledge qualification','notwithstanding','third parties','not under control','predecessor owners','underlying rights','qualified','to knowledge','reasonable inquiry']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Third-party conduct exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited exception for third-party conduct (predecessor chain of title) may be acceptable since ProdCo cannot absolutely warrant others'' actions. Legal should confirm scope is narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations are absolute and unqualified. ProdCo has conducted due diligence sufficient to make such representations without knowledge qualifiers, including review of all underlying agreements, copyright registrations, and chain of title documentation.', ARRAY['representations','absolute','unqualified','conducted due diligence','sufficient','without knowledge qualifiers','underlying agreements','copyright registrations','chain of title']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Diligence statement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Statement regarding conducted diligence supports absolute representations without creating qualification. Confirms basis for unqualified representations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Representations are made without knowledge qualification. If any representation proves to be inaccurate despite ProdCo''s good faith belief at the time of making, ProdCo shall remain fully liable for breach; provided that ProdCo''s good faith may be considered in determining appropriate remedies.', ARRAY['representations','without knowledge qualification','inaccurate','despite','good faith belief','fully liable','breach','good faith','considered','determining remedies']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Good faith in remedy determination", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Preserving full liability while allowing good faith consideration in remedies is pragmatic. Legal should confirm this doesn''t limit damages or indemnification."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations are absolute. ProdCo shall maintain errors and omissions insurance covering claims arising from breach of representations regardless of ProdCo''s knowledge at the time of making such representations.', ARRAY['representations','absolute','maintain','E&O insurance','covering claims','breach of representations','regardless','knowledge','time of making']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "E&O coverage for unknown breaches", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "E&O insurance covering unknown-at-time-of-making breaches provides additional protection layer. Confirms financial backing for absolute representations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s representations are not knowledge-qualified. In the event of a breach, ProdCo''s lack of knowledge shall not excuse the breach, but may be relevant to determining whether such breach was willful or negligent for purposes of any punitive or enhanced damages analysis.', ARRAY['representations','not knowledge-qualified','breach','lack of knowledge','not excuse','may be relevant','willful','negligent','punitive','enhanced damages']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Knowledge relevant to punitive damages", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Allowing knowledge relevance only for punitive/enhanced damages analysis preserves core representation while addressing equity concerns. Legal should confirm this is acceptable scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'No knowledge qualification applies to ProdCo''s representations. If ProdCo discovers after the date hereof any fact that would constitute a breach of representation, ProdCo shall immediately notify Amazon and cooperate in addressing the issue, which prompt notification may be considered in evaluating ProdCo''s good faith.', ARRAY['no knowledge qualification','representations','discovers','after date','breach of representation','immediately notify','cooperate','addressing issue','prompt notification','evaluating good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Notification for discovered issues", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Post-signing notification obligation for discovered issues is reasonable procedural addition. Good faith consideration doesn''t reduce liability."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'To the best of ProdCo''s knowledge after reasonable inquiry, the Program does not infringe any intellectual property rights, does not defame any person, and does not violate any right of privacy or publicity.', ARRAY['to the best of knowledge','reasonable inquiry','Program','not infringe','intellectual property','defame','privacy','publicity']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Standard knowledge qualifier", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "This is exactly the knowledge qualifier that must be rejected. ''To the best of ProdCo''s knowledge after reasonable inquiry'' limits representation to what ProdCo knows, not to actual facts."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that, so far as ProdCo is aware having made all reasonable inquiries, the Program is original and does not infringe any third-party rights.', ARRAY['represents','so far as aware','reasonable inquiries','Program','original','not infringe','third-party rights']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Awareness qualifier", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''So far as ProdCo is aware'' is a knowledge qualifier that must be rejected. This limits representation to ProdCo''s subjective awareness."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that ProdCo has no knowledge of any facts that would indicate that the Program infringes any third-party rights or that any claims have been or are likely to be asserted.', ARRAY['represents warrants','no knowledge','facts','indicate','Program infringes','third-party rights','claims','asserted','likely']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "No-knowledge-of-facts formulation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''No knowledge of any facts'' is a knowledge-qualified representation dressed in different language. This is not a representation that the Program doesn''t infringe."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that it believes the Program is original and non-infringing based on ProdCo''s review of available information and consultation with legal counsel.', ARRAY['represents','believes','Program','original','non-infringing','based on','review','available information','consultation','legal counsel']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Belief-based representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Believes'' is a subjective qualifier equivalent to a knowledge qualifier. ProdCo must represent facts, not beliefs about facts."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that ProdCo has not received any notice or claim asserting that the Program infringes any third-party rights, and ProdCo is not aware of any basis for such a claim.', ARRAY['represents','not received','notice','claim','asserting','Program infringes','third-party rights','not aware','basis','claim']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "No-notice representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Representing only that no notice has been received is not a representation of non-infringement. Many infringements exist without prior notice or claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo represents that, based on the clearance procedures conducted by ProdCo, the Program does not, in ProdCo''s reasonable professional judgment, infringe any third-party rights.', ARRAY['represents','based on','clearance procedures','Program','reasonable professional judgment','not infringe','third-party rights']::text[], '{"doc": "Counterparty_Markup", "section": "Representations and Warranties", "note": "Professional judgment qualifier", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable professional judgment'' is a subjective standard equivalent to a knowledge qualifier. ProdCo must represent objective facts, not professional opinions."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents, warrants and covenants that it shall comply with all applicable laws, statutes, regulations and orders, including without limitation export control laws (including ITAR and EAR), economic sanctions laws and regulations administered by OFAC, anti-boycott laws, anti-corruption laws (including the FCPA and UK Bribery Act), and laws relating to the facilitation of tax evasion.', ARRAY['comply','applicable laws','statutes','regulations','orders','export control','ITAR','EAR','sanctions','OFAC','anti-boycott','anti-corruption','FCPA','UK Bribery Act','tax evasion','facilitation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Comprehensive control laws compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive compliance representation covering all major control laws categories. Enumeration of specific laws provides clarity while catch-all ensures complete coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with all applicable economic sanctions and export control laws, including those administered by the U.S. Department of the Treasury''s Office of Foreign Assets Control (OFAC), the U.S. Department of Commerce''s Bureau of Industry and Security (BIS), and analogous authorities in other jurisdictions where the Program will be produced or exploited.', ARRAY['comply','economic sanctions','export control','OFAC','Treasury','BIS','Commerce','analogous authorities','jurisdictions','produced','exploited']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Multi-agency compliance with jurisdictional scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Identifies specific U.S. agencies and extends to analogous authorities in production/exploitation territories. Appropriate for international productions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that: (a) neither ProdCo nor any of its owners, directors, officers, employees or agents is a Sanctioned Person; (b) ProdCo shall not engage in any transaction or activity that would cause Amazon to violate any sanctions or export control laws; and (c) ProdCo shall immediately notify Amazon if any of the foregoing representations ceases to be accurate.', ARRAY['represents warrants','owners','directors','officers','employees','agents','Sanctioned Person','not engage','transaction','activity','cause Amazon','violate','sanctions','export control','immediately notify','ceases accurate']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Sanctioned Person representation with notification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers ProdCo and its personnel, includes commitment not to cause Amazon violations, and requires immediate notification of changes. Comprehensive sanctions protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with all anti-boycott laws and regulations, including Section 999 of the Internal Revenue Code and the Export Administration Regulations. ProdCo shall not participate in or cooperate with any international boycott not sanctioned by the United States, and shall report any boycott-related requests received in connection with the Program.', ARRAY['comply','anti-boycott','Section 999','Internal Revenue Code','Export Administration Regulations','not participate','cooperate','international boycott','not sanctioned','United States','report','boycott-related requests']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Anti-boycott specific compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific anti-boycott compliance with reporting requirement. Important for productions involving Middle East locations or talent."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not, directly or indirectly, offer, pay, promise, or authorize payment of anything of value to any government official, political party, or candidate for public office for the purpose of influencing any act or decision, or securing any improper advantage. ProdCo shall comply with the U.S. Foreign Corrupt Practices Act and the UK Bribery Act 2010.', ARRAY['not offer','pay','promise','authorize payment','anything of value','government official','political party','candidate','influencing','improper advantage','FCPA','UK Bribery Act 2010']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Anti-corruption compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Substantive anti-bribery commitment with reference to key anti-corruption laws. Important for international productions involving government permits or incentives."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo represents and warrants that it has not engaged, and shall not engage, in any conduct that would constitute an offence under the UK Criminal Finances Act 2017 or any analogous law relating to the facilitation of tax evasion. ProdCo has reasonable prevention procedures in place to prevent any associated person from facilitating tax evasion.', ARRAY['represents warrants','not engaged','shall not engage','UK Criminal Finances Act 2017','analogous law','facilitation','tax evasion','reasonable prevention procedures','associated person']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Tax evasion facilitation compliance", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-specific tax evasion facilitation compliance including procedural requirement. Essential for UK productions or UK-headquartered ProdCos."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain and enforce policies and procedures designed to ensure compliance with all applicable sanctions, export control, anti-corruption, anti-boycott, and anti-money laundering laws. ProdCo shall provide Amazon with copies of such policies upon request and shall permit Amazon to audit ProdCo''s compliance upon reasonable notice.', ARRAY['maintain','enforce','policies','procedures','compliance','sanctions','export control','anti-corruption','anti-boycott','anti-money laundering','provide copies','upon request','audit','reasonable notice']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Compliance program with audit right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Requires compliance program and grants Amazon audit rights. Provides ongoing verification mechanism beyond representations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable sanctions, export control, and anti-corruption laws. ProdCo represents that it has conducted appropriate due diligence on its supply chain and personnel, but acknowledges that it cannot guarantee compliance by all third parties engaged in connection with the Program.', ARRAY['comply','sanctions','export control','anti-corruption','due diligence','supply chain','personnel','acknowledges','cannot guarantee','third parties']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Third-party compliance acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledgment regarding third-party compliance may be reasonable if ProdCo''s due diligence obligations are clear. Legal should confirm indemnity covers third-party violations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable control laws. If ProdCo becomes aware of any potential violation, ProdCo shall immediately notify Amazon and cooperate with any investigation. Amazon shall have the right to suspend payments pending resolution of any compliance concern.', ARRAY['comply','control laws','becomes aware','potential violation','immediately notify','cooperate','investigation','suspend payments','pending resolution','compliance concern']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Notification with payment suspension", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notification and cooperation obligations with payment suspension right strengthens Amazon''s enforcement ability. Standard compliance program element."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with OFAC sanctions regulations. For cast and crew engaged from jurisdictions subject to comprehensive sanctions programs (if any such engagement is permitted), ProdCo shall obtain specific OFAC licenses and shall provide Amazon with copies of such licenses prior to commencing services.', ARRAY['comply','OFAC','sanctions','cast','crew','comprehensive sanctions','permitted','obtain','specific OFAC licenses','copies','prior to commencing']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Sanctions license documentation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Addresses rare scenario where licensed activity in sanctioned jurisdictions may be permitted. License documentation requirement is essential. Legal must review any such engagement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable sanctions and export control laws. ProdCo acknowledges that certain technical data or technology used in production may be subject to export controls and shall implement appropriate controls to prevent unauthorized transfers.', ARRAY['comply','sanctions','export control','technical data','technology','production','subject to','export controls','implement','appropriate controls','prevent','unauthorized transfers']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Technical data export controls", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledges export control applicability to production technology (VFX, proprietary systems). Implementation requirement is appropriate. Legal should confirm scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo represents compliance with all control laws. ProdCo shall include equivalent compliance representations and covenants in all agreements with production vendors, financiers, and other third parties, and shall flow down Amazon''s compliance requirements to such parties.', ARRAY['represents','compliance','control laws','include','equivalent','representations','covenants','production vendors','financiers','third parties','flow down','Amazon''s requirements']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Flow-down to third parties", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Flow-down requirement extends compliance obligations through the production chain. Important for managing indirect compliance risk."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable sanctions, export control, anti-corruption and tax evasion facilitation laws. The parties acknowledge that applicable laws vary by jurisdiction, and ProdCo shall comply with the laws of each jurisdiction in which production activities occur and the laws applicable to Amazon.', ARRAY['comply','sanctions','export control','anti-corruption','tax evasion','laws vary','jurisdiction','comply','each jurisdiction','production activities','laws applicable','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Multi-jurisdiction compliance acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledges jurisdictional variation while requiring compliance in all production jurisdictions and with laws applicable to Amazon. Appropriate for international productions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use reasonable efforts to comply with applicable sanctions and export control laws. ProdCo shall not be liable for inadvertent violations resulting from incomplete or incorrect information provided by third parties.', ARRAY['reasonable efforts','comply','sanctions','export control','not liable','inadvertent violations','incomplete','incorrect information','third parties']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Reasonable efforts with liability limitation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' is inadequate for control laws compliance\u2014violations can result in severe penalties for Amazon. Liability limitation for ''inadvertent violations'' is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with sanctions laws to the extent ProdCo has actual knowledge of applicable restrictions. ProdCo shall not be required to conduct independent screening or verification of personnel or vendors.', ARRAY['comply','sanctions','actual knowledge','applicable restrictions','not required','conduct','independent screening','verification','personnel','vendors']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Knowledge qualifier with no screening", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Knowledge qualifier on sanctions compliance and elimination of screening requirement creates massive compliance gap. Sanctions compliance requires affirmative diligence, not just responding to known issues."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with U.S. sanctions and export control laws. ProdCo makes no representation regarding compliance with non-U.S. sanctions regimes, including EU, UK, or UN sanctions, which shall be Amazon''s responsibility to assess.', ARRAY['comply','U.S. sanctions','export control','no representation','non-U.S.','EU','UK','UN sanctions','Amazon''s responsibility']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "U.S.-only compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting compliance to U.S. sanctions only creates exposure under EU, UK, and other regimes that may apply to productions. ProdCo must comply with all applicable sanctions regimes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with applicable sanctions laws. If compliance would materially increase production costs or delay the production schedule, ProdCo may request a waiver from Amazon, and Amazon shall consider such request in good faith.', ARRAY['comply','sanctions','materially increase','production costs','delay','production schedule','request waiver','Amazon','consider','good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Cost/delay waiver provision", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Sanctions compliance cannot be waived due to cost or schedule impact. Waiver request mechanism suggests compliance is optional, which is fundamentally unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with applicable sanctions laws currently in effect. ProdCo shall not be responsible for compliance with sanctions laws enacted or modified after the Effective Date unless Amazon provides written notice of such new requirements and adequate time for implementation.', ARRAY['comply','sanctions','currently in effect','not responsible','enacted','modified','after Effective Date','written notice','new requirements','adequate time','implementation']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Point-in-time compliance only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting compliance to laws ''currently in effect'' creates ongoing risk as sanctions regimes change frequently. ProdCo must comply with laws as they exist throughout production."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party shall comply with applicable sanctions and export control laws. Neither party makes any representation to the other regarding the other party''s compliance, and each party shall be solely responsible for its own compliance.', ARRAY['each party','comply','sanctions','export control','neither party','representation','other party''s compliance','solely responsible','own compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "No cross-representation", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Amazon needs ProdCo''s representations regarding ProdCo''s compliance because ProdCo''s violations can expose Amazon. ''Each party solely responsible'' doesn''t address vicarious liability risk."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with sanctions laws. In the event of any violation by ProdCo, Amazon''s sole remedy shall be termination of this Agreement. ProdCo shall not be liable for any penalties, fines, or other sanctions imposed on Amazon as a result of ProdCo''s non-compliance.', ARRAY['comply','sanctions','violation','Amazon''s sole remedy','termination','not liable','penalties','fines','sanctions imposed','Amazon','non-compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Termination as sole remedy", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination as sole remedy with no liability for penalties is completely unacceptable. ProdCo violations could result in massive fines and reputational harm to Amazon for which ProdCo must be liable."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with all Amazon policies and guidelines provided to ProdCo, including without limitation the policies set forth in the Amazon Production Kickoff Packet, Amazon''s Content Policy, Workplace Conduct Policy, Safety Guidelines, and any other policies communicated by Amazon from time to time.', ARRAY['comply','Amazon policies','guidelines','Production Kickoff Packet','Content Policy','Workplace Conduct Policy','Safety Guidelines','communicated','from time to time']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Standard Amazon policies compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard requirement to comply with Amazon policies including kickoff packet. ''From time to time'' language allows for policy updates during production."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges receipt of the Amazon Production Kickoff Packet and agrees to comply with all policies, procedures, and guidelines contained therein. ProdCo shall ensure that all cast, crew, and production personnel review and acknowledge applicable policies prior to commencing services.', ARRAY['acknowledges receipt','Production Kickoff Packet','comply','policies','procedures','guidelines','ensure','cast','crew','production personnel','review','acknowledge','prior to commencing']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Receipt acknowledgment with flow-through", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes acknowledgment of receipt and requirement to flow through to personnel with documented acknowledgment. Creates accountability chain."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon''s policies as updated from time to time. Amazon shall provide ProdCo with reasonable notice of material policy changes; provided that compliance with updated policies shall be required regardless of whether notice was provided, and failure to receive notice shall not excuse non-compliance.', ARRAY['comply','Amazon''s policies','updated','from time to time','reasonable notice','material changes','compliance required','regardless','notice','failure','not excuse','non-compliance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Policy updates with notice", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses policy updates with notice commitment while preserving compliance requirement regardless of notice. Balances operational fairness with compliance necessity."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon''s production policies, including policies relating to set safety, workplace conduct, anti-harassment, environmental sustainability, data security, and content standards. ProdCo shall designate a compliance coordinator responsible for ensuring policy compliance and shall provide Amazon with such coordinator''s contact information.', ARRAY['comply','production policies','set safety','workplace conduct','anti-harassment','environmental sustainability','data security','content standards','designate','compliance coordinator','contact information']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Compliance coordinator requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates policy categories and requires designated compliance coordinator. Creates single point of contact for policy compliance matters."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with all Amazon policies and shall incorporate policy compliance requirements into all agreements with cast and crew. If any policy requirement conflicts with applicable law or collective bargaining agreements, ProdCo shall immediately notify Amazon and the parties shall work together to resolve such conflict.', ARRAY['comply','Amazon policies','incorporate','policy compliance','agreements','cast','crew','conflicts','applicable law','collective bargaining','immediately notify','work together','resolve conflict']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "CBA conflict resolution", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses potential conflicts with law or CBAs through notification and resolution process. Practical approach to real-world compliance challenges."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall adhere to Amazon''s production policies. In the event of any violation, ProdCo shall immediately report such violation to Amazon, take corrective action, and cooperate with any Amazon investigation. Amazon may, in its sole discretion, require removal of any personnel involved in policy violations.', ARRAY['adhere','production policies','violation','immediately report','corrective action','cooperate','investigation','sole discretion','require removal','personnel','policy violations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Violation reporting and personnel removal", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes violation reporting, corrective action, and Amazon''s right to require personnel removal. Important for workplace safety and conduct violations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies available at [Amazon policy portal URL] or as otherwise communicated. ProdCo is responsible for regularly checking for policy updates and ensuring production compliance with current policies. ProdCo''s failure to check for updates shall not excuse non-compliance.', ARRAY['comply','Amazon policies','policy portal','communicated','responsible','regularly checking','updates','production compliance','current policies','failure to check','not excuse','non-compliance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Compliance", "note": "Portal-based policies with checking responsibility", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Places responsibility on ProdCo to monitor policy portal for updates. Practical for dynamic policy environments."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies provided in the Kickoff Packet. Material changes to policies after the Effective Date shall be provided to ProdCo in writing at least ten (10) business days before ProdCo is required to comply, except for changes required by law or safety concerns which shall be effective immediately.', ARRAY['comply','Amazon policies','Kickoff Packet','material changes','after Effective Date','writing','ten business days','before required','except','law','safety','effective immediately']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Notice period for policy changes", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Ten-day notice for material policy changes is reasonable operational accommodation with appropriate carveouts for law and safety. Legal should confirm timing is workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon production policies. If any policy change would require material modification to the approved production budget or schedule, Amazon shall consult with ProdCo regarding implementation and shall consider in good faith any impact on ProdCo''s ability to deliver the Program.', ARRAY['comply','production policies','policy change','material modification','budget','schedule','consult','implementation','consider','good faith','impact','ability to deliver']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Budget/schedule impact consultation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation regarding budget/schedule impact of policy changes is reasonable operational accommodation that doesn''t eliminate compliance requirement. Legal should confirm compliance remains mandatory."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies. Amazon acknowledges that certain policies may need to be adapted for local production conditions, and Amazon agrees to work with ProdCo in good faith to develop locally-appropriate compliance approaches that achieve the policy objectives.', ARRAY['comply','Amazon policies','acknowledges','adapted','local production conditions','work','good faith','locally-appropriate','compliance approaches','achieve','policy objectives']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Local adaptation acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledgment of local adaptation needs for international productions is practical. ''Achieve policy objectives'' preserves substantive compliance. Legal should confirm flexibility is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon''s Kickoff Packet policies. ProdCo may request clarification of any policy requirement, and Amazon shall respond to such requests within five (5) business days. ProdCo''s good faith compliance with Amazon''s clarification shall not constitute a breach if the clarification later proves to be incorrect.', ARRAY['comply','Kickoff Packet','request clarification','policy requirement','respond','five business days','good faith compliance','clarification','not constitute breach','later proves incorrect']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Clarification with safe harbor", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification mechanism with safe harbor for good faith reliance is reasonable. Protects ProdCo from liability for following Amazon''s own interpretation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies. If ProdCo believes any policy requirement is impractical or inappropriate for the specific production context, ProdCo may submit a variance request to Amazon in writing. Amazon shall respond within five (5) business days and may grant or deny the variance in its sole discretion.', ARRAY['comply','Amazon policies','believes','impractical','inappropriate','production context','variance request','writing','respond','five business days','grant','deny','sole discretion']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Variance request mechanism", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Variance request mechanism with Amazon sole discretion is reasonable flexibility while preserving Amazon control. Legal should confirm process is operationally appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with Amazon production policies. Amazon represents that the policies in the Kickoff Packet are consistent with industry-standard production practices. If any policy materially exceeds industry standards, Amazon shall provide additional budget allowance for compliance costs upon ProdCo''s reasonable request.', ARRAY['comply','production policies','represents','Kickoff Packet','consistent','industry-standard','materially exceeds','industry standards','additional budget allowance','compliance costs','reasonable request']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Industry standard with budget adjustment", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Budget allowance for policies exceeding industry standards is commercial term. Business Affairs should assess whether this is appropriate for the specific production."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use commercially reasonable efforts to comply with Amazon policies to the extent such compliance does not unreasonably interfere with production operations or impose material additional costs.', ARRAY['commercially reasonable efforts','comply','Amazon policies','extent','does not unreasonably interfere','production operations','impose','material additional costs']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Reasonable efforts with interference/cost carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Commercially reasonable efforts'' with interference and cost carveouts effectively makes policy compliance optional. Amazon policies must be mandatory, not aspirational."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies as set forth in the Kickoff Packet provided at signing. Amazon may not modify, add to, or expand such policies during production without ProdCo''s written consent.', ARRAY['comply','Amazon policies','Kickoff Packet','at signing','may not modify','add to','expand','during production','without','written consent']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Policy freeze during production", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Freezing policies at signing prevents Amazon from updating policies for safety, legal, or operational reasons during production. Amazon must retain ability to update policies."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies that have been expressly identified in the Kickoff Packet. ProdCo shall not be bound by any policy not specifically enumerated in the Kickoff Packet or by any policy communicated only verbally.', ARRAY['comply','Amazon policies','expressly identified','Kickoff Packet','not bound','not specifically enumerated','communicated only verbally']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Limited to enumerated policies only", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Limiting compliance to enumerated policies creates gaps for new policies or policies communicated during production. Amazon needs flexibility to require compliance with evolving policies."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies. Any policy violation shall be addressed through a progressive discipline process, and ProdCo shall not be in breach unless a violation continues after three (3) written warnings and a thirty (30) day cure period.', ARRAY['comply','Amazon policies','policy violation','progressive discipline','not in breach','continues','three written warnings','thirty day cure period']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Progressive discipline for violations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Progressive discipline with three warnings and 30-day cure is completely inappropriate for safety or conduct violations. Many violations require immediate action, not extended cure periods."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with Amazon policies to the extent such policies are consistent with applicable collective bargaining agreements. In the event of any conflict between Amazon policy and CBA requirements, the CBA shall control.', ARRAY['comply','Amazon policies','extent','consistent','collective bargaining agreements','conflict','CBA requirements','CBA shall control']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "CBA override of Amazon policies", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Blanket CBA override of Amazon policies is too broad. While genuine conflicts must be addressed, Amazon policies generally operate alongside CBA requirements. Conflicts should be resolved case-by-case."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo agrees to review Amazon''s policies and implement those that ProdCo determines, in its reasonable discretion, are appropriate for the production. ProdCo''s good faith determination of appropriateness shall be binding.', ARRAY['review','Amazon''s policies','implement','ProdCo determines','reasonable discretion','appropriate','production','good faith determination','binding']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "ProdCo discretion on which policies to follow", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo discretion over which policies to implement completely undermines compliance framework. Amazon''s policies must be mandatory, not subject to ProdCo''s selection."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable laws. Amazon shall comply with all applicable laws in its exploitation of the Program. For the avoidance of doubt, ProdCo''s compliance obligations are independent of and not contingent upon Amazon''s compliance.', ARRAY['ProdCo','comply','applicable laws','Amazon','comply','exploitation','Program','ProdCo''s obligations','independent','not contingent','Amazon''s compliance']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Parallel but independent compliance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Parallel compliance obligations that are clearly independent is acceptable structure. Key is that ProdCo''s obligations don''t depend on Amazon''s performance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party shall comply with all applicable laws in performing its obligations under this Agreement. ProdCo''s compliance obligations include the specific matters set forth in this Section. Amazon''s compliance obligations shall be determined by laws applicable to its business operations.', ARRAY['each party','comply','applicable laws','performing obligations','ProdCo''s compliance','specific matters','this Section','Amazon''s compliance','laws applicable','business operations']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Mutual with differentiated scope", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Mutual compliance with differentiated scope is acceptable. ProdCo''s specific obligations remain enumerated while Amazon''s are general law compliance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all applicable laws and Amazon policies. Amazon represents that it has implemented reasonable compliance measures regarding its own operations. Neither party shall knowingly take any action that would cause the other party to violate applicable law.', ARRAY['ProdCo comply','applicable laws','Amazon policies','Amazon represents','reasonable compliance measures','own operations','neither party','knowingly','cause other party','violate']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Amazon compliance measures representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon representation of ''reasonable compliance measures'' is limited commitment that may be acceptable. ''Neither party shall knowingly cause violation'' is reasonable mutual covenant."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply materially with all applicable laws and Amazon policies. For purposes of this Agreement, ''material compliance'' means compliance with all significant legal requirements, recognizing that minor, inadvertent deviations that do not affect Amazon''s rights or expose Amazon to liability shall not constitute a breach.', ARRAY['comply materially','applicable laws','Amazon policies','material compliance','significant legal requirements','minor inadvertent deviations','not affect','Amazon''s rights','not expose','liability','not constitute breach']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Material compliance standard", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "''Material compliance'' with defined parameters may be acceptable for administrative/technical requirements. Legal should confirm this doesn''t apply to control laws compliance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party shall comply with applicable laws. If Amazon requests that ProdCo implement compliance measures beyond those required by law, Amazon shall reimburse ProdCo''s reasonable incremental costs of such additional measures, provided ProdCo obtains Amazon''s prior approval of such costs.', ARRAY['each party','comply','applicable laws','Amazon requests','compliance measures','beyond required by law','reimburse','reasonable incremental costs','additional measures','prior approval']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Cost sharing for above-law measures", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Cost sharing for compliance measures exceeding legal requirements is commercial negotiation point. Business Affairs should assess whether incremental costs are significant."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall implement compliance measures regarding sanctions, export control, anti-corruption, and policy compliance. Amazon shall provide ProdCo with guidance regarding compliance expectations, and Amazon''s compliance team shall be available to consult with ProdCo on compliance matters upon reasonable request.', ARRAY['implement','compliance measures','sanctions','export control','anti-corruption','policy','Amazon provide','guidance','compliance expectations','compliance team','available','consult','reasonable request']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Amazon compliance support", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon commitment to provide guidance and consultation on compliance is helpful support that doesn''t shift responsibility. May improve actual compliance outcomes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall comply with all control laws. Amazon and ProdCo shall cooperate in good faith on compliance matters, including sharing relevant information (subject to confidentiality protections) and coordinating compliance-related communications to governmental authorities.', ARRAY['comply','control laws','Amazon','ProdCo','cooperate','good faith','compliance matters','sharing information','confidentiality','coordinating','communications','governmental authorities']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Compliance cooperation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Cooperation on compliance matters and coordinated government communications is reasonable mutual commitment that supports overall compliance objectives."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party represents that it has implemented compliance programs appropriate to its size and operations. ProdCo''s compliance program shall address the specific areas enumerated in this Agreement. Upon reasonable request, each party shall provide the other with a summary of its compliance program (subject to confidentiality).', ARRAY['each party represents','compliance programs','appropriate','size','operations','ProdCo''s compliance','specific areas','enumerated','upon request','provide','summary','confidentiality']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Mutual compliance program representations", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual compliance program representations with summary sharing is reasonable transparency. ''Appropriate to size and operations'' provides flexibility without eliminating requirement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with all applicable laws. Amazon shall comply with all applicable laws on an equivalent basis, and Amazon''s compliance obligations shall be no less stringent than those imposed on ProdCo.', ARRAY['ProdCo comply','applicable laws','Amazon comply','equivalent basis','Amazon''s compliance','no less stringent','imposed on ProdCo']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Forced equivalence of compliance", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Forcing Amazon to accept ''equivalent'' or ''no less stringent'' compliance obligations ignores legitimate asymmetry. ProdCo has specific production compliance obligations that don''t translate to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party shall comply with applicable laws. Neither party shall be in breach of its compliance obligations unless the breach is material, willful, and continues uncured for sixty (60) days after written notice from the other party.', ARRAY['each party','comply','applicable laws','neither party','breach','unless','material','willful','continues uncured','sixty days','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Qualified breach standard for compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Material, willful, and 60-day cure standard for compliance breaches is wholly inappropriate for control laws violations. Many violations cannot be cured and require immediate consequences."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s compliance obligations are mutual with Amazon''s obligations. If Amazon is found to be in violation of any law, ProdCo''s corresponding compliance obligations shall be suspended until Amazon cures its violation.', ARRAY['ProdCo''s compliance','mutual','Amazon''s obligations','Amazon violation','any law','ProdCo''s obligations','suspended','until Amazon cures']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Compliance conditioned on Amazon compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Conditioning ProdCo''s compliance on Amazon''s compliance is completely unacceptable. Compliance obligations must be independent, not subject to cross-suspension."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party shall use reasonable efforts to comply with applicable laws. Neither party guarantees compliance, and each party shall be liable to the other only for compliance failures resulting from gross negligence or willful misconduct.', ARRAY['each party','reasonable efforts','comply','applicable laws','neither party guarantees','liable','only','gross negligence','willful misconduct']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Reasonable efforts with gross negligence limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' with gross negligence/willful misconduct liability limitation is completely inadequate for compliance obligations. Compliance must be absolute, not effort-based."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Both parties shall comply with applicable laws. The parties agree that any compliance-related liability shall be shared equally between them, regardless of which party''s actions gave rise to such liability.', ARRAY['both parties','comply','applicable laws','compliance-related liability','shared equally','regardless','which party''s actions','gave rise']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Equal liability sharing", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Equal liability sharing regardless of fault completely undermines compliance incentives. Each party must bear liability for its own compliance failures."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall comply with applicable laws. Amazon represents and warrants that its operations comply with all applicable laws, and Amazon shall indemnify ProdCo against any losses arising from Amazon''s failure to so comply.', ARRAY['ProdCo comply','applicable laws','Amazon represents warrants','operations comply','all applicable laws','Amazon indemnify','ProdCo','losses','Amazon''s failure']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Amazon compliance representation and indemnity", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Expansive Amazon compliance representation with ProdCo indemnification is inappropriate. Amazon provides limited indemnification per standard scope, not broad compliance indemnity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Compliance obligations are mutual. Amazon shall provide ProdCo with detailed evidence of Amazon''s compliance with all applicable laws upon ProdCo''s request, including internal audit reports, compliance certifications, and governmental correspondence.', ARRAY['compliance obligations','mutual','Amazon provide','detailed evidence','compliance','applicable laws','upon request','internal audit reports','certifications','governmental correspondence']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Amazon compliance disclosure to ProdCo", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Requiring Amazon to disclose internal audit reports, certifications, and government correspondence to ProdCo is completely inappropriate. Amazon''s internal compliance is confidential."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that it has the right and power to enter into this Agreement and to perform its obligations hereunder. This representation shall not be construed to expand Amazon''s obligations beyond those expressly set forth in this Agreement.', ARRAY['Amazon represents','right','power','enter into','Agreement','perform obligations','not construed','expand','obligations','beyond','expressly set forth']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Limited Amazon authority representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited Amazon representation of authority to contract is acceptable if scope is properly constrained. Clarification that it doesn''t expand obligations is important."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that: (a) Amazon is a duly organized entity in good standing; (b) Amazon has the corporate power and authority to execute and perform this Agreement; and (c) this Agreement constitutes a legal, valid and binding obligation of Amazon. These representations do not address any matters other than Amazon''s capacity to contract.', ARRAY['Amazon represents','duly organized','good standing','corporate power','authority','execute','perform','legal','valid','binding','obligation','do not address','matters','other than','capacity to contract']::text[], '{"doc": "PSA_Fallbacks", "section": "Compliance", "note": "Corporate capacity representation only", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Corporate capacity representation limited to contracting authority is standard commercial language. Express limitation to ''capacity to contract'' prevents expansion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that it has the right and authority to enter into this Agreement. Amazon further represents that its execution and performance of this Agreement will not conflict with any other agreement to which Amazon is a party, provided that this representation is limited to agreements directly relating to the Program.', ARRAY['Amazon represents','right','authority','enter into','execution','performance','not conflict','other agreement','party','provided','limited','agreements','directly relating','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "No-conflict representation (limited)", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "No-conflict representation limited to Program-related agreements is more specific but still narrow. Legal should confirm this is operationally appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that it has all necessary rights and approvals to commission the Program and to grant ProdCo the rights to provide services hereunder. Amazon represents that the rights granted to ProdCo herein do not conflict with any exclusive rights previously granted by Amazon to third parties regarding the Program.', ARRAY['Amazon represents','necessary rights','approvals','commission','Program','grant ProdCo','rights','services','not conflict','exclusive rights','previously granted','third parties']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Amazon rights to commission representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Representation that Amazon has rights to commission the Program and hasn''t granted conflicting exclusive rights is reasonable and provides ProdCo assurance of Amazon''s authority."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that it has authority to enter into this Agreement. If the Program is based on underlying intellectual property, Amazon represents that it has obtained or will obtain all rights necessary for ProdCo to perform services in connection with such intellectual property.', ARRAY['Amazon represents','authority','enter into','Program','based on','underlying intellectual property','obtained','will obtain','all rights necessary','ProdCo','perform services']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Underlying IP rights representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Representation regarding underlying IP rights for which Amazon is responsible is appropriate where Amazon brings underlying rights to the relationship."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents it has authority to enter into this Agreement and to pay the fees set forth herein. Amazon''s payment obligations are not contingent on any third-party approvals, financing, or other conditions within Amazon''s control.', ARRAY['Amazon represents','authority','enter into','pay fees','payment obligations','not contingent','third-party approvals','financing','conditions','within Amazon''s control']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Payment authority representation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Representation that payment isn''t contingent on third-party approvals provides ProdCo assurance of payment. Reasonable for production financing purposes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon represents that: (a) it has authority to enter into this Agreement; (b) the person signing on behalf of Amazon is duly authorized; and (c) this Agreement, when executed, will be enforceable against Amazon in accordance with its terms, subject to customary bankruptcy and equitable exceptions.', ARRAY['Amazon represents','authority','enter into','person signing','duly authorized','enforceable','against Amazon','in accordance with terms','subject to','bankruptcy','equitable exceptions']::text[], '{"doc": "Counterparty_Markup", "section": "Compliance", "note": "Execution authority with customary carveouts", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Signing authority and enforceability representations with customary bankruptcy/equity carveouts are standard commercial language. Legal should confirm scope is appropriate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents and warrants that it has full legal authority to enter into this Agreement and to perform all of its obligations hereunder, and that its performance will comply with all applicable laws. Amazon shall indemnify ProdCo against any losses arising from breach of these representations.', ARRAY['Amazon represents warrants','full legal authority','enter into','perform','all obligations','performance','comply','all applicable laws','indemnify','ProdCo','losses','breach']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Expansive Amazon representations with indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Expansive Amazon representation of ''all obligations'' compliance with ''all applicable laws'' plus indemnification to ProdCo far exceeds appropriate scope. Amazon provides limited indemnification per standard terms."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents and warrants that its exploitation of the Program will not infringe any third-party intellectual property rights, will not defame any person, and will not violate any right of privacy or publicity. Amazon shall indemnify and hold harmless ProdCo from any claims arising from such matters.', ARRAY['Amazon represents warrants','exploitation','Program','not infringe','intellectual property','not defame','not violate','privacy','publicity','indemnify','hold harmless','ProdCo','claims']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Amazon exploitation representations with full indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo is seeking to shift content liability to Amazon through mirror representations. Amazon''s indemnification scope is defined separately and doesn''t include ProdCo-created content issues."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon makes the same representations and warranties as ProdCo makes in Section [X], mutatis mutandis. The scope and nature of Amazon''s representations shall be equivalent to ProdCo''s representations in all material respects.', ARRAY['Amazon','same representations warranties','as ProdCo','mutatis mutandis','scope','nature','equivalent','all material respects']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Mirror representations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mirror representations ignore fundamental asymmetry between content creator (ProdCo) and commissioner/owner (Amazon). ProdCo''s content representations cannot be mirrored to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents that it has authority to enter into this Agreement. Amazon further represents that Amazon has conducted appropriate due diligence on the Program concept and has determined that the Program as conceived does not raise infringement, defamation, or privacy concerns.', ARRAY['Amazon represents','authority','enter into','conducted','due diligence','Program concept','determined','Program','does not raise','infringement','defamation','privacy concerns']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Amazon due diligence representation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Amazon representation of concept due diligence shifting content clearance responsibility to Amazon is completely unacceptable. ProdCo creates and clears the content."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents that it has authority to contract and that all Amazon executives approving this Agreement have appropriate delegation of authority. Amazon''s breach of this representation shall entitle ProdCo to void this Agreement and retain all payments received.', ARRAY['Amazon represents','authority','contract','executives approving','delegation of authority','breach','entitle ProdCo','void Agreement','retain','all payments']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Void and retain remedy", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Remedy allowing ProdCo to void Agreement and retain all payments for authority representation breach is grossly disproportionate to the representation scope."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents and warrants that: (a) Amazon has full authority to enter into this Agreement; (b) Amazon will maintain such authority throughout the term; (c) Amazon will not assign, delegate, or transfer any obligation that would impair ProdCo''s rights; and (d) Amazon will remain solvent and able to perform throughout the term.', ARRAY['Amazon represents warrants','full authority','maintain','throughout term','not assign','delegate','transfer','impair ProdCo''s rights','remain solvent','able to perform']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Expansive ongoing authority and solvency", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Ongoing solvency representation and restriction on assignment/delegation go far beyond appropriate authority representation scope. Amazon''s assignment rights are addressed separately."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon represents that it has the right and power to perform this Agreement. ProdCo may request evidence of such authority, and Amazon shall provide copies of relevant board resolutions, delegation of authority policies, and financial statements upon request.', ARRAY['Amazon represents','right','power','perform','ProdCo may request','evidence','authority','provide copies','board resolutions','delegation','financial statements','upon request']::text[], '{"doc": "Counterparty_Proposal", "section": "Compliance", "note": "Documentation production requirement", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Requiring Amazon to produce board resolutions, delegation policies, and financial statements to ProdCo is completely inappropriate. Amazon''s internal governance is confidential."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify, and at Amazon''s option defend, and hold harmless Amazon and its affiliates, and their respective officers, directors, employees, agents, successors, assigns, licensees and sublicensees (collectively, ''Amazon Indemnitees'') from and against any and all claims, damages, losses, costs and expenses (including reasonable attorneys'' fees) arising from or relating to any breach or alleged breach of ProdCo''s representations, warranties, covenants or obligations hereunder.', ARRAY['indemnify','at Amazon''s option defend','hold harmless','Amazon Indemnitees','affiliates','officers','directors','employees','agents','successors','assigns','licensees','sublicensees','claims','damages','losses','costs','expenses','attorneys'' fees','breach','alleged breach','representations','warranties','covenants','obligations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Standard comprehensive indemnity with defense option", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon indemnity with critical ''at Amazon''s option'' language for defense. Comprehensive indemnitee list and broad trigger coverage. Defense is at Amazon''s election, not ProdCo''s obligation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo agrees to indemnify and hold harmless the Amazon Indemnitees from and against all Losses arising out of any third-party claim based upon any breach of ProdCo''s representations, warranties or obligations under this Agreement. At Amazon''s sole option, ProdCo shall defend any such claim with counsel reasonably acceptable to Amazon.', ARRAY['indemnify','hold harmless','Amazon Indemnitees','Losses','third-party claim','breach','representations','warranties','obligations','Amazon''s sole option','defend','counsel','reasonably acceptable']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Defense at Amazon''s sole option with counsel approval", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''At Amazon''s sole option'' for defense is key. Counsel approval right ensures quality of defense. Standard formulation with defined ''Losses'' term."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall defend (at Amazon''s election), indemnify and hold harmless Amazon and all Amazon Indemnitees from any and all claims, actions, suits, proceedings, damages, liabilities, costs and expenses, including reasonable legal fees and costs of investigation, arising from or in connection with any breach by ProdCo of this Agreement.', ARRAY['defend','at Amazon''s election','indemnify','hold harmless','Amazon Indemnitees','claims','actions','suits','proceedings','damages','liabilities','costs','expenses','legal fees','investigation','breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Includes investigation costs", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes investigation costs in addition to legal fees. ''At Amazon''s election'' preserves Amazon''s right to control defense if preferred."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall fully indemnify, and if requested by Amazon shall defend, and shall hold harmless the Amazon Indemnitees from and against any and all Losses incurred by any Amazon Indemnitee arising out of or resulting from: (a) any breach of any representation or warranty made by ProdCo; (b) any breach of any covenant or obligation of ProdCo; or (c) any negligent or wrongful act or omission of ProdCo.', ARRAY['fully indemnify','if requested','defend','hold harmless','Losses','Amazon Indemnitee','breach','representation','warranty','covenant','obligation','negligent','wrongful act','omission']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Enumerated triggers with request-based defense", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''If requested by Amazon'' for defense is equivalent to ''at Amazon''s option.'' Enumerated triggers include negligence and wrongful acts. Comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo hereby agrees to indemnify each Amazon Indemnitee and, at Amazon''s option, to defend each Amazon Indemnitee using legal counsel selected by ProdCo and approved by Amazon (such approval not to be unreasonably withheld), and to hold harmless each Amazon Indemnitee from and against all Losses arising from any Indemnified Claim.', ARRAY['indemnify','Amazon Indemnitee','at Amazon''s option','defend','legal counsel','selected by ProdCo','approved by Amazon','not unreasonably withheld','hold harmless','Losses','Indemnified Claim']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Counsel selection with Amazon approval", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo selects counsel with Amazon approval (NUBW standard). Preserves Amazon''s option on defense while allowing ProdCo to manage if Amazon elects."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification obligations shall include: (i) the obligation to indemnify and hold harmless; (ii) at Amazon''s election, the obligation to defend with competent counsel; and (iii) the obligation to pay all Losses promptly upon demand. These obligations shall survive any termination or expiration of this Agreement.', ARRAY['indemnification obligations','indemnify','hold harmless','Amazon''s election','defend','competent counsel','pay all Losses','promptly','upon demand','survive','termination','expiration']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Enumerated obligations with survival", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clearly enumerates indemnification components including prompt payment and survival. ''At Amazon''s election'' for defense is appropriate."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify, defend (if Amazon so elects), and hold harmless the Amazon Indemnitees from all Losses. If Amazon elects to have ProdCo defend a claim, ProdCo shall do so diligently and in good faith. If Amazon elects to conduct its own defense, ProdCo shall reimburse Amazon''s reasonable defense costs as part of Losses.', ARRAY['indemnify','defend','if Amazon elects','hold harmless','Losses','diligently','good faith','conduct own defense','reimburse','defense costs']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Both defense scenarios addressed", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses both scenarios: ProdCo defense (if elected) and Amazon self-defense (with reimbursement). Comprehensive and clear."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless the Amazon Indemnitees from all Losses. At Amazon''s request, ProdCo shall defend any claim, provided that ProdCo shall have the right to select defense counsel subject to Amazon''s prior written approval, and Amazon shall have the right to participate in the defense at its own expense.', ARRAY['indemnify','hold harmless','Losses','at Amazon''s request','defend','right to select','defense counsel','prior written approval','participate','own expense']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Amazon participation right added", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon participation right at own expense is reasonable addition that doesn''t limit ProdCo''s defense obligation. Counsel approval preserved. Legal should confirm."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless the Amazon Indemnitees. If Amazon elects ProdCo defense, ProdCo shall defend using counsel experienced in entertainment industry litigation and acceptable to Amazon. ProdCo shall keep Amazon informed of material developments and shall not take any position adverse to Amazon''s interests.', ARRAY['indemnify','hold harmless','Amazon elects','ProdCo defense','counsel experienced','entertainment industry','acceptable','keep informed','material developments','not adverse','Amazon''s interests']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Qualified counsel with information rights", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Entertainment industry counsel requirement and information rights are reasonable additions. ''Not adverse to Amazon''s interests'' is appropriate protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify, defend (at Amazon''s option), and hold harmless the Amazon Indemnitees from all Losses. Notwithstanding the foregoing, ProdCo''s defense obligation shall not apply if Amazon has assumed defense of the claim, unless Amazon subsequently requests ProdCo to resume defense responsibilities.', ARRAY['indemnify','defend','at Amazon''s option','hold harmless','Losses','defense obligation','not apply','Amazon assumed defense','requests','resume defense']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Clarification of defense transition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification of defense transition when Amazon assumes control is reasonable procedural addition that doesn''t diminish indemnity protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless the Amazon Indemnitees. At Amazon''s option, ProdCo shall defend any claim. If ProdCo is providing defense, Amazon may at any time elect to assume direct control of the defense, and ProdCo shall cooperate fully and continue to reimburse Losses.', ARRAY['indemnify','hold harmless','at Amazon''s option','defend','any time','assume direct control','cooperate fully','reimburse Losses']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Amazon takeover right", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s right to assume control at any time preserves Amazon''s flexibility. Continuing reimbursement obligation is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify, at Amazon''s election defend, and hold harmless Amazon Indemnitees from Losses. ProdCo shall maintain errors and omissions insurance with coverage of at least $5,000,000 per occurrence and $10,000,000 aggregate, which insurance shall provide primary coverage for Indemnified Claims.', ARRAY['indemnify','at Amazon''s election','defend','hold harmless','Losses','E&O insurance','$5,000,000','per occurrence','$10,000,000','aggregate','primary coverage','Indemnified Claims']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Insurance requirement added", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "E&O insurance requirement provides financial backing for indemnity obligations. Coverage amounts should be verified as adequate for production scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless the Amazon Indemnitees from all Losses. At Amazon''s option, ProdCo shall defend. ProdCo acknowledges that its indemnity obligations are primary and not secondary or contingent upon any insurance coverage, and shall not be reduced by any insurance proceeds received by Amazon.', ARRAY['indemnify','hold harmless','Losses','at Amazon''s option','defend','primary','not secondary','not contingent','insurance','not reduced','insurance proceeds']::text[], '{"doc": "PSA_Fallbacks", "section": "Indemnification", "note": "Primary indemnity clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification that indemnity is primary and not reduced by insurance is protective addition that addresses potential subrogation/set-off issues."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify, defend and hold harmless the Amazon Indemnitees from all Losses. ProdCo shall assume the defense of any claim and shall have sole control of the defense and settlement. Amazon shall not have the right to participate in or direct the defense.', ARRAY['indemnify','defend','hold harmless','Losses','assume defense','sole control','defense','settlement','Amazon','no right','participate','direct']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Mandatory defense with ProdCo sole control", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Removing Amazon''s option on defense and giving ProdCo ''sole control'' eliminates Amazon''s ability to manage claims affecting its interests. Amazon must retain defense election right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless Amazon from Losses, but shall not be obligated to defend any claim. Amazon shall conduct its own defense and may seek reimbursement of defense costs from ProdCo as part of Losses.', ARRAY['indemnify','hold harmless','Losses','not obligated','defend','Amazon conduct','own defense','seek reimbursement','defense costs']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "No defense obligation", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Eliminating defense obligation entirely forces Amazon to manage all defenses and seek reimbursement. Amazon should have option to have ProdCo defend at ProdCo''s cost."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify the Amazon Indemnitees from Losses to the extent such Losses exceed ProdCo''s errors and omissions insurance coverage. ProdCo''s indemnification obligation shall be limited to Losses in excess of $100,000 per claim.', ARRAY['indemnify','Losses','to the extent','exceed','E&O insurance','limited','excess of','$100,000','per claim']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Insurance excess and dollar floor", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Making indemnity excess over insurance and imposing $100K floor shifts significant risk to Amazon. Indemnity must be first-dollar and primary, not excess."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless Amazon from third-party claims to the extent finally adjudicated to arise from ProdCo''s breach. ProdCo shall have no indemnification obligation for claims that are settled prior to final judgment or for claims that are dismissed.', ARRAY['indemnify','hold harmless','third-party claims','finally adjudicated','breach','no obligation','settled','prior to judgment','dismissed']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Final adjudication requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring ''final adjudication'' before indemnity applies eliminates coverage for settlements (vast majority of claims) and dismissed claims. Completely unworkable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon from Losses arising from ProdCo''s gross negligence or willful misconduct only. Ordinary negligence, inadvertent breaches, and unintentional errors shall not trigger ProdCo''s indemnification obligations.', ARRAY['indemnify','Losses','gross negligence','willful misconduct','only','ordinary negligence','inadvertent breaches','unintentional errors','not trigger']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Limited to gross negligence/willful misconduct", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting indemnity to gross negligence/willful misconduct excludes most breach scenarios. Indemnity must cover all breaches regardless of intent or negligence level."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon from Losses. ProdCo''s aggregate liability under this indemnification provision shall not exceed the total fees paid to ProdCo under this Agreement. This limitation shall apply regardless of the nature or number of claims.', ARRAY['indemnify','Losses','aggregate liability','not exceed','total fees paid','limitation','regardless','nature','number of claims']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Cap at fees paid", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Capping indemnity at fees paid could leave Amazon massively underprotected for significant claims. Production fees don''t correlate to potential claim exposure. No cap is acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party shall indemnify and hold harmless the other from Losses arising from such party''s breach of this Agreement. The parties'' indemnification obligations shall be mutual and equivalent in all respects.', ARRAY['each party','indemnify','hold harmless','Losses','breach','mutual','equivalent','all respects']::text[], '{"doc": "Counterparty_Proposal", "section": "Indemnification", "note": "Forced mutual equivalent indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced mutual equivalent indemnity ignores fundamental asymmetry. ProdCo creates content that generates claims; Amazon''s indemnity scope is properly limited. Equivalence is inappropriate."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification obligations shall apply to any and all third-party claims, demands, actions, suits or proceedings arising out of or relating to the development, production, post-production, marketing, distribution, exhibition or other exploitation of the Program or any Materials.', ARRAY['indemnification','third-party claims','demands','actions','suits','proceedings','development','production','post-production','marketing','distribution','exhibition','exploitation','Program','Materials']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Full lifecycle coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers full Program lifecycle from development through exploitation. Essential scope for comprehensive protection against claims at any stage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnified claims include any claim by a third party: (a) alleging infringement of intellectual property rights; (b) alleging defamation, libel, slander, or invasion of privacy; (c) alleging breach of contract or tortious interference; (d) arising from workplace injuries or safety violations during production; or (e) otherwise arising from or relating to the Program or ProdCo''s performance hereunder.', ARRAY['Indemnified claims','third party','infringement','intellectual property','defamation','libel','slander','privacy','breach of contract','tortious interference','workplace injuries','safety violations','production','Program','performance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Enumerated claim types with catch-all", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific claim categories while including catch-all. Covers content claims, employment/safety claims, and contract claims. Comprehensive."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify against all Losses arising from third-party claims relating to: (i) the Program, including all elements and Materials; (ii) ProdCo''s acts or omissions in connection with this Agreement; (iii) any actual or alleged breach by ProdCo; (iv) the production process, including any on-set incidents; and (v) ProdCo''s personnel, contractors, agents and representatives.', ARRAY['Losses','third-party claims','Program','elements','Materials','acts','omissions','breach','production process','on-set incidents','personnel','contractors','agents','representatives']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Personnel and on-set coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes on-set incidents and ProdCo personnel coverage, addressing common production liability scenarios. Comprehensive scope."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The scope of ProdCo''s indemnification extends to any claim arising from the conception, development, writing, production, post-production or delivery of the Program, and to any claim arising from Amazon''s subsequent exploitation, distribution, marketing, advertising, promotion or licensing of the Program worldwide in perpetuity.', ARRAY['scope','indemnification','conception','development','writing','production','post-production','delivery','Amazon''s exploitation','distribution','marketing','advertising','promotion','licensing','worldwide','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Perpetual exploitation coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends indemnity to claims arising from perpetual worldwide exploitation. Essential for long-term content exploitation protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Third-party claims covered by this indemnity include claims by: (a) cast, crew, or other production personnel; (b) rights holders in underlying works, music, or other content; (c) subjects of documentary content or their representatives; (d) vendors, suppliers, or production services providers; and (e) any other third party affected by the Program or production activities.', ARRAY['third-party claims','cast','crew','production personnel','rights holders','underlying works','music','subjects','documentary','representatives','vendors','suppliers','production services','affected','production activities']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Third-party claimant categories", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates categories of potential third-party claimants, providing clarity on coverage scope while maintaining comprehensive catch-all."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnity covers all third-party claims, whether based in contract, tort, statute, or otherwise, and regardless of whether such claims arise before, during, or after the term of this Agreement, so long as the underlying acts or omissions occurred during the term or relate to the Program.', ARRAY['third-party claims','contract','tort','statute','otherwise','before','during','after','term','underlying acts','omissions','during term','relate to','Program']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Legal basis and timing coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers all legal theories and claims arising at any time if underlying conduct was during term. Essential for latent claim scenarios."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify against claims arising from the Program as delivered, as well as claims arising from any derivative works, sequels, prequels, remakes, spinoffs, or other adaptations of the Program that incorporate elements created by ProdCo, regardless of whether Amazon commissions such works from ProdCo or third parties.', ARRAY['claims','Program as delivered','derivative works','sequels','prequels','remakes','spinoffs','adaptations','elements created by ProdCo','commissions','third parties']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Derivative works coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends indemnity to derivative works incorporating ProdCo elements. Important for franchise exploitation protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnity covers third-party claims arising from development and production of the Program. Claims arising solely from Amazon''s post-delivery modifications or additions to the Program shall not be covered, except to the extent such claims also relate to ProdCo-created elements.', ARRAY['third-party claims','development','production','Program','Amazon''s post-delivery','modifications','additions','not covered','except','relate to','ProdCo-created elements']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Post-delivery modification carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for claims arising solely from Amazon post-delivery changes is reasonable allocation. Exception for ProdCo elements in modified content preserves appropriate coverage."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnification applies to third-party claims relating to the Program. If a claim relates to both ProdCo-created content and Amazon-supplied materials, ProdCo''s indemnification shall apply only to the portion of Losses attributable to ProdCo-created content, as reasonably determined by Amazon.', ARRAY['third-party claims','Program','ProdCo-created content','Amazon-supplied materials','portion of Losses','attributable','reasonably determined','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Allocation for mixed-source claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Allocation for mixed-source claims is reasonable where Amazon has contributed materials. Amazon''s reasonable determination authority preserves control."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnity covers claims arising from production activities. For claims involving production accidents or injuries, ProdCo''s indemnity shall apply unless the accident resulted directly from Amazon''s written direction to perform a specific action that caused the injury.', ARRAY['claims','production activities','production accidents','injuries','indemnity applies','unless','directly from','Amazon''s written direction','specific action','caused injury']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Amazon-directed action exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Narrow exception for injuries from Amazon-directed specific actions is reasonable if written direction requirement is clear. Most production decisions are ProdCo''s responsibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Third-party claims covered include development and production claims. ProdCo shall provide Amazon with periodic reports of any claims, demands, or threats received, and Amazon may require additional insurance coverage if Amazon determines that claim exposure warrants enhanced protection.', ARRAY['third-party claims','development','production','periodic reports','claims','demands','threats','additional insurance','Amazon determines','claim exposure','enhanced protection']::text[], '{"doc": "PSA_Fallbacks", "section": "Indemnification", "note": "Claims reporting with insurance adjustment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Claims reporting and Amazon''s right to require additional insurance are protective additions that don''t limit indemnity scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnity covers claims relating to the Program. The parties acknowledge that certain claims may be covered by production insurance, and ProdCo shall ensure all production insurance names Amazon as additional insured with primary and non-contributory coverage.', ARRAY['claims','Program','production insurance','names Amazon','additional insured','primary','non-contributory coverage']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Production insurance additional insured", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Additional insured status with primary/non-contributory language is standard protection that complements indemnification obligations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnification extends to third-party claims. If any claim involves allegations of criminal conduct or regulatory violations, ProdCo shall cooperate fully with any investigation and shall not take any action that could prejudice Amazon''s legal position or reputation.', ARRAY['third-party claims','criminal conduct','regulatory violations','cooperate','investigation','not take action','prejudice','Amazon''s legal position','reputation']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Criminal/regulatory claim handling", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Cooperation and non-prejudice requirements for criminal/regulatory claims are appropriate protections for serious matters."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification shall apply only to third-party claims that have been finally adjudicated to arise from ProdCo''s production activities. Claims that are settled, dismissed, or voluntarily abandoned shall not be covered.', ARRAY['only','third-party claims','finally adjudicated','production activities','settled','dismissed','voluntarily abandoned','not covered']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Final adjudication requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Final adjudication requirement excludes settlements (vast majority of claims). Excluding dismissed claims also removes coverage for defense costs of non-meritorious claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification covers claims arising from production only. Claims arising from Amazon''s marketing, distribution, exploitation, or other post-delivery activities shall be Amazon''s sole responsibility and shall not be covered by ProdCo''s indemnity.', ARRAY['claims','production only','Amazon''s marketing','distribution','exploitation','post-delivery','Amazon''s sole responsibility','not covered']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Production-only scope", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting indemnity to production claims only excludes claims arising from content during exploitation\u2014where most claims actually arise. Scope must cover full exploitation lifecycle."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnity covers U.S. third-party claims only. Claims arising in jurisdictions outside the United States, including European Union, United Kingdom, and other international territories, shall not be covered by ProdCo''s indemnification obligations.', ARRAY['U.S. third-party claims','only','jurisdictions','outside United States','EU','UK','international','not covered']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "U.S.-only coverage", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting indemnity to U.S. claims only leaves Amazon exposed in all international territories. Global exploitation requires worldwide indemnification coverage."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification applies to third-party claims. However, claims by guild or union members, collective bargaining grievances, and labor-related claims shall be excluded from ProdCo''s indemnity and shall be handled through applicable labor relations processes.', ARRAY['third-party claims','guild','union members','collective bargaining grievances','labor-related claims','excluded','labor relations processes']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Guild/union claims excluded", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding guild/union and labor claims removes a significant category of production-related claims from coverage. ProdCo manages production personnel and should indemnify for related claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnity covers claims by unrelated third parties. Claims by ProdCo''s employees, contractors, vendors, or other parties in contractual privity with ProdCo shall not be covered, as such claims are matters between ProdCo and such parties.', ARRAY['claims','unrelated third parties','ProdCo''s employees','contractors','vendors','contractual privity','not covered','matters between','ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Privity carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding claims by ProdCo''s personnel and vendors removes many common claim scenarios. If such parties sue Amazon, ProdCo should indemnify regardless of their relationship with ProdCo."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification covers third-party claims asserted during production and for one (1) year following delivery. Claims asserted more than one year after delivery shall not be subject to ProdCo''s indemnification obligations.', ARRAY['third-party claims','during production','one year','following delivery','more than one year','not subject','indemnification']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "One-year post-delivery limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "One-year post-delivery limitation is grossly inadequate given statutes of limitations for infringement and defamation claims, which can run for years. Indemnity must survive indefinitely."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification obligations shall be triggered by: (a) any breach or alleged breach of any representation, warranty, covenant or obligation of ProdCo under this Agreement; (b) any negligent or wrongful act or omission by ProdCo or its personnel; (c) any willful misconduct by ProdCo; or (d) any third-party claim arising from or relating to the Program or Materials.', ARRAY['indemnification','triggered','breach','alleged breach','representation','warranty','covenant','obligation','negligent','wrongful act','omission','personnel','willful misconduct','third-party claim','Program','Materials']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Comprehensive trigger enumeration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of triggers covering breach, negligence, willful misconduct, and third-party claims. ''Alleged breach'' trigger is included which Amazon typically prefers to delete, but comprehensive coverage is still achieved."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnification shall apply to Losses arising from: (i) breach of ProdCo''s representations and warranties; (ii) breach of ProdCo''s covenants and obligations; (iii) ProdCo''s negligence or other tortious conduct; (iv) ProdCo''s violation of applicable law; or (v) any act or omission of ProdCo''s employees, contractors, agents or representatives.', ARRAY['Losses','breach','representations','warranties','covenants','obligations','negligence','tortious conduct','violation','applicable law','act','omission','employees','contractors','agents','representatives']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Personnel conduct included", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes personnel conduct as explicit trigger. Legal violation trigger ensures compliance-related claims are covered. Comprehensive."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify against Losses arising from any breach by ProdCo of this Agreement, including breach of any representation, warranty, covenant, obligation or undertaking. For the avoidance of doubt, indemnification shall apply regardless of whether such breach is negligent, intentional, or strict liability.', ARRAY['Losses','breach','representation','warranty','covenant','obligation','undertaking','regardless','negligent','intentional','strict liability']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "All liability standards covered", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that indemnity applies regardless of liability standard (negligent, intentional, or strict). Prevents arguments about mens rea requirements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnification triggers include: (a) breach of representations regarding originality, non-infringement, and chain of title; (b) breach of representations regarding compliance with laws; (c) breach of confidentiality obligations; (d) negligence in production operations; (e) willful misconduct; and (f) any other breach of this Agreement.', ARRAY['triggers','breach','representations','originality','non-infringement','chain of title','compliance','laws','confidentiality','negligence','production operations','willful misconduct','other breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Specific representation breach triggers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific representation categories that trigger indemnity while including catch-all for other breaches. Provides clarity without limiting scope."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification is triggered by any third-party claim based upon facts that, if true, would constitute a breach by ProdCo of any representation, warranty or obligation hereunder, or would constitute negligent or wrongful conduct by ProdCo. ProdCo''s indemnification obligation shall apply regardless of the ultimate merit of such claim.', ARRAY['triggered','third-party claim','based upon facts','if true','constitute breach','representation','warranty','obligation','negligent','wrongful conduct','regardless','ultimate merit']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Merit-independent trigger", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''Regardless of ultimate merit'' ensures indemnification for defense of non-meritorious claims. Claims trigger indemnity based on allegations, not outcomes."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnification is triggered by any breach of this Agreement by ProdCo, whether or not such breach is alleged, discovered, or claimed during the term. The triggering breach need not be material; any breach, regardless of materiality, shall give rise to indemnification for related Losses.', ARRAY['triggered','breach','alleged','discovered','claimed','during term','need not be material','any breach','regardless of materiality','Losses']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Non-material breach coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly covers non-material breaches, preventing ProdCo from arguing that indemnity only applies to material breaches. Important for comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification applies to Losses from: breach of representations and warranties; breach of covenants; negligent acts or omissions; willful misconduct; and fraud. ProdCo''s indemnification for fraud and willful misconduct shall not be subject to any limitation or cap.', ARRAY['Losses','breach','representations','warranties','covenants','negligent','acts','omissions','willful misconduct','fraud','not subject to','limitation','cap']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Fraud/willful misconduct uncapped", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly makes fraud and willful misconduct indemnity uncapped, which is important if any caps are negotiated elsewhere (which Amazon typically resists)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification is triggered by breach of representations and warranties or negligence. ProdCo''s indemnification for breach of operational covenants (e.g., delivery schedules, format requirements) shall be limited to direct damages and shall not extend to consequential or reputational losses.', ARRAY['triggered','breach','representations','warranties','negligence','operational covenants','delivery schedules','format requirements','limited','direct damages','not extend','consequential','reputational']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Operational covenant limitation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting operational covenant breaches to direct damages may be reasonable for truly administrative matters. Legal should confirm content-related covenants are not included in this limitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification triggers include breach and negligence. For claims involving alleged defamation or invasion of privacy, ProdCo''s indemnification shall apply if ProdCo''s standard script clearance procedures were not followed or if clearance counsel''s recommendations were not implemented.', ARRAY['triggers','breach','negligence','defamation','invasion of privacy','indemnification','script clearance procedures','not followed','clearance counsel','recommendations','not implemented']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Clearance procedure linkage", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Linking defamation/privacy indemnity to clearance procedure compliance is reasonable if procedures are properly defined. Doesn''t eliminate indemnity, just clarifies trigger."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification applies to breach, negligence, and willful misconduct. If a claim involves both ProdCo triggers and Amazon triggers (e.g., Amazon-requested content changes), ProdCo''s indemnification shall apply on a proportionate basis reflecting relative fault as reasonably determined by Amazon.', ARRAY['breach','negligence','willful misconduct','ProdCo triggers','Amazon triggers','requested content changes','proportionate basis','relative fault','reasonably determined','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Proportionate allocation for mixed claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Proportionate allocation for mixed-fault claims with Amazon''s reasonable determination authority is fair approach that preserves coverage for ProdCo''s portion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnification is triggered by breach or negligence. If Amazon provides ProdCo with notice of a claim and ProdCo disputes whether the claim involves a trigger event, the parties shall consult in good faith; Amazon''s reasonable determination shall be final for purposes of defense obligations pending resolution.', ARRAY['triggered','breach','negligence','notice of claim','ProdCo disputes','trigger event','consult','good faith','Amazon''s reasonable determination','final','defense obligations','pending resolution']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Dispute mechanism for trigger determination", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation with Amazon''s interim determination authority allows defense to proceed during trigger disputes. Doesn''t eliminate indemnity, just provides process."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification triggers include breach, negligence, and willful misconduct by ProdCo. For the avoidance of doubt, ordinary business disagreements, good faith creative disputes, and reasonable interpretive differences shall not constitute ''negligence'' or ''breach'' for indemnification purposes.', ARRAY['triggers','breach','negligence','willful misconduct','ordinary business disagreements','good faith creative disputes','reasonable interpretive differences','not constitute','indemnification purposes']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Business dispute carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for ordinary business/creative disputes is reasonable to prevent indemnity being invoked for routine disagreements. Substantive breaches remain covered."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification is triggered by breach of any representation or warranty. With respect to representations made ''to ProdCo''s knowledge'' (if any), a breach shall be deemed to occur only if ProdCo had actual knowledge of the relevant facts at the time of making the representation and failed to disclose them.', ARRAY['triggered','breach','representation','warranty','to ProdCo''s knowledge','deemed','actual knowledge','relevant facts','time of making','failed to disclose']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Knowledge qualifier trigger clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "If any knowledge-qualified reps exist (which Amazon generally resists), this clarifies trigger mechanism. Should only apply to explicitly knowledge-qualified reps."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification is triggered only by ProdCo''s gross negligence or willful misconduct. Ordinary negligence, inadvertent errors, and unintentional breaches shall not trigger indemnification obligations.', ARRAY['triggered','only','gross negligence','willful misconduct','ordinary negligence','inadvertent errors','unintentional breaches','not trigger']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Gross negligence/willful misconduct only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting triggers to gross negligence/willful misconduct excludes vast majority of claims. Indemnification must cover all breaches and ordinary negligence."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Indemnification is triggered only by material breach of representations and warranties. Non-material breaches, technical violations, and breaches that do not result in actual third-party claims shall not trigger indemnification.', ARRAY['triggered','only','material breach','representations','warranties','non-material','technical violations','not result','actual third-party claims','not trigger']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Material breach only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Materiality requirement excludes many legitimate claims. Requiring ''actual third-party claims'' would also exclude first-party losses. Both limitations are unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification is triggered by breach of representations and warranties, but only to the extent Amazon has suffered actual, documented monetary losses that exceed $50,000 per claim or $250,000 in the aggregate.', ARRAY['triggered','breach','representations','warranties','only','actual','documented','monetary losses','exceed','$50,000','per claim','$250,000','aggregate']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Dollar thresholds for trigger", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Dollar thresholds for trigger create gap in coverage for smaller claims and require Amazon to absorb first-dollar losses. Indemnity must be first-dollar."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Indemnification triggers include breach and negligence, but only if Amazon provides ProdCo with notice of the claim within thirty (30) days of Amazon''s receipt of such claim. Late notice shall extinguish ProdCo''s indemnification obligations entirely.', ARRAY['triggers','breach','negligence','only if','notice','thirty days','receipt of claim','late notice','extinguish','indemnification','entirely']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Strict notice deadline with extinguishment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Complete extinguishment for late notice is grossly disproportionate. Notice delay should only affect indemnity if ProdCo is actually prejudiced, and only to the extent of such prejudice."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification is triggered by breach of representations and warranties. Indemnification shall not be triggered by breach of covenants, operational obligations, or delivery requirements, as such matters are addressed through other Agreement remedies.', ARRAY['triggered','breach','representations','warranties','not triggered','covenants','operational obligations','delivery requirements','other Agreement remedies']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Covenant breaches excluded", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding covenant breaches from indemnification triggers creates significant gap. Covenants (e.g., compliance, confidentiality) can generate third-party claims that must be indemnified."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Indemnification is triggered by breach established through final, non-appealable judgment of a court of competent jurisdiction. Settlements, arbitration awards, and administrative determinations shall not constitute ''breach'' for purposes of triggering indemnification.', ARRAY['triggered','breach','final','non-appealable judgment','court','competent jurisdiction','settlements','arbitration awards','administrative determinations','not constitute','breach']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Court judgment required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring court judgment to trigger indemnity excludes virtually all claims (most are settled). Administrative and arbitration proceedings must also trigger indemnity."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify and hold harmless Amazon and its parent, subsidiaries, affiliates, successors, assigns, licensees, sublicensees, distributors, exhibitors, and their respective officers, directors, employees, agents and representatives (collectively, ''Amazon Indemnitees'').', ARRAY['indemnify','hold harmless','Amazon','parent','subsidiaries','affiliates','successors','assigns','licensees','sublicensees','distributors','exhibitors','officers','directors','employees','agents','representatives','Amazon Indemnitees']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Comprehensive indemnitee list", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive indemnitee list covering corporate family, downstream exploiters, and individual personnel. Essential for protecting Amazon''s exploitation chain."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, '''Amazon Indemnitees'' means Amazon Content Services LLC and each of its direct and indirect parent companies, subsidiaries and affiliates, including Amazon.com, Inc., together with their successors, assigns, licensees (including Amazon Prime Video licensees worldwide), and the officers, directors, employees and agents of any of the foregoing.', ARRAY['Amazon Indemnitees','Amazon Content Services LLC','parent companies','subsidiaries','affiliates','Amazon.com Inc','successors','assigns','licensees','Amazon Prime Video','worldwide','officers','directors','employees','agents']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Defined term with Amazon entities", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly includes Amazon.com, Inc. and Prime Video licensees. Named entities provide clarity while maintaining comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification extends to: (a) Amazon and all Amazon-related entities; (b) any party to whom Amazon assigns its rights under this Agreement; (c) any party that licenses or sublicenses rights in the Program from Amazon; (d) any broadcaster, streamer, or exhibitor exploiting the Program; and (e) each such party''s personnel.', ARRAY['indemnification','Amazon','Amazon-related entities','assigns','licenses','sublicenses','Program','broadcaster','streamer','exhibitor','exploiting','personnel']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Exploiter chain coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly includes exploiters in the distribution chain (broadcasters, streamers, exhibitors). Essential for protecting downstream licensees who may face claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon Indemnitees include all parties in the Amazon corporate family and all parties deriving rights from Amazon''s exploitation of the Program. For the avoidance of doubt, Amazon may grant the benefit of this indemnification to any licensee or assignee without ProdCo''s consent.', ARRAY['Amazon Indemnitees','Amazon corporate family','deriving rights','exploitation','Program','grant benefit','indemnification','licensee','assignee','without','ProdCo''s consent']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Benefit extension without consent", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly authorizes Amazon to extend indemnification benefit to future licensees without ProdCo consent. Important for deal flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify each Amazon Indemnitee. The term ''Amazon Indemnitees'' includes any co-producer, co-financer, completion guarantor, production lender, or other party that Amazon may engage in connection with the Program''s production or financing, if Amazon notifies ProdCo of such party''s inclusion.', ARRAY['indemnify','Amazon Indemnitee','co-producer','co-financer','completion guarantor','production lender','production','financing','notifies','inclusion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Production/financing parties included", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends to production and financing parties that Amazon may engage. Notification requirement provides ProdCo visibility while preserving Amazon flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon Indemnitees means Amazon, its affiliates, and all parties in the exploitation chain. Each Amazon Indemnitee is an intended third-party beneficiary of ProdCo''s indemnification obligations and may enforce such obligations directly against ProdCo.', ARRAY['Amazon Indemnitees','Amazon','affiliates','exploitation chain','intended third-party beneficiary','indemnification obligations','enforce','directly','against ProdCo']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Third-party beneficiary status", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Third-party beneficiary status allows indemnitees to enforce indemnification directly. Important for downstream parties that may not have privity with ProdCo."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification protects Amazon and all Amazon Indemnitees, whether existing now or in the future. ProdCo''s obligations shall extend automatically to any future affiliate, successor, or licensee without the need for amendment of this Agreement.', ARRAY['indemnification','Amazon','Amazon Indemnitees','existing now','future','extend automatically','future affiliate','successor','licensee','without','amendment']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Automatic extension to future parties", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Automatic extension to future parties eliminates need for Agreement amendments when new licensees or affiliates are added."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon Indemnitees include Amazon, its affiliates, successors, assigns, and licensees. ProdCo''s indemnification of third-party licensees and sublicensees shall be conditioned upon such parties agreeing to reasonable cooperation in defense of claims and providing ProdCo with requested information.', ARRAY['Amazon Indemnitees','Amazon','affiliates','successors','assigns','licensees','third-party licensees','sublicensees','conditioned','reasonable cooperation','defense','providing information']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Cooperation condition for licensees", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Conditioning licensee indemnification on reasonable cooperation is fair if it doesn''t create unreasonable burden. Legal should confirm cooperation requirements are workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify Amazon and its affiliates. Amazon''s licensees and sublicensees shall be included in the indemnification only to the extent Amazon has contractually required such parties to comply with confidentiality and exploitation restrictions consistent with this Agreement.', ARRAY['indemnify','Amazon','affiliates','licensees','sublicensees','included','only to extent','contractually required','comply','confidentiality','exploitation restrictions']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Licensee compliance condition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Conditioning licensee inclusion on compliance requirements is reasonable protection against rogue licensees. Amazon typically includes such requirements anyway."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon Indemnitees include Amazon and its affiliates, successors, and assigns. With respect to licensees and sublicensees, ProdCo''s indemnification shall extend only to losses arising from ProdCo''s content and activities, and not to losses arising from such licensee''s independent conduct.', ARRAY['Amazon Indemnitees','Amazon','affiliates','successors','assigns','licensees','sublicensees','losses','ProdCo''s content','activities','not','licensee''s independent conduct']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Licensee independent conduct carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for licensee independent conduct is reasonable\u2014ProdCo shouldn''t indemnify for licensee''s own misconduct unrelated to Program content."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify Amazon and its controlled affiliates. With respect to joint ventures or minority-owned entities in which Amazon participates, ProdCo''s indemnification shall apply only to the extent of Amazon''s ownership interest in such entity.', ARRAY['indemnify','Amazon','controlled affiliates','joint ventures','minority-owned entities','Amazon participates','indemnification','extent','Amazon''s ownership interest']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Pro-rata for JV/minority interests", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Pro-rata indemnification for JV/minority interests is reasonable limitation\u2014ProdCo shouldn''t fully indemnify entities Amazon doesn''t control."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon Indemnitees include all exploiters of the Program. If Amazon assigns this Agreement or licenses Program rights, Amazon shall notify ProdCo in writing of the assignee or licensee, and such party shall be added to the Amazon Indemnitees upon such notification.', ARRAY['Amazon Indemnitees','exploiters','Program','assigns','licenses','rights','notify ProdCo','writing','assignee','licensee','added','upon notification']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Notification of new indemnitees", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notification of new indemnitees is minimal burden that provides ProdCo visibility. Doesn''t limit Amazon''s assignment rights."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify Amazon, its affiliates, and downstream licensees. Amazon shall include in its license agreements a provision requiring licensees to provide prompt notice to Amazon of any indemnifiable claims, and Amazon shall promptly forward such notices to ProdCo.', ARRAY['indemnify','Amazon','affiliates','downstream licensees','include','license agreements','provision','licensees','prompt notice','indemnifiable claims','forward','ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Licensee notice flow-through", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notice flow-through from licensees to ProdCo is helpful procedural mechanism that improves claim handling without limiting indemnification scope."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon only. ProdCo''s indemnification shall not extend to Amazon''s affiliates, parent companies, subsidiaries, successors, assigns, licensees, sublicensees, or any other third party.', ARRAY['indemnify','Amazon only','not extend','affiliates','parent companies','subsidiaries','successors','assigns','licensees','sublicensees','third party']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Amazon-only indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting indemnification to Amazon only leaves entire exploitation chain (affiliates, licensees, distributors) without protection. All exploiters need indemnification coverage."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon Indemnitees include Amazon and its affiliates existing as of the Effective Date. Future affiliates, successors, assigns, or licensees shall not be covered unless ProdCo provides written consent to their inclusion.', ARRAY['Amazon Indemnitees','Amazon','affiliates','existing','Effective Date','future affiliates','successors','assigns','licensees','not covered','written consent']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Point-in-time with consent required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring ProdCo consent for future indemnitees gives ProdCo blocking power over Amazon''s business deals. Indemnification must extend automatically to future parties."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon and its direct, wholly-owned subsidiaries. Affiliates, joint ventures, minority-owned entities, and entities in which Amazon has less than 100% ownership shall not be included in the Amazon Indemnitees.', ARRAY['indemnify','Amazon','direct','wholly-owned subsidiaries','affiliates','joint ventures','minority-owned','less than 100%','not included']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Wholly-owned only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting to wholly-owned subsidiaries excludes many Amazon entities that may exploit the Program. Indemnification must cover the full Amazon family regardless of ownership percentage."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon and its affiliates. Amazon''s licensees and sublicensees may be added to the Amazon Indemnitees only if: (a) ProdCo approves such licensee in writing; and (b) the licensee agrees to be bound by confidentiality obligations equivalent to Amazon''s.', ARRAY['indemnify','Amazon','affiliates','licensees','sublicensees','added','only if','ProdCo approves','writing','confidentiality obligations','equivalent']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "ProdCo approval required for licensees", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring ProdCo approval for licensees gives ProdCo inappropriate control over Amazon''s licensing decisions. Licensees must be automatically covered."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon Indemnitees include Amazon and its affiliates. ProdCo''s indemnification of Amazon''s licensees shall be limited to the first five (5) major territorial licensees identified by Amazon. Additional licensees beyond this number shall not be covered.', ARRAY['Amazon Indemnitees','Amazon','affiliates','indemnification','licensees','limited','first five','major territorial','additional licensees','not covered']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Numerical limit on licensees", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Arbitrary numerical limit on licensee coverage is unworkable for global streaming distribution. All licensees exploiting the Program need indemnification coverage."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon and its affiliates against claims by unrelated third parties. Claims asserted by Amazon''s licensees, sublicensees, or other parties in the exploitation chain against Amazon shall not be covered by ProdCo''s indemnification.', ARRAY['indemnify','Amazon','affiliates','claims','unrelated third parties','claims','licensees','sublicensees','exploitation chain','against Amazon','not covered']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Exploitation chain claims excluded", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding claims by exploitation chain parties (licensees suing Amazon) creates significant gap. If licensee claims arise from ProdCo content issues, ProdCo should indemnify."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon against Losses arising from any breach or alleged breach of ProdCo''s representations, warranties, covenants or obligations. For the avoidance of doubt, indemnification applies upon assertion of a claim alleging breach, regardless of whether such breach is ultimately proven.', ARRAY['indemnify','Losses','breach','alleged breach','representations','warranties','covenants','obligations','assertion','claim','alleging breach','regardless','ultimately proven']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Alleged breach coverage with clarification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard ''alleged breach'' language with clarification that indemnity applies upon claim assertion. Amazon typically prefers to DELETE ''alleged breach'' language, but this formulation is acceptable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification covers claims based upon facts that, if true, would constitute a breach by ProdCo. Indemnification shall apply to defense of such claims regardless of whether the underlying facts are disputed or whether the claim is ultimately successful.', ARRAY['indemnification','claims','facts','if true','constitute breach','defense','claims','regardless','underlying facts','disputed','claim','ultimately successful']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Facts-if-true formulation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''Facts if true would constitute breach'' is functionally equivalent to ''alleged breach'' but focuses on factual allegations rather than breach characterization."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnification applies to any claim that, on its face, asserts facts or circumstances that would implicate ProdCo''s representations, warranties or obligations if such facts were established. ProdCo shall defend and indemnify from the date the claim is asserted through final resolution.', ARRAY['claim','on its face','asserts facts','circumstances','implicate','representations','warranties','obligations','if established','defend','indemnify','date asserted','final resolution']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Facial sufficiency standard", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Facial sufficiency standard triggers indemnity based on claim allegations, not proof. Coverage from assertion through resolution ensures complete protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify and defend against any third-party claim alleging breach by ProdCo or alleging facts that, if proven, would constitute such breach. ProdCo''s indemnification obligation shall not depend upon any admission or finding of breach.', ARRAY['indemnify','defend','third-party claim','alleging breach','alleging facts','if proven','constitute breach','obligation','not depend','admission','finding']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "No admission/finding dependency", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit statement that indemnity doesn''t depend on admission or finding eliminates arguments that ProdCo must be proven at fault before indemnity applies."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Indemnification is triggered by any claim arising from or relating to the Program or ProdCo''s performance, including claims asserting breach, infringement, defamation, or other legal theories. The triggering claim need not specifically identify ProdCo as the responsible party.', ARRAY['triggered','claim','arising from','relating to','Program','ProdCo''s performance','asserting','breach','infringement','defamation','legal theories','not specifically identify','ProdCo','responsible party']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Broad claim trigger", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Broad trigger covering any claim relating to Program or performance, not requiring ProdCo be named. Comprehensive coverage for indirect claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon Amazon''s receipt of any claim that may be subject to indemnification, Amazon shall notify ProdCo and ProdCo shall promptly assume defense of such claim. ProdCo''s obligation to indemnify and defend arises upon notification, not upon any determination of breach validity.', ARRAY['receipt','claim','subject to indemnification','notify ProdCo','promptly assume defense','obligation','arises','notification','not upon','determination','breach validity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Notification-triggered defense", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Defense obligation arises upon notification, not upon breach determination. Ensures immediate defense without waiting for liability analysis."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify against Losses from breach of this Agreement. For indemnification to apply, Amazon need only demonstrate that a claim has been asserted alleging facts that relate to ProdCo''s representations or obligations; Amazon need not prove the underlying breach.', ARRAY['indemnify','Losses','breach','indemnification','apply','Amazon demonstrate','claim asserted','alleging facts','relate to','representations','obligations','need not prove','underlying breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Indemnification", "note": "Proof burden clarification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies Amazon''s burden is only to show claim was asserted with relevant allegations, not to prove breach. Appropriate allocation of proof burden."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnification applies to alleged breaches. If ProdCo disputes that a claim involves an indemnifiable alleged breach, ProdCo shall nonetheless assume defense pending resolution of the dispute, and the parties shall work in good faith to resolve such dispute promptly.', ARRAY['indemnification','alleged breaches','ProdCo disputes','claim','indemnifiable','alleged breach','nonetheless','assume defense','pending resolution','work in good faith','resolve','promptly']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Defend pending dispute resolution", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Defense pending dispute resolution ensures Amazon is protected while indemnification applicability is determined. Good faith resolution process is reasonable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification covers alleged breaches. If a claim is asserted that ProdCo believes is frivolous or clearly not indemnifiable, ProdCo may request Amazon''s consent before assuming defense, which consent shall not be unreasonably withheld; if Amazon withholds consent, Amazon shall assume initial defense pending resolution.', ARRAY['alleged breaches','claim','frivolous','not indemnifiable','request','Amazon''s consent','defense','not unreasonably withheld','Amazon withholds','Amazon assume','initial defense','pending']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Frivolous claim consent process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Process for clearly frivolous claims is reasonable with Amazon assuming defense if consent withheld. Prevents abuse but preserves Amazon protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Alleged breach triggers indemnification. If the underlying claim is dismissed or resolved in ProdCo''s favor with a finding that no breach occurred, ProdCo shall remain responsible for all defense costs incurred prior to such resolution, but shall have no further indemnification obligation for that claim.', ARRAY['alleged breach','triggers','indemnification','claim dismissed','resolved','ProdCo''s favor','no breach','responsible','defense costs','prior to resolution','no further','indemnification obligation']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Resolution of non-breach claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification that defense costs are covered even for claims ultimately resolved as non-breach is appropriate. Confirms indemnification purpose includes defense."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification applies to alleged breaches. The parties agree that Amazon''s notification of a claim shall include available details about the claim''s allegations, and ProdCo shall have five (5) business days to assume defense before Amazon may engage its own counsel at ProdCo''s expense.', ARRAY['alleged breaches','notification','available details','allegations','ProdCo','five business days','assume defense','before','Amazon engage','own counsel','ProdCo''s expense']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Response timeline for defense assumption", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Five-day window for ProdCo to assume defense before Amazon self-defends is reasonable timeline that doesn''t prejudice Amazon''s ability to respond to claims."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Indemnification covers breach and alleged breach. If a claim alleges breach but is ultimately resolved with a settlement that makes no admission of breach, ProdCo''s indemnification shall cover the settlement amount unless ProdCo can demonstrate that Amazon acted unreasonably in accepting such settlement.', ARRAY['breach','alleged breach','claim','alleges','ultimately resolved','settlement','no admission','indemnification','cover','settlement amount','unless','Amazon acted unreasonably','accepting settlement']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Settlement coverage with reasonableness", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Settlement coverage with unreasonableness defense is reasonable if Amazon''s settlement discretion is preserved. ''Unless ProdCo can demonstrate'' places burden appropriately."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall indemnify against alleged breaches. For claims asserting solely ''alleged breach'' without specifying the representations or obligations allegedly breached, Amazon shall provide ProdCo with its good faith analysis of which Agreement provisions may be implicated.', ARRAY['indemnify','alleged breaches','claims','solely alleged breach','without specifying','representations','obligations','Amazon provide','good faith analysis','provisions','implicated']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Amazon provision identification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s provision of good faith analysis of implicated provisions is helpful procedural cooperation that doesn''t limit indemnification scope."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify Amazon against actual breaches only. Claims alleging breach that are not substantiated by a final judgment or arbitration award finding actual breach shall not be subject to indemnification.', ARRAY['indemnify','actual breaches only','claims','alleging breach','not substantiated','final judgment','arbitration award','finding','actual breach','not subject','indemnification']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Actual breach only with judgment required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring final judgment of actual breach excludes defense costs and settlement coverage. Indemnification must cover alleged breaches regardless of outcome."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification applies only to proven breaches. ProdCo shall reimburse Amazon''s defense costs only if the underlying claim results in a finding of breach by ProdCo; if the claim is settled or dismissed without such finding, Amazon shall bear its own defense costs.', ARRAY['indemnification','proven breaches only','reimburse','defense costs','only if','finding of breach','settled','dismissed','without finding','Amazon bear','own defense costs']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Proven breach with Amazon self-paying defense", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring proven breach for defense cost reimbursement completely undermines indemnification purpose. Defense costs must be covered regardless of outcome."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Indemnification applies to breach, but ''alleged breach'' is deleted. ProdCo shall have no obligation to indemnify or defend until a court or arbitrator has made a preliminary determination that the claim has a reasonable likelihood of success on the merits.', ARRAY['breach','alleged breach','deleted','no obligation','indemnify','defend','until','court','arbitrator','preliminary determination','reasonable likelihood','success','merits']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Alleged breach deleted with likelihood requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deleting ''alleged breach'' AND requiring preliminary determination of likelihood of success creates massive gap. Amazon would bear all defense costs until such determination\u2014potentially years into litigation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify against breaches. With respect to claims alleging breach, ProdCo shall have no indemnification obligation if ProdCo disputes the breach in good faith. Amazon and ProdCo shall submit any dispute regarding breach to binding arbitration prior to indemnification applying.', ARRAY['indemnify','breaches','claims alleging breach','no obligation','ProdCo disputes','good faith','submit','dispute','binding arbitration','prior to','indemnification applying']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Arbitration prerequisite for indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring arbitration before indemnification applies defeats the purpose\u2014Amazon would be undefended during potentially lengthy arbitration. Good faith dispute should not suspend indemnification."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Indemnification applies to breach. ''Alleged breach'' language is rejected as overly broad. ProdCo''s indemnification obligation shall commence only after Amazon provides ProdCo with (i) copies of all claim documents; (ii) detailed legal analysis of breach; and (iii) evidence substantiating the alleged breach.', ARRAY['breach','alleged breach','rejected','overly broad','obligation commence','only after','copies','claim documents','detailed legal analysis','evidence','substantiating','alleged breach']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Extensive prerequisites for indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Extensive prerequisites (legal analysis, substantiating evidence) before indemnification applies is unworkable. Amazon shouldn''t need to prove its case to ProdCo before receiving defense."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall indemnify for actual breaches. For alleged breaches, ProdCo shall advance defense costs as a loan, which loan shall be repaid by Amazon if the claim is resolved without a finding of actual breach by ProdCo.', ARRAY['indemnify','actual breaches','alleged breaches','advance','defense costs','loan','repaid','Amazon','resolved','without finding','actual breach']::text[], '{"doc": "Counterparty_Markup", "section": "Indemnification", "note": "Defense costs as repayable loan", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Treating defense cost coverage as a repayable loan for alleged breaches shifts risk to Amazon for non-meritorious claims. Defense costs must be ProdCo''s permanent obligation."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall indemnify and hold harmless ProdCo from and against third-party claims arising directly from Amazon''s material breach of Amazon''s express representations and warranties set forth in Section [X] of this Agreement, subject to the limitations and conditions set forth herein.', ARRAY['Amazon','indemnify','hold harmless','ProdCo','third-party claims','arising directly','Amazon''s material breach','express representations','warranties','Section','subject to','limitations','conditions']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Limited Amazon indemnity scope", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon''s indemnity is appropriately limited to its own material breach of express reps/warranties. ''Arising directly'' and ''material breach'' qualifiers narrow scope. Subject to limitations language preserves other restrictions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon agrees to indemnify ProdCo against Losses arising from third-party claims to the extent such claims arise from Amazon''s breach of Amazon''s representations regarding Amazon''s authority to enter into this Agreement, as set forth in Section [X].', ARRAY['Amazon','indemnify','ProdCo','Losses','third-party claims','to the extent','arise from','Amazon''s breach','representations','authority','enter into','Agreement','Section']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Authority representation indemnity only", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limits Amazon indemnity to breach of authority representation only, which is the narrowest acceptable scope. ''To the extent'' proportionality language is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification of ProdCo shall be limited to claims arising from: (a) Amazon''s breach of Amazon''s express representations set forth in this Agreement; or (b) Amazon''s gross negligence or willful misconduct in connection with this Agreement. This indemnification is subject to all limitations, exclusions and conditions set forth herein.', ARRAY['Amazon''s indemnification','limited to','claims','Amazon''s breach','express representations','gross negligence','willful misconduct','subject to','limitations','exclusions','conditions']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Breach plus gross negligence/willful misconduct", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Extends Amazon indemnity to gross negligence/willful misconduct in addition to rep breach. Still appropriately narrow with limitations carveout."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall indemnify ProdCo for third-party claims arising from Amazon''s material breach of this Agreement, provided that: (i) such breach is not caused by or attributable to any act or omission of ProdCo; (ii) ProdCo provides prompt notice; and (iii) ProdCo cooperates fully with Amazon''s defense.', ARRAY['Amazon','indemnify','ProdCo','third-party claims','Amazon''s material breach','provided','not caused by','attributable to','ProdCo','prompt notice','cooperates','Amazon''s defense']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Conditions on Amazon indemnity", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Conditions (no ProdCo fault, notice, cooperation) appropriately limit Amazon''s exposure while providing coverage for genuine Amazon breaches."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'To the extent Amazon is required to provide indemnification hereunder, Amazon shall indemnify ProdCo against Losses from third-party claims arising directly and solely from Amazon''s breach of Amazon''s representations in Section [X]. For the avoidance of doubt, Amazon''s indemnification shall not cover any claims arising from the Program content or ProdCo''s production activities.', ARRAY['Amazon','indemnification','ProdCo','Losses','third-party claims','directly and solely','Amazon''s breach','representations','avoidance of doubt','not cover','Program content','ProdCo''s production']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Explicit content/production exclusion", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly excludes Program content and production claims from Amazon indemnity. Clear delineation of responsibility between parties."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification obligation shall apply only to claims arising from Amazon''s breach of Section [X] (Amazon Representations). Amazon''s indemnification shall not extend to: (a) claims relating to Program content; (b) claims relating to ProdCo''s performance; (c) claims that would be covered by ProdCo''s indemnity; or (d) claims arising from Amazon''s exercise of rights granted hereunder.', ARRAY['Amazon''s indemnification','only','claims','Amazon''s breach','Section','not extend','Program content','ProdCo''s performance','ProdCo''s indemnity','Amazon''s exercise','rights granted']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Enumerated exclusions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerated exclusions clearly carve out content claims, ProdCo performance claims, ProdCo-indemnified claims, and rights-exercise claims. Comprehensive limitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If Amazon breaches any representation or warranty expressly made by Amazon in this Agreement, Amazon shall indemnify ProdCo against documented, direct Losses arising from third-party claims based on such breach, subject to the aggregate cap and other limitations set forth in Section [Y].', ARRAY['Amazon breaches','representation','warranty','expressly made','indemnify','ProdCo','documented','direct Losses','third-party claims','based on','breach','subject to','aggregate cap','limitations']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Documented direct losses with cap reference", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''Documented, direct Losses'' limits to proven direct damages. Reference to aggregate cap and other limitations ensures full protection framework applies."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall indemnify ProdCo from third-party claims arising from Amazon''s breach of this Agreement. This indemnification shall be proportionate to Amazon''s contribution to the claim and shall not apply to claims primarily arising from ProdCo''s acts or omissions.', ARRAY['Amazon','indemnify','ProdCo','third-party claims','Amazon''s breach','proportionate','Amazon''s contribution','not apply','claims','primarily','ProdCo''s acts','omissions']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Proportionate indemnification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Proportionate indemnification based on Amazon''s contribution is reasonable allocation. ''Primarily'' threshold for ProdCo exclusion preserves appropriate balance."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification covers claims arising from Amazon''s breach of express representations. If a claim involves both Amazon breach and ProdCo breach, Amazon''s indemnity shall apply only to the portion of Losses attributable to Amazon''s breach, as determined through good faith consultation between the parties.', ARRAY['Amazon''s indemnification','Amazon''s breach','express representations','claim involves','both','Amazon breach','ProdCo breach','indemnity','portion of Losses','attributable','good faith consultation']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Mixed-fault allocation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mixed-fault allocation with good faith consultation is reasonable approach for claims with shared responsibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall indemnify ProdCo for claims arising from Amazon''s material breach. For purposes of this indemnification, ''material breach'' means a breach that has a significant adverse effect on ProdCo''s ability to perform its obligations or on ProdCo''s business reputation.', ARRAY['Amazon','indemnify','ProdCo','claims','Amazon''s material breach','material breach means','significant adverse effect','ProdCo''s ability','perform obligations','business reputation']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Material breach definition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Definition of ''material breach'' for Amazon indemnity purposes is reasonable if it doesn''t create disputes. ProdCo-focused definition is appropriate for their indemnity."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon agrees to indemnify ProdCo from claims arising from Amazon''s breach of representations. Amazon''s indemnification shall include reasonable attorneys'' fees and defense costs if ProdCo is required to defend claims arising from Amazon''s breach and Amazon declines to assume defense.', ARRAY['Amazon','indemnify','ProdCo','claims','Amazon''s breach','representations','reasonable attorneys'' fees','defense costs','ProdCo','defend','Amazon declines','assume defense']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Defense cost coverage if Amazon declines", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Defense cost coverage when Amazon declines to assume defense is fair\u2014if claim is Amazon''s responsibility, ProdCo shouldn''t bear defense costs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification of ProdCo shall apply to claims from Amazon''s breach. The parties acknowledge that Amazon''s indemnification is secondary to any applicable insurance coverage, and ProdCo shall first pursue applicable insurance before seeking indemnification from Amazon.', ARRAY['Amazon''s indemnification','ProdCo','claims','Amazon''s breach','acknowledge','secondary','applicable insurance','pursue insurance','before seeking','indemnification','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Insurance priority", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Insurance priority for Amazon indemnity claims is reasonable given Amazon typically requires production insurance. Doesn''t eliminate Amazon obligation, just orders recovery."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall indemnify ProdCo for claims arising from Amazon''s breach. This indemnification shall survive termination of this Agreement for a period of three (3) years, except for claims based on fraud or willful misconduct, which shall survive indefinitely.', ARRAY['Amazon','indemnify','ProdCo','claims','Amazon''s breach','survive termination','three years','except','fraud','willful misconduct','survive indefinitely']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Three-year survival with fraud exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Three-year survival for Amazon indemnity with fraud/willful misconduct exception is reasonable limitation. ProdCo indemnity typically survives longer due to content nature."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify and hold harmless ProdCo from and against any and all claims, damages, losses, costs and expenses arising from or relating to Amazon''s exploitation of the Program, including claims of infringement, defamation, or privacy violation.', ARRAY['Amazon','indemnify','hold harmless','ProdCo','any and all claims','damages','losses','costs','arising from','relating to','Amazon''s exploitation','Program','infringement','defamation','privacy']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Broad exploitation indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Amazon cannot indemnify for exploitation claims\u2014these arise from Program content which is ProdCo''s responsibility. This would effectively shift all content liability to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify ProdCo against all claims arising from the Program to the same extent and scope as ProdCo indemnifies Amazon. The parties'' indemnification obligations shall be mutual and equivalent.', ARRAY['Amazon','indemnify','ProdCo','all claims','arising from','Program','same extent','scope','ProdCo indemnifies','Amazon','mutual','equivalent']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Mirror indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mirror indemnity ignores fundamental asymmetry\u2014ProdCo creates content, Amazon exploits. Content claims are ProdCo''s responsibility. Equivalence is inappropriate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify ProdCo against claims arising from: (a) Amazon''s breach; (b) Amazon''s modifications to the Program after delivery; (c) Amazon''s marketing and promotional activities; (d) Amazon''s distribution and licensing activities; and (e) Amazon''s exploitation decisions.', ARRAY['Amazon','indemnify','ProdCo','claims','Amazon''s breach','modifications','after delivery','marketing','promotional','distribution','licensing','exploitation decisions']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Expansive operational indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Expansive indemnity for modifications, marketing, distribution, and exploitation shifts content liability to Amazon. These claims typically arise from content ProdCo created."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification shall cover all claims that ProdCo could not have anticipated or prevented through its clearance processes, as the risk of such claims should properly rest with the party that controls exploitation.', ARRAY['Amazon''s indemnification','all claims','ProdCo could not have anticipated','prevented','clearance processes','risk','rest with','party','controls exploitation']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Unanticipated claims indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Could not have anticipated'' standard is impossible to administer and would shift virtually all claims to Amazon. ProdCo is responsible for content clearance regardless of anticipation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify ProdCo against claims arising from the Program in any territory where Amazon exploits the Program without ProdCo''s express written consent, as ProdCo cannot warrant clearance for unauthorized exploitation territories.', ARRAY['Amazon','indemnify','ProdCo','claims','Program','territory','Amazon exploits','without','ProdCo''s consent','warrant clearance','unauthorized','territories']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Territorial consent-based indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Amazon has worldwide exploitation rights and doesn''t need ProdCo consent for territories. Conditioning indemnification on consent flips the rights structure entirely."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify ProdCo for claims arising from Amazon''s failure to obtain proper clearances for exploitation of the Program. ProdCo''s clearance obligations relate only to production; exploitation clearances are Amazon''s responsibility.', ARRAY['Amazon','indemnify','ProdCo','claims','Amazon''s failure','obtain clearances','exploitation','Program','ProdCo''s clearance','production only','exploitation clearances','Amazon''s responsibility']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Split clearance responsibility", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo clears content for all exploitation, not just production. This attempts to split clearance responsibility in a way that shifts content liability to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall indemnify ProdCo against claims arising from the Program to the extent E&O insurance does not cover such claims. Amazon''s indemnification shall function as excess coverage above insurance limits.', ARRAY['Amazon','indemnify','ProdCo','claims','Program','to the extent','E&O insurance','does not cover','Amazon''s indemnification','excess coverage','above insurance']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Amazon as excess insurer", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Making Amazon the excess insurer for Program claims shifts content liability to Amazon for claims above insurance limits. ProdCo bears this responsibility, not Amazon."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding any Amazon indemnification obligation, Amazon shall have no obligation to indemnify ProdCo for any claim arising from or relating to: (a) the Program or any Materials; (b) any act or omission of ProdCo; (c) any breach by ProdCo of this Agreement; or (d) any matter for which ProdCo is obligated to indemnify Amazon.', ARRAY['notwithstanding','Amazon indemnification','no obligation','indemnify ProdCo','claim','arising from','relating to','Program','Materials','act','omission','ProdCo','breach','ProdCo obligated','indemnify Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "Standard exclusions from Amazon indemnity", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard exclusions ensuring Amazon doesn''t indemnify for Program content, ProdCo conduct, ProdCo breach, or ProdCo-indemnified matters. Essential carveouts."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s indemnification expressly excludes claims based upon: (i) the content of the Program, including any allegations of infringement, defamation, privacy violation, or moral rights; (ii) ProdCo''s production activities; (iii) ProdCo''s personnel; or (iv) any underlying rights or clearances.', ARRAY['Amazon''s indemnification','expressly excludes','claims','content','Program','infringement','defamation','privacy','moral rights','production activities','personnel','underlying rights','clearances']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "Content claims exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly excludes content-based claims (infringement, defamation, privacy, moral rights) from Amazon''s indemnity. These are ProdCo''s core responsibilities."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall not be obligated to indemnify ProdCo for any claim that arises from or relates to any representation, warranty, covenant or obligation of ProdCo under this Agreement, regardless of whether Amazon''s actions contributed to such claim.', ARRAY['Amazon','not obligated','indemnify ProdCo','claim','arises from','relates to','representation','warranty','covenant','obligation','ProdCo','regardless','Amazon''s actions','contributed']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "ProdCo obligation exclusion even with Amazon contribution", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Excludes claims relating to ProdCo obligations even if Amazon contributed. ProdCo''s representations create primary responsibility regardless of Amazon''s role."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Exclusions from Amazon indemnification include: claims arising from the Program as delivered by ProdCo; claims arising from Materials created by ProdCo; claims relating to ProdCo''s chain of title; claims involving ProdCo''s personnel or contractors; and claims based on facts that would trigger ProdCo''s indemnity.', ARRAY['Exclusions','Amazon indemnification','claims','Program as delivered','Materials created','chain of title','personnel','contractors','claims','facts','trigger ProdCo''s indemnity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "Enumerated exclusions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of exclusions covering delivered content, created materials, chain of title, personnel, and ProdCo-indemnified matters."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For the avoidance of doubt, Amazon''s indemnification shall not apply to any claim that would not have arisen but for the content of the Program or ProdCo''s creation of such content. The risk of content-related claims rests with ProdCo as the content creator.', ARRAY['avoidance of doubt','Amazon''s indemnification','not apply','claim','would not have arisen','but for','content','Program','ProdCo''s creation','risk','content-related claims','rests with ProdCo','content creator']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "But-for causation exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''But for'' causation test ensures content-caused claims are excluded from Amazon''s indemnity. Explicitly assigns content risk to ProdCo as creator."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s indemnification does not cover claims relating to: (a) any inaccuracy in ProdCo''s representations; (b) any failure by ProdCo to perform its obligations; (c) any negligent or wrongful act of ProdCo; (d) any infringement, defamation, or privacy claim arising from Program content; or (e) any production-related claim.', ARRAY['Amazon''s indemnification','does not cover','inaccuracy','ProdCo''s representations','failure','perform obligations','negligent','wrongful act','infringement','defamation','privacy','Program content','production-related claim']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "Comprehensive claim type exclusions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive exclusion covering ProdCo rep inaccuracy, performance failure, negligence/wrongful acts, content claims, and production claims. Complete protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall not indemnify ProdCo for claims arising from Amazon''s exercise of any right expressly granted under this Agreement, including Amazon''s right to edit, modify, adapt, or otherwise alter the Program. Such exercise of rights shall not constitute breach triggering indemnification.', ARRAY['Amazon','not indemnify','ProdCo','claims','Amazon''s exercise','right expressly granted','edit','modify','adapt','alter','Program','exercise of rights','not constitute breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Amazon Indemnification", "note": "Rights exercise exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s exercise of granted rights (edit, modify, adapt) cannot trigger indemnification. These are rights ProdCo has granted, not Amazon breaches."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification excludes content claims except to the extent such claims arise solely and directly from Amazon''s post-delivery modifications that introduce new infringing or defamatory material not present in ProdCo''s delivered Program.', ARRAY['Amazon''s indemnification','excludes','content claims','except','solely and directly','Amazon''s post-delivery modifications','introduce','new infringing','defamatory material','not present','delivered Program']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Amazon modification exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Exception for Amazon-introduced infringing/defamatory material is fair allocation. ''Solely and directly'' and ''not present'' qualifiers appropriately limit scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Exclusions from Amazon''s indemnity include content claims. However, if Amazon''s marketing materials contain statements about the Program that are false or misleading and not derived from ProdCo-provided materials, Amazon shall be responsible for claims arising therefrom.', ARRAY['Exclusions','Amazon''s indemnity','content claims','however','Amazon''s marketing','statements','false','misleading','not derived','ProdCo-provided','Amazon responsible','claims','arising therefrom']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Amazon marketing statement exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon responsibility for its own false/misleading marketing statements not derived from ProdCo materials is fair. Amazon controls its marketing."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Content claims are excluded from Amazon''s indemnity. If a content claim arises from Amazon''s direction to include specific material that ProdCo objected to in writing prior to inclusion, and such material is the sole basis for the claim, Amazon''s exclusion shall not apply to that claim.', ARRAY['Content claims','excluded','Amazon''s indemnity','claim arises','Amazon''s direction','specific material','ProdCo objected','writing','prior to inclusion','sole basis','claim','exclusion','not apply']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Written objection exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Exception for material ProdCo objected to in writing is fair if narrowly applied. ''Sole basis'' requirement prevents abuse. Incentivizes ProdCo to document objections."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification excludes production and content claims. The parties agree to maintain records of any instances where Amazon directs inclusion of specific material over ProdCo''s documented clearance concerns, and such matters shall be addressed separately if claims arise.', ARRAY['Amazon''s indemnification','excludes','production','content claims','maintain records','Amazon directs','specific material','documented clearance concerns','addressed separately','claims arise']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Record-keeping for directed content", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Record-keeping for Amazon-directed content over clearance concerns provides documentation without automatically shifting liability. ''Addressed separately'' preserves flexibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnity excludes content claims. If Amazon supplies materials for inclusion in the Program (as documented per Section [X]), claims arising solely from such Amazon-supplied materials shall not be subject to this exclusion.', ARRAY['Amazon''s indemnity','excludes','content claims','Amazon supplies','materials','inclusion','documented','claims','solely','Amazon-supplied materials','not subject','exclusion']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Amazon-supplied materials exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Exception for claims arising solely from documented Amazon-supplied materials is appropriate reciprocal to ProdCo''s rep exception for Amazon-supplied materials."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Exclusions from Amazon indemnification include all content and production claims. The exclusions shall not apply to claims arising from Amazon''s willful misconduct in connection with exploitation of the Program, which shall be subject to Amazon''s indemnification regardless of claim type.', ARRAY['Exclusions','Amazon indemnification','content','production claims','not apply','claims','Amazon''s willful misconduct','exploitation','Program','subject to','indemnification','regardless','claim type']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Willful misconduct override", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Willful misconduct override of exclusions is reasonable. Amazon shouldn''t benefit from exclusions if claims arise from Amazon''s intentional wrongdoing."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification exclusions shall not apply if Amazon approved the content giving rise to the claim. Amazon''s approval of any content, script, or Material shall constitute Amazon''s assumption of responsibility for claims arising therefrom.', ARRAY['Amazon''s indemnification','exclusions','not apply','Amazon approved','content','claim','Amazon''s approval','content','script','Material','assumption of responsibility','claims']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Approval as responsibility assumption", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Amazon approval does not shift content responsibility. Amazon approves for its own purposes; content clearance remains ProdCo''s obligation. This would gut all exclusions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exclusions from Amazon''s indemnity apply only to claims that ProdCo could reasonably have prevented through its clearance processes. Claims arising from sophisticated or latent issues that ProdCo could not reasonably have identified shall be Amazon''s responsibility.', ARRAY['Exclusions','Amazon''s indemnity','only','claims','ProdCo could reasonably have prevented','clearance','sophisticated','latent issues','not reasonably identified','Amazon''s responsibility']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Reasonableness override of exclusions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Could not reasonably have identified'' exception is impossible to administer and shifts difficult claims to Amazon. ProdCo is responsible for clearance regardless of difficulty."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s exclusions shall not apply to claims arising in territories where Amazon''s exploitation extends beyond ProdCo''s clearance scope. ProdCo''s clearance is limited to territories expressly identified in Exhibit A; claims from other territories are Amazon''s responsibility.', ARRAY['Amazon''s exclusions','not apply','claims','territories','exploitation extends beyond','clearance scope','ProdCo''s clearance','limited','territories','Exhibit A','other territories','Amazon''s responsibility']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Territorial clearance limitation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo clears for worldwide exploitation. Attempting to limit clearance to scheduled territories and shift remaining territory risk to Amazon is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnity exclusions are subject to ProdCo''s compliance with all clearance best practices. If ProdCo has complied with industry-standard clearance procedures, any claim arising despite such compliance shall be excluded from ProdCo''s indemnity and included in Amazon''s indemnity.', ARRAY['Amazon''s indemnity exclusions','subject to','ProdCo''s compliance','clearance best practices','complied','industry-standard','clearance procedures','claim','despite compliance','excluded','ProdCo''s indemnity','included','Amazon''s indemnity']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Best practices compliance shift", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Compliance with clearance procedures doesn''t eliminate ProdCo''s content liability. Claims can arise from proper clearance; ProdCo still represents and warrants non-infringement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s exclusions for content claims shall sunset three (3) years after initial release. After such period, content claims shall be Amazon''s responsibility as the ongoing exploiter of the Program with continuing benefit from exploitation.', ARRAY['Amazon''s exclusions','content claims','sunset','three years','initial release','after period','content claims','Amazon''s responsibility','ongoing exploiter','continuing benefit','exploitation']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Time-limited exclusions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Content exclusions cannot sunset. Content liability persists throughout exploitation regardless of time. Three-year limit would shift perpetual content risk to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exclusions from Amazon''s indemnity shall be proportionate. If a claim involves both excluded content issues and non-excluded Amazon conduct issues, exclusions shall apply only to the portion of the claim attributable to content, with Amazon indemnifying for the remainder.', ARRAY['Exclusions','Amazon''s indemnity','proportionate','claim','excluded content issues','non-excluded','Amazon conduct','exclusions apply','portion','attributable to content','Amazon indemnifying','remainder']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Proportionate exclusions", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Proportionate exclusions create complex allocation disputes for every claim. Content exclusions should be categorical, not proportional. This invites litigation over allocation."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'To receive Amazon indemnification, ProdCo shall: (a) provide Amazon with prompt written notice of any claim; (b) grant Amazon sole control of the defense and settlement of such claim; (c) cooperate fully with Amazon''s defense at Amazon''s expense; and (d) not make any admission or settlement without Amazon''s prior written consent.', ARRAY['Amazon indemnification','ProdCo','prompt written notice','claim','grant Amazon','sole control','defense','settlement','cooperate fully','Amazon''s expense','no admission','settlement','prior written consent']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Standard indemnification procedures", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard indemnification procedures including notice, Amazon control of defense/settlement, cooperation, and no unauthorized admissions/settlements. Appropriate for Amazon-controlled claims."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s right to Amazon indemnification is conditioned upon: (i) ProdCo providing notice to Amazon within ten (10) business days of receiving any claim; (ii) ProdCo not taking any position adverse to Amazon''s interests; (iii) ProdCo providing Amazon with all relevant information and documents; and (iv) ProdCo cooperating with Amazon''s selected counsel.', ARRAY['right to','Amazon indemnification','conditioned','notice','ten business days','receiving claim','not taking position','adverse','Amazon''s interests','relevant information','documents','cooperating','Amazon''s counsel']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Notice timeline and conditions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Ten-day notice requirement and enumerated conditions are clear and reasonable. Adverse position prohibition and document production requirements are standard."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have the right to control the defense and settlement of any claim for which Amazon provides indemnification. Amazon may select counsel, determine strategy, and settle claims in Amazon''s sole discretion. ProdCo shall not interfere with or obstruct Amazon''s defense.', ARRAY['Amazon','control','defense','settlement','claim','indemnification','select counsel','determine strategy','settle','sole discretion','ProdCo','not interfere','obstruct','defense']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Amazon defense control", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s control over defense and settlement of indemnified claims is appropriate. Indemnifying party should control defense to manage exposure. ProdCo non-interference is standard."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Failure to provide timely notice of a claim shall not relieve Amazon of its indemnification obligation except to the extent Amazon is actually prejudiced by such failure. ProdCo shall bear the burden of demonstrating that Amazon was not prejudiced by late notice.', ARRAY['Failure','timely notice','not relieve','Amazon','indemnification','except','actually prejudiced','failure','ProdCo','burden','demonstrating','not prejudiced','late notice']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Prejudice-based notice failure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Prejudice-based notice failure standard with burden on ProdCo is balanced approach. Protects Amazon from late notice harm while not requiring forfeiture for minor delays."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall cooperate with Amazon''s defense of any indemnified claim, including making personnel available for depositions and testimony, providing documents and information, and assisting with factual investigation. Amazon shall reimburse ProdCo''s reasonable out-of-pocket costs for such cooperation.', ARRAY['cooperate','Amazon''s defense','indemnified claim','personnel','depositions','testimony','documents','information','factual investigation','reimburse','reasonable','out-of-pocket costs','cooperation']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Cooperation with cost reimbursement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Detailed cooperation requirements with cost reimbursement is fair. ProdCo assists defense; Amazon covers ProdCo''s cooperation costs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may settle any indemnified claim without ProdCo''s consent, provided that any settlement that includes an admission of liability by ProdCo or imposes any ongoing obligation on ProdCo shall require ProdCo''s prior written consent, which shall not be unreasonably withheld.', ARRAY['Amazon','settle','indemnified claim','without','ProdCo''s consent','provided','settlement','admission of liability','ProdCo','ongoing obligation','require','prior written consent','not unreasonably withheld']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Settlement with ProdCo admission/obligation consent", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon settlement discretion with consent requirement for ProdCo admissions or ongoing obligations is balanced. Protects ProdCo from settlements affecting its interests."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Written notice to Amazon shall include: (a) a copy of the claim or demand; (b) a description of the facts underlying the claim; (c) ProdCo''s assessment of the claim''s relationship to Amazon''s indemnification obligations; and (d) any other relevant information in ProdCo''s possession.', ARRAY['Written notice','Amazon','copy','claim','demand','description','facts','ProdCo''s assessment','relationship','Amazon''s indemnification','relevant information','possession']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Notice content requirements", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notice content requirements ensure Amazon receives sufficient information to evaluate and respond to claims. ProdCo assessment requirement aids initial evaluation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall provide prompt notice of claims. Amazon shall notify ProdCo within fifteen (15) business days whether Amazon will assume defense of the claim. If Amazon does not assume defense, ProdCo may defend with counsel of its choosing at Amazon''s expense.', ARRAY['prompt notice','claims','Amazon notify','ProdCo','fifteen business days','assume defense','Amazon does not assume','ProdCo may defend','counsel','choosing','Amazon''s expense']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Defense assumption timeline", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Fifteen-day window for Amazon''s defense assumption decision is reasonable. ProdCo''s right to defend if Amazon doesn''t assume is fair given Amazon''s indemnification obligation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon controls defense of indemnified claims. ProdCo shall have the right to participate in the defense at its own expense with counsel of its choosing, provided that ProdCo''s participation shall not interfere with Amazon''s control of the defense or settlement.', ARRAY['Amazon controls','defense','indemnified claims','ProdCo','right to participate','own expense','counsel','choosing','not interfere','Amazon''s control','defense','settlement']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "ProdCo participation right", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "ProdCo''s participation right at own expense without interfering with Amazon''s control is reasonable. Allows ProdCo visibility into defense without undermining Amazon''s management."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall keep ProdCo reasonably informed of the status of any indemnified claim, including significant developments, settlement discussions, and strategic decisions. ProdCo''s input shall be considered in good faith but Amazon shall retain final decision-making authority.', ARRAY['Amazon','keep ProdCo','reasonably informed','status','indemnified claim','significant developments','settlement discussions','strategic decisions','ProdCo''s input','considered','good faith','Amazon','final decision-making authority']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Information and input rights", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Information rights and good faith consideration of ProdCo input are reasonable additions that don''t undermine Amazon''s control. Final authority remains with Amazon."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall provide notice of claims within thirty (30) days of receipt. Failure to provide notice within such period shall reduce Amazon''s indemnification obligation by the amount of any losses or costs that Amazon demonstrates would have been avoided with timely notice.', ARRAY['notice','claims','thirty days','receipt','failure','notice','reduce','Amazon''s indemnification','amount','losses','costs','Amazon demonstrates','avoided','timely notice']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Proportionate reduction for late notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Proportionate reduction for late notice based on demonstrated avoidable losses is fair compared to full forfeiture. Thirty-day window is reasonable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may settle claims in its discretion. If Amazon proposes to settle a claim on terms that would require ProdCo to cease any activity or admit any wrongdoing, Amazon shall consult with ProdCo prior to accepting such settlement, and ProdCo may reject such settlement if the proposed terms are unreasonable.', ARRAY['Amazon','settle','discretion','proposes','settlement','require ProdCo','cease activity','admit wrongdoing','consult','ProdCo','prior to accepting','ProdCo may reject','terms','unreasonable']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Settlement with activity/admission consultation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation and rejection right for settlements affecting ProdCo''s activities or requiring admissions is fair protection. ''Unreasonable'' standard provides objective measure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The parties shall cooperate on indemnification procedures. If a claim appears to involve both Amazon indemnification and ProdCo indemnification triggers, the parties shall consult in good faith to coordinate defense and allocate costs appropriately pending resolution of coverage issues.', ARRAY['cooperate','indemnification procedures','claim','involves','Amazon indemnification','ProdCo indemnification','triggers','consult','good faith','coordinate defense','allocate costs','pending resolution','coverage issues']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Mixed-claim coordination", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Coordination mechanism for claims with mixed indemnification triggers is practical. Good faith allocation pending resolution addresses common real-world scenario."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall have the right to control the defense of any claim for which ProdCo seeks Amazon indemnification. ProdCo shall select counsel and determine strategy, and Amazon shall reimburse ProdCo''s costs. Amazon may not assume defense over ProdCo''s objection.', ARRAY['ProdCo','right to control','defense','claim','seeks Amazon indemnification','select counsel','determine strategy','Amazon reimburse','costs','Amazon may not','assume defense','ProdCo''s objection']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "ProdCo defense control", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo cannot control defense of Amazon-indemnified claims. Indemnifying party (Amazon) must control defense to manage its exposure. This inverts proper indemnification structure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall not settle any indemnified claim without ProdCo''s prior written consent, which consent may be withheld in ProdCo''s sole discretion for any reason.', ARRAY['Amazon','not settle','indemnified claim','without','ProdCo''s prior written consent','withheld','ProdCo''s sole discretion','any reason']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "ProdCo settlement veto", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo veto over settlement in ''sole discretion for any reason'' gives ProdCo inappropriate control over Amazon''s exposure. Amazon needs settlement discretion for claims it indemnifies."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall provide notice of claims when practicable. Failure to provide timely notice shall not affect Amazon''s indemnification obligation under any circumstances, as ProdCo should not lose coverage for administrative lapses.', ARRAY['notice','claims','when practicable','failure','timely notice','not affect','Amazon''s indemnification','any circumstances','not lose coverage','administrative lapses']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "No notice consequence", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Eliminating all consequences for notice failure removes Amazon''s ability to protect itself. Timely notice is essential for proper defense. Some consequence for failure is required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall respond to indemnification requests within five (5) business days. Failure to respond shall constitute acceptance of the indemnification request and assumption of all related costs and defense obligations.', ARRAY['Amazon','respond','indemnification requests','five business days','failure to respond','constitute acceptance','indemnification request','assumption','all related costs','defense obligations']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Deemed acceptance for non-response", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Five-day deemed acceptance is unreasonable. Amazon needs adequate time to evaluate claims. Deemed acceptance for non-response could create liability for non-indemnifiable claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may settle any claim for which Amazon indemnification is sought without Amazon''s consent if the settlement amount is less than $100,000. Amazon shall reimburse such settlements promptly upon ProdCo''s request with documentation.', ARRAY['ProdCo may settle','claim','Amazon indemnification','without','Amazon''s consent','settlement amount','less than $100,000','Amazon reimburse','settlements','promptly','request','documentation']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "ProdCo settlement without consent below threshold", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo settlement authority without consent removes Amazon''s control over its indemnification exposure. Amazon cannot be forced to reimburse settlements it didn''t approve."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification obligation shall be triggered upon ProdCo''s assertion that a claim falls within Amazon''s indemnification scope. Amazon may not dispute such assertion except through binding arbitration, and Amazon shall fund defense pending arbitration resolution.', ARRAY['Amazon''s indemnification','triggered','ProdCo''s assertion','claim','indemnification scope','Amazon may not dispute','except','binding arbitration','fund defense','pending','arbitration resolution']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "ProdCo-triggered indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo''s unilateral assertion triggering indemnification with Amazon funding pending arbitration completely inverts proper indemnification structure. Amazon must determine if claims are indemnifiable."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s aggregate liability under this indemnification provision shall not exceed the total fees actually paid by Amazon to ProdCo under this Agreement. This limitation shall not apply to Amazon''s fraud or willful misconduct.', ARRAY['Amazon''s aggregate liability','indemnification','not exceed','total fees','actually paid','Amazon','ProdCo','limitation','not apply','Amazon''s fraud','willful misconduct']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Fees-paid cap with fraud/willful misconduct exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Cap at fees paid is reasonable limitation on Amazon''s exposure. Fraud/willful misconduct exception preserves accountability for serious conduct. Standard commercial limitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification liability shall be subject to an aggregate cap of [specified amount]. This cap shall apply to all claims in the aggregate, not per claim. Claims arising from Amazon''s gross negligence or willful misconduct shall not be subject to this cap.', ARRAY['Amazon''s indemnification','liability','aggregate cap','specified amount','all claims','aggregate','not per claim','claims','gross negligence','willful misconduct','not subject to','cap']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Fixed aggregate cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Fixed aggregate cap with gross negligence/willful misconduct exception is appropriate limitation. Aggregate (not per-claim) basis provides predictable exposure limit."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability under the indemnification provisions shall be limited to direct damages and shall not include consequential, incidental, special, punitive or exemplary damages, lost profits, or loss of business opportunity, regardless of whether such damages were foreseeable.', ARRAY['Amazon''s liability','indemnification','limited','direct damages','not include','consequential','incidental','special','punitive','exemplary','lost profits','loss of business opportunity','regardless','foreseeable']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Consequential damages exclusion", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Consequential damages exclusion is standard commercial limitation. Direct damages limitation provides reasonable protection while covering actual third-party claim costs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Any liability cap on Amazon''s indemnification shall not apply to: (a) claims arising from Amazon''s breach of confidentiality; (b) claims arising from Amazon''s violation of applicable law; (c) Amazon''s fraud; or (d) Amazon''s willful misconduct.', ARRAY['liability cap','Amazon''s indemnification','not apply','claims','breach of confidentiality','violation','applicable law','fraud','willful misconduct']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Super-cap exceptions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Exceptions to cap for confidentiality breach, legal violations, fraud, and willful misconduct are standard commercial terms that preserve accountability for serious matters."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s total liability to ProdCo under this Agreement, including under the indemnification provisions, shall not exceed [2x/3x] the Production Fee. This limitation applies to all claims arising under or relating to this Agreement in the aggregate.', ARRAY['Amazon''s total liability','ProdCo','Agreement','including','indemnification','not exceed','2x/3x','Production Fee','limitation','all claims','aggregate']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Multiple of Production Fee cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Cap at multiple of Production Fee provides reasonable ceiling tied to deal economics. Applies to all claims, providing comprehensive limitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification liability shall be reduced by amounts recovered by ProdCo from insurance or other sources. ProdCo shall use commercially reasonable efforts to pursue available insurance coverage before seeking payment from Amazon under this indemnification.', ARRAY['Amazon''s indemnification','liability','reduced','amounts recovered','ProdCo','insurance','other sources','commercially reasonable efforts','pursue','insurance coverage','before seeking','payment','Amazon']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Insurance offset", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Insurance offset reduces Amazon''s exposure and requires ProdCo to pursue available coverage. Prevents double recovery while ensuring ProdCo is made whole."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability for indemnified claims shall be subject to an annual cap equal to the lesser of (a) the total fees paid in the applicable contract year, or (b) $[amount]. This cap resets annually on the anniversary of the Effective Date.', ARRAY['Amazon''s liability','indemnified claims','annual cap','lesser of','total fees','applicable contract year','amount','cap resets','annually','anniversary','Effective Date']::text[], '{"doc": "PSA_Fallbacks", "section": "Amazon Indemnification", "note": "Annual resetting cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Annual resetting cap provides ongoing protection while limiting single-year exposure. Appropriate for multi-year or series deals."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification liability shall be capped at the greater of (a) the total fees paid to ProdCo, or (b) $1,000,000. This cap shall not apply to fraud, willful misconduct, or breach of Amazon''s representations regarding authority.', ARRAY['Amazon''s indemnification','liability','capped','greater of','total fees','$1,000,000','cap','not apply','fraud','willful misconduct','breach','representations','authority']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Greater-of cap with floor", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Floor amount ($1M) ensures minimum coverage regardless of fee level. ''Greater of'' formula benefits ProdCo for larger deals. Exceptions are standard."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification cap applies to monetary damages only. Equitable relief, including specific performance and injunctive relief, shall be available to ProdCo without regard to any cap, if ProdCo demonstrates irreparable harm.', ARRAY['Amazon''s indemnification','cap','monetary damages only','equitable relief','specific performance','injunctive relief','available','without regard to','cap','irreparable harm']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Equitable relief exception to cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carving equitable relief from cap is standard commercial approach. Doesn''t expand monetary exposure but preserves non-monetary remedies."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability is capped as set forth in this Agreement. The cap shall be adjusted upward by 10% for each full year following the Effective Date to account for inflation, not to exceed 150% of the original cap amount.', ARRAY['Amazon''s liability','capped','adjusted upward','10%','each full year','Effective Date','account for inflation','not to exceed','150%','original cap amount']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Inflation adjustment to cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Inflation adjustment to cap is reasonable for long-term deals. 150% ceiling provides predictability while addressing real-value erosion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s aggregate indemnification liability is capped. If multiple Amazon entities are named in a claim, the cap shall apply to all Amazon entities collectively, not separately to each entity. Joint and several claims shall be subject to a single cap.', ARRAY['Amazon''s aggregate','indemnification','liability','capped','multiple Amazon entities','claim','cap','collectively','not separately','joint and several','single cap']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Multi-entity cap clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification that cap applies collectively to all Amazon entities prevents stacking of caps. Single cap for joint claims is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification liability shall be capped at the Production Fee. If the claim arises from conduct occurring after final delivery, the cap shall be the greater of (a) the Production Fee, or (b) twelve (12) months of exploitation revenue attributable to the Program.', ARRAY['Amazon''s indemnification','capped','Production Fee','claim arises','after final delivery','cap','greater of','Production Fee','twelve months','exploitation revenue','attributable','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Revenue-based cap for post-delivery claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Revenue-based alternative cap for post-delivery claims acknowledges ongoing exploitation value. Provides additional coverage for exploitation-phase issues."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s indemnification shall be subject to an aggregate cap. The cap shall not reduce amounts payable for defense costs; Amazon shall pay reasonable defense costs in addition to any capped liability for judgments or settlements.', ARRAY['Amazon''s indemnification','aggregate cap','cap','not reduce','defense costs','Amazon','pay','reasonable defense costs','addition to','capped liability','judgments','settlements']::text[], '{"doc": "Counterparty_Markup", "section": "Amazon Indemnification", "note": "Defense costs outside cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Defense costs outside cap is common approach that ensures ProdCo can mount adequate defense regardless of ultimate liability outcome. May be acceptable depending on cap amount."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification shall be uncapped and unlimited. Amazon shall be liable for all losses, costs, and expenses arising from any indemnified claim without any limitation.', ARRAY['Amazon''s indemnification','uncapped','unlimited','Amazon','liable','all losses','costs','expenses','indemnified claim','without','limitation']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Uncapped Amazon indemnity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Uncapped Amazon indemnity creates unlimited exposure. Amazon''s indemnity scope is already narrow; reasonable cap is appropriate additional protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification cap shall be no less than ProdCo''s indemnification cap (if any). If ProdCo''s indemnification is uncapped, Amazon''s indemnification shall also be uncapped to maintain parity.', ARRAY['Amazon''s indemnification','cap','no less than','ProdCo''s indemnification cap','ProdCo''s indemnification','uncapped','Amazon''s indemnification','uncapped','maintain parity']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Forced cap parity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced parity ignores fundamental asymmetry. ProdCo''s content indemnity is appropriately uncapped; Amazon''s narrow indemnity appropriately has caps. Different scopes justify different limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification cap shall be equal to the total revenue generated by Amazon from exploitation of the Program. The cap shall increase as exploitation revenue increases.', ARRAY['Amazon''s indemnification','cap','equal to','total revenue','generated','Amazon','exploitation','Program','cap','increase','exploitation revenue increases']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Revenue-based expanding cap", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Revenue-based cap with unlimited upside creates unpredictable, potentially massive exposure. Cap must be fixed or tied to fees paid, not exploitation revenue."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s cap shall not apply to any claim that ProdCo asserts arises from Amazon''s breach. ProdCo''s good faith assertion that a claim is uncapped shall be dispositive unless Amazon proves such assertion was made in bad faith.', ARRAY['Amazon''s cap','not apply','claim','ProdCo asserts','arises from','Amazon''s breach','good faith assertion','uncapped','dispositive','unless','Amazon proves','bad faith']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "ProdCo-controlled cap exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo''s assertion eliminating cap unless Amazon proves bad faith gives ProdCo effective control over cap application. Completely undermines cap protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s indemnification cap applies only to the first claim asserted. Subsequent claims shall be uncapped, as a pattern of claims suggests systemic issues requiring Amazon accountability.', ARRAY['Amazon''s indemnification','cap','only','first claim','subsequent claims','uncapped','pattern of claims','systemic issues','Amazon accountability']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "First-claim-only cap", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting cap to first claim creates unlimited exposure for subsequent claims. Multiple claims could arise from single issue (multiple territories, claimants). Cap must apply to all claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability cap shall not include attorneys'' fees, defense costs, investigation expenses, or other litigation-related costs. Such costs shall be payable by Amazon without limit in addition to the capped damages.', ARRAY['Amazon''s liability cap','not include','attorneys'' fees','defense costs','investigation expenses','litigation-related costs','payable','Amazon','without limit','addition to','capped damages']::text[], '{"doc": "Counterparty_Proposal", "section": "Amazon Indemnification", "note": "Unlimited costs outside cap", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Unlimited costs outside cap could result in defense costs exceeding cap amount, potentially by multiples. Some cost limitation is needed for predictable exposure."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'IN NO EVENT SHALL AMAZON BE LIABLE TO PRODCO FOR ANY CONSEQUENTIAL, INDIRECT, INCIDENTAL, SPECIAL, PUNITIVE OR EXEMPLARY DAMAGES, INCLUDING WITHOUT LIMITATION LOST PROFITS, LOSS OF BUSINESS, LOSS OF GOODWILL, OR LOSS OF DATA, ARISING OUT OF OR RELATING TO THIS AGREEMENT, REGARDLESS OF THE THEORY OF LIABILITY.', ARRAY['Amazon','not liable','consequential','indirect','incidental','special','punitive','exemplary damages','lost profits','loss of business','goodwill','loss of data','regardless','theory of liability']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Standard Amazon consequential damages exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive exclusion of consequential and similar damages. Caps style formatting emphasizes importance. Covers key categories including lost profits and business losses."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall not be liable for any indirect, consequential, special, incidental or punitive damages of any kind, whether arising in contract, tort (including negligence), strict liability, or otherwise, even if Amazon has been advised of the possibility of such damages.', ARRAY['Amazon','not liable','indirect','consequential','special','incidental','punitive damages','contract','tort','negligence','strict liability','advised of possibility']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Multi-theory coverage with foreseeability waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers all liability theories (contract, tort, strict liability) and includes ''advised of possibility'' language to negate foreseeability-based claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding anything to the contrary in this Agreement, Amazon''s liability shall be limited to direct damages only. Amazon expressly disclaims and excludes all liability for consequential damages, special damages, punitive damages, incidental damages, indirect damages, lost revenues, lost profits, and damages for loss of use, business interruption, or loss of information or data.', ARRAY['Amazon''s liability','limited','direct damages only','disclaims','excludes','consequential','special','punitive','incidental','indirect','lost revenues','lost profits','loss of use','business interruption','loss of information','data']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Direct damages limitation with comprehensive exclusion list", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Affirmatively limits to direct damages while comprehensively listing excluded damage types. Business interruption and data loss explicitly covered."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have no liability for any consequential, indirect, incidental, special, exemplary or punitive damages, including damages for loss of profits, goodwill, use, data or other intangible losses, even if Amazon has been advised of the possibility of such damages. This exclusion applies to the maximum extent permitted by applicable law.', ARRAY['Amazon','no liability','consequential','indirect','incidental','special','exemplary','punitive','loss of profits','goodwill','use','data','intangible losses','advised of possibility','maximum extent','applicable law']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Intangible losses with maximum extent language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes intangible losses and ''maximum extent permitted by law'' language for jurisdictions with mandatory liability provisions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The exclusion of consequential damages set forth herein shall apply regardless of: (a) the form of action, whether in contract, warranty, tort, negligence, strict liability, or otherwise; (b) whether the damages were foreseeable; (c) whether Amazon was advised of the possibility of such damages; or (d) whether the limited remedy provided herein fails of its essential purpose.', ARRAY['exclusion','consequential damages','apply regardless of','form of action','contract','warranty','tort','negligence','strict liability','foreseeable','advised of possibility','limited remedy','fails','essential purpose']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Comprehensive applicability language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses key legal doctrines that could otherwise circumvent exclusion: theory of liability, foreseeability, notice, and failure of essential purpose."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges and agrees that the exclusion of consequential and other damages set forth herein is an essential element of the bargain between the parties, and that the fees and other terms of this Agreement reflect this allocation of risk. Amazon would not enter into this Agreement without such exclusion.', ARRAY['acknowledges','agrees','exclusion','consequential','damages','essential element','bargain','fees','terms','allocation of risk','would not enter','without exclusion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Bargained-for acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment that exclusion is bargained-for element reinforces enforceability and prevents unconscionability arguments."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'AMAZON EXCLUDES ALL LIABILITY FOR CONSEQUENTIAL, INDIRECT, SPECIAL, INCIDENTAL, AND PUNITIVE DAMAGES. For purposes of this exclusion, ''consequential damages'' includes, without limitation: lost profits; lost revenues; cost of substitute services; loss of data; loss of goodwill; business interruption; and any damages arising from third-party claims against ProdCo.', ARRAY['Amazon excludes','liability','consequential','indirect','special','incidental','punitive','consequential damages includes','lost profits','revenues','substitute services','loss of data','goodwill','business interruption','third-party claims']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Defined consequential damages", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Defines ''consequential damages'' to include specific categories, preventing disputes about what falls within the exclusion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon excludes liability for consequential, indirect, and punitive damages. This exclusion shall not apply to damages arising from Amazon''s fraud, willful misconduct, or gross negligence, for which Amazon shall remain liable under applicable law.', ARRAY['Amazon excludes','liability','consequential','indirect','punitive','exclusion','not apply','Amazon''s fraud','willful misconduct','gross negligence','remain liable','applicable law']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Fraud/willful misconduct/gross negligence exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Exceptions for fraud, willful misconduct, and gross negligence are common and generally acceptable. May be required in some jurisdictions anyway."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon excludes consequential and indirect damages. Notwithstanding the foregoing, this exclusion shall not apply to damages arising from Amazon''s breach of its payment obligations, which shall be recoverable as direct damages without limitation.', ARRAY['Amazon excludes','consequential','indirect','notwithstanding','exclusion','not apply','Amazon''s breach','payment obligations','recoverable','direct damages','without limitation']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Payment breach exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Payment breach exception is reasonable\u2014failure to pay is a direct breach with direct damages. Doesn''t actually expand consequential damages exposure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party excludes liability to the other for consequential, indirect, incidental, special, and punitive damages. This mutual exclusion applies equally to both parties and shall survive termination of this Agreement.', ARRAY['each party','excludes liability','other','consequential','indirect','incidental','special','punitive','mutual exclusion','equally','both parties','survive termination']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Mutual consequential damages exclusion", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual exclusion is acceptable as Amazon also benefits. Key is ensuring ProdCo''s indemnification obligations are not affected by this exclusion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon excludes consequential damages liability. This exclusion shall not apply to consequential damages that are the direct and proximate result of Amazon''s material breach of this Agreement and that were reasonably foreseeable at the time of contracting.', ARRAY['Amazon excludes','consequential damages','exclusion','not apply','direct','proximate result','Amazon''s material breach','reasonably foreseeable','time of contracting']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Material breach with foreseeability exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Material breach exception with foreseeability requirement is more limited than broad exception. Foreseeability at contracting time provides some predictability."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon excludes consequential and punitive damages. The parties acknowledge that certain statutory claims may not be subject to this exclusion under applicable law, and to the extent any such claim is not excludable, the exclusion shall not apply to such claim.', ARRAY['Amazon excludes','consequential','punitive','acknowledge','statutory claims','not subject to','exclusion','applicable law','not excludable','not apply']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Statutory non-excludable claims acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledgment of statutory non-excludable claims is practical reality in some jurisdictions. Preserves exclusion to maximum extent permitted."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s consequential damages exclusion shall apply. However, if Amazon''s breach causes ProdCo to lose a specific, documented third-party opportunity that ProdCo can prove with reasonable certainty, such lost opportunity damages may be recoverable as direct damages up to [specified cap].', ARRAY['Amazon''s consequential','exclusion','apply','however','Amazon''s breach','causes','lose','specific','documented','third-party opportunity','prove','reasonable certainty','recoverable','direct damages','cap']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Limited lost opportunity exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited, documented lost opportunity exception with cap may be acceptable. ''Specific, documented'' and ''reasonable certainty'' requirements limit exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon excludes consequential damages liability, except that this exclusion shall not apply to any damages arising from Amazon''s failure to release the Program, Amazon''s early termination of the Agreement, or Amazon''s decision not to order additional seasons.', ARRAY['Amazon excludes','consequential','except','not apply','damages','Amazon''s failure','release','Program','early termination','decision','not order','additional seasons']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Business decision exceptions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exceptions for non-release, termination, and season decisions would create massive exposure for Amazon''s core business discretion. These must be excluded."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party excludes consequential damages liability to the other. Notwithstanding the foregoing, this exclusion shall not affect ProdCo''s right to recover consequential damages for Amazon''s breach of any confidentiality, exclusivity, or credit obligations.', ARRAY['each party excludes','consequential damages','notwithstanding','not affect','ProdCo''s right','recover','consequential damages','Amazon''s breach','confidentiality','exclusivity','credit obligations']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Specific obligation exceptions", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Carving out confidentiality, exclusivity, and credit obligations from exclusion creates significant unpredictable exposure for specific breach categories."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s consequential damages exclusion applies only to damages that ProdCo cannot prove with documentary evidence. Consequential damages that ProdCo can prove through financial records, contracts, or other documentation shall be recoverable.', ARRAY['Amazon''s consequential','exclusion','applies only','cannot prove','documentary evidence','damages','prove','financial records','contracts','documentation','recoverable']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Documentary evidence exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting exclusion to unprovable damages effectively eliminates the exclusion. Most consequential damages can be documented to some degree."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon excludes consequential damages. This exclusion is subject to an aggregate floor of $500,000; consequential damages up to $500,000 are recoverable despite the exclusion, with only damages exceeding such amount being excluded.', ARRAY['Amazon excludes','consequential damages','exclusion','subject to','aggregate floor','$500,000','recoverable','despite exclusion','exceeding','excluded']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Dollar floor on exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Dollar floor effectively allows $500K in consequential damages, defeating purpose of exclusion. Exclusion must be absolute, not subject to minimums."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s consequential damages exclusion shall not apply if Amazon''s conduct giving rise to damages was unreasonable under the circumstances. ProdCo may recover consequential damages if Amazon acted unreasonably in breaching the Agreement.', ARRAY['Amazon''s consequential','exclusion','not apply','Amazon''s conduct','unreasonable','circumstances','ProdCo may recover','consequential damages','acted unreasonably','breaching']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Unreasonableness exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Unreasonable'' exception is subjective and could apply to virtually any breach. Would require litigating reasonableness for every claim, defeating exclusion purpose."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Consequential damages are excluded. However, ''consequential damages'' shall be narrowly construed and shall not include lost profits, lost revenues, or loss of business opportunity, which are deemed direct damages for purposes of this Agreement.', ARRAY['consequential damages','excluded','narrowly construed','not include','lost profits','lost revenues','loss of business opportunity','deemed','direct damages']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Recharacterization of consequential as direct", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Recharacterizing lost profits and revenues as ''direct damages'' completely guts the exclusion. These are classic consequential damages that must remain excluded."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'AMAZON''S TOTAL AGGREGATE LIABILITY ARISING OUT OF OR RELATING TO THIS AGREEMENT SHALL NOT EXCEED THE TOTAL FEES ACTUALLY PAID BY AMAZON TO PRODCO UNDER THIS AGREEMENT DURING THE TWELVE (12) MONTH PERIOD PRECEDING THE CLAIM.', ARRAY['Amazon''s total aggregate liability','arising out of','relating to','Agreement','not exceed','total fees','actually paid','Amazon','ProdCo','twelve month period','preceding claim']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Standard fees-paid cap with lookback", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard cap at fees paid with 12-month lookback period. Caps format emphasizes importance. Lookback provides reasonable limitation for long-term agreements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s maximum liability under this Agreement, whether arising in contract, tort, or otherwise, shall be limited to the aggregate amount of Production Fees paid by Amazon hereunder. This cap applies to all claims in the aggregate, not on a per-claim basis.', ARRAY['Amazon''s maximum liability','Agreement','contract','tort','otherwise','limited','aggregate amount','Production Fees','paid','cap applies','all claims','aggregate','not per-claim']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "All-theories cap with aggregate clarification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Covers all liability theories with explicit aggregate (not per-claim) application. Production Fees reference ties cap to deal value."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'In no event shall Amazon''s liability to ProdCo exceed [specified dollar amount] in the aggregate for all claims arising under or relating to this Agreement. This limitation applies regardless of the number of claims, causes of action, or theories of recovery.', ARRAY['Amazon''s liability','not exceed','specified dollar amount','aggregate','all claims','arising under','relating to','limitation applies','regardless','number of claims','causes of action','theories']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Fixed dollar cap", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Fixed dollar cap provides predictable exposure ceiling. Appropriate for deals where fee structure makes percentage cap impractical."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s total liability shall be capped at the greater of: (a) the Production Fee paid under this Agreement; or (b) $1,000,000. This cap shall not apply to Amazon''s payment obligations under Section [X] (Payment Terms).', ARRAY['Amazon''s total liability','capped','greater of','Production Fee','$1,000,000','cap','not apply','Amazon''s payment obligations','Payment Terms']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Greater-of cap with payment carveout", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Greater-of formula ensures minimum cap regardless of fee level. Payment obligation carveout is standard\u2014cap shouldn''t limit contractual payment obligations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s liability cap equals the fees paid hereunder. This cap does not apply to: (i) Amazon''s express payment obligations; (ii) amounts owed under Amazon''s indemnification obligations; or (iii) Amazon''s fraud or willful misconduct.', ARRAY['Amazon''s liability cap','equals','fees paid','cap does not apply','express payment obligations','amounts owed','indemnification obligations','fraud','willful misconduct']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Standard carveouts from cap", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard carveouts for payments, indemnification, and fraud/willful misconduct. Appropriate exceptions that don''t undermine core liability protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The liability cap herein reflects the parties'' agreed allocation of risk. ProdCo acknowledges that Amazon''s fees and other economic terms have been negotiated in light of this limitation, and that Amazon would not offer such terms absent this limitation.', ARRAY['liability cap','reflects','agreed allocation of risk','acknowledges','fees','economic terms','negotiated','in light of','limitation','would not offer','absent limitation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Risk allocation acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment reinforces enforceability by establishing that cap was bargained-for and reflected in pricing."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For series orders, Amazon''s liability cap shall be calculated on a per-season basis, with the cap for each season equal to the Production Fee paid for that season. Claims relating to multiple seasons shall be allocated proportionately.', ARRAY['series orders','Amazon''s liability cap','per-season basis','cap','each season','Production Fee','that season','claims','multiple seasons','allocated proportionately']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Per-season cap for series", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Per-season cap structure is appropriate for multi-season series deals. Proportionate allocation for multi-season claims is practical approach."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability is capped at fees paid hereunder. The cap shall increase by the amount of any documented out-of-pocket costs incurred by ProdCo in direct reliance on Amazon''s material breach, up to an additional 50% of the base cap.', ARRAY['Amazon''s liability','capped','fees paid','cap','increase','documented out-of-pocket costs','ProdCo','direct reliance','Amazon''s material breach','additional 50%','base cap']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Reliance costs addition to cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited increase for documented reliance costs is reasonable if capped at 50% of base cap. ''Direct reliance'' and ''documented'' requirements limit exposure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s aggregate liability shall not exceed the total fees paid. This cap shall be adjusted annually for inflation using the Consumer Price Index, with adjustments applied on each anniversary of the Effective Date.', ARRAY['Amazon''s aggregate liability','not exceed','total fees','cap','adjusted annually','inflation','Consumer Price Index','adjustments','anniversary','Effective Date']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Inflation adjustment to cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Inflation adjustment is reasonable for long-term deals to preserve real value of cap. CPI is objective standard. Requires Legal review of implementation mechanics."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability cap equals fees paid. If a claim arises after the initial release of the Program, the cap shall be the greater of (a) fees paid, or (b) an amount equal to six (6) months of Net Receipts attributable to the Program.', ARRAY['Amazon''s liability cap','equals','fees paid','claim arises','after initial release','cap','greater of','fees paid','six months','Net Receipts','attributable','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Post-release revenue-based cap alternative", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Revenue-based alternative for post-release claims acknowledges ongoing exploitation value. Six-month limitation contains exposure. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability is capped at fees paid. This cap shall apply separately to each distinct breach, such that the aggregate cap for multiple unrelated breaches shall equal the fees paid multiplied by the number of distinct breaches, not to exceed three times (3x) the fees paid in total.', ARRAY['Amazon''s liability','capped','fees paid','cap','apply separately','distinct breach','aggregate cap','multiple','unrelated breaches','multiplied','number of breaches','not to exceed','3x','total']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Per-breach cap with overall ceiling", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Per-breach cap with 3x overall ceiling provides some additional coverage for multiple distinct issues while maintaining overall limit. Complex to administer but capped."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s aggregate liability shall be capped at fees paid. Defense costs incurred by ProdCo in connection with third-party claims arising from Amazon''s breach shall be excluded from the cap and payable by Amazon in addition to capped amounts.', ARRAY['Amazon''s aggregate liability','capped','fees paid','defense costs','ProdCo','third-party claims','Amazon''s breach','excluded from cap','payable','Amazon','addition to','capped amounts']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Defense costs outside cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Defense costs outside cap for third-party claims from Amazon breach is reasonable given Amazon''s indemnification structure. Ensures ProdCo can adequately defend."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s liability is capped at the Production Fee. For purposes of calculating the cap, ''Production Fee'' shall include all amounts paid by Amazon to ProdCo under this Agreement, including any bonuses, adjustments, or additional payments.', ARRAY['Amazon''s liability','capped','Production Fee','calculating','cap','Production Fee','include','all amounts paid','Amazon','ProdCo','bonuses','adjustments','additional payments']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Inclusive cap calculation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Inclusive definition of Production Fee for cap purposes benefits ProdCo and is fair\u2014cap should relate to total deal value."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability cap shall equal the total exploitation revenue generated by Amazon from the Program. The cap shall increase as exploitation continues, with no upper limit.', ARRAY['Amazon''s liability cap','equal','total exploitation revenue','generated','Amazon','Program','cap','increase','exploitation continues','no upper limit']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Revenue-based unlimited cap", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Revenue-based cap with no upper limit creates unlimited, unpredictable exposure. Cap must be fixed or tied to fees paid, not open-ended revenue."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability shall be capped at fees paid. This cap shall not apply to any claim where ProdCo can demonstrate that the damages suffered exceed the cap amount, in which case Amazon''s liability shall equal actual damages.', ARRAY['Amazon''s liability','capped','fees paid','cap','not apply','claim','ProdCo can demonstrate','damages','exceed','cap amount','Amazon''s liability','equal','actual damages']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Actual damages exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exception for claims exceeding cap defeats entire purpose of cap. Cap applies precisely to limit exposure when damages are large."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability is capped at fees paid. However, if Amazon''s breach is determined to be material, the cap shall not apply, and Amazon shall be liable for actual damages without limitation.', ARRAY['Amazon''s liability','capped','fees paid','however','Amazon''s breach','material','cap','not apply','Amazon','liable','actual damages','without limitation']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Material breach exception to cap", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Material breach exception eliminates cap for exactly the claims it''s meant to address. Material breaches are the high-damage scenarios where cap is most needed."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s and ProdCo''s liability caps shall be equivalent. If Amazon''s cap is set at fees paid, ProdCo''s cap shall also be set at fees paid. Any asymmetry in caps shall be prohibited.', ARRAY['Amazon''s','ProdCo''s','liability caps','equivalent','Amazon''s cap','fees paid','ProdCo''s cap','fees paid','asymmetry','caps','prohibited']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Forced cap equivalence", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced cap equivalence ignores that ProdCo''s content obligations create different risk profile than Amazon''s. Amazon''s cap on ProdCo would limit indemnification recovery."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability cap shall be the lesser of (a) fees paid, or (b) $100,000. This cap applies to all claims including indemnification claims and payment disputes.', ARRAY['Amazon''s liability cap','lesser of','fees paid','$100,000','cap applies','all claims','including','indemnification','payment disputes']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Low-dollar cap including payments", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "$100K cap including payment disputes would allow Amazon to limit payment obligations. Cap must exclude payments and should be reasonable relative to deal size."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s liability is uncapped and unlimited. The parties agree that liability caps are inappropriate given the collaborative nature of this production relationship and the significant investment made by ProdCo.', ARRAY['Amazon''s liability','uncapped','unlimited','liability caps','inappropriate','collaborative nature','production relationship','significant investment','ProdCo']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "No cap on Amazon liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Uncapped Amazon liability creates unlimited exposure. Amazon requires liability cap as fundamental commercial protection regardless of relationship characterization."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The limitations of liability set forth in this Section shall not apply to ProdCo. ProdCo''s liability to Amazon and the Amazon Indemnitees under this Agreement, including under the indemnification provisions, shall be unlimited.', ARRAY['limitations of liability','not apply','ProdCo','ProdCo''s liability','Amazon','Amazon Indemnitees','Agreement','including','indemnification','unlimited']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "ProdCo excluded from limitations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo exclusion from liability limitations is essential for Amazon protection. ProdCo''s content obligations create risks that must not be capped."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding any other provision of this Agreement, ProdCo''s liability under the indemnification provisions, for breach of representations and warranties, and for breach of confidentiality obligations shall not be subject to any limitation or cap.', ARRAY['notwithstanding','ProdCo''s liability','indemnification','breach','representations','warranties','breach','confidentiality','not subject to','limitation','cap']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Specific ProdCo obligation carveouts", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Carves out key ProdCo obligations (indemnification, reps/warranties, confidentiality) from any limitations. Core protection areas must be unlimited."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo agrees that no limitation of liability, whether contained in this Agreement or implied by law, shall apply to: (a) ProdCo''s indemnification obligations; (b) breach of ProdCo''s representations and warranties; (c) ProdCo''s confidentiality obligations; (d) infringement or misappropriation of intellectual property; or (e) ProdCo''s fraud, gross negligence or willful misconduct.', ARRAY['no limitation','liability','apply','ProdCo''s indemnification','breach','representations','warranties','confidentiality','infringement','misappropriation','intellectual property','fraud','gross negligence','willful misconduct']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Comprehensive ProdCo carveouts", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of ProdCo obligations excluded from limitations. IP infringement and fraud/willful misconduct explicitly carved out."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges and agrees that Amazon is relying on the unlimited nature of ProdCo''s indemnification and warranty obligations in entering into this Agreement, and that any limitation on such obligations would be material to Amazon''s willingness to contract.', ARRAY['acknowledges','agrees','Amazon relying','unlimited nature','ProdCo''s indemnification','warranty obligations','entering into','Agreement','limitation','material','Amazon''s willingness','contract']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "ProdCo acknowledgment of unlimited liability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment reinforces that unlimited liability is bargained-for and essential to the deal, preventing later challenges."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Any liability cap or limitation that might otherwise apply under this Agreement or applicable law is expressly waived by ProdCo with respect to claims arising from: the Program content; ProdCo''s production activities; and ProdCo''s personnel.', ARRAY['liability cap','limitation','otherwise apply','Agreement','applicable law','expressly waived','ProdCo','claims','Program content','production activities','personnel']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Waiver of content/production limitations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Express waiver of limitations for content, production, and personnel claims. Addresses potential statutory limitations in some jurisdictions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The consequential damages exclusion set forth above is mutual; however, such exclusion shall not limit ProdCo''s indemnification obligations, which shall include all damages (including consequential damages) incurred by Amazon Indemnitees from third-party claims.', ARRAY['consequential damages exclusion','mutual','not limit','ProdCo''s indemnification','include','all damages','including consequential','Amazon Indemnitees','third-party claims']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Indemnification preserved from mutual exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that mutual consequential damages exclusion doesn''t affect ProdCo''s indemnification, which must cover all third-party damages including consequential."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For the avoidance of doubt, ProdCo''s liability under this Agreement is not capped, limited, or otherwise restricted. ProdCo shall be fully liable for all damages, losses, costs and expenses arising from breach of this Agreement or from any matter subject to indemnification.', ARRAY['avoidance of doubt','ProdCo''s liability','not capped','limited','restricted','fully liable','all damages','losses','costs','expenses','breach','Agreement','indemnification']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Explicit unlimited ProdCo liability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit statement of unlimited ProdCo liability prevents any ambiguity. Comprehensive coverage of all damage types."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s liability is unlimited for indemnification, reps/warranties, and confidentiality. For other ProdCo obligations (such as delivery schedules and format requirements), ProdCo''s liability shall be capped at the Production Fee.', ARRAY['ProdCo''s liability','unlimited','indemnification','reps/warranties','confidentiality','other obligations','delivery schedules','format requirements','capped','Production Fee']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Limited cap for operational obligations", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Cap for purely operational obligations (delivery, format) while preserving unlimited liability for core content/indemnification may be acceptable. Legal should confirm scope of ''operational'' is narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s liability is unlimited. However, ProdCo shall not be liable for consequential damages to Amazon arising from ProdCo''s breach of purely administrative obligations (e.g., late delivery of accounting statements), provided such exclusion shall not apply to the indemnification or content-related obligations.', ARRAY['ProdCo''s liability','unlimited','not liable','consequential damages','Amazon','breach','administrative obligations','late delivery','accounting','exclusion','not apply','indemnification','content-related']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Administrative consequential carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Narrow carveout for consequential damages from administrative breaches may be acceptable if truly limited to administrative matters and doesn''t affect content/indemnification."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s liability is not capped for core obligations. Both parties acknowledge that ProdCo maintains errors and omissions insurance with coverage of at least $5,000,000, which provides financial backing for ProdCo''s unlimited liability obligations.', ARRAY['ProdCo''s liability','not capped','core obligations','acknowledge','E&O insurance','coverage','$5,000,000','financial backing','unlimited liability']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Insurance acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Insurance acknowledgment provides context for unlimited liability. Doesn''t limit liability but confirms financial backing exists. Beneficial addition."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s liability is unlimited. In the event of a claim exceeding $[threshold], ProdCo shall have the right to dispute the amount, and the parties shall engage in good faith discussions before Amazon may pursue recovery beyond such threshold.', ARRAY['ProdCo''s liability','unlimited','claim exceeding','threshold','right to dispute','amount','good faith discussions','Amazon may pursue','recovery','beyond threshold']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Dispute process for large claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Good faith discussion requirement for large claims doesn''t limit liability but provides process. May be acceptable if it doesn''t create precondition to recovery."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s indemnification liability is unlimited. ProdCo''s liability for direct breaches by ProdCo of its non-indemnification obligations (e.g., service delivery) shall be subject to a cap equal to the Production Fee.', ARRAY['ProdCo''s indemnification','liability','unlimited','ProdCo''s liability','direct breaches','non-indemnification obligations','service delivery','subject to','cap','Production Fee']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Cap for non-indemnification direct breaches", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Preserving unlimited indemnification while capping service delivery breaches may be acceptable. Legal should confirm that content-related claims flow through indemnification, not direct breach."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo''s liability under the indemnification provisions is unlimited. ProdCo shall maintain insurance with Amazon named as additional insured, with coverage of not less than [amount] per occurrence and [amount] aggregate, to support these unlimited obligations.', ARRAY['ProdCo''s liability','indemnification','unlimited','maintain insurance','Amazon','additional insured','coverage','per occurrence','aggregate','support','unlimited obligations']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Insurance requirements for unlimited liability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Insurance requirement as support for unlimited liability is beneficial. Doesn''t cap liability but ensures financial backing for indemnification obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s aggregate liability under this Agreement, including under the indemnification provisions, shall not exceed the Production Fee paid to ProdCo hereunder.', ARRAY['ProdCo''s aggregate liability','Agreement','including','indemnification','not exceed','Production Fee','paid']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "ProdCo cap including indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Capping ProdCo''s liability including indemnification would massively limit Amazon''s recovery for content claims. ProdCo''s content liability must be unlimited."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The liability limitations in this Section apply equally to both parties. Each party''s aggregate liability shall be capped at the Production Fee, with no party having greater or lesser liability exposure than the other.', ARRAY['liability limitations','apply equally','both parties','each party''s','aggregate liability','capped','Production Fee','no party','greater','lesser','liability exposure']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Forced mutual liability caps", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced mutual caps ignore fundamental asymmetry. ProdCo creates content that generates claims; Amazon doesn''t. Mutual caps would gut Amazon''s protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s liability for indemnification claims shall be limited to the extent of available insurance coverage. Claims exceeding insurance coverage shall not be ProdCo''s responsibility.', ARRAY['ProdCo''s liability','indemnification','limited','extent','available insurance coverage','claims exceeding','insurance','not','ProdCo''s responsibility']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Insurance-limited liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting ProdCo liability to insurance coverage shifts excess risk to Amazon. ProdCo must be liable regardless of insurance limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not be liable for consequential, indirect, special, incidental or punitive damages to Amazon under any circumstances, including in connection with indemnification claims.', ARRAY['ProdCo','not liable','consequential','indirect','special','incidental','punitive damages','Amazon','any circumstances','including','indemnification claims']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "ProdCo consequential exclusion including indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo consequential damages exclusion covering indemnification would exclude vast categories of third-party claim damages. ProdCo must cover all indemnified damages."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s liability is unlimited for willful misconduct and fraud only. For all other breaches, including breach of representations and warranties, ProdCo''s liability shall be capped at two times (2x) the Production Fee.', ARRAY['ProdCo''s liability','unlimited','willful misconduct','fraud only','other breaches','including','representations','warranties','capped','2x','Production Fee']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Cap on rep/warranty breach", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Capping rep/warranty breach liability would limit recovery for core content claims (infringement, defamation). Rep/warranty breaches must be unlimited."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification liability is unlimited. However, ProdCo''s liability shall be reduced proportionately to the extent Amazon contributed to the claim through Amazon''s approvals, direction, or creative input.', ARRAY['ProdCo''s indemnification','unlimited','liability','reduced proportionately','extent','Amazon contributed','claim','Amazon''s approvals','direction','creative input']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Proportionate reduction for Amazon contribution", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Proportionate reduction for Amazon approvals/direction would reduce ProdCo liability for virtually all claims since Amazon provides creative input. Content responsibility is ProdCo''s regardless."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The limitations of liability set forth in this Section shall not apply to: (a) a party''s indemnification obligations; (b) a party''s breach of confidentiality obligations; (c) infringement or misappropriation of intellectual property; (d) fraud or intentional misconduct; or (e) obligations that by their nature cannot be limited (such as payment obligations).', ARRAY['limitations of liability','not apply','indemnification obligations','breach','confidentiality','infringement','misappropriation','intellectual property','fraud','intentional misconduct','obligations','cannot be limited','payment obligations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Standard super-cap exceptions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive exceptions covering indemnification, confidentiality, IP, fraud/misconduct, and inherently unlimited obligations. Essential carveouts from any caps."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding any limitation herein, neither party''s liability shall be limited with respect to: (i) death or personal injury caused by negligence; (ii) fraud or fraudulent misrepresentation; (iii) willful misconduct or gross negligence; (iv) indemnification obligations; or (v) breach of confidentiality or data protection obligations.', ARRAY['notwithstanding','limitation','neither party''s liability','limited','death','personal injury','negligence','fraud','fraudulent misrepresentation','willful misconduct','gross negligence','indemnification','confidentiality','data protection']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Personal injury and data protection exceptions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes death/personal injury and data protection in exceptions. Important for production safety and modern data handling requirements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The following shall not be subject to any cap, exclusion, or limitation of liability: ProdCo''s indemnification obligations; ProdCo''s representations and warranties; ProdCo''s confidentiality obligations; and any claim arising from ProdCo''s fraud, willful misconduct, or gross negligence.', ARRAY['not subject to','cap','exclusion','limitation','ProdCo''s indemnification','representations','warranties','confidentiality','claim','ProdCo''s fraud','willful misconduct','gross negligence']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "ProdCo-specific unlimited categories", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo-specific carveouts ensuring all core content and conduct obligations are unlimited. Includes reps/warranties as separate category."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Exclusions from the liability limitations include: (a) any amounts owed under indemnification provisions (which shall cover all damages including consequential damages); (b) breach of any obligation to maintain confidentiality of the other party''s information; (c) infringement, misappropriation, or unauthorized use of intellectual property rights.', ARRAY['Exclusions','liability limitations','amounts owed','indemnification','all damages','consequential','breach','confidentiality','other party''s information','infringement','misappropriation','unauthorized use','intellectual property']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Indemnification covers all damages clarification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that indemnification exception includes all damages (including consequential). Important to ensure limitation doesn''t indirectly cap indemnification."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Neither the liability cap nor the consequential damages exclusion shall apply to: fraud; willful misconduct; gross negligence; indemnification obligations; confidentiality breaches; intellectual property infringement; or violations of law resulting in fines or penalties.', ARRAY['liability cap','consequential damages exclusion','not apply','fraud','willful misconduct','gross negligence','indemnification','confidentiality','intellectual property infringement','violations of law','fines','penalties']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Legal violation fines/penalties exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes legal violation fines/penalties in exceptions. Important for regulatory compliance matters where penalties may be substantial."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The parties agree that the exceptions to liability limitations set forth herein are essential to the Agreement and are not subject to negotiation or modification. Any provision purporting to limit these exceptions shall be void and of no effect.', ARRAY['exceptions','liability limitations','essential','Agreement','not subject to','negotiation','modification','provision','limit','exceptions','void','no effect']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Non-waivable exceptions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Protective language preventing future modification of exceptions. Ensures exceptions remain in place even if Agreement is amended."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For the avoidance of doubt, the limitations set forth in this Section shall not limit any party''s liability for: (i) breach of exclusivity obligations; (ii) unauthorized use or disclosure of the other party''s intellectual property or confidential information; (iii) failure to comply with data protection laws; or (iv) any obligation that cannot lawfully be limited.', ARRAY['avoidance of doubt','limitations','not limit','liability','breach','exclusivity','unauthorized use','disclosure','intellectual property','confidential information','data protection laws','cannot lawfully be limited']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Exclusivity and data protection exceptions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes exclusivity breach and data protection in exceptions. Addresses modern privacy requirements and relationship exclusivity."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Exceptions to limitations include fraud, willful misconduct, and indemnification. For gross negligence, the liability cap shall be increased to two times (2x) the standard cap, but gross negligence shall not be entirely unlimited.', ARRAY['Exceptions','limitations','fraud','willful misconduct','indemnification','gross negligence','liability cap','increased','2x','standard cap','not entirely unlimited']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Elevated cap for gross negligence", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Elevated (but not unlimited) cap for gross negligence may be acceptable as middle ground. Legal should confirm fraud and willful misconduct remain unlimited."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Standard exceptions apply to limitations. With respect to confidentiality breaches, the exception applies only to breaches involving intentional disclosure to competitors or public disclosure of NPI, not to inadvertent disclosures to non-competitors.', ARRAY['Standard exceptions','limitations','confidentiality breaches','exception applies','only','intentional disclosure','competitors','public disclosure','NPI','not','inadvertent','non-competitors']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Limited confidentiality exception scope", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting confidentiality exception to intentional/competitor/public disclosures narrows scope but covers most serious scenarios. Legal should assess if inadvertent disclosure exclusion is acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Fraud, willful misconduct, and indemnification are excepted from limitations. For IP infringement exceptions, the exception applies to infringement claims by third parties (covered by indemnification) but not to direct IP claims between the parties, which remain subject to the cap.', ARRAY['Fraud','willful misconduct','indemnification','excepted','limitations','IP infringement','exception','third parties','covered by indemnification','direct IP claims','between parties','subject to','cap']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Third-party IP exception only", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting IP exception to third-party claims (via indemnification) while capping inter-party IP claims may be acceptable. Most IP exposure is from third parties anyway."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Exceptions to caps include fraud, willful misconduct, indemnification, confidentiality, and IP. For ProdCo specifically, the exception for representations and warranties shall be limited to representations regarding content originality, chain of title, and non-infringement.', ARRAY['Exceptions','caps','fraud','willful misconduct','indemnification','confidentiality','IP','ProdCo','exception','representations','warranties','limited','content originality','chain of title','non-infringement']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Specific rep exception categories", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting rep exception to content-related reps (originality, chain of title, non-infringement) may be acceptable as these are the core risk areas. Legal should confirm coverage is adequate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The parties agree to the following exceptions from the liability limitations: fraud (unlimited); willful misconduct (unlimited); gross negligence (cap at 3x fees); indemnification (unlimited); confidentiality (cap at 2x fees); IP infringement by third parties (unlimited through indemnification).', ARRAY['exceptions','liability limitations','fraud','unlimited','willful misconduct','unlimited','gross negligence','cap','3x fees','indemnification','unlimited','confidentiality','cap','2x fees','IP infringement','third parties','unlimited','indemnification']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Tiered exception structure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Tiered exception structure with different caps for different categories is more complex but may be acceptable if core protections (fraud, willful misconduct, indemnification) remain unlimited."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Exceptions from limitations apply to the enumerated matters. The parties acknowledge that ''fraud'' for purposes of this exception requires proof of intentional misrepresentation with knowledge of falsity and intent to induce reliance, not merely negligent misstatement.', ARRAY['Exceptions','limitations','enumerated matters','acknowledge','fraud','requires proof','intentional misrepresentation','knowledge of falsity','intent to induce reliance','not','negligent misstatement']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Fraud definition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Definition of fraud requiring intentional misrepresentation is reasonable common law standard. Distinguishes from negligent misrepresentation, which remains subject to limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The limitations of liability shall apply to all claims without exception. There are no carveouts for fraud, willful misconduct, indemnification, confidentiality, or any other category of claim.', ARRAY['limitations','liability','apply','all claims','without exception','no carveouts','fraud','willful misconduct','indemnification','confidentiality','any other category']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "No exceptions to limitations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating all exceptions would cap even fraud and indemnification. Essential exceptions must be preserved for Agreement enforceability and risk allocation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exceptions from limitations apply to fraud and willful misconduct only. Indemnification obligations, confidentiality breaches, and IP claims shall remain subject to the standard cap and consequential damages exclusion.', ARRAY['Exceptions','limitations','fraud','willful misconduct only','Indemnification','confidentiality','IP claims','subject to','standard cap','consequential damages exclusion']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Limited exceptions excluding indemnification", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Capping indemnification defeats the entire indemnification structure. ProdCo''s indemnification must be unlimited to protect Amazon from third-party claims."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exceptions from the cap apply equally to both parties. If ProdCo''s indemnification is excepted from the cap, Amazon''s indemnification must also be excepted. Asymmetric exceptions are not permitted.', ARRAY['Exceptions','cap','apply equally','both parties','ProdCo''s indemnification','excepted','Amazon''s indemnification','also excepted','asymmetric exceptions','not permitted']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Forced symmetric exceptions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced symmetric exceptions ignore that ProdCo''s indemnification scope is much broader than Amazon''s. Asymmetric exceptions reflect asymmetric obligations appropriately."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The fraud exception applies only to fraud that has been finally adjudicated by a court of competent jurisdiction. Alleged fraud, pending fraud claims, and fraud settlements shall remain subject to the cap until judicial determination.', ARRAY['fraud exception','applies only','fraud','finally adjudicated','court','competent jurisdiction','alleged fraud','pending','settlements','subject to','cap','until','judicial determination']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Adjudication requirement for fraud exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring final adjudication before fraud exception applies creates years of delay and caps exposure during litigation. Fraud exception must apply when fraud is alleged."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exceptions from limitations require mutual written agreement at the time the claim arises. Neither party may invoke an exception without the other party''s consent to excepting the specific claim from limitations.', ARRAY['Exceptions','limitations','require','mutual written agreement','time','claim arises','neither party','invoke','exception','without','other party''s consent','excepting','specific claim']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Consent requirement for exceptions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Consent requirement for exceptions gives breaching party veto over having exceptions apply to its breach. Completely defeats purpose of exceptions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Exceptions from the cap apply to fraud and willful misconduct. For purposes of this Agreement, ''willful misconduct'' requires proof that the party acted with specific intent to harm the other party, not merely reckless disregard for consequences.', ARRAY['Exceptions','cap','fraud','willful misconduct','Agreement','willful misconduct','requires proof','specific intent to harm','other party','not','reckless disregard']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Heightened willful misconduct standard", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Requiring ''specific intent to harm'' for willful misconduct is heightened standard that excludes reckless conduct. Willful misconduct should include reckless disregard, not require malicious intent."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The limitations of liability set forth in this Section apply to Amazon only. ProdCo''s liability to Amazon and the Amazon Indemnitees is not limited by this Section and shall be governed by the indemnification and other provisions of this Agreement.', ARRAY['limitations of liability','apply','Amazon only','ProdCo''s liability','Amazon','Amazon Indemnitees','not limited','Section','governed by','indemnification','other provisions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Amazon-only limitations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "One-sided limitations applying only to Amazon is appropriate given asymmetric risk profile. ProdCo''s content obligations require unlimited exposure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s liability is subject to the cap and exclusions set forth herein. For the avoidance of doubt, these limitations do not apply to ProdCo, whose liability to Amazon shall be unlimited as set forth in the indemnification provisions.', ARRAY['Amazon''s liability','subject to','cap','exclusions','limitations','do not apply','ProdCo','liability','Amazon','unlimited','indemnification provisions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Clear one-sided structure", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear statement that limitations apply to Amazon but not ProdCo. Cross-references indemnification for ProdCo''s unlimited obligations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The parties acknowledge the asymmetric risk profile of this Agreement, with ProdCo creating content and Amazon exploiting it. Accordingly, the liability limitations herein reflect this asymmetry: Amazon''s liability is limited while ProdCo''s liability for content-related matters is unlimited.', ARRAY['acknowledge','asymmetric risk profile','Agreement','ProdCo creating content','Amazon exploiting','liability limitations','reflect asymmetry','Amazon''s liability','limited','ProdCo''s liability','content-related','unlimited']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Risk asymmetry acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit acknowledgment of asymmetric risk profile justifies asymmetric limitations. Reinforces enforceability of one-sided structure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Section [X] (Limitation of Liability) applies to claims by ProdCo against Amazon. Claims by Amazon against ProdCo, including indemnification claims, are not subject to Section [X] and shall be governed by the indemnification and representations/warranties provisions.', ARRAY['Limitation of Liability','applies','claims','ProdCo against Amazon','claims','Amazon against ProdCo','indemnification claims','not subject to','governed by','indemnification','representations/warranties']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "Direction of application", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear statement of limitation direction: applies to ProdCo claims against Amazon, not Amazon claims against ProdCo."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s liability is capped and Amazon excludes consequential damages as set forth herein. ProdCo waives any right to assert that similar limitations should apply to ProdCo''s obligations, acknowledging that the asymmetric structure is bargained-for and essential to the deal.', ARRAY['Amazon''s liability','capped','excludes consequential damages','ProdCo waives','right to assert','similar limitations','ProdCo''s obligations','acknowledging','asymmetric structure','bargained-for','essential']::text[], '{"doc": "PSA_Principal_Terms", "section": "Limitation of Liability", "note": "ProdCo waiver of symmetry arguments", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo waiver of symmetry arguments prevents later challenges to one-sided structure. Reinforces that asymmetry was intentional and bargained-for."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The consequential damages exclusion is mutual and applies to both parties. The liability cap applies to Amazon only. ProdCo''s liability is subject only to the mutual consequential exclusion and is otherwise unlimited.', ARRAY['consequential damages exclusion','mutual','both parties','liability cap','Amazon only','ProdCo''s liability','subject only','mutual consequential exclusion','otherwise unlimited']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Mutual consequential with one-sided cap", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual consequential exclusion with one-sided cap may be acceptable if indemnification obligations are carved out from the mutual exclusion. Legal should confirm indemnification is preserved."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party''s direct liability to the other is subject to the cap set forth herein. Notwithstanding the foregoing, ProdCo''s indemnification obligations to Amazon Indemnitees are not capped and remain unlimited regardless of any cap on direct liability.', ARRAY['each party''s','direct liability','other','subject to','cap','notwithstanding','ProdCo''s indemnification','Amazon Indemnitees','not capped','unlimited','regardless','cap','direct liability']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Mutual direct liability cap with indemnification carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual cap on direct inter-party claims with indemnification carved out preserves core protection. Most content claims flow through indemnification anyway."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The limitations herein apply to both parties. However, the parties acknowledge that the exceptions enumerated above apply differently: Amazon''s exceptions include only fraud and willful misconduct; ProdCo''s exceptions include all enumerated matters (indemnification, reps/warranties, confidentiality, IP, fraud, willful misconduct).', ARRAY['limitations','both parties','acknowledge','exceptions','apply differently','Amazon''s exceptions','fraud','willful misconduct','ProdCo''s exceptions','all enumerated','indemnification','reps/warranties','confidentiality','IP']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Mutual limitations with asymmetric exceptions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual baseline with asymmetric exceptions achieves similar result to one-sided structure. ProdCo''s broader exceptions ensure core protections remain."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The consequential damages exclusion applies mutually. The cap applies to Amazon''s liability for direct breach of Agreement. The cap does not apply to ProdCo''s liability, which is unlimited for indemnification, reps/warranties, confidentiality, and IP matters.', ARRAY['consequential damages exclusion','mutually','cap','Amazon''s liability','direct breach','Agreement','cap does not apply','ProdCo''s liability','unlimited','indemnification','reps/warranties','confidentiality','IP']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Split mutual/one-sided structure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Split structure with mutual consequential exclusion but one-sided cap may be acceptable if ProdCo''s indemnification obligations cover all consequential damages to Amazon from third-party claims."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Both parties agree to the limitations set forth herein. For ProdCo, the limitations apply only to claims by Amazon arising from operational breaches (delivery, format, scheduling). Content-related claims against ProdCo (through indemnification or reps/warranties) are unlimited.', ARRAY['both parties','limitations','ProdCo','limitations apply','only','claims','Amazon','operational breaches','delivery','format','scheduling','content-related claims','ProdCo','indemnification','reps/warranties','unlimited']::text[], '{"doc": "Counterparty_Markup", "section": "Limitation of Liability", "note": "Operational vs. content distinction for ProdCo", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting ProdCo cap to operational matters while preserving unlimited content liability may be acceptable. Legal should confirm operational category is genuinely narrow."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The limitations of liability apply equally and symmetrically to both parties. Each party''s aggregate liability is capped at the Production Fee, and each party excludes consequential damages. No party shall have greater liability exposure than the other.', ARRAY['limitations of liability','equally','symmetrically','both parties','each party''s','aggregate liability','capped','Production Fee','excludes consequential','no party','greater liability exposure']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Forced symmetric limitations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Forced symmetric limitations would cap ProdCo''s indemnification, destroying Amazon''s protection against content claims. Symmetry ignores fundamental risk asymmetry."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon''s liability is capped, ProdCo''s liability shall be capped at the same amount. If Amazon''s cap is set at the Production Fee, ProdCo''s cap shall also equal the Production Fee. Parity in liability exposure is required.', ARRAY['Amazon''s liability','capped','ProdCo''s liability','capped','same amount','Amazon''s cap','Production Fee','ProdCo''s cap','equal','Production Fee','parity','liability exposure','required']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Mandatory parity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mandatory parity ignores that Amazon''s risks (service delivery) are different from ProdCo''s risks (content liability). ProdCo''s content obligations require unlimited exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The liability limitations are mutual. If Amazon later seeks to amend this Section to make limitations one-sided, ProdCo shall have the right to terminate this Agreement without penalty and retain all amounts paid.', ARRAY['liability limitations','mutual','Amazon seeks','amend','Section','one-sided','ProdCo','right to terminate','without penalty','retain','amounts paid']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Termination right for asymmetry", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination right triggered by asymmetric amendments prevents appropriate risk allocation changes. Combined with mutual limitations, creates unacceptable structure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The parties reject any asymmetric limitation structure as unconscionable. Both parties are sophisticated commercial entities entitled to equal protection. Any limitation applying to one party shall automatically apply to the other.', ARRAY['reject','asymmetric limitation','unconscionable','sophisticated commercial entities','equal protection','limitation','one party','automatically apply','other']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Unconscionability argument for symmetry", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Characterizing asymmetry as unconscionable misunderstands commercial reality. Asymmetric risk allocation is appropriate for content production agreements with different party roles."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may limit its liability only if ProdCo is entitled to equivalent limitations. If Amazon''s limitations would result in ProdCo bearing greater uncapped exposure, Amazon''s limitations shall be void and unenforceable.', ARRAY['Amazon may limit','only if','ProdCo entitled','equivalent limitations','Amazon''s limitations','result','ProdCo','greater uncapped exposure','Amazon''s limitations','void','unenforceable']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Conditional Amazon limitations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Conditioning Amazon''s limitations on ProdCo equivalence would void Amazon''s protections given necessary asymmetry. Appropriate asymmetry is feature, not bug."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Both parties agree to mutual unlimited liability. Neither party''s liability shall be capped or limited in any way. The parties accept the risks inherent in their respective obligations without limitation.', ARRAY['both parties','mutual unlimited liability','neither party''s liability','capped','limited','any way','accept risks','inherent','respective obligations','without limitation']::text[], '{"doc": "Counterparty_Proposal", "section": "Limitation of Liability", "note": "Mutual unlimited liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mutual unlimited liability eliminates Amazon''s fundamental commercial protection. Amazon requires liability cap regardless of ProdCo''s position."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement at any time, for any reason or no reason, in Amazon''s sole and absolute discretion, upon written notice to ProdCo. No advance notice period shall be required for such termination.', ARRAY['Amazon may terminate','any time','any reason','no reason','sole and absolute discretion','written notice','no advance notice','required']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Standard termination for convenience", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon termination for convenience right with no notice requirement. Essential for maintaining flexibility over production commitments. Sole discretion language is appropriate."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have the right to terminate this Agreement for convenience at any time prior to completion of principal photography by providing written notice to ProdCo. After completion of principal photography, Amazon''s termination right shall be limited to termination for cause.', ARRAY['Amazon','right to terminate','for convenience','any time','prior to','completion','principal photography','written notice','after completion','termination for cause']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Pre-principal photography convenience termination", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Convenience termination limited to pre-principal photography is reasonable milestone-based approach. Preserves Amazon flexibility during development while providing production-phase certainty."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement at will at any stage of production. Upon such termination, Amazon shall pay ProdCo for all services rendered and costs properly incurred through the termination date, but shall have no obligation to pay any amounts not yet earned or incurred.', ARRAY['Amazon may terminate','at will','any stage','production','pay ProdCo','services rendered','costs properly incurred','termination date','no obligation','not yet earned','incurred']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Convenience termination with earned payment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Termination at will with payment for earned amounts is fair approach. No obligation for unearned amounts preserves Amazon''s ability to limit exposure upon termination."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement for convenience by providing written notice. Amazon''s decision to terminate shall not require any justification, explanation, or prior consultation with ProdCo. ProdCo waives any right to challenge Amazon''s termination decision.', ARRAY['Amazon may terminate','for convenience','written notice','not require','justification','explanation','prior consultation','ProdCo waives','right to challenge','termination decision']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Unchallengeable termination right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit waiver of challenge rights reinforces Amazon''s sole discretion. No justification requirement is essential for convenience termination."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s termination for convenience right shall apply to: (a) the entire Agreement; (b) any individual season ordered; (c) any individual episode ordered; or (d) any development services. Amazon may exercise partial termination without affecting the remainder of the Agreement.', ARRAY['termination for convenience','apply to','entire Agreement','individual season','individual episode','development services','partial termination','without affecting','remainder']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Granular termination scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Granular termination options allow Amazon to reduce scope without fully terminating. Flexibility to terminate portions is important for series orders."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience. Upon such termination: (i) ProdCo shall immediately cease all work; (ii) ProdCo shall deliver all Materials in whatever state of completion; (iii) all rights shall vest in Amazon; and (iv) Amazon shall make payments as set forth in Schedule [X].', ARRAY['terminate for convenience','upon termination','immediately cease','all work','deliver','Materials','state of completion','all rights','vest','Amazon','payments','Schedule']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Termination mechanics enumerated", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear enumeration of termination consequences including work stoppage, materials delivery, rights vesting, and payment. Schedule reference provides payment specificity."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement for any reason. ProdCo acknowledges that the entertainment industry involves inherent uncertainty and that Amazon''s decision not to proceed with the Program shall not give rise to any claim, liability, or cause of action by ProdCo against Amazon.', ARRAY['Amazon may terminate','any reason','acknowledges','entertainment industry','inherent uncertainty','decision not to proceed','not give rise','claim','liability','cause of action']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Industry uncertainty acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment of industry uncertainty reinforces that termination is expected possibility, not breach. Waiver of claims is essential."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for convenience upon thirty (30) days'' prior written notice to ProdCo. During such notice period, ProdCo shall continue to perform services and Amazon shall continue to pay applicable fees.', ARRAY['Amazon may terminate','for convenience','thirty days','prior written notice','notice period','ProdCo','continue','perform services','Amazon','continue','pay','fees']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "30-day notice period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "30-day notice period is reasonable accommodation for production wind-down. Continued performance and payment during notice is appropriate quid pro quo."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for convenience. If termination occurs after commencement of principal photography, Amazon shall pay ProdCo''s documented, reasonable wind-down costs incurred within thirty (30) days following termination, up to a cap of [specified amount].', ARRAY['terminate for convenience','termination','after','commencement','principal photography','pay','documented','reasonable','wind-down costs','thirty days','following','cap','specified amount']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Capped wind-down costs", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Capped wind-down costs for post-photography termination is reasonable commercial accommodation. Cap provides predictability; documented/reasonable requirements limit exposure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for convenience at any time. Amazon shall provide ProdCo with as much advance notice as is reasonably practicable under the circumstances, taking into account the stage of production and any third-party commitments of which Amazon is aware.', ARRAY['terminate for convenience','any time','provide','advance notice','reasonably practicable','circumstances','stage of production','third-party commitments','Amazon is aware']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Reasonable practicable notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "''Reasonably practicable'' notice is softer than fixed period and appropriate flexibility. ''Of which Amazon is aware'' qualifier is important limitation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate this Agreement for convenience. If Amazon exercises this right more than once across multiple projects with ProdCo within a twelve (12) month period, Amazon shall meet with ProdCo to discuss in good faith the reasons for terminations.', ARRAY['terminate','for convenience','exercises','more than once','multiple projects','twelve month period','meet with ProdCo','discuss','good faith','reasons']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Repeat termination discussion", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Good faith discussion requirement for repeated terminations is relationship-focused addition that doesn''t limit termination right itself. May be acceptable for valued partners."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for convenience. Upon termination, Amazon shall pay: (a) the applicable kill fee set forth in Schedule [X]; plus (b) all documented third-party costs that ProdCo has irrevocably committed to and cannot mitigate, up to [specified cap].', ARRAY['terminate for convenience','upon termination','pay','kill fee','Schedule','documented','third-party costs','irrevocably committed','cannot mitigate','cap']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Kill fee plus committed costs", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Kill fee plus capped committed costs is commercial negotiation point. Business Affairs should assess whether amounts are appropriate for production scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s convenience termination right applies. If Amazon terminates during active production, Amazon shall cooperate reasonably with ProdCo''s efforts to reassign or release personnel and to cancel or assign third-party contracts, to the extent such cooperation does not impose material cost on Amazon.', ARRAY['convenience termination','applies','terminates','active production','cooperate reasonably','reassign','release personnel','cancel','assign','third-party contracts','cooperation','not impose','material cost']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Cooperation on wind-down", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Reasonable cooperation with wind-down without material Amazon cost is helpful addition. Assists orderly termination without creating Amazon obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement for convenience only upon ninety (90) days'' prior written notice and payment of a termination fee equal to fifty percent (50%) of the remaining Production Fee.', ARRAY['terminate','for convenience','only','ninety days','prior written notice','payment','termination fee','fifty percent','remaining Production Fee']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Extended notice with penalty", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "90-day notice with 50% of remaining fee as penalty substantially limits Amazon''s flexibility. Convenience termination must be unrestricted and without penalty."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience only prior to commencement of pre-production. Once pre-production has commenced, Amazon may terminate only for cause as defined herein.', ARRAY['terminate for convenience','only','prior to','commencement','pre-production','once','commenced','terminate','only','for cause']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Convenience limited to pre-pre-production", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting convenience termination to pre-pre-production is far too restrictive. Amazon needs convenience termination right through at least principal photography commencement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience. However, if Amazon terminates and subsequently produces a program substantially similar to the Program within three (3) years, ProdCo shall be entitled to the full Production Fee as if the Program had been completed.', ARRAY['terminate for convenience','however','terminates','subsequently produces','substantially similar','Program','three years','ProdCo entitled','full Production Fee','Program completed']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Similar program penalty", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Penalty for producing similar content essentially prevents Amazon from terminating and developing similar projects. Fundamentally restricts Amazon''s creative development rights."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience only with ProdCo''s prior written consent, which consent shall not be unreasonably withheld. If ProdCo withholds consent, Amazon may terminate only upon payment of the full remaining Production Fee.', ARRAY['terminate for convenience','only','ProdCo''s prior written consent','not unreasonably withheld','ProdCo withholds consent','terminate','only','payment','full remaining Production Fee']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "ProdCo consent required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring ProdCo consent for convenience termination eliminates Amazon''s discretion entirely. Amazon must have unilateral termination right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Neither party may terminate this Agreement for convenience. Termination shall be permitted only for material breach by the other party, subject to the cure provisions set forth herein.', ARRAY['neither party','terminate','for convenience','termination permitted','only','material breach','other party','subject to','cure provisions']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "No convenience termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating convenience termination entirely removes Amazon''s fundamental right to control its slate. Amazon must retain convenience termination under all circumstances."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience. Upon such termination, ProdCo shall be entitled to the full Production Fee for all ordered episodes, regardless of the stage of production, as liquidated damages for the lost opportunity.', ARRAY['terminate for convenience','upon termination','ProdCo entitled','full Production Fee','all ordered episodes','regardless','stage of production','liquidated damages','lost opportunity']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Full fee as liquidated damages", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Full Production Fee upon convenience termination makes termination economically prohibitive. Would effectively eliminate Amazon''s ability to terminate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for convenience, but only during specified decision windows: (a) within 30 days after delivery of each script; (b) within 14 days after each production milestone; and (c) within 7 days after each cut delivery. Outside these windows, termination for convenience is not permitted.', ARRAY['terminate for convenience','only','decision windows','30 days','script','14 days','production milestone','7 days','cut delivery','outside windows','not permitted']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Window-limited convenience termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting termination to narrow decision windows eliminates Amazon''s flexibility to respond to changing circumstances. Convenience termination must be available at any time."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement immediately upon written notice if ProdCo: (a) materially breaches any provision of this Agreement; (b) breaches any representation or warranty; (c) becomes insolvent or files for bankruptcy; (d) is the subject of any governmental investigation relating to the Program; or (e) engages in conduct that brings Amazon into disrepute.', ARRAY['Amazon may terminate','immediately','written notice','materially breaches','provision','breaches','representation','warranty','insolvent','bankruptcy','governmental investigation','conduct','brings Amazon','disrepute']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Comprehensive cause termination triggers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of cause termination triggers including breach, insolvency, investigation, and reputational harm. Immediate termination without cure for serious matters is appropriate."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause immediately if ProdCo breaches any material term. For non-material breaches, Amazon shall provide written notice and ProdCo shall have ten (10) business days to cure. If uncured after such period, Amazon may terminate immediately.', ARRAY['terminate for cause','immediately','breaches','material term','non-material breaches','written notice','ten business days','cure','uncured','terminate immediately']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Tiered cure based on materiality", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Tiered approach with immediate termination for material breach and short cure period for non-material breach is reasonable. Ten business days is adequate for minor issues."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate this Agreement for cause upon any breach by ProdCo of: (i) confidentiality or NPI obligations; (ii) compliance with applicable law; (iii) Amazon''s policies; (iv) representations regarding content originality or non-infringement; or (v) any obligation designated as a ''Termination Event'' in this Agreement.', ARRAY['terminate for cause','breach','confidentiality','NPI','compliance','applicable law','Amazon''s policies','representations','originality','non-infringement','Termination Event']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Specific termination event categories", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific high-priority breach categories that warrant immediate termination. Termination Event designation allows flexibility for deal-specific triggers."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause if any Key Person (as defined in Exhibit [X]) is no longer attached to the Program and a mutually acceptable replacement is not identified within thirty (30) days of such departure, or if ProdCo fails to deliver any deliverable by the applicable deadline and such failure continues for more than five (5) business days.', ARRAY['terminate for cause','Key Person','no longer attached','mutually acceptable replacement','thirty days','departure','fails to deliver','deliverable','deadline','failure continues','five business days']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Key person and delivery triggers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Key person departure and delivery failure are common cause triggers. Reasonable cure periods (30 days for replacement, 5 days for delivery) before termination applies."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate immediately for cause if any third party asserts a claim alleging that the Program infringes intellectual property rights, invades privacy, or constitutes defamation, regardless of the merit of such claim, if Amazon reasonably determines that the claim poses material risk.', ARRAY['terminate immediately','for cause','third party','asserts claim','alleging','Program infringes','intellectual property','invades privacy','defamation','regardless','merit','reasonably determines','material risk']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Third-party claim trigger", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Third-party claim trigger allows Amazon to terminate when content claims arise, regardless of merit. Protects against ongoing production amid legal uncertainty."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Termination for cause shall be in addition to, and not in lieu of, any other remedies available to Amazon at law or in equity. Amazon''s exercise of termination rights shall not waive or limit Amazon''s right to seek damages, indemnification, or other relief.', ARRAY['termination for cause','in addition to','not in lieu of','other remedies','law','equity','exercise','termination rights','not waive','not limit','damages','indemnification','other relief']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Non-exclusive remedy", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that termination doesn''t waive other remedies. Essential for preserving indemnification and damage claims alongside termination."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause if ProdCo or any of its principals, officers, directors, or Key Persons is publicly accused of, charged with, or convicted of any felony or crime of moral turpitude, or is the subject of credible public allegations of sexual misconduct or harassment.', ARRAY['terminate for cause','ProdCo','principals','officers','directors','Key Persons','publicly accused','charged','convicted','felony','crime of moral turpitude','credible public allegations','sexual misconduct','harassment']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Morals/misconduct trigger", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Morals clause covering criminal conduct and credible misconduct allegations. Extends to key personnel to protect against reputational harm from associated individuals."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for cause upon material breach. Before exercising such right, Amazon shall provide written notice specifying the breach in reasonable detail and ProdCo shall have fifteen (15) business days to cure, except that no cure period applies to breaches of confidentiality, compliance, or representations.', ARRAY['terminate for cause','material breach','before exercising','written notice','specifying','breach','reasonable detail','fifteen business days','cure','except','no cure period','confidentiality','compliance','representations']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "15-day cure with exceptions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "15-day cure period is longer than preferred but may be acceptable for operational breaches. Exceptions for core matters (confidentiality, compliance, reps) preserve immediate termination where needed."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for cause. If ProdCo disputes that a termination trigger has occurred, ProdCo may provide written notice of dispute within five (5) business days, and the parties shall consult in good faith before Amazon''s termination becomes effective, provided such consultation shall not exceed ten (10) business days.', ARRAY['terminate for cause','ProdCo disputes','termination trigger','written notice','dispute','five business days','consult','good faith','before termination','effective','consultation','not exceed','ten business days']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Dispute consultation period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Short dispute consultation period (capped at 10 days) may be acceptable as it doesn''t prevent termination, just delays briefly for discussion. Timeboxed to prevent prolonged disputes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for material breach. For purposes of this Agreement, a breach shall be deemed ''material'' if it: (a) cannot be cured; (b) relates to core content, compliance, or confidentiality matters; (c) significantly impairs Amazon''s ability to exploit the Program; or (d) exposes Amazon to material liability or reputational harm.', ARRAY['terminate','material breach','breach','deemed material','cannot be cured','core content','compliance','confidentiality','significantly impairs','ability to exploit','Program','exposes Amazon','material liability','reputational harm']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Material breach definition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Definition of ''material'' breach provides clarity and may reduce disputes. Categories listed are appropriately broad. Legal should confirm definition covers anticipated scenarios."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for cause. If the alleged cause relates to conduct of a specific individual (other than ProdCo''s principals), ProdCo shall have the opportunity to remove such individual from the production within five (5) business days in lieu of Agreement termination.', ARRAY['terminate for cause','alleged cause','relates to','conduct','specific individual','other than','principals','opportunity','remove','individual','five business days','in lieu of','Agreement termination']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Individual removal alternative", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Removal alternative for individual misconduct (not principals) may be acceptable as it addresses the issue without full termination. Preserves Amazon''s right if removal doesn''t occur."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for cause upon breach. If ProdCo believes Amazon''s termination notice was issued in error or in bad faith, ProdCo may invoke the dispute resolution procedure in Section [X]; however, the Program shall remain suspended during such dispute proceedings.', ARRAY['terminate for cause','breach','ProdCo believes','termination notice','error','bad faith','invoke','dispute resolution','Section','Program','suspended','during','dispute proceedings']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Dispute resolution with suspension", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Dispute resolution option with production suspension preserves Amazon''s ability to stop work while providing ProdCo procedural recourse. Suspension is essential protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may terminate for cause. Amazon''s termination notice shall identify the specific breach and the provision breached. If Amazon''s notice fails to specify the breach with reasonable particularity, ProdCo may request clarification, and Amazon shall provide such clarification within three (3) business days.', ARRAY['terminate for cause','termination notice','identify','specific breach','provision breached','fails to specify','reasonable particularity','request clarification','provide','three business days']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Breach specification requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Breach specification requirement is reasonable procedural addition. Three-day clarification period is short and doesn''t materially delay termination."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause only upon ProdCo''s material breach that remains uncured for sixty (60) days after written notice. During such cure period, all payments shall continue and production shall proceed as scheduled.', ARRAY['terminate for cause','only','material breach','uncured','sixty days','written notice','cure period','payments','continue','production','proceed','scheduled']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Extended cure with continued payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "60-day cure period is far too long, and required continued payment during cure is unacceptable. Amazon must be able to terminate and suspend payments upon material breach."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause only if the breach is material and incurable, or if the breach is curable but ProdCo has failed to cure after two (2) separate written notices with thirty (30) day cure periods each.', ARRAY['terminate for cause','only','breach','material','incurable','curable','failed to cure','two separate','written notices','thirty day','cure periods','each']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Double notice requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring two separate 30-day cure periods (60+ days total) before termination is completely unacceptable. Single reasonable cure period is sufficient."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause. However, before termination becomes effective, Amazon must submit the dispute to binding arbitration and obtain an arbitral determination that ProdCo''s breach constitutes cause for termination.', ARRAY['terminate for cause','before termination','effective','submit','dispute','binding arbitration','obtain','arbitral determination','breach','constitutes','cause','termination']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Arbitration prerequisite", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring arbitration before termination is effective could take months or years. Amazon must be able to terminate immediately upon breach, with arbitration for disputed damages."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause only for breaches that are both material and willful. Negligent breaches, inadvertent breaches, and breaches resulting from circumstances beyond ProdCo''s reasonable control shall not constitute cause for termination.', ARRAY['terminate for cause','only','breaches','material','willful','negligent breaches','inadvertent','circumstances','beyond','reasonable control','not constitute','cause']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Willful breach only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting cause to willful breaches excludes negligent breaches that may still be serious. Many material breaches are not willful but still warrant termination."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s right to terminate for cause shall be subject to an aggregate cap. Amazon may exercise cause termination no more than once per contract year, and each exercise shall reduce the cap by $[amount].', ARRAY['right to terminate','for cause','subject to','aggregate cap','exercise','cause termination','no more than once','per contract year','exercise','reduce','cap','amount']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Capped termination right", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Capping termination rights makes no sense\u2014Amazon''s right to terminate for breach cannot be limited by frequency or cost. This is fundamentally misconceived."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may terminate for cause. If Amazon terminates for cause but ProdCo disputes the existence of cause, and an arbitrator subsequently determines that cause did not exist, Amazon shall pay ProdCo the full remaining Production Fee plus [50%] as a termination penalty.', ARRAY['terminate for cause','ProdCo disputes','existence of cause','arbitrator','determines','cause did not exist','pay ProdCo','full remaining Production Fee','50%','termination penalty']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Penalty for disputed cause termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "150% penalty for disputed cause termination creates massive disincentive to terminate even for legitimate cause. Would chill appropriate termination decisions."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not have the right to terminate this Agreement for any reason. ProdCo''s sole remedy for any breach by Amazon shall be an action for monetary damages, subject to the limitations of liability set forth herein.', ARRAY['ProdCo','not have','right to terminate','any reason','ProdCo''s sole remedy','breach','Amazon','action','monetary damages','subject to','limitations of liability']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "No ProdCo termination right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo having no termination right is standard. Amazon controls whether production continues. ProdCo''s remedy is limited to monetary damages under Agreement limitations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may not terminate this Agreement. ProdCo acknowledges that specific performance and injunctive relief may be appropriate remedies for Amazon, and ProdCo waives any right to terminate as a remedy for alleged breach by Amazon.', ARRAY['ProdCo','may not terminate','acknowledges','specific performance','injunctive relief','appropriate remedies','Amazon','waives','right to terminate','remedy','alleged breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Termination waiver with equitable remedies acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit waiver of termination right as remedy. Acknowledgment of equitable remedies for Amazon reinforces that ProdCo must continue performing."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Only Amazon may terminate this Agreement. ProdCo''s exclusive remedy for any Amazon breach shall be to seek monetary damages after completion of ProdCo''s services. Under no circumstances may ProdCo cease performance, withhold Materials, or terminate this Agreement.', ARRAY['Only Amazon','may terminate','ProdCo''s exclusive remedy','Amazon breach','seek monetary damages','after completion','ProdCo''s services','no circumstances','cease performance','withhold Materials','terminate']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "No performance cessation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly prohibits ProdCo from ceasing performance or withholding Materials. Damages remedy only after completion ensures production continuity."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo does not have termination rights under this Agreement. If Amazon materially breaches, ProdCo''s remedy is limited to: (a) notice to Amazon of the breach; (b) a reasonable opportunity for Amazon to cure; and (c) if uncured, an action for damages subject to Agreement limitations.', ARRAY['ProdCo','does not have','termination rights','Amazon materially breaches','ProdCo''s remedy','limited','notice','breach','reasonable opportunity','cure','uncured','action for damages','Agreement limitations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Structured non-termination remedy", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Provides ProdCo with notice and cure process before damages claim, but no termination right. Structured approach while preserving Amazon control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement may be terminated by Amazon only. ProdCo irrevocably waives any right it may have under applicable law or otherwise to terminate, rescind, or cancel this Agreement or to cease performance for any reason.', ARRAY['Agreement','terminated','Amazon only','ProdCo irrevocably waives','right','applicable law','otherwise','terminate','rescind','cancel','cease performance','any reason']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Comprehensive termination waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive waiver covering termination, rescission, and cancellation rights. Addresses potential statutory or common law rights that might otherwise exist."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo has no termination rights. ProdCo agrees that the Program and Amazon''s exploitation thereof are unique, and that termination by ProdCo would cause irreparable harm to Amazon for which monetary damages would be inadequate.', ARRAY['ProdCo','no termination rights','agrees','Program','Amazon''s exploitation','unique','termination','ProdCo','irreparable harm','Amazon','monetary damages','inadequate']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Irreparable harm acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment of uniqueness and irreparable harm supports Amazon''s entitlement to specific performance and injunctive relief."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not terminate. Any purported termination by ProdCo shall be void and of no effect, and ProdCo shall remain obligated to perform. Amazon may treat any purported termination by ProdCo as a material breach entitling Amazon to terminate and pursue all remedies.', ARRAY['ProdCo','shall not terminate','purported termination','void','no effect','remain obligated','perform','Amazon may treat','purported termination','material breach','entitling','terminate','pursue','remedies']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Void purported termination", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Makes any ProdCo termination attempt void while treating it as material breach. Strong deterrent against wrongful termination attempts."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may not terminate except in the limited circumstance where Amazon fails to pay undisputed amounts when due and such failure continues for sixty (60) days after written notice. Even then, ProdCo must first exhaust dispute resolution procedures before any termination.', ARRAY['ProdCo','may not terminate','except','limited circumstance','Amazon fails to pay','undisputed amounts','due','failure continues','sixty days','written notice','exhaust','dispute resolution','before','termination']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Payment failure exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited termination right for prolonged (60-day) undisputed payment failure with dispute resolution prerequisite may be acceptable. Protects ProdCo from non-payment while preserving Amazon control."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo has no general termination right. However, if Amazon''s breach creates an imminent risk of physical harm to production personnel, ProdCo may suspend (but not terminate) production until the risk is addressed, with notice to Amazon and cooperation in remediation.', ARRAY['ProdCo','no general termination right','Amazon''s breach','imminent risk','physical harm','production personnel','suspend','not terminate','production','risk addressed','notice','cooperation','remediation']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Safety suspension only", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Suspension (not termination) right for imminent physical safety risks is reasonable. Protects personnel while preserving Amazon''s ultimate control over Agreement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may not terminate. ProdCo may request that Amazon terminate the Agreement if extraordinary circumstances make continued performance impracticable, and Amazon shall consider such request in good faith, but the decision to terminate remains solely with Amazon.', ARRAY['ProdCo','may not terminate','request','Amazon terminate','Agreement','extraordinary circumstances','impracticable','Amazon','consider','good faith','decision','terminate','solely','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Termination request process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Request process for extraordinary circumstances preserves Amazon''s sole termination authority while acknowledging practical realities. Good faith consideration is minimal burden."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo has no termination right. If Amazon''s breach is material and uncured for ninety (90) days despite ProdCo''s reasonable efforts to obtain cure, ProdCo may seek a judicial declaration that the Agreement is terminated, but may not unilaterally cease performance pending such declaration.', ARRAY['ProdCo','no termination right','Amazon''s breach','material','uncured','ninety days','reasonable efforts','cure','seek','judicial declaration','terminated','not unilaterally','cease performance','pending']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Judicial declaration process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Judicial process for termination declaration (rather than unilateral right) preserves Amazon''s control and ensures dispute resolution. Continued performance requirement is essential."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo waives termination rights. Notwithstanding the foregoing, ProdCo may terminate this Agreement if Amazon is adjudicated bankrupt or makes a general assignment for the benefit of creditors, provided ProdCo exercises such right within thirty (30) days of such event.', ARRAY['ProdCo waives','termination rights','notwithstanding','terminate','Amazon','adjudicated bankrupt','general assignment','benefit of creditors','exercises','within','thirty days','event']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Bankruptcy exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Bankruptcy termination exception is reasonable given fundamental change in counterparty circumstances. 30-day exercise window prevents stale claims."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not terminate. If ProdCo believes Amazon has materially breached, ProdCo shall provide written notice and the parties shall meet within ten (10) business days to attempt resolution. ProdCo''s sole remedy is damages; continued performance during dispute is required.', ARRAY['ProdCo','shall not terminate','believes','Amazon','materially breached','written notice','meet','ten business days','attempt resolution','sole remedy','damages','continued performance','during dispute','required']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Resolution meeting with continued performance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Resolution meeting process provides procedural mechanism for disputes without termination right. Continued performance requirement is preserved. Reasonable addition."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may terminate this Agreement upon Amazon''s material breach that remains uncured for thirty (30) days after written notice from ProdCo.', ARRAY['ProdCo may terminate','Amazon''s material breach','uncured','thirty days','written notice']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "ProdCo termination for cause", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo termination right for Amazon breach reverses appropriate control structure. Amazon controls whether production continues; ProdCo''s remedy is damages."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party may terminate this Agreement for material breach by the other party. ProdCo and Amazon shall have equivalent termination rights as befits their status as equal contracting parties.', ARRAY['each party','may terminate','material breach','other party','ProdCo','Amazon','equivalent termination rights','equal contracting parties']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Mutual termination rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mutual termination rights ignore asymmetric relationship. Amazon commissions and controls content; ProdCo provides services. ProdCo cannot have equivalent termination authority."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may terminate this Agreement for convenience upon sixty (60) days'' written notice to Amazon. Upon such termination, ProdCo shall deliver all Materials completed through the termination date.', ARRAY['ProdCo may terminate','for convenience','sixty days','written notice','upon termination','deliver','Materials','completed','termination date']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "ProdCo convenience termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo convenience termination right is completely unacceptable. Would allow ProdCo to abandon production for any reason, destroying Amazon''s investment and plans."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may terminate if Amazon fails to approve any deliverable within the time periods specified herein, as such failure constitutes Amazon''s material breach of its obligation to provide timely feedback.', ARRAY['ProdCo may terminate','Amazon fails to approve','deliverable','time periods','specified','failure constitutes','Amazon''s material breach','obligation','timely feedback']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Approval delay termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination for approval delays gives ProdCo leverage to force approvals or escape Agreement. Amazon approval processes cannot be used as termination triggers."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may terminate this Agreement if Amazon orders fewer than the minimum number of episodes specified in Section [X] for any season, as such reduction constitutes a material change to the agreed scope.', ARRAY['ProdCo may terminate','Amazon orders','fewer','minimum number','episodes','specified','Section','reduction constitutes','material change','agreed scope']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Episode reduction termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination for episode reduction restricts Amazon''s ordering discretion. Amazon''s right to determine episode orders is fundamental; ProdCo cannot terminate based on order quantity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon''s creative decisions materially deviate from ProdCo''s creative vision for the Program as set forth in the Series Bible, ProdCo may terminate this Agreement and reclaim all rights in the Program.', ARRAY['Amazon''s creative decisions','materially deviate','ProdCo''s creative vision','Program','Series Bible','ProdCo may terminate','reclaim','all rights']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Creative deviation termination with rights recapture", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Creative deviation termination with rights recapture inverts entire ownership and control structure. Amazon owns the Program and has creative control; ProdCo cannot terminate or reclaim rights."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon termination for any reason: (a) all rights granted herein shall remain vested in Amazon; (b) ProdCo shall deliver all Materials, work product, and documentation to Amazon; (c) Amazon shall own all work in progress; and (d) ProdCo shall have no right to any reversion of rights.', ARRAY['upon termination','any reason','all rights','remain vested','Amazon','deliver','Materials','work product','documentation','Amazon','own','work in progress','no right','reversion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "No reversion on termination", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear statement that rights remain with Amazon on any termination. No reversion under any circumstances. Essential for protecting Amazon''s investment."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Termination shall not affect: (i) Amazon''s ownership of all rights in the Program and Materials; (ii) Amazon''s right to exploit the Program in any manner; (iii) ProdCo''s indemnification obligations; (iv) any accrued rights or obligations; or (v) any provision that by its nature should survive termination.', ARRAY['termination','not affect','Amazon''s ownership','all rights','Program','Materials','right to exploit','any manner','indemnification','accrued rights','obligations','provision','nature','survive']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Survival of key provisions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive survival provisions ensuring ownership, exploitation rights, and indemnification continue post-termination. Accrued rights preservation is standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon Amazon''s termination for convenience, Amazon shall pay ProdCo: (a) all amounts earned through the termination date; (b) documented costs properly incurred prior to termination; and (c) reasonable documented wind-down costs, up to [specified cap]. No other amounts shall be payable.', ARRAY['termination for convenience','pay ProdCo','amounts earned','termination date','documented costs','properly incurred','prior to termination','reasonable','wind-down costs','cap','no other amounts','payable']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Convenience termination payment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear enumeration of convenience termination payments covering earned amounts and documented costs. Capped wind-down costs and ''no other amounts'' language limit exposure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If Amazon terminates for ProdCo''s breach, Amazon shall have no obligation to make any further payments to ProdCo, and Amazon may recover from ProdCo all damages, costs, and expenses arising from the breach, including the cost of completing the Program with a replacement production company.', ARRAY['terminates','ProdCo''s breach','no obligation','further payments','recover','ProdCo','all damages','costs','expenses','breach','cost of completing','Program','replacement production company']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Cause termination consequences", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "For-cause termination appropriately eliminates payment obligation and allows Amazon to recover all damages including replacement production costs."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Rights do not revert upon termination. ProdCo acknowledges that Amazon''s substantial investment in development, production, and marketing creates an interest that would be irreparably harmed by reversion, and ProdCo waives any reversion right that might otherwise exist.', ARRAY['Rights','not revert','termination','acknowledges','Amazon''s substantial investment','development','production','marketing','irreparably harmed','reversion','waives','reversion right']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Reversion waiver with justification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ProdCo acknowledgment of Amazon''s investment and waiver of reversion rights reinforces no-reversion position and provides enforcement support."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon termination, ProdCo shall within ten (10) business days: deliver all Materials in ProdCo''s possession; provide Amazon with access to all production files, accounts, and systems; assign to Amazon any third-party contracts Amazon elects to assume; and cooperate with Amazon''s transition to a replacement provider.', ARRAY['upon termination','ten business days','deliver','Materials','possession','provide','access','production files','accounts','systems','assign','Amazon','third-party contracts','elects','assume','cooperate','transition','replacement provider']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Transition cooperation requirements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Detailed transition requirements ensure Amazon can continue or complete production without ProdCo. Ten-day timeline and specific deliverables create clear obligations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall have no right to any ''kill fee,'' termination payment, or other compensation upon termination except as expressly set forth in the payment schedule. Any industry custom or practice regarding termination payments is hereby waived by ProdCo.', ARRAY['no right','kill fee','termination payment','other compensation','termination','except','expressly set forth','payment schedule','industry custom','practice','termination payments','waived']::text[], '{"doc": "PSA_Principal_Terms", "section": "Termination", "note": "Kill fee waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit waiver of kill fees and industry customs limits ProdCo to express Agreement terms. Prevents claims based on industry practice."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon termination, all rights remain with Amazon. If Amazon does not commercially exploit the Program within five (5) years of termination, ProdCo may request in writing that Amazon discuss a potential license back of certain development materials, which Amazon may grant or deny in its sole discretion.', ARRAY['termination','all rights','remain','Amazon','does not commercially exploit','Program','five years','ProdCo','request','writing','discuss','license back','development materials','grant','deny','sole discretion']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "License-back discussion for unexploited work", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Discussion right (not reversion right) for unexploited materials after 5 years with Amazon sole discretion may be acceptable. Doesn''t create automatic reversion or obligation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon Amazon''s convenience termination, ProdCo shall receive payments per the termination payment schedule. Additionally, if termination occurs during principal photography, Amazon shall pay the industry-standard penalty payments required to be paid to attached talent under their agreements.', ARRAY['convenience termination','ProdCo','receive payments','termination payment schedule','termination','during','principal photography','pay','industry-standard','penalty payments','attached talent','agreements']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Talent penalty passthrough", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Talent penalty passthrough for mid-photography termination is reasonable\u2014these are third-party obligations ProdCo cannot avoid. Should be verified against talent agreements."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Rights do not revert upon termination. However, ProdCo shall retain the right to receive any contingent compensation or profit participation it would have earned had the Program been completed and exploited, to the extent Amazon actually exploits the terminated Program materials.', ARRAY['Rights','not revert','termination','ProdCo','retain','right','contingent compensation','profit participation','earned','Program completed','exploited','Amazon','actually exploits','terminated','Program materials']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Contingent compensation survival", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Contingent compensation for actually-exploited terminated materials may be acceptable. Ties payment to actual exploitation rather than termination penalty."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon termination, Amazon owns all Materials. If Amazon terminates for convenience and later produces a version of the Program substantially similar to ProdCo''s creative approach, Amazon shall provide ProdCo with appropriate credit as set forth in the credit provisions, but no additional compensation.', ARRAY['termination','Amazon owns','all Materials','terminates','convenience','produces','version','Program','substantially similar','ProdCo''s creative approach','provide','appropriate credit','credit provisions','no additional compensation']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Credit for similar subsequent production", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Credit (no compensation) for subsequently-produced similar content is reasonable acknowledgment of ProdCo''s contribution without financial burden."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo acknowledges no reversion rights exist. Upon termination, ProdCo may retain copies of Materials solely for archival and portfolio purposes, subject to continued confidentiality obligations. ProdCo may reference its work on the Program in general terms for business development.', ARRAY['acknowledges','no reversion rights','termination','ProdCo','retain copies','Materials','archival','portfolio purposes','confidentiality obligations','reference','work','Program','general terms','business development']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Portfolio retention right", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Limited portfolio retention with confidentiality and general reference rights may be acceptable for ProdCo''s business development purposes without affecting Amazon''s ownership."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'No reversion upon termination. Amazon agrees that if it terminates for convenience and does not proceed with the Program, Amazon shall not assert claims against ProdCo for developing unrelated projects that may share incidental similarities with general concepts from the terminated Program.', ARRAY['no reversion','termination','Amazon','terminates','convenience','does not proceed','Program','not assert claims','ProdCo','developing','unrelated projects','incidental similarities','general concepts','terminated Program']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "No claims for unrelated similar work", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Non-assertion for incidental similarities in unrelated projects may be acceptable. Limited to general concepts, not specific Program elements. Allows ProdCo career continuity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Upon termination for any reason, all rights in the Program and Materials shall automatically revert to ProdCo. Amazon shall have no further rights to exploit the Program or any derivative works.', ARRAY['upon termination','any reason','all rights','Program','Materials','automatically revert','ProdCo','Amazon','no further rights','exploit','Program','derivative works']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Automatic reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Automatic reversion upon any termination completely destroys Amazon''s investment and rights. No reversion is permitted under any circumstances."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon terminates for convenience, all rights shall revert to ProdCo upon ProdCo''s repayment of 50% of amounts received from Amazon. ProdCo may then exploit the Program through any means.', ARRAY['Amazon terminates','convenience','all rights','revert','ProdCo','repayment','50%','amounts received','Amazon','exploit','Program','any means']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Buy-back reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Buy-back reversion even at 50% allows ProdCo to obtain rights Amazon invested in developing. Amazon''s rights must be absolute regardless of termination reason."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Upon Amazon''s termination for convenience, Amazon shall pay ProdCo the full remaining Production Fee for all ordered episodes as if production had been completed. This payment reflects ProdCo''s lost profits and opportunity costs.', ARRAY['termination for convenience','Amazon','pay ProdCo','full remaining Production Fee','all ordered episodes','production completed','lost profits','opportunity costs']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Full fee upon convenience termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Full Production Fee upon convenience termination makes termination economically prohibitive. Would eliminate Amazon''s practical ability to terminate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon terminates for cause, ProdCo disputes the cause, and an arbitrator determines the termination was wrongful, all rights shall revert to ProdCo and Amazon shall pay ProdCo the full Production Fee plus 100% as wrongful termination damages.', ARRAY['terminates for cause','ProdCo disputes','arbitrator determines','termination','wrongful','all rights','revert','ProdCo','pay','full Production Fee','100%','wrongful termination damages']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Reversion and penalty for disputed termination", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Reversion plus 200% payment for disputed cause termination creates massive disincentive to terminate even for legitimate cause. Rights must never revert regardless of termination circumstances."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Upon termination, rights remain with Amazon. However, ProdCo shall retain all underlying rights, including rights in the original literary property, format, and characters created by ProdCo, which shall revert to ProdCo free and clear.', ARRAY['upon termination','rights remain','Amazon','however','ProdCo','retain','underlying rights','original literary property','format','characters','created','ProdCo','revert','free and clear']::text[], '{"doc": "Counterparty_Markup", "section": "Termination", "note": "Underlying rights reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Reversion of underlying rights, format, and characters makes Amazon''s Program rights worthless. All rights, including underlying rights, must remain with Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon does not release the Program within two (2) years of delivery, all rights shall automatically revert to ProdCo. ProdCo may then produce the Program independently or license it to third parties.', ARRAY['Amazon','does not release','Program','two years','delivery','all rights','automatically revert','ProdCo','produce','Program','independently','license','third parties']::text[], '{"doc": "Counterparty_Proposal", "section": "Termination", "note": "Time-based automatic reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Automatic time-based reversion removes Amazon''s perpetual ownership rights. Amazon''s decision whether and when to release is its sole discretion; no reversion trigger is acceptable."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may suspend this Agreement and all work thereunder, including all payments, immediately upon notice to ProdCo if Amazon in good faith believes that grounds for termination may exist or if investigation of any matter relating to the Program or ProdCo is warranted.', ARRAY['Amazon may suspend','Agreement','all work','including','payments','immediately','notice','good faith believes','grounds for termination','may exist','investigation','matter','relating to','Program','ProdCo','warranted']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Broad suspension right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Broad suspension right for potential termination grounds or investigation needs. Payment suspension included. Amazon''s good faith belief is sufficient trigger."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may suspend production upon written notice if: (a) ProdCo may be in breach; (b) any third-party claim is asserted; (c) any governmental investigation is commenced; (d) any Key Person is subject to public allegations; or (e) Amazon determines that reputational risk exists. Payments shall be suspended during any suspension period.', ARRAY['Amazon may suspend','production','written notice','ProdCo','breach','third-party claim','asserted','governmental investigation','commenced','Key Person','public allegations','Amazon determines','reputational risk','payments','suspended','suspension period']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Enumerated suspension triggers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of suspension triggers including breach, claims, investigations, allegations, and reputational risk. Payment suspension protects Amazon during uncertainty."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'During any suspension, ProdCo shall immediately cease all work, preserve all Materials and documentation, cooperate with any Amazon investigation, and not take any action that would prejudice Amazon''s rights or position. ProdCo shall bear its own costs during suspension.', ARRAY['during suspension','ProdCo','immediately cease','all work','preserve','Materials','documentation','cooperate','Amazon investigation','not take','action','prejudice','Amazon''s rights','position','bear','own costs','suspension']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Suspension obligations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear enumeration of ProdCo''s suspension obligations including work stoppage, preservation, cooperation, and non-prejudice. ProdCo bearing own costs is appropriate given suspension trigger."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s suspension right shall be without limitation as to duration. Amazon may suspend for as long as Amazon reasonably deems necessary to investigate, evaluate, or address the matter giving rise to suspension. Amazon may terminate at any time during suspension.', ARRAY['suspension right','without limitation','duration','suspend','as long as','reasonably deems necessary','investigate','evaluate','address','matter','giving rise','suspension','terminate','any time','during suspension']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Unlimited suspension duration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Unlimited suspension duration provides Amazon maximum flexibility. Termination right during suspension ensures Amazon can exit if investigation reveals problems."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may suspend pending investigation of any credible allegation against any cast or crew member. During such suspension, Amazon may require that the subject individual be removed from the production as a condition of lifting the suspension, even if allegations are later not substantiated.', ARRAY['suspend','pending investigation','credible allegation','cast','crew member','require','subject individual','removed','production','condition','lifting suspension','allegations','not substantiated']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Personnel allegation suspension", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Personnel allegation suspension with removal condition protects production environment and Amazon reputation. Removal requirement even without substantiation is appropriate for serious allegations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If Amazon suspends due to force majeure event (pandemic, natural disaster, civil unrest), Amazon may extend the suspension for the duration of the event plus a reasonable recovery period. Suspension payments shall be determined per Schedule [X] for force majeure events.', ARRAY['suspends','force majeure','pandemic','natural disaster','civil unrest','extend','suspension','duration','event','reasonable recovery period','suspension payments','determined','Schedule','force majeure events']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Force majeure suspension", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Force majeure suspension with recovery period addresses production disruption events. Schedule reference for payments provides specificity for these circumstances."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s suspension right is in addition to, not in lieu of, termination rights. Amazon may lift suspension and resume production, lift suspension and terminate, or continue suspension indefinitely. ProdCo shall have no right to compel Amazon to lift suspension or to resume production.', ARRAY['suspension right','in addition to','not in lieu of','termination','lift suspension','resume production','terminate','continue suspension','indefinitely','ProdCo','no right','compel','lift suspension','resume production']::text[], '{"doc": "PSA_Principal_Terms", "section": "Suspension", "note": "Suspension outcome options", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear statement that suspension doesn''t limit termination and that ProdCo cannot compel lifting. Multiple outcome options preserve Amazon''s flexibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may suspend upon notice. If suspension continues for more than ninety (90) days, Amazon shall pay ProdCo''s documented reasonable costs of maintaining production readiness during the suspension period, up to [specified cap] per month.', ARRAY['suspend','notice','suspension continues','ninety days','Amazon','pay','documented','reasonable costs','maintaining','production readiness','suspension period','cap','per month']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Readiness payments after 90 days", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Capped readiness payments after extended suspension may be acceptable to maintain production capability. 90-day trigger and monthly cap limit exposure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may suspend pending investigation. Amazon shall use reasonable efforts to complete its investigation within sixty (60) days. If investigation extends beyond sixty days, Amazon shall provide ProdCo with status updates every thirty (30) days.', ARRAY['suspend','pending investigation','reasonable efforts','complete','investigation','sixty days','extends beyond','sixty days','provide','ProdCo','status updates','thirty days']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Investigation timeline with updates", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Reasonable efforts on investigation timeline and status updates are procedural accommodations that don''t limit Amazon''s suspension rights or duration."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may suspend upon notice. During suspension, ProdCo may request in writing an explanation of the general basis for suspension. Amazon shall respond within ten (10) business days with such information as Amazon deems appropriate to share, consistent with any confidentiality or legal constraints.', ARRAY['suspend','notice','during suspension','ProdCo','request','writing','explanation','general basis','suspension','respond','ten business days','information','Amazon deems appropriate','confidentiality','legal constraints']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Explanation upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited explanation right (general basis, Amazon discretion on content) may be acceptable. Preserves confidentiality and legal constraints while providing minimal transparency."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may suspend. If Amazon lifts suspension and elects to resume production, Amazon shall provide ProdCo with reasonable time (not less than fifteen (15) business days) to remobilize production resources before resumption of the production schedule.', ARRAY['suspend','lifts suspension','elects','resume production','provide','ProdCo','reasonable time','fifteen business days','remobilize','production resources','resumption','production schedule']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Remobilization period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Remobilization period upon resumption is practical operational need. 15 business days is reasonable minimum for production restart."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s suspension right includes the right to suspend individual elements (e.g., specific episodes, specific personnel) while permitting other production to continue. Payments shall be adjusted proportionately for partial suspensions as reasonably determined by Amazon.', ARRAY['suspension right','suspend','individual elements','specific episodes','specific personnel','permitting','other production','continue','payments','adjusted proportionately','partial suspensions','reasonably determined','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Partial suspension option", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Partial suspension option provides granularity to address specific issues without full production stoppage. Proportionate payment adjustment is reasonable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If suspension results from force majeure, the parties shall cooperate in good faith to address the force majeure event and resume production as soon as practicable. Neither party shall be liable for delays caused by force majeure, but the suspension provisions shall otherwise apply.', ARRAY['suspension','force majeure','cooperate','good faith','address','force majeure event','resume production','as soon as practicable','neither party','liable','delays','caused','force majeure','suspension provisions','apply']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Force majeure cooperation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Good faith cooperation on force majeure with no delay liability is standard. Clarification that suspension provisions otherwise apply preserves Amazon''s rights."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may suspend for a maximum of thirty (30) days. If Amazon does not lift the suspension within thirty days, Amazon must either resume production or terminate. Suspension may not be extended beyond thirty days without ProdCo''s consent.', ARRAY['suspend','maximum','thirty days','does not lift','suspension','thirty days','must','resume production','terminate','may not be extended','beyond','thirty days','ProdCo''s consent']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "30-day suspension limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "30-day suspension limit with forced decision or ProdCo consent is completely inadequate. Investigations and circumstances may require extended suspension without artificial limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may suspend with written notice. During any suspension, Amazon shall continue to make all payments to ProdCo as if production were continuing, as ProdCo must maintain its team and production infrastructure.', ARRAY['suspend','written notice','during suspension','Amazon','continue','all payments','ProdCo','production','continuing','maintain','team','production infrastructure']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Full payment during suspension", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Full payment during suspension eliminates Amazon''s ability to limit exposure during uncertainty. Payment suspension is essential component of suspension right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may suspend only for the specific grounds enumerated in this Section. Suspensions for reasons not expressly listed, or suspensions that ProdCo believes are pretextual, shall entitle ProdCo to continue production and require Amazon to continue payments.', ARRAY['suspend','only','specific grounds','enumerated','Section','suspensions','not expressly listed','ProdCo believes','pretextual','entitle','ProdCo','continue production','require','Amazon','continue payments']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Limited grounds with pretext challenge", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting suspension to enumerated grounds with pretext challenge right gives ProdCo ability to override Amazon''s suspension decision. Amazon must have broad, unchallengeable suspension right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon suspends, ProdCo may elect to terminate this Agreement upon thirty (30) days'' written notice if the suspension continues for more than sixty (60) days, and upon such termination all rights shall revert to ProdCo.', ARRAY['Amazon suspends','ProdCo','elect','terminate','thirty days','written notice','suspension continues','sixty days','termination','all rights','revert','ProdCo']::text[], '{"doc": "Counterparty_Proposal", "section": "Suspension", "note": "ProdCo termination and reversion for extended suspension", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo termination right with reversion for extended suspension completely undermines Amazon''s suspension right. Would force Amazon to lift suspension or lose rights."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may suspend upon notice. Any suspension exceeding fourteen (14) days shall entitle ProdCo to compensation equal to [percentage] of the Production Fee for each week of continued suspension, as liquidated damages for the disruption.', ARRAY['suspend','notice','suspension exceeding','fourteen days','entitle','ProdCo','compensation','percentage','Production Fee','each week','continued suspension','liquidated damages','disruption']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Per-week suspension penalty", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Weekly suspension penalty makes extended suspension economically prohibitive. Would pressure Amazon to lift suspension before investigation is complete."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may suspend only after providing ProdCo with detailed written grounds for suspension and giving ProdCo fifteen (15) business days to respond to such grounds. If ProdCo''s response satisfactorily addresses the grounds, Amazon may not proceed with suspension.', ARRAY['suspend','only after','detailed written grounds','suspension','giving ProdCo','fifteen business days','respond','ProdCo''s response','satisfactorily addresses','grounds','Amazon may not proceed','suspension']::text[], '{"doc": "Counterparty_Markup", "section": "Suspension", "note": "Pre-suspension response period", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Pre-suspension response period with ProdCo ability to block suspension eliminates Amazon''s ability to act quickly when needed. Immediate suspension must be available."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall obtain and maintain throughout the term of this Agreement and for a period of not less than three (3) years thereafter: (a) Commercial General Liability insurance with limits of not less than $2,000,000 per occurrence and $5,000,000 aggregate; (b) Errors and Omissions insurance with limits of not less than $3,000,000 per claim and $5,000,000 aggregate; (c) Workers'' Compensation insurance as required by applicable law; and (d) Commercial Automobile Liability insurance with limits of not less than $1,000,000 combined single limit.', ARRAY['obtain','maintain','throughout term','three years thereafter','Commercial General Liability','$2,000,000 per occurrence','$5,000,000 aggregate','Errors and Omissions','$3,000,000 per claim','$5,000,000 aggregate','Workers'' Compensation','applicable law','Commercial Automobile Liability','$1,000,000 combined single limit']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Standard insurance requirements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive insurance requirements covering CGL, E&O, Workers'' Comp, and Auto. Limits are appropriate minimums for production activities. Three-year tail provides post-production coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain: (i) Commercial General Liability insurance covering bodily injury, property damage, personal injury, and advertising injury; (ii) Producers Errors and Omissions insurance covering claims arising from the content of the Program including infringement, defamation, and invasion of privacy; (iii) Workers'' Compensation and Employers Liability insurance; and (iv) Hired and Non-Owned Automobile Liability insurance.', ARRAY['Commercial General Liability','bodily injury','property damage','personal injury','advertising injury','Producers Errors and Omissions','claims','content','Program','infringement','defamation','invasion of privacy','Workers'' Compensation','Employers Liability','Hired and Non-Owned Automobile']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Specified coverage types", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specifies coverage types for each policy category. E&O specifically covers content-related claims. Hired/Non-Owned Auto addresses production vehicle use."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Insurance requirements include: Cast Insurance covering death, disability, or incapacity of Key Persons; Negative Film and Videotape Insurance covering loss of or damage to raw stock, exposed film, and recorded videotape; Faulty Stock, Camera, and Processing Insurance; Extra Expense Insurance; and Props, Sets, and Wardrobe Insurance.', ARRAY['Cast Insurance','death','disability','incapacity','Key Persons','Negative Film','Videotape Insurance','loss','damage','raw stock','exposed film','recorded videotape','Faulty Stock','Camera','Processing','Extra Expense','Props','Sets','Wardrobe']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Production-specific coverages", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Production-specific insurance types addressing cast contingency, negative/media protection, equipment, and physical assets. Essential for comprehensive production protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall obtain Umbrella/Excess Liability insurance with limits of not less than $10,000,000 per occurrence and aggregate, providing excess coverage over the Commercial General Liability, Automobile Liability, and Employers Liability policies.', ARRAY['Umbrella','Excess Liability','$10,000,000','per occurrence','aggregate','excess coverage','Commercial General Liability','Automobile Liability','Employers Liability']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Umbrella coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Umbrella coverage provides additional protection above primary limits. $10M is appropriate for significant productions. Excess over multiple policy types ensures comprehensive protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All required insurance policies shall: (a) be written on an occurrence basis (except E&O which may be claims-made with retroactive date prior to commencement of services); (b) be issued by insurers with A.M. Best ratings of A- VII or better; (c) be primary and non-contributory; and (d) include a waiver of subrogation in favor of Amazon.', ARRAY['occurrence basis','except E&O','claims-made','retroactive date','prior to commencement','A.M. Best','A- VII','primary','non-contributory','waiver of subrogation','favor of Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Policy specifications", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Key policy specifications: occurrence basis for CGL, claims-made with retro date for E&O, carrier quality rating, primary/non-contributory status, and subrogation waiver. Industry-standard requirements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain Cyber Liability insurance with limits of not less than $1,000,000 covering data breach, network security liability, media liability, and regulatory defense and penalties, to the extent ProdCo handles personal data or confidential information in connection with the production.', ARRAY['Cyber Liability','$1,000,000','data breach','network security liability','media liability','regulatory defense','penalties','personal data','confidential information','production']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Cyber liability coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Cyber coverage is increasingly important for productions handling personal data. Coverage for breach, security liability, and regulatory matters addresses modern production risks."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For productions involving stunts, special effects, pyrotechnics, or hazardous activities, ProdCo shall obtain additional coverage including Stunt Liability, Pyrotechnics Coverage, Aircraft/Watercraft Liability (as applicable), and increased CGL limits of not less than $5,000,000 per occurrence.', ARRAY['stunts','special effects','pyrotechnics','hazardous activities','additional coverage','Stunt Liability','Pyrotechnics Coverage','Aircraft','Watercraft Liability','increased CGL','$5,000,000 per occurrence']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Hazardous activity coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Additional coverage requirements for hazardous production activities. Increased CGL limits and specialized policies address elevated risk scenarios."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain the insurance types specified herein. If any required coverage is not commercially available on reasonable terms, ProdCo shall promptly notify Amazon and the parties shall discuss alternatives. Amazon may waive or modify requirements in its reasonable discretion.', ARRAY['insurance types','specified','not commercially available','reasonable terms','promptly notify','Amazon','discuss alternatives','waive','modify','reasonable discretion']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Commercial availability exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Commercial availability exception with Amazon waiver discretion is reasonable given occasional market constraints. Prompt notification and Amazon approval required."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Insurance limits may be satisfied through any combination of primary and umbrella/excess policies. The aggregate of primary and excess limits shall meet or exceed the required amounts. Certificates shall identify all policies contributing to required limits.', ARRAY['limits','satisfied','combination','primary','umbrella','excess policies','aggregate','meet','exceed','required amounts','certificates','identify','policies','contributing']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Combined limit satisfaction", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Allowing combined primary/excess to meet limits provides flexibility without reducing coverage. Certificate identification ensures transparency."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain required coverages. For productions with budgets under $[threshold], the following reduced limits shall apply: CGL $1,000,000/$2,000,000; E&O $1,000,000/$2,000,000; Umbrella $5,000,000. Amazon may increase limits if production scope expands.', ARRAY['required coverages','productions','budgets under','threshold','reduced limits','CGL $1,000,000/$2,000,000','E&O $1,000,000/$2,000,000','Umbrella $5,000,000','increase limits','production scope expands']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Budget-based tiered limits", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Tiered limits based on budget may be acceptable for smaller productions. Amazon''s right to increase limits preserves flexibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain E&O insurance on a claims-made basis with a retroactive date no later than the earlier of the Effective Date or commencement of development services. The policy shall be maintained for at least three (3) years following final delivery, or ProdCo shall purchase an extended reporting period (tail) of equivalent duration.', ARRAY['E&O insurance','claims-made','retroactive date','Effective Date','commencement','development services','maintained','three years','final delivery','extended reporting period','tail','equivalent duration']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Claims-made tail requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Claims-made policy with proper retro date and tail requirement ensures coverage for claims arising after production. Three-year tail is appropriate minimum."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain insurance as specified. ProdCo may self-insure the first $[amount] of any claim under CGL or Auto policies, provided ProdCo demonstrates financial capacity to cover such self-insured retention and Amazon approves the arrangement in writing.', ARRAY['insurance','specified','self-insure','first','amount','claim','CGL','Auto','financial capacity','self-insured retention','Amazon approves','writing']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Self-insured retention option", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Self-insured retention with Amazon approval and financial capacity demonstration may be acceptable for established ProdCos. Maintains insurance above retention level."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Insurance requirements specified herein represent minimums. ProdCo acknowledges that Amazon''s risk management team may require increased limits or additional coverages based on specific production risks, locations, or activities, and ProdCo shall comply with such requirements.', ARRAY['requirements','minimums','Amazon''s risk management','require','increased limits','additional coverages','production risks','locations','activities','comply','requirements']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Risk-based adjustment right", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s ability to require increased coverage for specific risks is appropriate. Stated minimums don''t limit Amazon''s ability to require more based on circumstances."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use commercially reasonable efforts to obtain the insurance coverages specified herein. If any coverage is unavailable or prohibitively expensive, ProdCo shall notify Amazon and proceed with production without such coverage.', ARRAY['commercially reasonable efforts','obtain','insurance coverages','unavailable','prohibitively expensive','notify Amazon','proceed','production','without','coverage']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Reasonable efforts with proceed-without option", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' standard with ability to proceed without coverage is completely unacceptable. Insurance is mandatory; Amazon cannot be exposed to uninsured production risks."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain CGL and Workers'' Compensation insurance as required by law. E&O insurance shall be optional and at ProdCo''s discretion. Amazon shall not require insurance coverages beyond those mandated by applicable law.', ARRAY['CGL','Workers'' Compensation','required by law','E&O','optional','ProdCo''s discretion','Amazon','not require','insurance','beyond','mandated','applicable law']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "E&O optional with legal minimum only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "E&O is essential for content liability; making it optional is completely unacceptable. Amazon''s insurance requirements properly exceed legal minimums."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall obtain insurance with limits determined by ProdCo based on industry standards and ProdCo''s assessment of production risks. Amazon may not specify minimum limits or required coverage types.', ARRAY['insurance','limits','determined by ProdCo','industry standards','ProdCo''s assessment','production risks','Amazon may not specify','minimum limits','required coverage types']::text[], '{"doc": "Counterparty_Proposal", "section": "Insurance", "note": "ProdCo-determined coverage", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo-determined coverage with no Amazon minimums eliminates Amazon''s protection. Amazon must specify required coverage types and minimum limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Insurance requirements shall be shared between the parties. Amazon shall obtain and pay for E&O insurance covering the Program. ProdCo shall obtain CGL and Workers'' Compensation only.', ARRAY['insurance requirements','shared','parties','Amazon','obtain','pay for','E&O','covering','Program','ProdCo','CGL','Workers'' Compensation only']::text[], '{"doc": "Counterparty_Proposal", "section": "Insurance", "note": "Split insurance responsibility", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Shifting E&O to Amazon reverses appropriate allocation. ProdCo creates content and must insure against content claims. Amazon should be additional insured, not primary insured."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain insurance. The cost of all required insurance shall be a production cost reimbursable by Amazon as a line item in the Production Budget, with no cap on insurance costs.', ARRAY['maintain insurance','cost','required insurance','production cost','reimbursable','Amazon','line item','Production Budget','no cap','insurance costs']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Uncapped insurance cost passthrough", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Uncapped insurance cost passthrough shifts all insurance cost risk to Amazon. Insurance should be within approved budget, not unlimited passthrough."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain E&O insurance with limits of $500,000 per claim and $1,000,000 aggregate. These limits reflect industry standards for independent productions and shall not be increased.', ARRAY['E&O insurance','$500,000 per claim','$1,000,000 aggregate','industry standards','independent productions','not be increased']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Inadequate E&O limits", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "$500K/$1M E&O limits are grossly inadequate for Amazon content. Minimum E&O should be $3M/$5M or higher depending on production scope."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All insurance policies required hereunder (except Workers'' Compensation) shall name Amazon.com, Inc. and its parents, subsidiaries, affiliates, successors, assigns, officers, directors, employees, and agents as additional insureds. Such coverage shall be primary and non-contributory with respect to any insurance or self-insurance maintained by Amazon.', ARRAY['insurance policies','except Workers'' Compensation','name','Amazon.com Inc','parents','subsidiaries','affiliates','successors','assigns','officers','directors','employees','agents','additional insureds','primary','non-contributory','insurance','self-insurance','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Standard additional insured with primary/non-contributory", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive additional insured designation covering Amazon corporate family and personnel. Primary/non-contributory status ensures Amazon''s insurance is not accessed. Workers'' Comp exception is standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall be named as additional insured using ISO form CG 20 10 (or equivalent broad form endorsement) for ongoing operations and CG 20 37 (or equivalent) for completed operations. The additional insured status shall provide coverage for Amazon''s vicarious liability arising from ProdCo''s acts or omissions.', ARRAY['additional insured','ISO form','CG 20 10','equivalent','broad form endorsement','ongoing operations','CG 20 37','completed operations','coverage','Amazon''s vicarious liability','ProdCo''s acts','omissions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Specified endorsement forms", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specifies industry-standard ISO endorsement forms for ongoing and completed operations. Vicarious liability coverage is essential for protecting Amazon from ProdCo conduct."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The additional insured coverage shall not be subject to any cross-liability exclusion, separation of insureds condition limitation, or any endorsement limiting coverage for additional insureds to the extent such limitations would reduce coverage for Amazon below that available to ProdCo as the named insured.', ARRAY['additional insured coverage','not subject to','cross-liability exclusion','separation of insureds','limitation','endorsement limiting','coverage','additional insureds','reduce coverage','Amazon','below','ProdCo','named insured']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "No coverage limitations for additional insureds", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Ensures additional insured coverage is not limited by common policy exclusions. Amazon should have equivalent coverage to the named insured."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s insurers shall waive any right of subrogation against Amazon and all Amazon Indemnitees. Such waiver shall be evidenced by endorsement to the applicable policies and shall apply regardless of whether the loss arises from Amazon''s negligence.', ARRAY['insurers','waive','right of subrogation','Amazon','Amazon Indemnitees','waiver','evidenced','endorsement','applicable policies','regardless','Amazon''s negligence']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Subrogation waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Subrogation waiver prevents ProdCo''s insurers from pursuing Amazon after paying claims. Application regardless of Amazon negligence provides complete protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s status as additional insured shall: (a) be effective as of the earlier of the Effective Date or commencement of any services; (b) continue throughout the term and thereafter for claims arising from covered activities; and (c) extend to all Amazon-related entities that may be involved in exploitation of the Program.', ARRAY['Amazon''s status','additional insured','effective','Effective Date','commencement','services','continue','throughout term','thereafter','claims','covered activities','extend','Amazon-related entities','exploitation','Program']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Temporal and entity scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive temporal scope from pre-production through post-term claims. Extension to all Amazon-related entities ensures complete coverage of exploitation chain."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The primary and non-contributory requirement means that ProdCo''s insurance shall respond first without seeking contribution from any insurance maintained by Amazon. Amazon''s insurance shall be excess only and shall not be called upon to contribute until ProdCo''s insurance limits are exhausted.', ARRAY['primary','non-contributory','ProdCo''s insurance','respond first','without seeking contribution','insurance','Amazon','Amazon''s insurance','excess only','not called upon','contribute','limits','exhausted']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Primary/non-contributory explanation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear explanation of primary/non-contributory meaning prevents interpretation disputes. Amazon''s insurance is pure excess after ProdCo''s limits exhaust."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All required policies shall include an endorsement providing that Amazon shall receive not less than thirty (30) days'' prior written notice of any cancellation, non-renewal, or material change in coverage. ProdCo shall ensure that any replacement policy provides continuous coverage without gap.', ARRAY['endorsement','Amazon','receive','thirty days','prior written notice','cancellation','non-renewal','material change','coverage','replacement policy','continuous coverage','without gap']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Notice of cancellation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "30-day cancellation notice requirement is industry standard. Continuous coverage obligation ensures no gap in protection during policy transitions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall be named as additional insured. If ProdCo''s insurer will only provide ten (10) days'' notice of cancellation for non-payment of premium (which is industry standard), this shall be acceptable provided ProdCo maintains thirty (30) days'' notice for all other cancellations.', ARRAY['additional insured','insurer','ten days','notice','cancellation','non-payment','premium','industry standard','acceptable','thirty days','notice','other cancellations']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "10-day notice exception for non-payment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "10-day notice for non-payment cancellation is common insurer limitation. Acceptable if 30 days maintained for other cancellations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall be additional insured. If the policy uses a ''blanket additional insured'' endorsement that automatically covers parties required by contract, this shall satisfy the additional insured requirement provided the endorsement scope covers Amazon''s categories of additional insureds.', ARRAY['additional insured','blanket additional insured','endorsement','automatically covers','parties','required by contract','satisfy','requirement','endorsement scope','covers','Amazon''s categories']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Blanket AI endorsement acceptable", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Blanket additional insured endorsements are common and acceptable if scope is adequate. More efficient than specific endorsements for each contract."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Primary and non-contributory coverage applies. The parties acknowledge that certain excess/umbrella policies may follow the underlying insurance terms regarding contribution. Excess/umbrella following form shall be acceptable provided primary policies are non-contributory.', ARRAY['primary','non-contributory','applies','acknowledge','excess','umbrella policies','follow','underlying insurance terms','contribution','following form','acceptable','primary policies','non-contributory']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Excess following form acceptable", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Excess policies following primary terms on contribution is common structure. Acceptable if primary policies are properly non-contributory."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall be additional insured with primary and non-contributory coverage. Amazon''s additional insured status on E&O policies shall be subject to standard industry exclusions for insureds'' own independent negligence or intentional acts.', ARRAY['additional insured','primary','non-contributory','E&O','subject to','standard industry exclusions','insureds''','independent negligence','intentional acts']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "E&O standard exclusions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "E&O exclusions for Amazon''s own negligence or intentional acts are common and generally acceptable. Coverage for ProdCo-caused claims is primary purpose."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All policies shall include Amazon as additional insured. Amazon Indemnitees beyond Amazon.com, Inc. and its direct affiliates shall be added upon Amazon''s written request, and ProdCo shall use reasonable efforts to obtain such additional coverage without material additional premium.', ARRAY['policies','include','Amazon','additional insured','Amazon Indemnitees','beyond','Amazon.com Inc','direct affiliates','added','written request','reasonable efforts','additional coverage','without material additional premium']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Extended AI upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Core Amazon entities as automatic AI with others upon request is acceptable structure. Reasonable efforts qualification and material premium exception are practical limitations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Subrogation waiver in favor of Amazon applies. Such waiver shall be obtained where available and commercially reasonable. If waiver is not available, ProdCo shall notify Amazon and the parties shall discuss allocation of any subrogation risk.', ARRAY['subrogation waiver','favor of Amazon','applies','obtained','available','commercially reasonable','not available','notify Amazon','discuss','allocation','subrogation risk']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Subrogation waiver with availability exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Subrogation waiver with commercial availability exception addresses occasional insurer limitations. Discussion of allocation provides flexibility for unusual situations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall be named as additional insured on a contributory basis. ProdCo''s insurance and Amazon''s insurance shall contribute equally to any covered claims based on respective policy limits.', ARRAY['additional insured','contributory basis','ProdCo''s insurance','Amazon''s insurance','contribute equally','covered claims','respective policy limits']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Contributory instead of non-contributory", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Contributory rather than non-contributory defeats purpose of insurance requirements. Amazon''s insurance should be accessed only after ProdCo''s is exhausted."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may be named as additional insured only if ProdCo''s insurer agrees without additional premium. If additional premium is required, Amazon may elect to pay such premium or waive the additional insured requirement.', ARRAY['additional insured','only if','insurer agrees','without additional premium','additional premium required','Amazon','elect','pay','premium','waive','additional insured requirement']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "AI contingent on no premium", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Conditioning additional insured status on no additional premium effectively makes it optional. Additional insured is mandatory requirement regardless of premium impact."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall be additional insured on CGL only. E&O coverage shall insure ProdCo only; Amazon shall be covered by its own E&O policy for any claims arising from the Program.', ARRAY['additional insured','CGL only','E&O','insure','ProdCo only','Amazon','covered','own E&O','claims','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "AI on CGL only, not E&O", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding Amazon from E&O additional insured status removes coverage for the most significant claims (content liability). Amazon must be AI on all required policies except Workers'' Comp."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s additional insured coverage shall be secondary to any insurance maintained by Amazon. If Amazon has available insurance, that coverage shall respond first before ProdCo''s policies are accessed.', ARRAY['additional insured coverage','secondary','insurance','Amazon','Amazon has available insurance','coverage','respond first','ProdCo''s policies','accessed']::text[], '{"doc": "Counterparty_Proposal", "section": "Insurance", "note": "Secondary rather than primary", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Secondary coverage inverts proper insurance structure. ProdCo''s insurance must be primary; Amazon''s insurance should be pure excess."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain additional insured status for Amazon subject to standard policy exclusions. Amazon''s additional insured coverage shall be limited to claims directly caused by ProdCo''s sole negligence and shall not cover claims arising from Amazon''s comparative fault.', ARRAY['additional insured status','Amazon','standard policy exclusions','limited','claims','directly caused','ProdCo''s sole negligence','not cover','claims','Amazon''s comparative fault']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Sole negligence limitation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Sole negligence limitation excludes claims where Amazon has any fault. Vicarious liability claims typically involve some Amazon involvement; coverage must apply to all claims arising from ProdCo''s conduct."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may be additional insured. ProdCo''s insurers reserve the right to subrogate against Amazon for any claims arising from Amazon''s negligence, direction, or instructions provided to ProdCo during production.', ARRAY['additional insured','insurers','reserve','right','subrogate','Amazon','claims','Amazon''s negligence','direction','instructions','provided','ProdCo','production']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Retained subrogation rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Retained subrogation rights defeat purpose of additional insured status. Amazon would face claims from ProdCo''s insurers after they pay claims. Subrogation must be waived."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Minimum insurance limits shall be: CGL: $2,000,000 per occurrence / $5,000,000 aggregate; E&O: $3,000,000 per claim / $5,000,000 aggregate; Umbrella: $10,000,000 per occurrence and aggregate; Auto: $1,000,000 combined single limit; Employers Liability: $1,000,000 per accident.', ARRAY['minimum insurance limits','CGL','$2,000,000 per occurrence','$5,000,000 aggregate','E&O','$3,000,000 per claim','$5,000,000 aggregate','Umbrella','$10,000,000','Auto','$1,000,000 combined single limit','Employers Liability','$1,000,000 per accident']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Standard minimum limits", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard minimum limits appropriate for typical productions. E&O at $3M/$5M provides adequate content liability coverage. $10M umbrella supplements primary limits."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For productions with budgets exceeding $25,000,000, the following enhanced limits shall apply: CGL: $5,000,000 per occurrence / $10,000,000 aggregate; E&O: $5,000,000 per claim / $10,000,000 aggregate; Umbrella: $25,000,000 per occurrence and aggregate.', ARRAY['productions','budgets exceeding','$25,000,000','enhanced limits','CGL','$5,000,000 per occurrence','$10,000,000 aggregate','E&O','$5,000,000 per claim','$10,000,000 aggregate','Umbrella','$25,000,000']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Enhanced limits for large productions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Budget-scaled limits for larger productions appropriately match insurance to production scope. Higher limits for higher-budget content reflect greater exposure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Errors and Omissions insurance shall provide coverage for: (a) copyright and trademark infringement; (b) defamation, libel, and slander; (c) invasion of privacy and publicity rights; (d) infliction of emotional distress; (e) breach of contract (third party); and (f) negligent misrepresentation. Defense costs shall be in addition to, not within, policy limits.', ARRAY['Errors and Omissions','coverage','copyright','trademark infringement','defamation','libel','slander','invasion of privacy','publicity rights','infliction','emotional distress','breach of contract','negligent misrepresentation','defense costs','in addition to','not within','policy limits']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "E&O coverage scope with defense outside limits", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive E&O coverage scope addressing all content-related claims. Defense costs outside limits is preferred structure preserving full limits for damages."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may, in its reasonable discretion, require increased limits based on: (a) unusual production risks (stunts, pyrotechnics, exotic locations); (b) use of minors; (c) documentary content involving public figures; (d) true crime or controversial subject matter; or (e) other factors creating elevated liability exposure.', ARRAY['Amazon','reasonable discretion','require','increased limits','unusual production risks','stunts','pyrotechnics','exotic locations','minors','documentary','public figures','true crime','controversial','elevated liability exposure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Discretionary limit increases", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s discretion to require increased limits for elevated-risk scenarios ensures coverage matches actual risk profile. Enumerated factors provide guidance."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The E&O policy shall have a deductible or self-insured retention of no more than $50,000. ProdCo shall be responsible for payment of any deductible or retention. Amazon shall be included in the policy as a loss payee for any deductible recovery.', ARRAY['E&O policy','deductible','self-insured retention','no more than','$50,000','ProdCo','responsible','payment','deductible','retention','Amazon','loss payee','deductible recovery']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Deductible limits", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Reasonable deductible cap ensures coverage is accessible without significant first-dollar exposure. ProdCo responsibility and loss payee status protects Amazon."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Minimum limits specified herein are per-project minimums. If ProdCo maintains corporate policies covering multiple productions, such policies shall have aggregate limits sufficient to provide not less than the specified per-project minimums for this production while maintaining adequate reserves for other covered productions.', ARRAY['minimum limits','per-project minimums','corporate policies','multiple productions','aggregate limits','sufficient','per-project minimums','this production','adequate reserves','other covered productions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Corporate policy adequacy", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses corporate policies covering multiple productions. Requires adequate reserves to ensure this production has effective minimums despite aggregation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Insurance limits shall be maintained at the specified minimums throughout the term of this Agreement and for a period of not less than five (5) years following final delivery of the Program. If any policy is cancelled or limits reduced, ProdCo shall obtain replacement coverage immediately.', ARRAY['insurance limits','maintained','specified minimums','throughout term','five years','following','final delivery','Program','policy','cancelled','limits reduced','obtain','replacement coverage','immediately']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Maintenance period with replacement requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Five-year post-delivery maintenance ensures coverage for latent claims. Immediate replacement requirement addresses mid-term coverage lapses."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Minimum limits shall apply. If any required policy is offered only with higher deductibles or retentions than specified, ProdCo shall accept such terms provided the deductible does not exceed $100,000 per occurrence, and ProdCo demonstrates financial capacity to cover such retention.', ARRAY['minimum limits','apply','policy','higher deductibles','retentions','than specified','accept','terms','deductible','not exceed','$100,000','per occurrence','financial capacity','cover','retention']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Higher deductible flexibility", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Flexibility on higher deductibles up to $100K may be acceptable given market conditions. Financial capacity demonstration protects Amazon from unfunded retentions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Specified minimum limits apply. For unscripted/reality productions, E&O limits may be reduced to $2,000,000 per claim / $3,000,000 aggregate given the lower content liability typically associated with such formats, subject to Amazon approval.', ARRAY['minimum limits','apply','unscripted','reality productions','E&O limits','reduced','$2,000,000 per claim','$3,000,000 aggregate','lower content liability','formats','Amazon approval']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Reduced limits for unscripted", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Lower E&O for unscripted may be acceptable if Amazon approves based on specific content. Some reality content has higher risk; approval requirement preserves discretion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Limits shall meet specified minimums. If ProdCo maintains an annual policy with aggregate limits that may be eroded by claims on other projects, ProdCo shall monitor aggregate availability and notify Amazon if remaining aggregate falls below 75% of policy aggregate.', ARRAY['limits','specified minimums','annual policy','aggregate limits','eroded','claims','other projects','monitor','aggregate availability','notify Amazon','remaining aggregate','falls below','75%','policy aggregate']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Aggregate monitoring obligation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Aggregate monitoring for multi-project policies addresses erosion risk. 75% threshold provides early warning before limits become inadequate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Minimum limits are specified above. Defense costs may be within policy limits (eroding limits) for E&O policies if defense-outside-limits coverage is not available in the market or would require premium exceeding 125% of defense-within premium.', ARRAY['minimum limits','defense costs','within policy limits','eroding limits','E&O','defense-outside-limits','not available','market','premium exceeding','125%','defense-within premium']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Defense-within-limits exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Defense-within-limits is less favorable but may be acceptable with market availability exception. Premium threshold provides objective standard for exception."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'E&O coverage shall be maintained for five years post-delivery. If obtaining a five-year tail is cost-prohibitive (exceeding 200% of annual premium), ProdCo shall purchase a three-year tail and notify Amazon, and the parties shall discuss allocation of post-tail risk.', ARRAY['E&O','maintained','five years','post-delivery','five-year tail','cost-prohibitive','exceeding','200%','annual premium','purchase','three-year tail','notify Amazon','discuss','allocation','post-tail risk']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Tail cost flexibility", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Tail cost exception with 200% threshold may be acceptable for extraordinary pricing. Three-year minimum tail and allocation discussion preserves protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Limits shall be maintained as specified. Amazon acknowledges that E&O limits are shared across the policy period and may be reduced by claims. Amazon may require ProdCo to reinstate limits if aggregate is materially reduced during production.', ARRAY['limits','maintained','specified','acknowledges','E&O limits','shared','policy period','reduced','claims','require','ProdCo','reinstate limits','aggregate','materially reduced','during production']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Limit reinstatement right", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledgment of aggregate erosion with reinstatement right addresses practical policy mechanics while preserving Amazon''s protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Insurance limits shall be determined by ProdCo based on industry standards and production budget. ProdCo represents that it maintains adequate insurance for its operations and shall ensure coverage is appropriate for this production.', ARRAY['insurance limits','determined by ProdCo','industry standards','production budget','represents','maintains','adequate insurance','operations','ensure','coverage','appropriate','production']::text[], '{"doc": "Counterparty_Proposal", "section": "Insurance", "note": "ProdCo-determined limits", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo-determined limits with no Amazon-specified minimums provides no protection. Amazon must specify minimum limits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'E&O insurance with limits of $500,000 per claim and $1,000,000 aggregate shall be sufficient for this production, which is consistent with independent production industry standards.', ARRAY['E&O insurance','$500,000 per claim','$1,000,000 aggregate','sufficient','production','consistent','independent production','industry standards']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Inadequate E&O limits", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "$500K/$1M E&O limits are grossly inadequate for Amazon content. Single content claim can easily exceed these limits. Minimum should be $3M/$5M."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Minimum limits shall apply only during active production. Following completion of principal photography, limits may be reduced by 50%. Following final delivery, ProdCo shall maintain only statutory minimum coverages.', ARRAY['minimum limits','only during','active production','following completion','principal photography','limits','reduced','50%','following final delivery','maintain','only','statutory minimum']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Post-production limit reductions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Post-production limit reductions to 50% or statutory minimums leaves Amazon exposed when content claims are most likely to arise (after release). Full limits must be maintained through tail period."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Insurance limits specified herein are aspirational targets. ProdCo shall use best efforts to obtain such limits but shall not be in breach if lower limits are obtained, provided coverage is commercially reasonable for productions of this type.', ARRAY['limits','specified','aspirational targets','best efforts','obtain','limits','not be in breach','lower limits','obtained','coverage','commercially reasonable','productions']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Aspirational limits only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Aspirational'' limits with no breach for lower amounts effectively makes limits optional. Insurance minimums must be mandatory requirements, not targets."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain E&O insurance. The policy may contain standard industry exclusions including exclusions for: prior knowledge; intellectual property claims; claims by investors or financiers; intentional acts; and cyber-related claims.', ARRAY['E&O insurance','policy','standard industry exclusions','prior knowledge','intellectual property claims','investors','financiers','intentional acts','cyber-related claims']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Excessive E&O exclusions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Intellectual property exclusion in E&O defeats primary purpose of the coverage. Some exclusions are standard (intentional acts), but IP exclusion is completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Limits shall be shared between Amazon''s productions covered under ProdCo''s policy. The specified limits are total aggregate limits across all Amazon projects, not per-project limits.', ARRAY['limits','shared','Amazon''s productions','ProdCo''s policy','specified limits','total aggregate','across all','Amazon projects','not per-project']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Shared limits across Amazon projects", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Shared limits across multiple Amazon projects could leave this production without adequate coverage if other projects have claims. Per-project minimums are required."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall deliver to Amazon certificates of insurance evidencing all required coverages within ten (10) business days of the Effective Date and prior to commencement of any production activities. Certificates shall specifically identify the production covered and confirm compliance with all requirements set forth herein.', ARRAY['deliver','Amazon','certificates of insurance','evidencing','required coverages','ten business days','Effective Date','prior to','commencement','production activities','specifically identify','production','confirm compliance','requirements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Certificate delivery timing", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear certificate delivery timeline with requirement to deliver before production begins. Production identification and compliance confirmation ensure proper documentation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Certificates of insurance shall: (a) identify Amazon as additional insured; (b) confirm primary and non-contributory status; (c) evidence waiver of subrogation; (d) state policy limits meeting or exceeding required minimums; and (e) provide that Amazon shall receive not less than thirty (30) days'' notice of cancellation, non-renewal, or material modification.', ARRAY['certificates of insurance','identify','Amazon','additional insured','confirm','primary','non-contributory','evidence','waiver of subrogation','state','policy limits','meeting','exceeding','minimums','Amazon','receive','thirty days','notice','cancellation','non-renewal','material modification']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Certificate content requirements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive certificate content requirements ensuring all key terms are documented on face of certificate. Cancellation notice requirement is essential."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon Amazon''s request, ProdCo shall provide copies of actual insurance policies, including all endorsements, within ten (10) business days of such request. Amazon may request policy copies at any time and from time to time throughout the term.', ARRAY['Amazon''s request','provide','copies','actual insurance policies','including','endorsements','ten business days','request','any time','from time to time','throughout term']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Policy copy request right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Right to request actual policy copies allows Amazon to verify coverage terms beyond certificate face. Ten-day turnaround is reasonable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall provide updated certificates: (a) annually, no later than the policy renewal date; (b) upon any policy change, cancellation, or replacement; (c) upon request by Amazon; and (d) upon any change in the production scope that may affect coverage requirements.', ARRAY['updated certificates','annually','policy renewal date','policy change','cancellation','replacement','request','Amazon','change','production scope','affect','coverage requirements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Certificate update triggers", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Multiple certificate update triggers ensure Amazon has current coverage information throughout production. Annual, change-based, and scope-based updates provide comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Failure to deliver required certificates or policies, or delivery of certificates evidencing non-compliant coverage, shall constitute a material breach entitling Amazon to suspend production and all payments until compliant documentation is provided.', ARRAY['failure','deliver','required certificates','policies','delivery','certificates','non-compliant coverage','material breach','entitling','Amazon','suspend','production','payments','compliant documentation','provided']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Certificate failure consequences", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Material breach characterization for certificate failures with suspension right ensures compliance. Production should not proceed without proper insurance documentation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Certificates shall be issued on ACORD form 25 (or equivalent) and shall be executed by an authorized representative of the insurer or an authorized agent. Certificates issued by brokers without binding authority shall not be acceptable unless accompanied by evidence of broker authority.', ARRAY['certificates','ACORD form 25','equivalent','executed','authorized representative','insurer','authorized agent','certificates','brokers','without binding authority','not acceptable','accompanied','evidence','broker authority']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Certificate form and execution", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "ACORD 25 specification ensures standardized format. Authorized representative requirement and broker authority verification prevent questionable certificates."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain copies of all insurance policies and certificates for not less than ten (10) years following completion of the Program. Upon Amazon''s request during such period, ProdCo shall provide copies within twenty (20) business days.', ARRAY['maintain','copies','insurance policies','certificates','ten years','following','completion','Program','Amazon''s request','during','period','provide copies','twenty business days']::text[], '{"doc": "PSA_Principal_Terms", "section": "Insurance", "note": "Long-term document retention", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Ten-year retention requirement ensures documentation is available for latent claims. Longer response time (20 days) is reasonable for archived documents."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall deliver certificates within ten (10) business days of the Effective Date. If certificates are not available within such period due to insurer processing delays, ProdCo shall provide a binder or cover note, with final certificates to follow within twenty (20) business days.', ARRAY['certificates','ten business days','Effective Date','not available','insurer processing delays','provide','binder','cover note','final certificates','follow','twenty business days']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Binder for processing delay", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Binder as temporary evidence for insurer delays is acceptable industry practice. Twenty-day follow-up for final certificates is reasonable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may request policy copies. ProdCo shall provide copies within fifteen (15) business days, provided that ProdCo may redact premium information and information relating to other insureds or productions unrelated to this Agreement.', ARRAY['Amazon','request','policy copies','provide copies','fifteen business days','redact','premium information','information','other insureds','productions','unrelated','Agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Redaction rights", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Redaction of premium and unrelated insured information is reasonable confidentiality protection. Doesn''t affect Amazon''s ability to verify coverage terms."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Certificates evidencing E&O coverage may be delivered separately from other certificates if E&O is placed through a specialty broker requiring additional processing time. E&O certificates shall be delivered no later than thirty (30) days after the Effective Date.', ARRAY['certificates','E&O coverage','delivered separately','other certificates','specialty broker','additional processing time','E&O certificates','delivered','thirty days','Effective Date']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Separate E&O timeline", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Extended E&O timeline for specialty placement may be acceptable given market realities. Thirty days is reasonable maximum."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If Amazon objects to any certificate as not evidencing required coverage, Amazon shall notify ProdCo in writing of the specific deficiency within ten (10) business days. ProdCo shall have five (5) business days to provide clarification or replacement certificate.', ARRAY['Amazon objects','certificate','not evidencing','required coverage','notify ProdCo','writing','specific deficiency','ten business days','ProdCo','five business days','clarification','replacement certificate']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Certificate objection process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Certificate objection process with specific deficiency identification is reasonable. Provides ProdCo opportunity to address issues before breach is triggered."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Certificates shall be delivered electronically to the email address designated by Amazon''s risk management department. Physical certificates shall not be required unless specifically requested by Amazon for regulatory or financing purposes.', ARRAY['certificates','delivered electronically','email address','designated','Amazon''s risk management','physical certificates','not required','unless','specifically requested','Amazon','regulatory','financing purposes']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Electronic delivery acceptable", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Electronic delivery is standard practice and acceptable. Physical certificate option for specific purposes provides flexibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Renewal certificates shall be delivered not less than fifteen (15) days prior to expiration of the current policy. If renewal terms include any reduction in limits, increase in deductibles, or addition of exclusions, ProdCo shall notify Amazon at least thirty (30) days prior to renewal.', ARRAY['renewal certificates','delivered','fifteen days','prior to expiration','current policy','renewal terms','reduction','limits','increase','deductibles','addition','exclusions','notify Amazon','thirty days','prior to renewal']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Renewal certificate timing and change notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Pre-expiration delivery requirement and advance notice of adverse changes ensures Amazon has visibility into coverage continuity. Reasonable timing requirements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall provide certificates of insurance upon Amazon''s request. No automatic delivery or update requirements shall apply. Amazon shall be responsible for requesting certificates when needed.', ARRAY['provide','certificates','upon request','no automatic delivery','update requirements','apply','Amazon','responsible','requesting','when needed']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Request-only certificates", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Request-only certificates without automatic delivery shifts monitoring burden to Amazon. Certificates must be delivered automatically at specified times."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall deliver certificates evidencing insurance coverage. Certificates shall be for informational purposes only and shall not create any contractual obligation to maintain coverage or give Amazon any rights under the policies.', ARRAY['deliver','certificates','evidencing','insurance','informational purposes only','not create','contractual obligation','maintain coverage','give Amazon','rights','under policies']::text[], '{"doc": "Counterparty_Proposal", "section": "Insurance", "note": "Informational only certificates", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Informational purposes only'' disclaimer defeats purpose of certificate requirement. Certificates must confirm contractual coverage obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may request policy copies but shall reimburse ProdCo''s reasonable costs of obtaining and providing copies. ProdCo shall have thirty (30) business days to respond to policy copy requests.', ARRAY['Amazon','request','policy copies','reimburse','ProdCo''s reasonable costs','obtaining','providing copies','thirty business days','respond','requests']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Cost reimbursement for copies", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Cost reimbursement for policy copies and 30-day response time is unreasonable. Standard document requests should be at ProdCo''s cost with reasonable turnaround."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Certificates shall be accepted as delivered unless Amazon provides written objection within five (5) business days. Absence of timely objection shall constitute Amazon''s acceptance that all insurance requirements have been satisfied.', ARRAY['certificates','accepted as delivered','unless','Amazon','written objection','five business days','absence','timely objection','constitute','Amazon''s acceptance','insurance requirements','satisfied']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Deemed acceptance of certificates", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deemed acceptance for non-objection shifts verification burden to Amazon with very short timeline. Certificates must comply regardless of Amazon''s review."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall provide certificates. ProdCo''s compliance with certificate requirements shall be satisfied by delivery of certificates; Amazon shall have no right to verify actual policy terms, endorsements, or coverage conditions beyond what appears on the certificate face.', ARRAY['provide','certificates','compliance','certificate requirements','satisfied','delivery','certificates','Amazon','no right','verify','actual policy terms','endorsements','coverage conditions','beyond','certificate face']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "No policy verification right", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating policy verification right leaves Amazon unable to confirm actual coverage matches certificates. Certificate-only compliance is insufficient protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Failure to timely deliver certificates shall not be a material breach. ProdCo shall have a reasonable cure period of not less than sixty (60) days to deliver required certificates before any breach-based remedies may be exercised.', ARRAY['failure','timely deliver','certificates','not','material breach','reasonable cure period','sixty days','deliver','required certificates','breach-based remedies','exercised']::text[], '{"doc": "Counterparty_Markup", "section": "Insurance", "note": "Extended cure for certificate failure", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Non-material characterization and 60-day cure for certificate failure allows production without insurance documentation. Suspension right upon non-delivery must be preserved."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain in strict confidence and shall not disclose to any third party any Confidential Information of Amazon, including without limitation: (a) the terms and conditions of this Agreement; (b) Amazon''s business plans, strategies, and projections; (c) Amazon''s non-public financial information; (d) Amazon''s technology, systems, and processes; and (e) any other information designated as confidential by Amazon.', ARRAY['maintain','strict confidence','not disclose','third party','Confidential Information','Amazon','terms','conditions','Agreement','business plans','strategies','projections','non-public financial','technology','systems','processes','designated','confidential']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Standard confidentiality scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive confidentiality scope covering Agreement terms, business information, financial data, and technology. Catch-all for designated information provides flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges that Amazon''s Non-Public Information (''NPI'') includes: customer data and viewing information; content strategy and programming decisions; marketing plans and advertising rates; vendor and talent compensation information; and any information that a reasonable person would understand to be confidential given the circumstances of disclosure.', ARRAY['acknowledges','Non-Public Information','NPI','customer data','viewing information','content strategy','programming decisions','marketing plans','advertising rates','vendor','talent compensation','reasonable person','understand','confidential','circumstances']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "NPI definition with reasonableness standard", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific enumeration of NPI categories plus reasonableness standard ensures comprehensive coverage without requiring formal designation for obviously confidential information."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall use Confidential Information solely for the purpose of performing its obligations under this Agreement and shall not use such information for any other purpose, including for ProdCo''s own benefit or the benefit of any third party. ProdCo shall not reverse engineer, decompile, or derive source code from any Amazon technology.', ARRAY['use','Confidential Information','solely','purpose','performing obligations','Agreement','not use','other purpose','ProdCo''s own benefit','benefit','third party','not reverse engineer','decompile','derive source code','Amazon technology']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Use restriction with technology protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Purpose limitation restricts use to Agreement performance. Prohibition on reverse engineering protects Amazon technology that may be accessed during production."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall protect Confidential Information using at least the same degree of care it uses to protect its own confidential information of like kind, but in no event less than reasonable care. ProdCo shall implement appropriate technical and organizational measures to prevent unauthorized access, disclosure, or loss.', ARRAY['protect','Confidential Information','same degree of care','own confidential information','like kind','no event','less than reasonable care','implement','appropriate','technical','organizational measures','prevent','unauthorized access','disclosure','loss']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Care standard with security measures", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Dual care standard (same as own, no less than reasonable) sets appropriate protection level. Technical and organizational measure requirement addresses modern security expectations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may disclose Confidential Information only to its employees, contractors, and agents who: (a) have a need to know such information for purposes of this Agreement; (b) have been informed of the confidential nature of the information; and (c) are bound by confidentiality obligations at least as protective as those set forth herein.', ARRAY['disclose','Confidential Information','only','employees','contractors','agents','need to know','purposes','Agreement','informed','confidential nature','bound','confidentiality obligations','at least as protective']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Limited disclosure with flow-down", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Need-to-know limitation with flow-down confidentiality requirements ensures protection extends to authorized recipients. Standard three-part requirement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall immediately notify Amazon upon becoming aware of any actual or suspected unauthorized access, disclosure, or use of Confidential Information. ProdCo shall cooperate with Amazon''s investigation and remediation efforts and shall take all reasonable steps to mitigate any harm from such breach.', ARRAY['immediately notify','Amazon','actual','suspected','unauthorized access','disclosure','use','Confidential Information','cooperate','investigation','remediation','take','reasonable steps','mitigate','harm','breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Breach notification and cooperation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Immediate notification requirement for actual or suspected breaches with cooperation and mitigation obligations is essential for incident response."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s confidentiality obligations shall survive expiration or termination of this Agreement for a period of five (5) years, except that obligations regarding trade secrets shall survive for so long as such information remains a trade secret under applicable law.', ARRAY['confidentiality obligations','survive','expiration','termination','Agreement','five years','except','trade secrets','survive','so long as','remains','trade secret','applicable law']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Survival period with trade secret exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Five-year post-termination survival is standard. Trade secret exception ensures indefinite protection for qualifying information."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain confidentiality of Amazon information. Confidential Information shall not include information that: (a) is or becomes publicly available without breach by ProdCo; (b) was rightfully in ProdCo''s possession prior to disclosure; (c) is independently developed by ProdCo without use of Confidential Information; or (d) is rightfully obtained from a third party without restriction.', ARRAY['maintain confidentiality','Confidential Information','not include','publicly available','without breach','rightfully','possession','prior to disclosure','independently developed','without use','rightfully obtained','third party','without restriction']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Standard exclusions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard confidentiality exclusions are appropriate. Each exclusion has appropriate qualifiers (without breach, rightfully, without use, without restriction)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose Confidential Information if required by law, regulation, or legal process, provided that ProdCo: (a) gives Amazon prompt written notice to permit Amazon to seek a protective order; (b) discloses only the minimum information legally required; and (c) cooperates with Amazon''s efforts to protect the information.', ARRAY['disclose','Confidential Information','required by law','regulation','legal process','gives Amazon','prompt written notice','protective order','discloses','minimum','legally required','cooperates','efforts','protect']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Compelled disclosure exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Compelled disclosure exception with notice, minimization, and cooperation requirements is standard and appropriate. Allows legal compliance while protecting Amazon''s interests."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Confidentiality obligations apply to Amazon information. ProdCo may share general, non-identifying information about its engagement with Amazon for purposes of business development, provided such disclosure does not reveal Agreement terms, Amazon strategies, or any NPI.', ARRAY['confidentiality obligations','Amazon information','share','general','non-identifying information','engagement','Amazon','business development','disclosure','not reveal','Agreement terms','Amazon strategies','NPI']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Limited business development disclosure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited general disclosure for business development (e.g., ''we work with major streamers'') may be acceptable if truly non-identifying and excluding all NPI and terms."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall protect Confidential Information. If ProdCo uses subcontractors who require access to Confidential Information, ProdCo shall: (a) obtain Amazon''s prior written approval of such subcontractor; (b) ensure subcontractor is bound by equivalent confidentiality terms; and (c) remain fully liable for subcontractor''s compliance.', ARRAY['protect','Confidential Information','subcontractors','require access','obtain','Amazon''s prior written approval','ensure','bound','equivalent confidentiality terms','remain','fully liable','subcontractor''s compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Subcontractor approval and liability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Subcontractor approval requirement with equivalent terms and continued liability ensures confidentiality extends through supply chain. Prior approval allows Amazon vetting."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon expiration or termination of this Agreement, or upon Amazon''s request, ProdCo shall promptly return or destroy all Confidential Information and certify such return or destruction in writing. ProdCo may retain one archival copy for legal compliance purposes only, subject to continuing confidentiality obligations.', ARRAY['expiration','termination','Agreement','Amazon''s request','promptly return','destroy','Confidential Information','certify','return','destruction','writing','retain','one archival copy','legal compliance','continuing confidentiality']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Return/destroy with archival exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Return or destroy requirement with certification is standard. Single archival copy for legal compliance is reasonable exception given potential litigation discovery needs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo acknowledges that Confidential Information is valuable and that breach would cause irreparable harm for which monetary damages would be inadequate. ProdCo agrees that Amazon shall be entitled to seek injunctive relief without posting bond, in addition to any other remedies.', ARRAY['acknowledges','Confidential Information','valuable','breach','irreparable harm','monetary damages','inadequate','agrees','Amazon','entitled','seek injunctive relief','without posting bond','other remedies']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Injunctive relief acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Irreparable harm acknowledgment and bond waiver for injunctive relief supports Amazon''s ability to obtain emergency protection against breaches."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain confidentiality of information expressly designated in writing as ''Confidential'' by Amazon at the time of disclosure. Information not so designated shall not be subject to confidentiality obligations.', ARRAY['maintain confidentiality','information','expressly designated','writing','Confidential','Amazon','time of disclosure','not designated','not subject to','confidentiality obligations']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Written designation required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring written ''Confidential'' designation at disclosure creates massive gap. Most NPI is shared verbally or without formal marking. Confidentiality must apply to information reasonably understood as confidential."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s confidentiality obligations shall expire upon expiration or termination of this Agreement. Post-termination, ProdCo shall have no further confidentiality obligations with respect to any Amazon information.', ARRAY['confidentiality obligations','expire','expiration','termination','Agreement','post-termination','no further','confidentiality obligations','Amazon information']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "No post-termination survival", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "No post-termination survival eliminates protection for confidential information shared during the relationship. Multi-year survival is essential."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain confidentiality using commercially reasonable efforts. ProdCo shall not be liable for inadvertent disclosures resulting from security breaches beyond ProdCo''s reasonable control.', ARRAY['maintain confidentiality','commercially reasonable efforts','not liable','inadvertent disclosures','security breaches','beyond','reasonable control']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Reasonable efforts with breach exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Commercially reasonable efforts'' is too low a standard for confidentiality. Breach exclusion eliminates liability for potentially negligent security failures. Strict confidentiality obligation is required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall protect Amazon''s Confidential Information. This obligation shall not restrict ProdCo from disclosing information to: (a) any potential investor or acquirer; (b) ProdCo''s attorneys and accountants; or (c) any party in connection with ProdCo''s business operations.', ARRAY['protect','Confidential Information','not restrict','disclosing','potential investor','acquirer','attorneys','accountants','party','connection','business operations']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Broad disclosure exceptions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exceptions for investors, acquirers, and business operations are far too broad. Could permit disclosure to Amazon competitors. Any M&A disclosure requires Amazon approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Confidentiality obligations are mutual. Amazon''s confidentiality obligations to ProdCo shall be identical in scope and duration to ProdCo''s obligations to Amazon. Neither party shall have greater protection than the other.', ARRAY['confidentiality obligations','mutual','Amazon''s confidentiality obligations','ProdCo','identical','scope','duration','ProdCo''s obligations','Amazon','neither party','greater protection']::text[], '{"doc": "Counterparty_Proposal", "section": "Confidentiality", "note": "Forced mutual equivalence", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Forced mutual equivalence ignores that Amazon typically shares more sensitive information (NPI, strategy, data). ProdCo''s obligations should be comprehensive; Amazon''s can be more limited."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Confidentiality obligations apply. ProdCo''s aggregate liability for breach of confidentiality shall not exceed $50,000 regardless of the nature or extent of the breach or the value of the information disclosed.', ARRAY['confidentiality obligations','apply','aggregate liability','breach','confidentiality','not exceed','$50,000','regardless','nature','extent','breach','value','information disclosed']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Liability cap on confidentiality", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "$50K cap on confidentiality breach liability is grossly inadequate given potential harm from NPI disclosure. Confidentiality breaches must be excluded from any liability limitations."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain strict confidentiality regarding all creative elements of the Program, including without limitation: scripts, treatments, and outlines; storylines, plot points, and character arcs; casting decisions and talent attachments; visual designs and production artwork; and any other creative information that could spoil the viewing experience if disclosed.', ARRAY['maintain strict confidentiality','creative elements','Program','scripts','treatments','outlines','storylines','plot points','character arcs','casting decisions','talent attachments','visual designs','production artwork','spoil','viewing experience','disclosed']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Creative confidentiality scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive creative confidentiality covering all elements that could constitute spoilers. Spoiler prevention is critical for content value protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges that premature disclosure of Program creative elements could cause irreparable harm to Amazon by diminishing audience interest, enabling competitive response, or reducing the Program''s commercial value. ProdCo shall treat all creative information as highly sensitive.', ARRAY['acknowledges','premature disclosure','Program creative elements','irreparable harm','Amazon','diminishing','audience interest','competitive response','reducing','commercial value','treat','creative information','highly sensitive']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Harm acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledgment of harm from premature disclosure supports injunctive relief and establishes context for strict confidentiality requirements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Scripts and other written materials shall be distributed only on a need-to-know basis with unique watermarks identifying the recipient. ProdCo shall maintain a log of all script distributions and shall collect and destroy scripts following completion of relevant production activities.', ARRAY['scripts','written materials','distributed','need-to-know','unique watermarks','identifying','recipient','maintain','log','script distributions','collect','destroy','scripts','completion','relevant production']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Script security protocols", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Watermarking, distribution logging, and collection/destruction protocols are industry-standard script security measures that enable tracking and limit exposure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall ensure that all cast, crew, and production personnel execute Amazon''s standard confidentiality and non-disclosure agreements prior to receiving any creative materials or commencing services. ProdCo shall maintain copies of such executed agreements and provide them to Amazon upon request.', ARRAY['ensure','cast','crew','production personnel','execute','Amazon''s standard','confidentiality','non-disclosure agreements','prior to','receiving','creative materials','commencing services','maintain copies','executed agreements','provide','Amazon','request']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Personnel NDA requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Personnel NDA requirement with Amazon''s form ensures consistent protection. Execution before access and record-keeping enables enforcement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall implement and enforce policies prohibiting: (a) photography, video recording, or audio recording on set without authorization; (b) posting of any production-related content on social media; (c) discussion of plot points or creative elements with unauthorized persons; and (d) removal of any creative materials from secure locations.', ARRAY['implement','enforce','policies','prohibiting','photography','video recording','audio recording','set','authorization','posting','production-related content','social media','discussion','plot points','creative elements','unauthorized persons','removal','creative materials','secure locations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "On-set security policies", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific prohibitions address common leak vectors including set photography, social media, and materials removal. Policy enforcement requirement creates accountability."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If any creative information is leaked or disclosed without authorization, ProdCo shall immediately notify Amazon, cooperate with Amazon''s investigation, and assist with containment and mitigation efforts. Amazon may direct ProdCo''s response to any leak situation.', ARRAY['creative information','leaked','disclosed','without authorization','immediately notify','Amazon','cooperate','investigation','assist','containment','mitigation','Amazon','direct','ProdCo''s response','leak situation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Leak response protocol", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Leak response protocol with immediate notification and Amazon direction ensures coordinated response. Amazon control over response is important for managing public relations."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall include confidentiality provisions equivalent to those set forth herein in all agreements with writers, directors, cast, and key crew. Failure of any such personnel to comply with confidentiality requirements shall not relieve ProdCo of its obligations to Amazon.', ARRAY['include','confidentiality provisions','equivalent','agreements','writers','directors','cast','key crew','failure','personnel','comply','confidentiality','not relieve','ProdCo','obligations','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Flow-down with continued liability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Flow-down requirement extends protection to personnel agreements. Continued ProdCo liability regardless of personnel breach ensures Amazon has recourse against responsible party."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Creative confidentiality applies. ProdCo may share general, non-spoiler information about its involvement in the production for purposes of industry recognition (e.g., award submissions, professional credits), subject to Amazon''s prior approval of the specific disclosure.', ARRAY['creative confidentiality','applies','share','general','non-spoiler information','involvement','production','industry recognition','award submissions','professional credits','Amazon''s prior approval','specific disclosure']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Industry recognition exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Industry recognition exception with Amazon approval may be acceptable for legitimate professional purposes. Prior approval requirement ensures Amazon control over what''s disclosed."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall protect creative elements. If ProdCo becomes aware of any third-party attempt to obtain or publish spoiler information, ProdCo shall notify Amazon immediately and shall not cooperate with or comment to any such third party without Amazon''s direction.', ARRAY['protect','creative elements','aware','third-party attempt','obtain','publish','spoiler information','notify Amazon','immediately','not cooperate','not comment','third party','Amazon''s direction']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Third-party inquiry handling", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Third-party inquiry protocol ensures Amazon awareness and control over responses. Non-cooperation without direction prevents inadvertent confirmations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Script security protocols apply. For audition purposes, ProdCo may provide audition sides (partial scenes) to casting candidates, provided such sides do not reveal major plot points, are watermarked with candidate identification, and are collected or destroyed following auditions.', ARRAY['script security','applies','audition purposes','provide','audition sides','partial scenes','casting candidates','not reveal','major plot points','watermarked','candidate identification','collected','destroyed','following auditions']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Audition sides exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Audition sides exception is operationally necessary for casting. Restrictions on content, watermarking, and collection/destruction maintain appropriate protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Creative confidentiality extends to location information. ProdCo shall not disclose specific filming locations in advance without Amazon approval, as such disclosure could enable paparazzi access, fan interference, or security threats to talent.', ARRAY['creative confidentiality','extends','location information','not disclose','specific filming locations','advance','Amazon approval','paparazzi access','fan interference','security threats','talent']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Location confidentiality", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Location confidentiality addresses practical security and operational concerns. Advance disclosure restrictions prevent production disruptions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain creative confidentiality. Notwithstanding the foregoing, ProdCo may share creative elements with legitimate collaborators (composers, VFX vendors, post-production facilities) under written confidentiality agreements, provided ProdCo notifies Amazon of such disclosures quarterly.', ARRAY['maintain','creative confidentiality','notwithstanding','share','creative elements','legitimate collaborators','composers','VFX vendors','post-production facilities','written confidentiality agreements','notifies Amazon','disclosures','quarterly']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Collaborator sharing with reporting", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Production collaborator exception is operationally necessary. Quarterly reporting provides Amazon visibility without requiring per-disclosure approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Script watermarking applies. For large-scale productions, ProdCo may use electronic watermarking systems that embed recipient identification in digital files rather than visible watermarks, provided such systems are auditable and can trace any leaked materials to the source.', ARRAY['script watermarking','applies','large-scale productions','electronic watermarking systems','embed','recipient identification','digital files','visible watermarks','auditable','trace','leaked materials','source']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Electronic watermarking alternative", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Electronic watermarking alternative for large productions is acceptable if traceable. Audit requirement ensures leak source identification capability is preserved."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use reasonable efforts to maintain confidentiality of creative elements. However, ProdCo shall not be responsible for disclosures by individual cast or crew members acting outside the scope of their employment.', ARRAY['reasonable efforts','maintain confidentiality','creative elements','not responsible','disclosures','individual cast','crew members','acting outside','scope','employment']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Personnel exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' is inadequate standard, and personnel exclusion eliminates liability for most likely leak sources. ProdCo must be responsible for personnel it engages."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Creative confidentiality applies until public announcement of the Program. Following Amazon''s public announcement of the Program''s existence, cast, and general premise, all creative confidentiality obligations shall terminate.', ARRAY['creative confidentiality','applies','until','public announcement','Program','following','Amazon''s public announcement','existence','cast','general premise','confidentiality obligations','terminate']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Termination upon announcement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination of creative confidentiality upon announcement eliminates spoiler protection. Announcement reveals existence, not plot details. Creative elements must remain confidential through release."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain creative confidentiality. If a leak occurs despite ProdCo''s reasonable precautions, ProdCo shall not be liable for damages arising from such leak, as leaks are inherent risks in film production.', ARRAY['maintain creative confidentiality','leak occurs','despite','reasonable precautions','not liable','damages','arising from','leak','inherent risks','film production']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Leak liability exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Leak liability exclusion based on ''inherent risk'' eliminates accountability. ProdCo must be liable for leaks; ''reasonable precautions'' defense shifts burden to Amazon."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Script distribution shall be at ProdCo''s discretion based on production needs. ProdCo shall not be required to implement watermarking, distribution logging, or other security measures that would impede efficient production operations.', ARRAY['script distribution','ProdCo''s discretion','production needs','not required','implement','watermarking','distribution logging','security measures','impede','efficient production operations']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "No security measures required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Discretionary distribution without security measures eliminates leak prevention and tracing capabilities. Watermarking and logging are essential and not unduly burdensome."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Creative elements are confidential. Notwithstanding, ProdCo and its personnel may discuss their creative contributions to the Program with press and media to promote their own careers, provided they avoid revealing specific plot details that Amazon designates as embargoed.', ARRAY['creative elements','confidential','notwithstanding','ProdCo','personnel','discuss','creative contributions','Program','press','media','promote','careers','avoid revealing','specific plot details','Amazon designates','embargoed']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Press discussion exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Press discussion exception for ''career promotion'' creates uncontrolled disclosure channel. Any press communication must be coordinated with and approved by Amazon."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not issue, and shall ensure that its personnel do not issue, any press release, public announcement, or other publicity regarding this Agreement, the Program, or ProdCo''s relationship with Amazon without Amazon''s prior written approval, which approval may be withheld in Amazon''s sole discretion.', ARRAY['not issue','ensure','personnel','not issue','press release','public announcement','publicity','Agreement','Program','relationship','Amazon','prior written approval','withheld','sole discretion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Standard publicity restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive publicity restriction requiring prior written approval for any public communications. Sole discretion withholding preserves Amazon''s complete control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have sole and exclusive control over all marketing, advertising, promotion, and publicity for the Program. ProdCo shall cooperate with Amazon''s publicity efforts as reasonably requested, including making talent available for promotional appearances, subject to talent availability.', ARRAY['Amazon','sole','exclusive control','marketing','advertising','promotion','publicity','Program','cooperate','publicity efforts','reasonably requested','talent available','promotional appearances','subject to','talent availability']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Amazon publicity control", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon''s exclusive publicity control with ProdCo cooperation requirement ensures coordinated promotional strategy. Talent availability qualifier is reasonable."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Publicity restrictions apply to all forms of communication, including: press releases; media interviews; social media posts; website content; trade publication statements; speaking engagements; and any other public or semi-public communication regarding the Program or Agreement.', ARRAY['publicity restrictions','all forms','communication','press releases','media interviews','social media','website content','trade publication','speaking engagements','public','semi-public','communication','Program','Agreement']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Comprehensive communication scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumeration of covered communication types ensures comprehensive coverage including social media and speaking engagements. Semi-public qualifier addresses industry events."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall include provisions in all talent and key personnel agreements requiring compliance with Amazon''s publicity guidelines and requiring prior Amazon approval for any public statements regarding the Program. Violation by personnel shall be a breach by ProdCo.', ARRAY['include provisions','talent','key personnel agreements','compliance','Amazon''s publicity guidelines','prior Amazon approval','public statements','Program','violation','personnel','breach','ProdCo']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Personnel flow-down with breach attribution", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Personnel agreement flow-down requirement with ProdCo breach attribution ensures accountability. Extends approval requirement to talent who may have direct media relationships."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may, in its sole discretion, approve, modify, or reject any proposed publicity. If Amazon does not respond to a publicity request within ten (10) business days, such request shall be deemed rejected. Approval of specific publicity shall not constitute approval of any other publicity.', ARRAY['Amazon','sole discretion','approve','modify','reject','proposed publicity','not respond','publicity request','ten business days','deemed rejected','approval','specific publicity','not constitute','approval','other publicity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Approval mechanics with deemed rejection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Deemed rejection for non-response (rather than deemed approval) prevents inadvertent approvals. Each approval is specific, preventing scope expansion."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not use Amazon''s name, logo, trademarks, or other branding elements in any publicity or communication without Amazon''s prior written approval. Any approved use shall comply with Amazon''s brand guidelines as provided from time to time.', ARRAY['not use','Amazon''s name','logo','trademarks','branding elements','publicity','communication','prior written approval','approved use','comply','Amazon''s brand guidelines','provided','from time to time']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Trademark use restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Trademark use restriction with brand guideline compliance ensures proper use of Amazon marks. Protects Amazon''s brand integrity in all public communications."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Following completion of the Program and public release, ProdCo may reference its involvement in the Program in general terms in company biographies, resumes, and professional portfolios, provided such references are factually accurate and do not imply Amazon endorsement of ProdCo.', ARRAY['following completion','Program','public release','reference','involvement','Program','general terms','company biographies','resumes','professional portfolios','factually accurate','not imply','Amazon endorsement']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Post-release portfolio exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Limited post-release portfolio exception allows reasonable professional references. Accuracy and non-endorsement requirements provide appropriate guardrails."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Publicity requires Amazon approval. Amazon shall respond to publicity requests within five (5) business days of receipt of complete proposed materials. If Amazon fails to respond within such period, ProdCo may re-submit the request with notice that non-response within three (3) additional business days shall constitute approval.', ARRAY['publicity','Amazon approval','respond','publicity requests','five business days','receipt','complete proposed materials','fails to respond','re-submit','request','notice','non-response','three additional business days','constitute approval']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Response timeline with deemed approval", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Deemed approval after re-submission and additional waiting period may be acceptable to address non-responsive situations. Total eight days plus re-submission provides adequate process."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon approval is required for publicity. ProdCo may respond to unsolicited press inquiries with ''no comment'' or by referring the inquiry to Amazon''s publicity department without prior approval, provided ProdCo does not provide any substantive information.', ARRAY['Amazon approval','required','publicity','respond','unsolicited press inquiries','no comment','referring','inquiry','Amazon''s publicity department','without prior approval','not provide','substantive information']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "No comment exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''No comment'' or referral response to unsolicited inquiries is reasonable operational exception. No substantive information qualifier is essential."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Publicity approval is required. Amazon agrees to make reasonable efforts to respond to publicity requests promptly. For time-sensitive publicity opportunities, Amazon shall designate a point of contact available to provide expedited review and approval.', ARRAY['publicity approval','required','Amazon','reasonable efforts','respond','publicity requests','promptly','time-sensitive','publicity opportunities','designate','point of contact','expedited review','approval']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Expedited process commitment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Amazon commitment to prompt response and expedited process for time-sensitive matters is reasonable operational accommodation without compromising approval right."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo requires Amazon approval for publicity. For publicity regarding industry awards (Emmy, Oscar, etc.) where timing is critical, Amazon shall pre-approve standard acceptance speech language and thank-you statements, subject to ProdCo''s submission for approval in advance of the award season.', ARRAY['Amazon approval','publicity','industry awards','Emmy','Oscar','timing','critical','pre-approve','standard acceptance speech language','thank-you statements','submission','approval','advance','award season']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Award speech pre-approval", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Award speech pre-approval process addresses practical reality of live events. Advance submission requirement gives Amazon opportunity to review and approve."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon approval required for publicity. ProdCo may share production stills and behind-the-scenes content with cast and crew for their personal archives, provided such materials are not publicly shared without Amazon approval and bear confidentiality notices.', ARRAY['Amazon approval','required','publicity','share','production stills','behind-the-scenes content','cast','crew','personal archives','not publicly shared','without Amazon approval','confidentiality notices']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Personal archive exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Personal archive sharing with non-public restriction is reasonable accommodation for personnel memories. Confidentiality notice requirement provides additional protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Publicity restrictions apply. Amazon shall coordinate with ProdCo regarding the timing and content of major publicity announcements, and shall consider in good faith ProdCo''s input on publicity matters, though Amazon shall have final decision-making authority.', ARRAY['publicity restrictions','apply','Amazon','coordinate','ProdCo','timing','content','major publicity announcements','consider','good faith','ProdCo''s input','publicity matters','Amazon','final decision-making authority']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Coordination and input rights", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Coordination and good faith consideration of ProdCo input is reasonable collaboration without compromising Amazon''s final authority over publicity decisions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may issue press releases and publicity regarding its involvement in the Program, subject only to a requirement to notify Amazon of planned publicity at least 48 hours in advance. Amazon may object, but ProdCo shall have final discretion.', ARRAY['issue','press releases','publicity','involvement','Program','subject','notify Amazon','planned publicity','48 hours','advance','Amazon','object','ProdCo','final discretion']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Notice only with ProdCo discretion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Notice-only requirement with ProdCo final discretion eliminates Amazon''s approval right. Amazon must have approval authority, not just objection opportunity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon approval is required for formal press releases. Informal publicity such as social media posts, interviews, and industry communications shall be at ProdCo''s discretion, provided ProdCo does not disparage Amazon.', ARRAY['Amazon approval','required','formal press releases','informal publicity','social media','interviews','industry communications','ProdCo''s discretion','not disparage','Amazon']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Informal publicity exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excepting social media, interviews, and industry communications from approval creates massive uncontrolled publicity channel. All forms require approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Publicity requires Amazon approval, which shall not be unreasonably withheld, conditioned, or delayed. Amazon''s failure to approve reasonable publicity requests shall entitle ProdCo to proceed with such publicity.', ARRAY['publicity','Amazon approval','not unreasonably withheld','conditioned','delayed','failure to approve','reasonable','publicity requests','entitle','ProdCo','proceed','publicity']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Unreasonable withholding standard", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Not unreasonably withheld'' standard with proceed-if-not-approved removes Amazon''s discretion. Amazon must have sole discretion over publicity approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Publicity restrictions are mutual. Amazon shall not issue publicity regarding the Program or ProdCo without ProdCo''s prior written approval, on the same terms as ProdCo requires Amazon approval.', ARRAY['publicity restrictions','mutual','Amazon','not issue publicity','Program','ProdCo','ProdCo''s prior written approval','same terms','ProdCo requires','Amazon approval']::text[], '{"doc": "Counterparty_Proposal", "section": "Publicity", "note": "Mutual approval requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mutual approval requirement prevents Amazon from controlling its own publicity for its own content. Amazon owns and controls the Program; ProdCo cannot have approval over Amazon''s publicity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not issue publicity about the Program without approval. However, ProdCo''s principals and key creative personnel retain personal publicity rights and may discuss their involvement in the Program with press without Amazon approval.', ARRAY['not issue publicity','Program','without approval','however','ProdCo''s principals','key creative personnel','personal publicity rights','discuss','involvement','Program','press','without Amazon approval']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Personal publicity carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Personal publicity carveout for principals and key creatives creates uncontrolled disclosure channel through exactly the people with most information. All publicity requires approval regardless of who initiates."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall implement and enforce Amazon''s social media guidelines for all cast, crew, and production personnel. Such guidelines shall prohibit posting any content related to the production, including photos, videos, locations, scripts, or any other production-related information, without Amazon''s prior written approval.', ARRAY['implement','enforce','Amazon''s social media guidelines','cast','crew','production personnel','prohibit','posting','content','production','photos','videos','locations','scripts','production-related information','Amazon''s prior written approval']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Standard social media restrictions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive social media restrictions with Amazon guidelines enforcement. Prohibits all production-related content without approval, addressing primary leak vector."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Cast members shall be permitted to post approved social media content only in accordance with a social media calendar coordinated with Amazon''s marketing team. All posts shall use designated hashtags, tagging, and content only. Spontaneous or uncoordinated posts regarding the Program are prohibited.', ARRAY['cast members','permitted','post','approved social media content','social media calendar','coordinated','Amazon''s marketing team','designated hashtags','tagging','content','spontaneous','uncoordinated posts','Program','prohibited']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Coordinated cast social media", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Coordinated social media calendar with Amazon marketing ensures strategic timing and messaging. Prohibition on spontaneous posts prevents uncontrolled communications."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall include in all cast and crew agreements a provision requiring: (a) compliance with Amazon''s social media policy; (b) immediate removal of any unauthorized posts upon Amazon''s request; (c) provision of social media account credentials to ProdCo for monitoring purposes if requested; and (d) consent to injunctive relief for violations.', ARRAY['include','cast','crew agreements','provision','compliance','Amazon''s social media policy','immediate removal','unauthorized posts','Amazon''s request','social media account credentials','monitoring','consent','injunctive relief','violations']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Personnel agreement requirements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Personnel flow-down of social media requirements with removal obligation, monitoring capability, and injunctive consent creates comprehensive enforcement framework."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Social media restrictions shall apply to all platforms, including without limitation: Instagram, Twitter/X, Facebook, TikTok, LinkedIn, YouTube, Snapchat, personal blogs, podcasts, and any other public or semi-public online communication platform, whether currently existing or developed in the future.', ARRAY['social media restrictions','apply','all platforms','Instagram','Twitter','X','Facebook','TikTok','LinkedIn','YouTube','Snapchat','personal blogs','podcasts','online communication platform','currently existing','developed','future']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Platform scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive platform enumeration with future-platform language ensures coverage regardless of social media evolution. Includes often-overlooked platforms like LinkedIn and podcasts."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If any production personnel violates social media restrictions, ProdCo shall: (a) immediately require removal of the offending content; (b) notify Amazon within two (2) hours of becoming aware; (c) cooperate with Amazon''s response efforts; and (d) at Amazon''s request, remove the violating individual from the production.', ARRAY['production personnel','violates','social media restrictions','immediately require removal','offending content','notify Amazon','two hours','becoming aware','cooperate','Amazon''s response efforts','Amazon''s request','remove','violating individual','production']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Violation response protocol", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Violation response protocol with short notification window and removal capability enables rapid containment. Personnel removal option provides meaningful consequence."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall designate a social media compliance officer responsible for: monitoring personnel social media accounts for production-related content; enforcing social media policies; coordinating approved posts with Amazon; and serving as the point of contact for social media issues.', ARRAY['designate','social media compliance officer','monitoring','personnel social media accounts','production-related content','enforcing','social media policies','coordinating','approved posts','Amazon','point of contact','social media issues']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "Compliance officer requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Designated compliance officer creates accountability and operational structure for social media management. Single point of contact improves coordination."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Production areas (sets, stages, production offices) shall be designated as phone-free or camera-restricted zones where photography and recording are prohibited. ProdCo shall post visible notices, provide secure storage for personal devices, and enforce these restrictions through on-set security personnel.', ARRAY['production areas','sets','stages','production offices','phone-free','camera-restricted zones','photography','recording','prohibited','visible notices','secure storage','personal devices','enforce','on-set security personnel']::text[], '{"doc": "PSA_Principal_Terms", "section": "Social Media", "note": "On-set device restrictions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Device restrictions in production areas prevent content capture at source. Storage, notices, and security enforcement address practical implementation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Social media restrictions apply. Following public announcement of a cast member''s involvement (by Amazon), such cast member may acknowledge their participation in general terms on personal social media, without revealing creative details, plot information, or behind-the-scenes content.', ARRAY['social media restrictions','apply','following','public announcement','cast member''s involvement','Amazon','acknowledge','participation','general terms','personal social media','without revealing','creative details','plot information','behind-the-scenes content']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Post-announcement acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited acknowledgment after Amazon announcement may be acceptable given information is already public. General terms and content restrictions provide guardrails."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Social media restrictions shall be enforced. For major cast (leads and series regulars), Amazon and ProdCo shall develop an individualized social media plan addressing the talent''s existing platform presence and follower expectations, while maintaining appropriate confidentiality protections.', ARRAY['social media restrictions','enforced','major cast','leads','series regulars','Amazon','ProdCo','develop','individualized social media plan','talent''s','existing platform presence','follower expectations','maintaining','confidentiality protections']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Individualized talent plans", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Individualized plans for major cast acknowledge their established social media presence and fan engagement. Confidentiality protection requirement ensures plans maintain appropriate restrictions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Crew members may share non-revealing content (e.g., photos of catering, generic equipment shots without identifiable branding, wrap party celebrations after public release) with Amazon''s pre-approval. ProdCo shall submit proposed crew social media content for approval at least 48 hours in advance.', ARRAY['crew members','share','non-revealing content','photos','catering','generic equipment shots','without','identifiable branding','wrap party','public release','Amazon''s pre-approval','submit','proposed','crew social media content','approval','48 hours','advance']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Crew non-revealing content exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Non-revealing crew content exception with pre-approval may be acceptable for morale purposes. 48-hour submission window provides review time."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Social media compliance includes monitoring. ProdCo shall use commercially available social media monitoring tools to detect unauthorized production-related posts and shall provide Amazon with weekly reports during production and monthly reports during post-production.', ARRAY['social media compliance','monitoring','commercially available','social media monitoring tools','detect','unauthorized','production-related posts','provide','Amazon','weekly reports','production','monthly reports','post-production']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Monitoring with reporting", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Monitoring tool requirement and regular reporting provides visibility into social media landscape and early detection of potential issues."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'During the promotional period surrounding Program release, Amazon may request that cast participate in coordinated social media campaigns. ProdCo shall use reasonable efforts to ensure cast availability and cooperation, subject to any limitations in cast agreements and scheduling constraints.', ARRAY['promotional period','Program release','Amazon','request','cast','participate','coordinated social media campaigns','reasonable efforts','ensure','cast availability','cooperation','subject to','limitations','cast agreements','scheduling constraints']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Promotional campaign participation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Promotional campaign participation request with reasonable efforts and cast agreement constraints acknowledges practical realities while supporting Amazon''s marketing needs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Social media restrictions apply. ProdCo acknowledges that influencer talent may have contractual obligations to brand partners requiring social media activity. Such activities shall be permitted provided they do not reference the Program and are disclosed to Amazon in advance.', ARRAY['social media restrictions','apply','acknowledges','influencer talent','contractual obligations','brand partners','social media activity','permitted','not reference','Program','disclosed','Amazon','advance']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Influencer brand obligation exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Influencer brand obligation acknowledgment with Program non-reference requirement and disclosure addresses modern talent realities while protecting production confidentiality."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use reasonable efforts to enforce social media restrictions. However, ProdCo cannot control the personal social media accounts of cast and crew and shall not be liable for their unauthorized posts.', ARRAY['reasonable efforts','enforce','social media restrictions','cannot control','personal social media accounts','cast','crew','not liable','unauthorized posts']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Reasonable efforts with no liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' with no liability for personnel posts eliminates accountability. ProdCo must be responsible for personnel it engages regardless of control limitations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Social media restrictions shall not apply to cast members'' personal accounts. Cast retain full rights to use their personal social media platforms as they see fit, including posting about their professional activities.', ARRAY['social media restrictions','not apply','cast members''','personal accounts','retain','full rights','use','personal social media platforms','posting','professional activities']::text[], '{"doc": "Counterparty_Proposal", "section": "Social Media", "note": "Cast personal account exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excepting cast personal accounts eliminates primary restriction need. Cast are most visible and have largest followings; their posts are highest-risk leak vector."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may provide social media guidelines but cannot mandate compliance. Guild and union rules protect talent''s personal expression rights, and any attempt to restrict social media would violate such rules.', ARRAY['Amazon','provide','social media guidelines','cannot mandate','compliance','guild','union rules','protect','talent''s','personal expression rights','restrict','social media','violate','rules']::text[], '{"doc": "Counterparty_Proposal", "section": "Social Media", "note": "Guild/union override claim", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Guild/union rules do not prevent contractual social media restrictions regarding production content. This is false characterization; confidentiality requirements are standard and enforceable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Production personnel may post personal photos from set showing themselves with colleagues, provided such photos do not reveal ''major spoilers'' as defined by Amazon. Non-spoiler behind-the-scenes content is permitted.', ARRAY['production personnel','post','personal photos','set','showing themselves','colleagues','not reveal','major spoilers','defined','Amazon','non-spoiler','behind-the-scenes content','permitted']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Non-spoiler BTS permitted", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Behind-the-scenes permission even with ''non-spoiler'' qualifier creates uncontrolled content flow. BTS photos can reveal sets, costumes, and other protectable elements. All production photos require approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Social media restrictions apply during production only. Once principal photography wraps, cast and crew may post freely about their experience working on the Program, subject only to not revealing major plot points that have not been publicly released.', ARRAY['social media restrictions','apply','during production only','principal photography wraps','cast','crew','post freely','experience','working on','Program','not revealing','major plot points','not','publicly released']::text[], '{"doc": "Counterparty_Markup", "section": "Social Media", "note": "Production-only restrictions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Production-only restrictions eliminate protection during post-production and pre-release marketing window. Restrictions must continue through release and coordinated promotional period."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Confidentiality obligations shall survive expiration or termination of this Agreement for a period of five (5) years, except that: (a) obligations regarding trade secrets shall survive indefinitely; (b) obligations regarding personal data shall survive for so long as such data is retained; and (c) obligations regarding NPI shall survive for seven (7) years.', ARRAY['confidentiality obligations','survive','expiration','termination','Agreement','five years','except','trade secrets','survive indefinitely','personal data','survive','so long as','data','retained','NPI','survive','seven years']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Tiered survival periods", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Tiered survival periods based on information type appropriately differentiates protection needs. Trade secret indefinite survival and extended NPI period reflect heightened sensitivity."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Upon expiration or termination of this Agreement, or upon Amazon''s request at any time, ProdCo shall: (a) immediately cease using all Confidential Information; (b) within ten (10) business days, return to Amazon or securely destroy all Confidential Information in any form; and (c) provide written certification of compliance.', ARRAY['expiration','termination','Agreement','Amazon''s request','any time','immediately cease using','Confidential Information','ten business days','return','Amazon','securely destroy','Confidential Information','any form','written certification','compliance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Return or destroy with certification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard return/destroy obligation with timeline and certification. On-request provision allows Amazon to require action at any time, not just termination."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Destruction of Confidential Information shall be completed using secure methods appropriate to the medium: physical documents shall be shredded; electronic files shall be securely deleted using industry-standard data destruction software; and cloud-stored information shall be permanently deleted with confirmation from the cloud provider.', ARRAY['destruction','Confidential Information','secure methods','appropriate','medium','physical documents','shredded','electronic files','securely deleted','industry-standard','data destruction software','cloud-stored','permanently deleted','confirmation','cloud provider']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Destruction standards by medium", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Media-specific destruction standards ensure appropriate methods for each format. Cloud provider confirmation addresses modern storage realities."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The return or destruction obligation extends to Confidential Information held by ProdCo''s agents, contractors, and subcontractors. ProdCo shall ensure such parties return or destroy Confidential Information on the same timeline and shall obtain and provide certifications from such parties.', ARRAY['return','destruction obligation','extends','Confidential Information','agents','contractors','subcontractors','ensure','parties','return','destroy','same timeline','obtain','provide','certifications','parties']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Third-party return/destroy", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extension to third parties with certification requirement ensures complete information recovery. Prevents residual information in supply chain."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The following provisions shall survive expiration or termination of this Agreement: confidentiality obligations; publicity restrictions; indemnification obligations; representations and warranties; limitation of liability; dispute resolution; and any other provision that by its nature should survive.', ARRAY['provisions','survive','expiration','termination','Agreement','confidentiality','publicity restrictions','indemnification','representations','warranties','limitation of liability','dispute resolution','provision','nature','should survive']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Comprehensive survival provisions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumeration of surviving provisions ensures key protections continue post-termination. Catch-all for nature-based survival addresses unenumerated provisions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s confidentiality obligations regarding Program creative elements shall survive until such elements have been publicly released by Amazon. Following public release, confidentiality obligations regarding those specific elements shall terminate, but obligations regarding unreleased elements and Amazon NPI shall continue.', ARRAY['confidentiality obligations','Program creative elements','survive','publicly released','Amazon','public release','confidentiality obligations','specific elements','terminate','unreleased elements','Amazon NPI','continue']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Release-based creative survival", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Release-based survival for creative elements is practical approach. Distinguishes between released content (public) and unreleased content (still confidential)."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may, at any time upon reasonable notice, conduct an audit to verify ProdCo''s compliance with confidentiality obligations, including verification of return or destruction of Confidential Information. ProdCo shall cooperate with such audits and provide access to relevant systems and personnel.', ARRAY['Amazon','any time','reasonable notice','conduct','audit','verify','ProdCo''s compliance','confidentiality obligations','verification','return','destruction','Confidential Information','cooperate','audits','access','systems','personnel']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Audit right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Audit right for confidentiality compliance verification provides enforcement mechanism. System and personnel access enables meaningful verification."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Confidentiality survives termination. ProdCo may retain one archival copy of Confidential Information solely for purposes of legal compliance and dispute resolution, provided such copy is stored securely, accessed only by authorized legal personnel, and destroyed upon resolution of any pending legal matters.', ARRAY['confidentiality survives','termination','retain','one archival copy','Confidential Information','legal compliance','dispute resolution','stored securely','accessed','authorized legal personnel','destroyed','resolution','pending legal matters']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Legal archival exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Single archival copy for legal purposes with security, access, and destruction requirements is reasonable exception addressing litigation and regulatory needs."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Return or destruction applies to Confidential Information. Information that has been incorporated into routine backup systems and cannot reasonably be identified and deleted may be retained subject to continuing confidentiality obligations, provided ProdCo uses reasonable efforts to delete such information when backups are rotated.', ARRAY['return','destruction','applies','Confidential Information','incorporated','routine backup systems','cannot reasonably','identified','deleted','retained','continuing confidentiality obligations','reasonable efforts','delete','backups','rotated']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Backup retention exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Backup exception acknowledges technical reality that commingled backup data is difficult to selectively delete. Continuing obligations and rotation-based deletion provide protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Survival of confidentiality is five years from termination. For information that remains a trade secret after five years, ProdCo''s obligations shall continue, but the determination of trade secret status shall be based on then-current law and circumstances.', ARRAY['survival','confidentiality','five years','termination','information','remains','trade secret','five years','obligations','continue','determination','trade secret status','then-current law','circumstances']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Trade secret determination clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Trade secret continuation with then-current law determination is reasonable legal framework. Protects information that retains trade secret status while not overreaching."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall return or destroy Confidential Information within thirty (30) days of termination. If destruction is not feasible due to technical limitations, ProdCo shall notify Amazon and propose an alternative approach, which Amazon may accept or reject.', ARRAY['return','destroy','Confidential Information','thirty days','termination','destruction','not feasible','technical limitations','notify Amazon','propose','alternative approach','Amazon','accept','reject']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Extended timeline with alternative", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Thirty-day timeline is slightly longer but may be acceptable. Technical limitation alternative with Amazon approval addresses practical challenges while preserving Amazon control."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon termination, ProdCo shall certify return or destruction. If Amazon disputes the completeness of compliance, Amazon may request specific verification measures, and ProdCo shall cooperate, provided such measures are reasonable and do not require disclosure of ProdCo''s privileged information.', ARRAY['termination','certify','return','destruction','Amazon disputes','completeness','compliance','request','specific verification measures','cooperate','reasonable','not require','disclosure','ProdCo''s privileged information']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Dispute verification with privilege protection", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Verification cooperation with privilege protection addresses legitimate concern while enabling compliance verification. Reasonableness requirement prevents overreaching."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Survival period is five years. ProdCo acknowledges that during such period, it remains bound by confidentiality obligations and may be required to respond to Amazon inquiries, litigation discovery, or regulatory investigations regarding Confidential Information.', ARRAY['survival period','five years','acknowledges','during period','bound','confidentiality obligations','required','respond','Amazon inquiries','litigation discovery','regulatory investigations','Confidential Information']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Post-termination cooperation acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Acknowledgment of ongoing obligations and cooperation requirements during survival period sets clear expectations for post-termination conduct."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Confidentiality obligations shall terminate upon expiration or termination of this Agreement. Following termination, ProdCo shall have no further confidentiality obligations with respect to any information disclosed during the term.', ARRAY['confidentiality obligations','terminate','expiration','termination','Agreement','following termination','no further','confidentiality obligations','information','disclosed','term']::text[], '{"doc": "Counterparty_Proposal", "section": "Confidentiality", "note": "No survival", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "No survival of confidentiality obligations eliminates all post-termination protection. Confidential information shared during the term requires ongoing protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Confidentiality survives for one (1) year following termination. This period reflects the practical reality that most information loses its competitive value within one year and that longer periods impose unreasonable burdens on ProdCo.', ARRAY['confidentiality survives','one year','following termination','practical reality','information','loses','competitive value','one year','longer periods','unreasonable burdens','ProdCo']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "One-year survival only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "One-year survival is grossly inadequate. Content-related confidential information retains value for years. Minimum five-year survival is required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall return or destroy Confidential Information upon request. However, ProdCo shall not be required to return or destroy information that has been incorporated into ProdCo''s work product, internal systems, or institutional knowledge.', ARRAY['return','destroy','Confidential Information','upon request','not required','return','destroy','information','incorporated','ProdCo''s work product','internal systems','institutional knowledge']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Work product/systems exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Exception for work product, systems, and ''institutional knowledge'' creates massive loophole. Allows ProdCo to retain virtually all information. Return/destroy must be comprehensive."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Return or destruction applies to physical documents only. Electronic information may be retained in ProdCo''s systems subject to ProdCo''s standard data retention policies, which ProdCo may modify at any time.', ARRAY['return','destruction','applies','physical documents only','electronic information','retained','ProdCo''s systems','standard data retention policies','modify','any time']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Physical only return", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting return/destroy to physical documents while allowing electronic retention defeats the purpose. Most confidential information is electronic and must be covered."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall certify return or destruction within ninety (90) days of termination. Certification by ProdCo shall be conclusive evidence of compliance, and Amazon shall have no right to audit or verify such certification.', ARRAY['certify','return','destruction','ninety days','termination','certification','ProdCo','conclusive evidence','compliance','Amazon','no right','audit','verify','certification']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Conclusive certification without audit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Ninety-day timeline is too long, and conclusive certification without audit right eliminates verification ability. Amazon must retain audit rights to verify compliance."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Survival and return obligations are mutual. Amazon shall return or destroy ProdCo''s Confidential Information on the same terms, and Amazon''s confidentiality obligations shall survive for the same period as ProdCo''s.', ARRAY['survival','return obligations','mutual','Amazon','return','destroy','ProdCo''s Confidential Information','same terms','Amazon''s confidentiality obligations','survive','same period','ProdCo''s']::text[], '{"doc": "Counterparty_Proposal", "section": "Confidentiality", "note": "Forced mutual return/destroy", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Forced mutual obligations ignore that Amazon receives far more confidential information from ProdCo than vice versa. Amazon''s obligations can be more limited given asymmetric information flow."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement shall be governed by and construed in accordance with the laws of the State of California, without regard to its conflict of laws principles. The parties irrevocably submit to the exclusive jurisdiction and venue of the state and federal courts located in Los Angeles County, California.', ARRAY['governed by','construed','laws','State of California','without regard to','conflict of laws','irrevocably submit','exclusive jurisdiction','venue','state','federal courts','Los Angeles County','California']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Standard California choice of law and venue", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "California law with Los Angeles venue is standard for entertainment industry agreements. Conflict of laws exclusion prevents forum shopping arguments. Exclusive jurisdiction creates certainty."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement shall be governed by the laws of the State of Washington. Any action arising out of or relating to this Agreement shall be brought exclusively in the state or federal courts located in King County, Washington. The parties consent to personal jurisdiction in such courts and waive any objection to venue.', ARRAY['governed by','laws','State of Washington','action','arising out of','relating to','brought exclusively','state','federal courts','King County','Washington','consent','personal jurisdiction','waive','objection','venue']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Washington choice of law and venue", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Washington law with King County venue is appropriate given Amazon''s headquarters location. Personal jurisdiction consent and venue waiver strengthen enforceability."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The laws of the State of New York shall govern this Agreement without regard to principles of conflicts of law. The parties agree that the state and federal courts sitting in New York County, New York shall have exclusive jurisdiction over any disputes and waive any defense of inconvenient forum.', ARRAY['laws','State of New York','govern','without regard to','conflicts of law','state','federal courts','New York County','exclusive jurisdiction','disputes','waive','defense','inconvenient forum']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "New York choice of law and venue", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "New York law and venue is standard alternative to California for entertainment agreements. Forum non conveniens waiver prevents dismissal motions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement shall be governed by California law. The United Nations Convention on Contracts for the International Sale of Goods and any uniform laws based thereon shall not apply to this Agreement.', ARRAY['governed by','California law','United Nations Convention','Contracts','International Sale of Goods','uniform laws','not apply','Agreement']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "CISG exclusion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "CISG exclusion is standard for U.S. agreements with international counterparties. Prevents application of international treaty that might otherwise govern."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Each party irrevocably waives any right to trial by jury in any action or proceeding arising out of or relating to this Agreement. The parties acknowledge that this waiver is knowing and voluntary and has been negotiated as part of the bargained-for exchange.', ARRAY['irrevocably waives','right','trial by jury','action','proceeding','arising out of','relating to','Agreement','waiver','knowing','voluntary','negotiated','bargained-for exchange']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Jury waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Jury waiver is standard in commercial agreements and preferred for complex entertainment disputes. Acknowledgment of knowing/voluntary waiver supports enforceability."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The choice of law and venue provisions herein are material terms of this Agreement. ProdCo agrees that it has had the opportunity to consult with counsel regarding these provisions and has knowingly and voluntarily agreed to California law and Los Angeles venue.', ARRAY['choice of law','venue provisions','material terms','Agreement','opportunity','consult','counsel','knowingly','voluntarily','agreed','California law','Los Angeles venue']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Counsel acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Counsel acknowledgment reinforces enforceability of choice of law and venue provisions. Establishes that provisions were knowingly accepted."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the exclusive venue provision, Amazon may bring an action for injunctive relief, specific performance, or enforcement of any judgment in any court of competent jurisdiction worldwide. ProdCo consents to jurisdiction in any such court for such purposes.', ARRAY['notwithstanding','exclusive venue','Amazon','bring action','injunctive relief','specific performance','enforcement','judgment','court','competent jurisdiction','worldwide','consents','jurisdiction','purposes']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Worldwide enforcement carveout", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Carveout for worldwide enforcement of injunctive relief and judgments allows Amazon to pursue relief where assets or activities are located."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'This Agreement shall be governed by California law. For disputes arising primarily from production activities conducted in a non-U.S. jurisdiction, the parties agree to consult regarding appropriate venue, provided that California law shall remain applicable regardless of venue.', ARRAY['governed by','California law','disputes','arising primarily','production activities','non-U.S. jurisdiction','consult','appropriate venue','California law','remain applicable','regardless','venue']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Non-U.S. production venue consultation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Venue consultation for non-U.S. production disputes may be acceptable while maintaining California law. Provides flexibility for international productions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'California law governs. Either party may serve process on the other by any means permitted by California law, including service by overnight courier to the notice address specified herein. Service shall be deemed complete upon delivery.', ARRAY['California law','governs','serve process','any means','permitted','California law','service','overnight courier','notice address','specified','service','deemed complete','delivery']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Alternative service provision", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Alternative service provision facilitating overnight courier service is practical addition that doesn''t limit forum selection. Streamlines process initiation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The Agreement is governed by California law. For intellectual property disputes involving rights registered outside the United States, such disputes may be brought in courts of the country where the rights are registered, applying California law to the extent permitted.', ARRAY['governed by','California law','intellectual property disputes','rights registered','outside','United States','brought','courts','country','rights registered','applying','California law','extent permitted']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Foreign IP registration forum", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Foreign IP registration forum option acknowledges that some IP disputes may need to be brought where rights are registered. California law application preserves consistency."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'California law and Los Angeles venue apply. If either party is required to enforce a judgment in a foreign jurisdiction, such party shall use reasonable efforts to seek recognition under applicable treaties or conventions. The other party shall not oppose such recognition proceedings.', ARRAY['California law','Los Angeles venue','apply','enforce','judgment','foreign jurisdiction','reasonable efforts','seek recognition','applicable treaties','conventions','not oppose','recognition proceedings']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Foreign judgment recognition cooperation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Foreign judgment recognition cooperation provision facilitates international enforcement. Non-opposition covenant prevents obstruction of legitimate enforcement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'This Agreement is governed by California law. ProdCo agrees that any action brought by ProdCo against Amazon must be brought in California courts within two (2) years of the claim accruing, and ProdCo waives any longer limitations period that might otherwise apply.', ARRAY['governed by','California law','action','brought','ProdCo','against Amazon','California courts','two years','claim accruing','waives','longer limitations period','otherwise apply']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Shortened limitations period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Two-year contractual limitations period is enforceable in California and provides reasonable window while limiting stale claims. One-sided application benefits Amazon."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'California law governs. The parties acknowledge that California has a substantial relationship to this Agreement and that application of California law is reasonable. ProdCo waives any argument that California law should not apply or that another jurisdiction''s law is more appropriate.', ARRAY['California law','governs','acknowledge','California','substantial relationship','Agreement','application','California law','reasonable','waives','argument','California law','not apply','another jurisdiction''s law','more appropriate']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Relationship acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Substantial relationship acknowledgment and waiver of challenge supports enforceability. Prevents later arguments that choice of law was unreasonable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This Agreement shall be governed by the laws of the jurisdiction in which ProdCo is incorporated. Venue shall be in the courts of such jurisdiction. Amazon consents to jurisdiction in such courts.', ARRAY['governed by','laws','jurisdiction','ProdCo','incorporated','venue','courts','such jurisdiction','Amazon consents','jurisdiction']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "ProdCo home jurisdiction", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo''s home jurisdiction for law and venue is unacceptable. Amazon requires consistent forum (California, Washington, or New York) for all production agreements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The parties agree that any dispute shall be resolved in the jurisdiction where the majority of production activities occurred. Choice of law shall be the law of such jurisdiction.', ARRAY['dispute','resolved','jurisdiction','majority','production activities occurred','choice of law','law','such jurisdiction']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Production location forum", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Production location forum creates unpredictable jurisdiction that varies by project. Amazon requires consistent forum regardless of production location."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Each party may bring actions in its home jurisdiction. Amazon agrees to submit to the jurisdiction of courts in ProdCo''s jurisdiction for any action brought by ProdCo against Amazon.', ARRAY['each party','bring actions','home jurisdiction','Amazon','submit','jurisdiction','courts','ProdCo''s jurisdiction','action','brought','ProdCo','against Amazon']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Split home jurisdictions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Split home jurisdiction forum allows ProdCo to sue Amazon in ProdCo''s home court. Amazon requires exclusive venue in Amazon''s chosen forum."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'No exclusive venue applies. Either party may bring an action in any court of competent jurisdiction where the other party does business, has assets, or can otherwise be served.', ARRAY['no exclusive venue','applies','either party','bring action','court','competent jurisdiction','other party','does business','has assets','served']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "No exclusive venue", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Non-exclusive venue allows forum shopping and creates unpredictability. Exclusive venue in Amazon''s chosen forum is required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This Agreement shall be governed by international commercial law principles, including UNIDROIT Principles and lex mercatoria. National law shall apply only where international principles are silent.', ARRAY['governed by','international commercial law principles','UNIDROIT Principles','lex mercatoria','national law','apply','only','international principles','silent']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "International law principles", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "International law principles instead of U.S. state law creates uncertainty. Entertainment agreements require specific U.S. state law governing."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'California law governs. However, if any provision of this Agreement is unenforceable under California law but would be enforceable under the law of ProdCo''s jurisdiction, such other law shall apply to that provision.', ARRAY['California law','governs','provision','Agreement','unenforceable','California law','enforceable','law','ProdCo''s jurisdiction','other law','apply','provision']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Alternative law for unenforceability", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Alternative law application for unenforceable provisions creates unpredictable hybrid governing law. California law must apply uniformly; if provisions are unenforceable, severability applies."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Any dispute, controversy, or claim arising out of or relating to this Agreement, including its formation, interpretation, performance, breach, or termination, shall be resolved exclusively by binding arbitration administered by JAMS in accordance with its Comprehensive Arbitration Rules.', ARRAY['dispute','controversy','claim','arising out of','relating to','Agreement','formation','interpretation','performance','breach','termination','resolved exclusively','binding arbitration','administered','JAMS','Comprehensive Arbitration Rules']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "JAMS arbitration clause", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "JAMS arbitration with comprehensive coverage is standard for entertainment agreements. Binding arbitration provides finality and confidentiality."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Disputes shall be resolved by arbitration. The arbitration shall be conducted by a single arbitrator with entertainment industry experience, mutually agreed by the parties. If the parties cannot agree on an arbitrator within fifteen (15) days, JAMS shall appoint one.', ARRAY['disputes','resolved','arbitration','conducted','single arbitrator','entertainment industry experience','mutually agreed','parties','cannot agree','arbitrator','fifteen days','JAMS','appoint']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Single arbitrator with industry experience", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Single arbitrator for efficiency with entertainment industry experience requirement ensures qualified decision-maker. Fallback to JAMS appointment prevents deadlock."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Arbitration is the exclusive remedy for disputes except that either party may seek: (a) injunctive or other equitable relief in any court of competent jurisdiction; (b) provisional remedies under applicable law; or (c) enforcement of any arbitration award in any court of competent jurisdiction.', ARRAY['arbitration','exclusive remedy','disputes','except','either party','seek','injunctive','equitable relief','court','competent jurisdiction','provisional remedies','applicable law','enforcement','arbitration award']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Arbitration with court carveouts", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard carveouts for injunctive relief, provisional remedies, and award enforcement preserve ability to seek emergency relief while maintaining arbitration for substantive disputes."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitrator shall have authority to award any remedy that would be available in court, including compensatory damages, specific performance, and injunctive relief. The arbitrator shall not have authority to award punitive or exemplary damages, and the parties waive any right thereto.', ARRAY['arbitrator','authority','award','remedy','available in court','compensatory damages','specific performance','injunctive relief','not have authority','award','punitive','exemplary damages','parties waive','right']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Arbitrator authority with punitive damages waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Broad arbitrator remedial authority with punitive damages exclusion is standard commercial approach. Ensures adequate relief while limiting unpredictable awards."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitration award shall be final and binding. Judgment on the award may be entered in any court of competent jurisdiction. The parties waive any right to appeal the award except as provided by the Federal Arbitration Act for vacatur of arbitration awards.', ARRAY['arbitration award','final','binding','judgment','award','entered','court','competent jurisdiction','waive','right to appeal','except','Federal Arbitration Act','vacatur','arbitration awards']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Final and binding with limited appeal", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Finality with FAA vacatur exception is standard. Waiver of broader appeal rights preserves arbitration efficiency while maintaining statutory protections."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Arbitration proceedings shall be confidential. Neither party shall disclose the existence, content, or results of the arbitration, except as required by law or to enforce the arbitration award. The arbitrator shall have authority to issue protective orders regarding confidential information.', ARRAY['arbitration proceedings','confidential','neither party','disclose','existence','content','results','arbitration','except','required by law','enforce','arbitration award','arbitrator','authority','protective orders','confidential information']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Arbitration confidentiality", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Arbitration confidentiality is key advantage over litigation. Protective order authority enables handling of sensitive business information."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the agreement to arbitrate, Amazon may elect to litigate any dispute in court by providing written notice to ProdCo prior to commencement of arbitration. ProdCo shall not have the corresponding right to elect litigation.', ARRAY['notwithstanding','agreement to arbitrate','Amazon','elect','litigate','dispute','court','written notice','ProdCo','prior to','commencement','arbitration','ProdCo','not have','corresponding right','elect litigation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Amazon litigation election option", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon-only litigation election option provides flexibility for disputes that may be better suited to court while maintaining arbitration as default."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Disputes shall be resolved by arbitration. For disputes involving claimed damages of less than $250,000, the parties agree to streamlined arbitration procedures with limited discovery and expedited timelines as set forth in Exhibit [X].', ARRAY['disputes','resolved','arbitration','disputes','claimed damages','less than $250,000','streamlined arbitration procedures','limited discovery','expedited timelines','Exhibit']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Small claims streamlined procedure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Streamlined procedures for smaller disputes reduces cost and time. $250K threshold and specific exhibit terms provide clarity on when streamlined process applies."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Arbitration applies to all disputes. Either party may request a panel of three arbitrators for disputes involving claimed damages exceeding $5,000,000, with costs of the additional arbitrators shared equally regardless of outcome.', ARRAY['arbitration','applies','all disputes','either party','request','panel','three arbitrators','disputes','claimed damages exceeding','$5,000,000','costs','additional arbitrators','shared equally','regardless','outcome']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Three-arbitrator panel option for large disputes", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Three-arbitrator panel option for large disputes provides additional review for significant matters. Equal cost sharing is fair approach."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Disputes shall be arbitrated. The parties agree to use JAMS unless JAMS is unavailable, in which case AAA shall administer the arbitration. Selection of an alternative administrator requires mutual written agreement.', ARRAY['disputes','arbitrated','use JAMS','unless','JAMS','unavailable','AAA','administer','arbitration','selection','alternative administrator','mutual written agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "JAMS with AAA backup", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "AAA as backup administrator if JAMS unavailable ensures arbitration can proceed. Both are reputable institutions with entertainment experience."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Arbitration is the exclusive remedy. The arbitrator shall issue a reasoned written decision explaining the factual and legal basis for the award. The decision shall be issued within sixty (60) days of the close of the evidentiary hearing.', ARRAY['arbitration','exclusive remedy','arbitrator','issue','reasoned written decision','explaining','factual','legal basis','award','decision','issued','sixty days','close','evidentiary hearing']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Reasoned decision requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Reasoned decision requirement improves transparency and provides basis for any vacatur challenge. 60-day timeline ensures timely resolution."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Binding arbitration applies. The Federal Arbitration Act shall govern the interpretation and enforcement of this arbitration agreement. State arbitration law shall apply only to the extent not preempted by the FAA.', ARRAY['binding arbitration','applies','Federal Arbitration Act','govern','interpretation','enforcement','arbitration agreement','state arbitration law','apply','only','extent','not preempted','FAA']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "FAA governance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "FAA governance provides strong federal policy favoring arbitration. Clarifies that state law is preempted to extent inconsistent with FAA."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Disputes shall be arbitrated except that disputes solely regarding payment amounts may, at the option of either party, be submitted to a single accounting arbitrator for expedited determination based on documentary evidence only.', ARRAY['disputes','arbitrated','except','disputes','solely','payment amounts','option','either party','submitted','single accounting arbitrator','expedited determination','documentary evidence only']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Payment dispute expedited process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Expedited accounting arbitration for payment disputes is efficient for disputes involving calculations rather than legal issues. Either party option is balanced."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Disputes may be resolved by arbitration only if both parties mutually agree in writing at the time the dispute arises. Absent such agreement, disputes shall be resolved in court.', ARRAY['disputes','resolved','arbitration','only if','both parties','mutually agree','writing','time','dispute arises','absent','agreement','disputes','resolved','court']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Optional arbitration only", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Mutual agreement at time of dispute effectively eliminates arbitration since parties rarely agree once dispute exists. Arbitration must be mandatory and binding."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may elect to resolve any dispute through arbitration or litigation at ProdCo''s sole option. Amazon shall be bound by ProdCo''s election and shall not have the right to select a different forum.', ARRAY['ProdCo','elect','resolve','dispute','arbitration','litigation','ProdCo''s sole option','Amazon','bound','ProdCo''s election','not have','right','select','different forum']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "ProdCo-only forum election", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo-only forum election gives ProdCo complete control over dispute forum. Amazon must have forum election rights or exclusive arbitration."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'All disputes shall be resolved by litigation in court. The parties agree that arbitration is not an appropriate forum for entertainment industry disputes given the complexity and public interest in such matters.', ARRAY['all disputes','resolved','litigation','court','parties agree','arbitration','not','appropriate forum','entertainment industry disputes','complexity','public interest']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Mandatory litigation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mandatory litigation eliminates arbitration benefits (confidentiality, speed, entertainment expertise). Arbitration is standard and appropriate for entertainment disputes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Arbitration shall not apply to claims that could be brought in small claims court. For claims under $75,000, either party may elect small claims court in the party''s home jurisdiction.', ARRAY['arbitration','not apply','claims','small claims court','claims','under $75,000','either party','elect','small claims court','party''s home jurisdiction']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Small claims exception", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Small claims exception for claims up to $75K in party''s home jurisdiction creates forum-shopping opportunity for significant claims. Arbitration must cover all disputes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The prevailing party in arbitration or litigation shall be entitled to recover reasonable attorneys'' fees from the non-prevailing party. ''Prevailing party'' shall be determined by the finder of fact.', ARRAY['prevailing party','arbitration','litigation','entitled','recover','reasonable attorneys'' fees','non-prevailing party','prevailing party','determined','finder of fact']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Loser pays fee shifting", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Prevailing party fee shifting creates significant risk if Amazon loses on any claim. Amazon typically prefers each party bearing own fees except for specific carveouts."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Disputes shall be resolved by arbitration. Any arbitration award shall be subject to de novo review by a court upon request of either party. The court''s determination shall supersede the arbitration award.', ARRAY['disputes','resolved','arbitration','arbitration award','subject to','de novo review','court','request','either party','court''s determination','supersede','arbitration award']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Court de novo review", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "De novo court review completely defeats arbitration benefits. Arbitration would become non-binding preliminary step. Awards must be final subject only to FAA vacatur."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitration shall be conducted in Los Angeles, California under the JAMS Comprehensive Arbitration Rules and Procedures in effect at the time of filing. The language of the arbitration shall be English. The arbitration shall be administered by JAMS.', ARRAY['arbitration','conducted','Los Angeles','California','JAMS Comprehensive Arbitration Rules','Procedures','in effect','time of filing','language','arbitration','English','administered','JAMS']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "JAMS comprehensive rules in LA", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Los Angeles is entertainment industry center with qualified arbitrators. JAMS Comprehensive Rules are appropriate for commercial disputes. English language ensures consistency."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Discovery in arbitration shall be limited to: (a) exchange of relevant documents; (b) up to five (5) depositions per side, each lasting no more than seven (7) hours; and (c) written interrogatories limited to twenty-five (25) questions per side. The arbitrator may permit additional discovery for good cause.', ARRAY['discovery','arbitration','limited','exchange','relevant documents','five depositions','per side','seven hours','written interrogatories','twenty-five questions','per side','arbitrator','permit','additional discovery','good cause']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Limited discovery parameters", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Limited discovery preserves arbitration efficiency while providing adequate fact-finding. Good cause exception allows expansion for complex matters."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The evidentiary hearing shall be conducted over no more than five (5) consecutive business days unless the arbitrator determines that additional time is necessary. Post-hearing briefs shall be submitted within thirty (30) days of the hearing''s conclusion.', ARRAY['evidentiary hearing','conducted','no more than','five','consecutive business days','unless','arbitrator determines','additional time','necessary','post-hearing briefs','submitted','thirty days','hearing''s conclusion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Hearing duration limits", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Five-day hearing limit promotes efficiency. Arbitrator discretion for additional time addresses complex matters. Thirty-day brief deadline provides adequate preparation time."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Each party shall bear its own costs and attorneys'' fees in the arbitration. The administrative fees of JAMS and the arbitrator''s fees and expenses shall be shared equally by the parties, subject to the arbitrator''s authority to reallocate such costs in the final award.', ARRAY['each party','bear','own costs','attorneys'' fees','arbitration','administrative fees','JAMS','arbitrator''s fees','expenses','shared equally','parties','subject to','arbitrator''s authority','reallocate','costs','final award']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Cost allocation with reallocation authority", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Each party bearing own fees is standard commercial approach. Equal sharing of arbitration costs with reallocation authority is fair and provides incentive against frivolous claims."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitrator shall be a retired judge or attorney with at least fifteen (15) years of experience in entertainment law, including experience with production agreements, content licensing, or related matters. The arbitrator shall disclose any potential conflicts of interest.', ARRAY['arbitrator','retired judge','attorney','fifteen years','experience','entertainment law','production agreements','content licensing','related matters','disclose','potential conflicts of interest']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Arbitrator qualifications", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific entertainment law experience requirement ensures qualified arbitrator. Fifteen years is appropriate for complex disputes. Conflict disclosure is standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitrator shall apply California substantive law and shall not have authority to apply equity or principles of law that would result in a different outcome than would be reached by strict application of California law. The arbitrator shall not add to or modify the Agreement.', ARRAY['arbitrator','apply','California substantive law','not have authority','apply equity','principles of law','different outcome','strict application','California law','not add to','modify','Agreement']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Substantive law constraints", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Constraints on equity application and Agreement modification limit arbitrator discretion to legal interpretation. Ensures predictability and faithful contract enforcement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All arbitration proceedings, including filings, evidence, testimony, and awards, shall be treated as confidential information. Neither party shall disclose any aspect of the arbitration except as necessary to enforce the award or as required by law.', ARRAY['arbitration proceedings','filings','evidence','testimony','awards','treated','confidential information','neither party','disclose','aspect','arbitration','except','necessary','enforce','award','required by law']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Comprehensive arbitration confidentiality", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive confidentiality covering all aspects of arbitration is key benefit. Exceptions for enforcement and legal requirements are necessary and appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Arbitration shall be in Los Angeles or, at Amazon''s election, by videoconference. If conducted by videoconference, the parties shall use a secure platform approved by JAMS. Witnesses may testify remotely with parties'' consent or arbitrator permission.', ARRAY['arbitration','Los Angeles','Amazon''s election','videoconference','conducted','videoconference','secure platform','approved','JAMS','witnesses','testify remotely','parties'' consent','arbitrator permission']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Videoconference option", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Videoconference option provides flexibility and cost savings. Amazon election right ensures choice remains with Amazon. Secure platform and witness appearance rules address practical concerns."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'JAMS Comprehensive Rules apply. Notwithstanding such rules, the arbitrator shall not have authority to order depositions of non-party witnesses except upon showing of compelling need and unavailability of information through other means.', ARRAY['JAMS Comprehensive Rules','apply','notwithstanding','arbitrator','not have authority','order depositions','non-party witnesses','except','showing','compelling need','unavailability','information','other means']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Non-party deposition limits", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Non-party deposition limits reduce burden on third parties while preserving access with compelling need showing. Consistent with limited discovery approach."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The arbitration shall proceed on an expedited basis if either party so requests and the claimed damages do not exceed $500,000. Expedited arbitration shall be completed within ninety (90) days of arbitrator appointment.', ARRAY['arbitration','proceed','expedited basis','either party','requests','claimed damages','not exceed','$500,000','expedited arbitration','completed','ninety days','arbitrator appointment']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Expedited arbitration for smaller claims", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Expedited option for smaller claims promotes efficiency. Either party request trigger and $500K threshold are reasonable parameters."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The arbitrator may conduct a preliminary hearing to address discovery scope, hearing schedule, and procedural issues. The parties shall cooperate to complete arbitration within twelve (12) months of filing, absent extraordinary circumstances.', ARRAY['arbitrator','conduct','preliminary hearing','address','discovery scope','hearing schedule','procedural issues','parties','cooperate','complete','arbitration','twelve months','filing','absent','extraordinary circumstances']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Preliminary hearing and timeline", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Preliminary hearing for procedural matters is efficient practice. Twelve-month target provides reasonable timeline with flexibility for complex matters."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If the arbitrator becomes unavailable after appointment, the parties shall select a replacement using the same process. The replacement arbitrator shall determine whether prior proceedings must be repeated or can be adopted.', ARRAY['arbitrator','becomes unavailable','after appointment','parties','select','replacement','same process','replacement arbitrator','determine','prior proceedings','repeated','adopted']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Arbitrator replacement procedure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Replacement procedure addresses practical contingency of arbitrator unavailability. Flexibility on prior proceedings adoption is reasonable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The evidentiary rules shall be relaxed in arbitration. The arbitrator may consider any evidence relevant to the dispute regardless of admissibility under formal rules of evidence, giving appropriate weight based on reliability and relevance.', ARRAY['evidentiary rules','relaxed','arbitration','arbitrator','consider','evidence','relevant','dispute','regardless','admissibility','formal rules','evidence','appropriate weight','reliability','relevance']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Relaxed evidentiary rules", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Relaxed evidentiary rules are common in arbitration and allow consideration of all relevant information. Weight-based approach provides appropriate flexibility."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The arbitration shall be conducted in ProdCo''s home city using the rules of the local bar association arbitration program. Amazon shall bear all costs of arbitration regardless of outcome.', ARRAY['arbitration','conducted','ProdCo''s home city','rules','local bar association','arbitration program','Amazon','bear','all costs','arbitration','regardless','outcome']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "ProdCo location with Amazon costs", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo home city venue and Amazon bearing all costs regardless of outcome is one-sided. Venue must be Amazon''s choice; costs should be shared or allocated by arbitrator."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Full federal court discovery rules shall apply in arbitration. Either party may take unlimited depositions and propound unlimited interrogatories. The arbitration schedule shall accommodate full discovery.', ARRAY['full federal court','discovery rules','apply','arbitration','either party','unlimited depositions','unlimited interrogatories','arbitration schedule','accommodate','full discovery']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Unlimited discovery", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Unlimited federal court-style discovery defeats arbitration efficiency benefits. Discovery must be limited and proportionate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The arbitration shall be conducted using AAA Entertainment Industry Arbitration Rules. All arbitration hearings shall be held in New York City regardless of the governing law or any venue provisions.', ARRAY['arbitration','conducted','AAA Entertainment Industry Arbitration Rules','arbitration hearings','held','New York City','regardless','governing law','venue provisions']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Inconsistent venue with rules", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Overriding venue provisions with different arbitration location creates inconsistency. Arbitration location must align with governing law venue."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The arbitrator shall have authority to award reasonable attorneys'' fees and costs to the prevailing party. ''Prevailing party'' means the party that achieves substantially all of its claimed relief.', ARRAY['arbitrator','authority','award','reasonable attorneys'' fees','costs','prevailing party','prevailing party means','party','achieves','substantially all','claimed relief']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Prevailing party fee shifting", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Prevailing party fee shifting creates significant risk exposure if Amazon doesn''t achieve substantially all relief. Each party bearing own fees is preferred."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The arbitrator may appoint independent experts at the parties'' expense to investigate any factual matters. Expert fees shall be borne by the party against whom the expert''s conclusions favor.', ARRAY['arbitrator','appoint','independent experts','parties'' expense','investigate','factual matters','expert fees','borne','party','against whom','expert''s conclusions','favor']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Appointed expert with outcome-based cost", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Outcome-based expert cost allocation creates unpredictable expense exposure. Expert costs should be shared or subject to arbitrator''s general cost allocation authority."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The arbitration shall be conducted in the international language of the party initiating the claim. If ProdCo initiates and requests proceedings in a non-English language, Amazon shall provide certified translations at its expense.', ARRAY['arbitration','conducted','international language','party','initiating','claim','ProdCo initiates','requests','proceedings','non-English language','Amazon','provide','certified translations','expense']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Non-English proceedings option", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Non-English proceedings with Amazon translation expense burden is unacceptable. Arbitration must be conducted in English regardless of initiating party."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the agreement to arbitrate, either party may seek temporary, preliminary, or permanent injunctive relief, specific performance, or other equitable remedies in any court of competent jurisdiction to protect its rights pending arbitration or to enforce arbitration outcomes.', ARRAY['notwithstanding','agreement to arbitrate','either party','seek','temporary','preliminary','permanent','injunctive relief','specific performance','equitable remedies','court','competent jurisdiction','protect','rights','pending arbitration','enforce','arbitration outcomes']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Standard injunctive relief carveout", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard carveout preserving access to courts for injunctive and equitable relief. Essential for protecting IP rights, confidentiality, and other interests requiring immediate action."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The parties acknowledge that breach of confidentiality, publicity, or intellectual property provisions may cause irreparable harm for which monetary damages would be inadequate. Amazon shall be entitled to seek injunctive relief without proof of actual damages or posting of bond.', ARRAY['acknowledge','breach','confidentiality','publicity','intellectual property','irreparable harm','monetary damages','inadequate','Amazon','entitled','seek injunctive relief','without proof','actual damages','posting of bond']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Irreparable harm acknowledgment with bond waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Irreparable harm acknowledgment supports injunction motions. Bond waiver removes practical barrier to obtaining emergency relief."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may seek a temporary restraining order or preliminary injunction in any court of competent jurisdiction without first demanding arbitration. The court''s order shall remain in effect until the arbitrator issues a superseding order or final award.', ARRAY['Amazon','seek','temporary restraining order','preliminary injunction','court','competent jurisdiction','without first','demanding arbitration','court''s order','remain in effect','arbitrator','issues','superseding order','final award']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "TRO/PI without arbitration demand", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Pre-arbitration TRO/PI access is essential for emergencies. Court order effectiveness until arbitrator supersedes provides continuous protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitrator shall have authority to issue preliminary injunctive relief and other provisional remedies. However, such authority shall not limit either party''s right to seek such relief from a court of competent jurisdiction at any time before or during arbitration.', ARRAY['arbitrator','authority','issue','preliminary injunctive relief','provisional remedies','not limit','either party''s right','seek','relief','court','competent jurisdiction','any time','before','during arbitration']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Dual arbitrator and court authority", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Parallel arbitrator and court authority for provisional relief provides maximum flexibility. Party can choose most effective forum for emergency relief."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Seeking injunctive relief in court shall not waive the right to arbitrate the underlying dispute. Following issuance of any injunction, the parties shall proceed to arbitration for determination of all claims on the merits.', ARRAY['seeking','injunctive relief','court','not waive','right to arbitrate','underlying dispute','following','issuance','injunction','parties','proceed','arbitration','determination','claims','merits']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "No waiver of arbitration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that court action for injunctive relief doesn''t waive arbitration for merits. Preserves arbitration for substantive dispute resolution."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may seek specific performance of ProdCo''s delivery obligations, grant of rights provisions, and any other obligations for which legal remedies would be inadequate. ProdCo consents to such specific performance and waives any defense that legal remedies are adequate.', ARRAY['Amazon','seek','specific performance','ProdCo''s delivery obligations','grant of rights','obligations','legal remedies','inadequate','ProdCo consents','specific performance','waives','defense','legal remedies','adequate']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Specific performance with defense waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific performance availability for key obligations with defense waiver ensures Amazon can compel performance rather than accept damages."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The court or arbitrator may issue such orders as necessary to preserve the status quo pending resolution, including orders to: (a) maintain confidentiality; (b) preserve evidence; (c) prevent dissipation of assets; and (d) prevent irreparable harm.', ARRAY['court','arbitrator','issue','orders','preserve','status quo','pending resolution','maintain confidentiality','preserve evidence','prevent dissipation','assets','prevent','irreparable harm']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Status quo preservation orders", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerated status quo preservation orders clarify scope of available interim relief. Addresses key protection needs during dispute resolution."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Either party may seek injunctive relief in court. The party seeking relief shall provide the other party with reasonable advance notice of any motion for injunctive relief, except where such notice would render the relief ineffective.', ARRAY['either party','seek','injunctive relief','court','party','seeking relief','provide','other party','reasonable advance notice','motion','injunctive relief','except','notice','render','relief','ineffective']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Advance notice with exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Advance notice requirement with effectiveness exception is balanced approach. Allows preparation while preserving emergency relief capability."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Injunctive relief may be sought in court. If a court issues preliminary relief, either party may request that the arbitrator review and modify such relief as appropriate. The arbitrator''s modification shall supersede the court''s order.', ARRAY['injunctive relief','sought','court','court issues','preliminary relief','either party','request','arbitrator','review','modify','relief','appropriate','arbitrator''s modification','supersede','court''s order']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Arbitrator review of court relief", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Arbitrator review of court-issued relief allows for reassessment in arbitration context. Provides path to modify relief as circumstances develop."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may seek emergency arbitrator relief under JAMS rules as an alternative to court proceedings. Emergency arbitrator proceedings shall not preclude subsequent court action if the emergency arbitrator''s order proves insufficient.', ARRAY['Amazon','seek','emergency arbitrator relief','JAMS rules','alternative','court proceedings','emergency arbitrator proceedings','not preclude','subsequent court action','emergency arbitrator''s order','insufficient']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Emergency arbitrator option", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Emergency arbitrator as alternative to court provides additional option. Non-preclusion of court action if insufficient preserves full remedies."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The injunctive relief carveout applies to both parties. However, ProdCo shall not seek injunctive relief to prevent Amazon from exercising its termination rights or to compel Amazon to continue production or release the Program.', ARRAY['injunctive relief carveout','applies','both parties','ProdCo','not seek','injunctive relief','prevent','Amazon','exercising','termination rights','compel','Amazon','continue production','release','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Limits on ProdCo injunctive relief", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout preventing ProdCo from enjoining Amazon''s termination or release decisions protects Amazon''s operational discretion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Injunctive relief is available. If either party obtains injunctive relief and is subsequently found not to have been entitled to such relief, such party shall indemnify the other for losses caused by the wrongfully obtained injunction.', ARRAY['injunctive relief','available','either party','obtains','injunctive relief','subsequently found','not entitled','such relief','party','indemnify','other','losses caused','wrongfully obtained','injunction']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Wrongful injunction indemnity", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Wrongful injunction indemnity is common counterbalance to injunctive relief access. May be acceptable given bond waiver benefit."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Court jurisdiction for injunctive relief shall be exclusive to the courts specified in the venue provision. Neither party may seek injunctive relief in any other court without the other''s consent.', ARRAY['court jurisdiction','injunctive relief','exclusive','courts','specified','venue provision','neither party','seek','injunctive relief','other court','without','other''s consent']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Venue-limited injunctive relief", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Venue limitation on injunctive relief may be acceptable if primary venue courts are available. Limits forum shopping for emergency relief."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The parties agree that disputes shall be resolved exclusively by arbitration. Neither party may seek injunctive or other equitable relief from any court, and the arbitrator shall have exclusive authority over all remedies.', ARRAY['disputes','resolved exclusively','arbitration','neither party','seek','injunctive','equitable relief','court','arbitrator','exclusive authority','all remedies']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "No court access for injunctive relief", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating court access for injunctive relief is unacceptable. Arbitration may be too slow for emergencies; court access for provisional remedies must be preserved."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Either party may seek injunctive relief in court. However, the party seeking relief must first obtain the arbitrator''s permission, which the arbitrator may grant or deny in its discretion.', ARRAY['either party','seek','injunctive relief','court','party','seeking relief','first obtain','arbitrator''s permission','arbitrator','grant','deny','discretion']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Arbitrator permission required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring arbitrator permission for court relief defeats emergency relief purpose. Court access must be immediately available without arbitrator involvement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may seek injunctive relief in court only after providing ProdCo with thirty (30) days'' advance written notice and an opportunity to cure the alleged violation.', ARRAY['Amazon','seek','injunctive relief','court','only after','providing','ProdCo','thirty days','advance written notice','opportunity','cure','alleged violation']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "30-day notice requirement for injunctive relief", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "30-day notice requirement defeats purpose of injunctive relief for emergencies. Irreparable harm often occurs immediately; notice delay is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The injunctive relief carveout is mutual. ProdCo may seek injunctive relief to compel Amazon to continue production, make scheduled payments, or proceed with release of the Program as planned.', ARRAY['injunctive relief carveout','mutual','ProdCo','seek','injunctive relief','compel','Amazon','continue production','make scheduled payments','proceed','release','Program','planned']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "ProdCo injunctive relief to compel Amazon", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo injunctive relief to compel Amazon performance would override Amazon''s termination and release discretion. Such compelled performance is inappropriate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Injunctive relief is available. However, if the party seeking relief does not ultimately prevail on the merits in arbitration, such party shall pay the other party''s attorneys'' fees incurred in opposing the injunction motion.', ARRAY['injunctive relief','available','party','seeking relief','not ultimately prevail','merits','arbitration','pay','other party''s','attorneys'' fees','incurred','opposing','injunction motion']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Fee shifting for unsuccessful merits", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Fee shifting based on merits outcome creates significant disincentive to seek legitimate emergency relief. Injunctive relief decision should be evaluated independently of merits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Injunctive relief may be sought only for violations of the confidentiality provisions. All other disputes, including intellectual property claims, shall be resolved exclusively by arbitration without access to court remedies.', ARRAY['injunctive relief','sought','only','violations','confidentiality provisions','other disputes','intellectual property claims','resolved exclusively','arbitration','without access','court remedies']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Confidentiality-only injunctive relief", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting injunctive relief to confidentiality excludes critical areas like IP infringement. Injunctive relief must be available for all appropriate circumstances."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Before initiating arbitration, the parties shall attempt to resolve the dispute through good faith negotiations. Within ten (10) business days of a party''s written dispute notice, executives with settlement authority shall meet (in person or by video) to attempt resolution.', ARRAY['before initiating','arbitration','parties','attempt','resolve','dispute','good faith negotiations','ten business days','party''s','written dispute notice','executives','settlement authority','meet','in person','video','attempt resolution']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Executive negotiation requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Executive negotiation requirement is reasonable pre-arbitration step. Ten-day timeline prevents extended delay. Settlement authority requirement ensures meaningful discussion."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The informal resolution period shall not exceed thirty (30) days from the date of the dispute notice. If resolution is not achieved within such period, either party may proceed to arbitration. The parties may mutually agree in writing to extend the negotiation period.', ARRAY['informal resolution period','not exceed','thirty days','date','dispute notice','resolution','not achieved','period','either party','proceed','arbitration','mutually agree','writing','extend','negotiation period']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "30-day negotiation cap", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "30-day cap prevents indefinite delay while allowing meaningful negotiation. Extension by mutual agreement provides flexibility without unilateral delay."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The informal resolution requirement shall not apply to: (a) claims requiring immediate injunctive relief; (b) claims where the statute of limitations would expire during the resolution period; or (c) claims where delay would cause irreparable harm.', ARRAY['informal resolution requirement','not apply','claims','immediate injunctive relief','claims','statute of limitations','expire','resolution period','claims','delay','cause','irreparable harm']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Exceptions to informal resolution", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Exceptions for time-sensitive matters ensure negotiation requirement doesn''t prejudice urgent claims. Essential carveouts for practical operation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Participation in informal resolution shall not waive any party''s claims or defenses, toll any limitations period, or be admissible as evidence in any subsequent proceeding. All discussions shall be treated as compromise negotiations under applicable evidence rules.', ARRAY['participation','informal resolution','not waive','claims','defenses','toll','limitations period','not admissible','evidence','subsequent proceeding','discussions','treated','compromise negotiations','applicable evidence rules']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "No waiver and confidentiality", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "No waiver and evidence protection for settlement discussions encourages candid negotiation. Standard treatment as compromise negotiations protects both parties."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For disputes involving alleged breach of payment obligations, the parties shall engage a mutually agreed accounting firm to review the disputed calculations before proceeding to arbitration. The accountant''s determination shall be advisory and non-binding.', ARRAY['disputes','alleged breach','payment obligations','engage','mutually agreed','accounting firm','review','disputed calculations','before','proceeding','arbitration','accountant''s determination','advisory','non-binding']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Expert review for payment disputes", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Expert accounting review for payment disputes can narrow issues before arbitration. Advisory/non-binding status preserves parties'' rights while adding informed perspective."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notice of a dispute shall include: (a) a description of the dispute; (b) identification of the Agreement provisions at issue; (c) the remedy sought; and (d) the name and contact information of the executive designated to participate in resolution discussions.', ARRAY['notice','dispute','include','description','dispute','identification','Agreement provisions','issue','remedy sought','name','contact information','executive','designated','participate','resolution discussions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Dispute notice requirements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific notice requirements ensure receiving party has sufficient information to prepare for meaningful discussion. Executive identification enables prompt scheduling."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Failure to participate in good faith in the informal resolution process shall not bar the non-participating party from arbitration, but the arbitrator may consider such failure in allocating costs and fees.', ARRAY['failure','participate','good faith','informal resolution','not bar','non-participating party','arbitration','arbitrator','consider','failure','allocating costs','fees']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Cost consequences for non-participation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Non-participation doesn''t bar arbitration (preserving access to remedy) but has cost consequences. Incentivizes good faith participation without creating procedural trap."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Before arbitration, the parties shall engage in a three-tier escalation process: (1) project-level representatives (10 days); (2) department heads (10 days); (3) executives with settlement authority (10 days). Each tier must be exhausted before proceeding to the next.', ARRAY['before arbitration','three-tier','escalation process','project-level representatives','10 days','department heads','10 days','executives','settlement authority','10 days','tier','exhausted','proceeding','next']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Three-tier escalation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Three-tier escalation totaling 30 days may be acceptable if exceptions for urgent matters are preserved. Structured escalation can effectively resolve disputes without arbitration."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The parties shall attempt good faith resolution before arbitration. If the dispute is not resolved within 30 days, either party may request non-binding mediation with JAMS before proceeding to arbitration. Mediation shall not exceed 30 additional days.', ARRAY['attempt','good faith resolution','before arbitration','dispute','not resolved','30 days','either party','request','non-binding mediation','JAMS','before','proceeding','arbitration','mediation','not exceed','30 additional days']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Optional mediation step", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Optional mediation as additional step may be acceptable given voluntary nature. 30-day cap prevents indefinite delay. Either party can proceed to arbitration if mediation fails."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Informal resolution discussions shall be conducted in person at a mutually convenient location, or by video conference if in-person meeting is not feasible within the required timeframe. Telephone-only discussions shall not satisfy the requirement.', ARRAY['informal resolution discussions','conducted','in person','mutually convenient location','video conference','in-person meeting','not feasible','required timeframe','telephone-only discussions','not satisfy','requirement']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Meeting format requirements", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "In-person or video meeting requirement promotes substantive engagement. Telephone exclusion ensures more formal discussion. Flexibility for feasibility is practical."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The informal resolution period shall toll any applicable statutes of limitations and contractual deadlines. Upon conclusion of the informal period without resolution, such limitations shall resume from where they were tolled.', ARRAY['informal resolution period','toll','applicable statutes of limitations','contractual deadlines','conclusion','informal period','without resolution','limitations','resume','where','tolled']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Tolling during informal period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Tolling during informal resolution eliminates statute of limitations concern and encourages good faith negotiation without time pressure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'For creative disputes regarding the direction of the Program, the parties shall first seek resolution through their respective heads of creative development before invoking the dispute resolution process. Such creative discussion shall precede any formal dispute notice.', ARRAY['creative disputes','direction','Program','seek resolution','heads of creative development','before invoking','dispute resolution process','creative discussion','precede','formal dispute notice']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Creative-specific pre-escalation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Creative-specific preliminary step recognizes unique nature of creative disputes and appropriate internal contacts. Keeps creative disagreements at appropriate level before escalation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Any settlement reached during informal resolution shall be memorialized in a written settlement agreement signed by both parties. Oral agreements or agreements not reduced to writing shall not be binding.', ARRAY['settlement','during','informal resolution','memorialized','written settlement agreement','signed','both parties','oral agreements','agreements','not reduced to writing','not binding']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Written settlement requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Written settlement requirement ensures clarity on terms and prevents disputes about what was agreed. Standard practice for meaningful settlements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Before initiating arbitration, the parties shall engage in mandatory mediation with a JAMS mediator for a minimum of three (3) full-day sessions. Arbitration may not be commenced until mediation is complete.', ARRAY['before initiating','arbitration','mandatory mediation','JAMS mediator','minimum','three','full-day sessions','arbitration','not be commenced','until','mediation','complete']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Mandatory three-day mediation", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Mandatory three-day mediation is excessive prerequisite that delays access to binding resolution. Reasonable negotiation is appropriate; extended mandatory mediation is not."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The parties shall engage in informal resolution for a minimum of ninety (90) days before either party may initiate arbitration. This period may not be shortened by either party unilaterally.', ARRAY['engage','informal resolution','minimum','ninety days','before','either party','initiate arbitration','period','not be shortened','either party','unilaterally']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "90-day mandatory negotiation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "90-day mandatory negotiation is excessive delay to binding resolution. 30 days maximum is acceptable; 90 days prevents timely dispute resolution."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Informal resolution is mandatory for all disputes. If a party initiates arbitration without completing the informal resolution process, the arbitration shall be dismissed and the filing party shall pay the other party''s attorneys'' fees.', ARRAY['informal resolution','mandatory','all disputes','party','initiates arbitration','without completing','informal resolution process','arbitration','dismissed','filing party','pay','other party''s','attorneys'' fees']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Dismissal and fees for non-compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Dismissal and fee shifting for informal resolution non-compliance is excessive remedy that could trap claims. Non-compliance should affect costs, not bar access to arbitration."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The informal resolution requirement applies to all disputes including claims for injunctive relief. Amazon may not seek emergency relief from any court or arbitrator until the informal resolution period has been exhausted.', ARRAY['informal resolution requirement','applies','all disputes','including','claims','injunctive relief','Amazon','not seek','emergency relief','court','arbitrator','until','informal resolution period','exhausted']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "No exception for injunctive relief", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Applying informal resolution to injunctive relief claims defeats emergency relief purpose. Clear exception for injunctive and emergency relief is essential."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'During the informal resolution period, the parties shall maintain the status quo and continue all performance obligations. Neither party may suspend performance or exercise any termination rights during such period.', ARRAY['during','informal resolution period','maintain','status quo','continue','all performance obligations','neither party','suspend performance','exercise','termination rights','during','period']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Suspension of termination rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Suspending termination rights during informal resolution prevents Amazon from acting on material breach. Termination rights must remain available regardless of dispute status."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The informal resolution process shall be administered by an independent mediator selected by ProdCo and paid for by Amazon. The mediator shall have authority to issue non-binding recommendations that the parties must consider in good faith.', ARRAY['informal resolution process','administered','independent mediator','selected by ProdCo','paid for by Amazon','mediator','authority','issue','non-binding recommendations','parties','consider','good faith']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "ProdCo-selected, Amazon-funded mediator", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "ProdCo selection with Amazon payment is one-sided. If mediation is included, mediator selection should be mutual and costs shared."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may not assign, transfer, delegate, or otherwise dispose of this Agreement or any of its rights or obligations hereunder, whether by operation of law or otherwise, without Amazon''s prior written consent, which Amazon may withhold in its sole discretion. Any purported assignment without such consent shall be null and void.', ARRAY['ProdCo','not assign','transfer','delegate','dispose','Agreement','rights','obligations','operation of law','otherwise','Amazon''s prior written consent','withhold','sole discretion','purported assignment','without consent','null and void']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Standard ProdCo assignment restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive assignment restriction covering all transfer types including by operation of law. Sole discretion withholding and nullity for violations provides complete protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may freely assign, transfer, or delegate this Agreement or any of its rights or obligations hereunder, in whole or in part, to any affiliate, successor, or acquirer, or in connection with any merger, acquisition, reorganization, or sale of all or substantially all of Amazon''s assets, without ProdCo''s consent.', ARRAY['Amazon','freely assign','transfer','delegate','Agreement','rights','obligations','whole','part','affiliate','successor','acquirer','merger','acquisition','reorganization','sale','substantially all','assets','without','ProdCo''s consent']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Amazon free assignment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon free assignment right to affiliates, successors, and acquirers without consent is essential for corporate flexibility. Covers all common transaction types."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For purposes of this Section, a ''change of control'' of ProdCo shall be deemed an assignment requiring Amazon''s consent. ''Change of control'' means: (a) sale of more than 50% of voting securities; (b) merger or consolidation where ProdCo is not the surviving entity; or (c) sale of all or substantially all assets.', ARRAY['change of control','ProdCo','deemed','assignment','Amazon''s consent','change of control means','sale','50%','voting securities','merger','consolidation','not surviving entity','sale','substantially all assets']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Change of control as assignment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Change of control treated as assignment ensures Amazon can vet new ownership. Clear definition covering equity sale, M&A, and asset sale provides comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not grant any lien, security interest, or encumbrance on this Agreement, the Program, or any rights hereunder without Amazon''s prior written consent. Any such grant without consent shall be void and shall constitute a material breach.', ARRAY['ProdCo','not grant','lien','security interest','encumbrance','Agreement','Program','rights','Amazon''s prior written consent','grant','without consent','void','material breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "No encumbrance without consent", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Security interest restriction prevents ProdCo from encumbering Agreement or Program rights. Void grant plus material breach characterization provides strong protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement shall be binding upon and inure to the benefit of the parties and their respective permitted successors and assigns. Nothing in this Agreement shall confer upon any third party any rights or remedies.', ARRAY['Agreement','binding upon','inure','benefit','parties','permitted successors','assigns','nothing','Agreement','confer','third party','rights','remedies']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Binding on successors with no third-party rights", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard binding clause with ''permitted'' qualifier reinforcing assignment restrictions. No third-party beneficiary provision prevents claims by non-parties."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may assign its payment obligations to any creditworthy assignee without ProdCo''s consent. ProdCo may not look to Amazon for payment after such assignment if the assignee has expressly assumed such obligations in writing.', ARRAY['Amazon','assign','payment obligations','creditworthy assignee','without','ProdCo''s consent','ProdCo','not look to Amazon','payment','after assignment','assignee','expressly assumed','obligations','writing']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Payment obligation assignment with release", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Payment obligation assignment with creditworthiness requirement and written assumption provides appropriate protection for ProdCo while giving Amazon flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may license, sublicense, or authorize third parties to exercise any of Amazon''s rights under this Agreement, including exploitation rights, without such license constituting an assignment. Amazon shall remain responsible for any licensee''s compliance with applicable Agreement terms.', ARRAY['Amazon','license','sublicense','authorize','third parties','exercise','Amazon''s rights','Agreement','exploitation rights','without','license','constituting','assignment','Amazon','remain responsible','licensee''s compliance','Agreement terms']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Licensing versus assignment clarification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification that licensing is not assignment preserves Amazon''s exploitation flexibility. Continued Amazon responsibility for licensee compliance protects ProdCo."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may not assign without Amazon''s consent, which shall not be unreasonably withheld for assignments to ProdCo''s wholly-owned subsidiaries, provided such subsidiary assumes all obligations and ProdCo remains jointly and severally liable.', ARRAY['ProdCo','not assign','Amazon''s consent','not unreasonably withheld','assignments','wholly-owned subsidiaries','subsidiary assumes','all obligations','ProdCo remains','jointly','severally liable']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Subsidiary assignment with continued liability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited ''not unreasonably withheld'' standard for wholly-owned subsidiary assignments with continued ProdCo liability may be acceptable. Provides operational flexibility without releasing ProdCo."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Assignment restrictions apply. Amazon agrees to provide written notice to ProdCo within thirty (30) days of any assignment by Amazon, identifying the assignee and the scope of assignment. Failure to provide notice shall not invalidate the assignment.', ARRAY['assignment restrictions','apply','Amazon','provide','written notice','ProdCo','thirty days','assignment','Amazon','identifying','assignee','scope','assignment','failure','provide notice','not invalidate','assignment']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Assignment notice requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Post-assignment notice requirement is reasonable transparency measure. Non-invalidation for notice failure preserves Amazon''s assignment effectiveness."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo requires Amazon consent for assignment. If Amazon does not respond to a written assignment request within thirty (30) days, Amazon shall be deemed to have denied the request. ProdCo may resubmit with additional information.', ARRAY['ProdCo requires','Amazon consent','assignment','Amazon','not respond','written assignment request','thirty days','deemed','denied','request','resubmit','additional information']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Deemed denial for non-response", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Deemed denial for non-response (rather than deemed approval) preserves Amazon''s control. Resubmission option provides path forward for ProdCo."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may assign to affiliates. For purposes of this Agreement, ''affiliate'' means any entity that directly or indirectly controls, is controlled by, or is under common control with Amazon, where ''control'' means ownership of more than 50% of voting securities.', ARRAY['Amazon','assign','affiliates','affiliate means','entity','directly','indirectly','controls','controlled by','common control','Amazon','control means','ownership','50%','voting securities']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Affiliate definition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear affiliate definition with 50% control threshold provides certainty on scope of Amazon''s affiliate assignment right. Standard corporate definition."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon any permitted assignment by ProdCo, the assignee shall execute an assumption agreement in form reasonably acceptable to Amazon. ProdCo shall provide a copy of such executed agreement to Amazon within ten (10) days of assignment.', ARRAY['permitted assignment','ProdCo','assignee','execute','assumption agreement','form','reasonably acceptable','Amazon','provide','copy','executed agreement','Amazon','ten days','assignment']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Assumption agreement requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Assumption agreement requirement ensures assignee is bound. Reasonable form acceptability standard and documentation timeline are appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If Amazon assigns to an entity that is a direct competitor of ProdCo in the production business, Amazon shall provide ProdCo with reasonable advance notice. Assignment to a competitor shall not release Amazon from confidentiality obligations regarding ProdCo''s proprietary production methods.', ARRAY['Amazon assigns','entity','direct competitor','ProdCo','production business','provide','reasonable advance notice','assignment','competitor','not release','Amazon','confidentiality obligations','ProdCo''s proprietary','production methods']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Competitor assignment notice and confidentiality", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Competitor notice and maintained confidentiality for ProdCo proprietary methods addresses legitimate concern without restricting Amazon''s assignment right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Neither party may assign this Agreement without the other party''s prior written consent. Assignment restrictions apply equally to Amazon and ProdCo, with consent not to be unreasonably withheld by either party.', ARRAY['neither party','assign','Agreement','without','other party''s','prior written consent','assignment restrictions','apply equally','Amazon','ProdCo','consent','not unreasonably withheld','either party']::text[], '{"doc": "Counterparty_Proposal", "section": "Assignment", "note": "Mutual assignment restriction", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mutual assignment restrictions limiting Amazon''s assignment right is unacceptable. Amazon requires free assignment to affiliates, successors, and in transactions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may not assign this Agreement to any competitor of ProdCo without ProdCo''s prior written consent. ''Competitor'' means any entity engaged in film or television production.', ARRAY['Amazon','not assign','Agreement','competitor','ProdCo','without','ProdCo''s prior written consent','competitor means','entity','engaged','film','television production']::text[], '{"doc": "Counterparty_Proposal", "section": "Assignment", "note": "Competitor assignment restriction on Amazon", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Competitor restriction on Amazon''s assignment is unacceptable, especially with broad ''film or television production'' definition that would include most potential acquirers."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may freely assign this Agreement to any entity under common ownership or control with ProdCo without Amazon''s consent. Such assignment shall release ProdCo from all obligations under this Agreement.', ARRAY['ProdCo','freely assign','Agreement','entity','common ownership','control','ProdCo','without','Amazon''s consent','assignment','release ProdCo','all obligations']::text[], '{"doc": "Counterparty_Proposal", "section": "Assignment", "note": "ProdCo free assignment with release", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo free assignment with release from obligations is completely unacceptable. Amazon must consent to any ProdCo assignment, and ProdCo should remain liable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon assigns this Agreement, ProdCo may elect to terminate this Agreement upon sixty (60) days'' notice and receive a termination payment equal to the remaining Production Fee.', ARRAY['Amazon assigns','Agreement','ProdCo','elect','terminate','Agreement','sixty days','notice','receive','termination payment','remaining Production Fee']::text[], '{"doc": "Counterparty_Proposal", "section": "Assignment", "note": "ProdCo termination right upon Amazon assignment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination right with full payment upon Amazon assignment makes assignment economically prohibitive. Amazon must have unrestricted assignment without triggering termination."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Any assignment by Amazon shall require the assignee to assume all of Amazon''s obligations and to guarantee payment of all amounts that may become due to ProdCo. ProdCo shall have direct recourse against any assignee.', ARRAY['assignment','Amazon','require','assignee','assume','all','Amazon''s obligations','guarantee payment','amounts','due','ProdCo','direct recourse','against','assignee']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Guarantee requirement for Amazon assignment", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Guarantee requirement for all Amazon assignments is inappropriate given creditworthiness of Amazon and typical assignees. Direct recourse against assignees creates ongoing obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Change of control of ProdCo shall not be deemed an assignment and shall not require Amazon''s consent, as ProdCo''s corporate transactions are independent of its contractual obligations.', ARRAY['change of control','ProdCo','not deemed','assignment','not require','Amazon''s consent','ProdCo''s corporate transactions','independent','contractual obligations']::text[], '{"doc": "Counterparty_Proposal", "section": "Assignment", "note": "Change of control not an assignment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding change of control from assignment requirement allows ProdCo to be acquired by competitors or problematic parties without Amazon consent. Change of control must require consent."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All notices required or permitted under this Agreement shall be in writing and shall be delivered: (a) personally; (b) by certified mail, return receipt requested; (c) by nationally recognized overnight courier; or (d) by email to the addresses set forth on the signature page, with a copy by one of the foregoing methods.', ARRAY['notices','required','permitted','Agreement','in writing','delivered','personally','certified mail','return receipt','nationally recognized','overnight courier','email','addresses','signature page','copy','foregoing methods']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Standard notice methods", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Multiple acceptable notice methods with email requiring backup ensures both convenience and reliability. Standard commercial notice provision."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notices shall be deemed given: (a) when delivered personally; (b) three (3) business days after mailing by certified mail; (c) one (1) business day after deposit with overnight courier; or (d) when sent by email if confirmed by delivery by another method within two (2) business days.', ARRAY['notices','deemed given','delivered personally','three business days','mailing','certified mail','one business day','deposit','overnight courier','sent','email','confirmed','delivery','another method','two business days']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Notice effectiveness timing", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear deemed delivery timing for each method provides certainty. Email requiring confirmation addresses reliability concerns while permitting electronic initial delivery."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Either party may change its notice address by providing written notice to the other party in accordance with this Section. Address changes shall be effective upon receipt of such notice.', ARRAY['either party','change','notice address','providing','written notice','other party','accordance','Section','address changes','effective','receipt','notice']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Address change procedure", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard address change provision with effectiveness upon receipt. Allows parties to update contact information as needed."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the foregoing, routine operational communications, including scheduling, production updates, and administrative matters, may be made by email without backup delivery. Formal notices regarding breach, termination, dispute, or assignment shall comply with the formal notice requirements.', ARRAY['notwithstanding','routine operational communications','scheduling','production updates','administrative matters','email','without backup','formal notices','breach','termination','dispute','assignment','comply','formal notice requirements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Operational versus formal notice distinction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Practical distinction between operational and formal notices. Email suffices for day-to-day matters; formal requirements for significant legal notices."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notices to Amazon shall be sent to the Legal Department at the address specified on the signature page, with a copy to the Amazon business contact identified therein. Notices to ProdCo shall be sent to the address specified on the signature page, with a copy to ProdCo''s counsel if identified.', ARRAY['notices','Amazon','sent','Legal Department','address','signature page','copy','Amazon business contact','identified','notices','ProdCo','sent','address','signature page','copy','ProdCo''s counsel','identified']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Specific recipients with copies", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear identification of notice recipients with copy requirements ensures notices reach appropriate parties. Legal Department copy for Amazon ensures proper handling."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Any notice delivered to an incorrect address but which actually reaches the intended recipient shall be deemed effective upon actual receipt. Parties shall use good faith efforts to bring notice errors to the other party''s attention promptly.', ARRAY['notice','delivered','incorrect address','actually reaches','intended recipient','deemed effective','actual receipt','good faith efforts','notice errors','other party''s attention','promptly']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Actual receipt effectiveness", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Actual receipt provision ensures substance over form. Good faith error notification promotes cooperative relationship without formal requirements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Refusal to accept delivery of a notice, or failure to maintain a valid notice address, shall not defeat the effectiveness of a notice properly sent to the last known address. In such cases, notice shall be deemed given when delivery is attempted.', ARRAY['refusal','accept delivery','notice','failure','maintain','valid notice address','not defeat','effectiveness','notice','properly sent','last known address','notice','deemed given','delivery','attempted']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Refusal and failed delivery", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Protection against delivery avoidance tactics. Deemed delivery upon attempted delivery to last known address prevents parties from evading notices."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Notices may be delivered by email alone if both parties have agreed in writing to accept email as the sole method of delivery for specified notice types. Such agreement may be revoked by either party upon ten (10) days'' written notice.', ARRAY['notices','delivered','email alone','both parties','agreed','writing','accept email','sole method','specified notice types','agreement','revoked','either party','ten days','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Email-only option by agreement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Optional email-only by mutual agreement provides flexibility while requiring affirmative consent. Revocation right preserves fall-back to formal methods."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'For time-sensitive notices where overnight courier would not achieve delivery within necessary timeframes, email notice shall be effective immediately upon transmission if the sender receives a delivery confirmation and the recipient does not object within two (2) hours.', ARRAY['time-sensitive notices','overnight courier','not achieve delivery','necessary timeframes','email notice','effective immediately','transmission','sender receives','delivery confirmation','recipient','not object','two hours']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Time-sensitive email exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Time-sensitive email exception with delivery confirmation and non-objection requirement addresses practical urgencies while maintaining some verification."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Notices regarding creative matters, production schedules, and delivery dates may be communicated through Amazon''s designated production management system. Communications through such system shall be deemed written notice for purposes of this Agreement.', ARRAY['notices','creative matters','production schedules','delivery dates','communicated','Amazon''s designated','production management system','communications','system','deemed','written notice','purposes','Agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Production system communications", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Production management system for operational notices streamlines communications. Limited to production matters, not formal legal notices."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain a notice address within the continental United States for purposes of receiving notices. If ProdCo is located outside the U.S., ProdCo shall designate a U.S. agent for service of notices.', ARRAY['ProdCo','maintain','notice address','continental United States','receiving notices','ProdCo','located outside','U.S.','designate','U.S. agent','service','notices']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "U.S. address requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "U.S. address requirement for non-U.S. ProdCos simplifies notice delivery and ensures reliable receipt. Agent designation is standard for international parties."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'In the event of a dispute, notices related to such dispute shall be sent to both the party''s general notice address and to any counsel who has appeared for such party in connection with the dispute.', ARRAY['event','dispute','notices','related','dispute','sent','party''s general notice address','counsel','appeared','party','connection','dispute']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Dispute notice to counsel", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Copy to appearing counsel for dispute-related notices ensures legal team awareness. Addresses practical reality that counsel often handles dispute communications."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Either party may designate additional notice recipients (not to exceed three (3) per party) by written notice. Notice to all designated recipients shall be required for termination and breach notices only.', ARRAY['either party','designate','additional notice recipients','not exceed','three','per party','written notice','notice','all designated recipients','required','termination','breach notices','only']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Additional recipients for key notices", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited additional recipients with cap (three per party) for termination and breach notices is reasonable. Ensures critical notices reach key stakeholders."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Notices shall be effective only upon actual receipt by an officer or director of the receiving party. Delivery to any other person or address shall not constitute effective notice.', ARRAY['notices','effective','only','actual receipt','officer','director','receiving party','delivery','other person','address','not constitute','effective notice']::text[], '{"doc": "Counterparty_Proposal", "section": "Notices", "note": "Officer/director actual receipt required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Officer/director actual receipt requirement makes notice delivery nearly impossible to confirm and allows avoidance. Standard deemed delivery rules are required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Notices must be delivered in person to a designated representative during business hours at the party''s principal place of business. Mail and courier delivery shall not constitute effective notice.', ARRAY['notices','delivered','in person','designated representative','business hours','principal place of business','mail','courier delivery','not constitute','effective notice']::text[], '{"doc": "Counterparty_Proposal", "section": "Notices", "note": "In-person only delivery", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "In-person only delivery is impractical and could enable notice avoidance. Standard mail, courier, and electronic methods must be acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Notices from Amazon to ProdCo shall be effective upon delivery. Notices from ProdCo to Amazon shall not be effective unless and until acknowledged in writing by Amazon''s Legal Department.', ARRAY['notices','Amazon','ProdCo','effective','delivery','notices','ProdCo','Amazon','not effective','unless','until','acknowledged','writing','Amazon''s Legal Department']::text[], '{"doc": "Counterparty_Proposal", "section": "Notices", "note": "Asymmetric acknowledgment requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring Amazon acknowledgment for ProdCo notice effectiveness creates massive asymmetry. Amazon could avoid notices indefinitely. Both parties'' notices must have equivalent effectiveness."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Notices shall be sent by email only to the email addresses specified herein. No other form of delivery shall be required or permitted. Email shall be deemed delivered when sent regardless of receipt.', ARRAY['notices','sent','email only','email addresses','specified','no other form','delivery','required','permitted','email','deemed delivered','when sent','regardless','receipt']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Email-only with sent equals delivered", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Email-only without backup and ''sent equals delivered'' regardless of receipt creates unreliable notice mechanism. Formal notices require more reliable delivery methods."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may provide notice to Amazon by posting on ProdCo''s website and providing a link to such posting via email. Amazon shall be responsible for monitoring ProdCo''s website for notices.', ARRAY['ProdCo','provide notice','Amazon','posting','ProdCo''s website','providing','link','posting','email','Amazon','responsible','monitoring','ProdCo''s website','notices']::text[], '{"doc": "Counterparty_Proposal", "section": "Notices", "note": "Website posting notice", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Website posting as notice method is completely unacceptable. Notices must be delivered directly to recipients, not posted for them to find."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Any notice not objected to within five (5) business days of delivery shall be deemed accepted and binding on the receiving party. Failure to object shall constitute agreement to the contents of the notice.', ARRAY['notice','not objected to','five business days','delivery','deemed accepted','binding','receiving party','failure','object','constitute','agreement','contents','notice']::text[], '{"doc": "Counterparty_Proposal", "section": "Notices", "note": "Deemed acceptance of notice contents", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deemed acceptance of notice contents is inappropriate. Notices communicate information; they don''t require response. This would create obligations based on non-response to any communication."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Neither party shall be liable for failure to perform its obligations (other than payment obligations) to the extent such failure results from a Force Majeure Event, provided that the affected party: (a) promptly notifies the other party; (b) uses reasonable efforts to mitigate the effects; and (c) resumes performance as soon as reasonably practicable.', ARRAY['neither party','liable','failure','perform','obligations','other than','payment obligations','extent','failure results','Force Majeure Event','affected party','promptly notifies','other party','reasonable efforts','mitigate','resumes performance','reasonably practicable']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "Standard FM clause with carveouts", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard force majeure provision with payment obligation exclusion and mitigation requirements. Reasonableness standard for resumption provides appropriate flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, '''Force Majeure Event'' means an event beyond a party''s reasonable control, including: acts of God; natural disasters; war, terrorism, or civil unrest; government actions or restrictions; labor strikes (except those involving only the affected party''s employees); and epidemics or pandemics.', ARRAY['Force Majeure Event','event','beyond','party''s reasonable control','acts of God','natural disasters','war','terrorism','civil unrest','government actions','restrictions','labor strikes','except','affected party''s employees','epidemics','pandemics']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "FM definition with enumeration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive FM definition with enumerated events and reasonable control standard. Strike exception for party''s own employees prevents abuse. Pandemic inclusion is post-COVID standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Force Majeure Events shall not include: (a) changes in economic or market conditions; (b) fluctuations in currency exchange rates; (c) financial difficulties or insolvency; (d) changes in law that do not make performance illegal; or (e) events that were reasonably foreseeable at the time of contracting.', ARRAY['Force Majeure Events','not include','changes','economic','market conditions','fluctuations','currency exchange rates','financial difficulties','insolvency','changes in law','not make','performance illegal','events','reasonably foreseeable','time of contracting']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "FM exclusions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard exclusions preventing FM claims for economic hardship, financial problems, and foreseeable events. Ensures FM applies only to genuinely unforeseeable external events."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If a Force Majeure Event prevents performance for more than ninety (90) consecutive days, either party may terminate this Agreement upon thirty (30) days'' written notice. Upon such termination, Amazon shall pay for work performed through the termination date; no other amounts shall be due.', ARRAY['Force Majeure Event','prevents performance','ninety','consecutive days','either party','terminate','Agreement','thirty days','written notice','termination','Amazon','pay','work performed','termination date','no other amounts','due']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "Extended FM termination right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Termination right after extended FM (90 days) provides exit for prolonged impossibility. Payment for work performed is fair; no additional payments limits exposure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'During a Force Majeure Event affecting production, Amazon may, in its sole discretion: (a) suspend production and payments until the event concludes; (b) modify the production schedule; (c) relocate production; or (d) terminate the affected production and proceed with alternative arrangements.', ARRAY['during','Force Majeure Event','affecting production','Amazon','sole discretion','suspend','production','payments','event concludes','modify','production schedule','relocate production','terminate','affected production','proceed','alternative arrangements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "Amazon FM response options", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Multiple response options for Amazon during production FM provides flexibility. Sole discretion ensures Amazon controls response to events affecting its content."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Force majeure shall not excuse ProdCo from its obligations regarding: (a) ownership and grant of rights to Amazon; (b) indemnification obligations; (c) confidentiality obligations; (d) representations and warranties regarding completed work; or (e) cooperation with Amazon''s alternative arrangements.', ARRAY['force majeure','not excuse','ProdCo','obligations','ownership','grant of rights','Amazon','indemnification','confidentiality','representations','warranties','completed work','cooperation','Amazon''s alternative arrangements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "Obligations not excused by FM", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Carving out key obligations from FM excuse ensures critical protections remain in place. Rights, indemnification, and confidentiality must not be suspended."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain production insurance covering production interruption, cast coverage, and related force majeure risks. ProdCo shall use insurance proceeds first to resume production; any excess proceeds shall be applied as directed by Amazon.', ARRAY['ProdCo','maintain','production insurance','covering','production interruption','cast coverage','force majeure risks','use insurance proceeds','first','resume production','excess proceeds','applied','directed','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "FM insurance requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "FM insurance requirement with proceeds application hierarchy protects against production interruption losses. Amazon direction on excess ensures proper allocation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Force majeure applies. If a FM Event affects a Key Person (death, incapacity, unavailability), Amazon may elect to: (a) recast the role; (b) modify the Program; (c) suspend pending replacement; or (d) terminate. The parties shall consult in good faith on the appropriate response.', ARRAY['force majeure','applies','FM Event','affects','Key Person','death','incapacity','unavailability','Amazon','elect','recast','role','modify','Program','suspend','pending replacement','terminate','consult','good faith','appropriate response']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "Key Person FM with consultation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Key Person FM handling with consultation is reasonable. Amazon retains decision authority but consultation provides ProdCo input on matters like recasting."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If force majeure affects only a portion of the production, performance of unaffected portions shall continue. The parties shall cooperate to modify the production schedule to accommodate both continued and suspended portions.', ARRAY['force majeure','affects','only','portion','production','performance','unaffected portions','continue','cooperate','modify','production schedule','accommodate','continued','suspended portions']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "Partial FM with continued performance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Continued performance of unaffected portions is practical approach. Cooperation on schedule modifications addresses real-world partial disruption scenarios."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Force majeure relief is available. The affected party shall provide: (a) written notice within 48 hours of becoming aware of the FM Event; (b) regular updates on status and expected resolution; and (c) documented evidence of the FM Event and its effects upon request.', ARRAY['force majeure relief','available','affected party','provide','written notice','48 hours','becoming aware','FM Event','regular updates','status','expected resolution','documented evidence','FM Event','effects','request']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "FM notice and documentation requirements", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific notice timeline, update requirement, and documentation obligation are reasonable procedural requirements for FM claims."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'During an FM Event affecting production, Amazon shall have the option, but not the obligation, to provide resources or assistance to help mitigate the FM Event''s effects. Any such assistance shall not affect the allocation of risk or expense under this Agreement.', ARRAY['during','FM Event','affecting production','Amazon','option','not obligation','provide','resources','assistance','mitigate','FM Event''s effects','assistance','not affect','allocation','risk','expense','Agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "Optional Amazon FM assistance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Optional Amazon assistance without obligation or risk reallocation provides flexibility to help while preserving Agreement structure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Industry-wide labor strikes affecting the film and television industry generally shall be treated as Force Majeure Events. Strikes limited to ProdCo''s employees or specific to ProdCo''s production shall not qualify as Force Majeure.', ARRAY['industry-wide','labor strikes','affecting','film','television industry','generally','Force Majeure Events','strikes','limited','ProdCo''s employees','specific','ProdCo''s production','not qualify','Force Majeure']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "Strike FM clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Industry-wide versus ProdCo-specific strike distinction is reasonable. General industry strikes are beyond control; ProdCo-specific labor issues are not FM-qualifying."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If Amazon terminates due to extended FM, and subsequently produces a Program substantially based on the terminated Program''s elements within three (3) years, ProdCo shall receive any applicable separation payment per Guild requirements.', ARRAY['Amazon terminates','extended FM','subsequently produces','Program','substantially based','terminated Program''s elements','three years','ProdCo','receive','separation payment','Guild requirements']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "FM termination with subsequent production credit", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Guild separation payment for subsequent production based on terminated elements is reasonable compliance with industry standards."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Force majeure shall excuse ProdCo from all obligations during the FM Event, including payment obligations owed by ProdCo to Amazon and delivery obligations. Amazon shall continue making payments to ProdCo during FM Events regardless of production status.', ARRAY['force majeure','excuse','ProdCo','all obligations','FM Event','including','payment obligations','owed','ProdCo','Amazon','delivery obligations','Amazon','continue','making payments','ProdCo','FM Events','regardless','production status']::text[], '{"doc": "Counterparty_Proposal", "section": "Force Majeure", "note": "Asymmetric FM obligations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Asymmetric FM treatment requiring Amazon to continue payments while ProdCo is excused from all obligations is completely unacceptable. FM relief must be reciprocal."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Force Majeure Events include any event that ProdCo, in its reasonable judgment, determines makes performance commercially impracticable or significantly more expensive than anticipated.', ARRAY['Force Majeure Events','include','event','ProdCo','reasonable judgment','determines','performance','commercially impracticable','significantly more expensive','anticipated']::text[], '{"doc": "Counterparty_Proposal", "section": "Force Majeure", "note": "ProdCo-determined commercial impracticability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo-determined commercial impracticability as FM is unacceptable. FM must be objective external events, not cost overruns or commercial difficulties."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If an FM Event continues for more than thirty (30) days, ProdCo may terminate this Agreement and receive the full remaining Production Fee as if production had been completed.', ARRAY['FM Event','continues','thirty days','ProdCo','terminate','Agreement','receive','full remaining Production Fee','production completed']::text[], '{"doc": "Counterparty_Proposal", "section": "Force Majeure", "note": "ProdCo FM termination with full payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo termination right with full payment after only 30 days of FM is completely unacceptable. Amazon should have FM termination rights; payment should be for work performed only."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Force majeure shall include any shortage of personnel, equipment, or facilities needed for production, regardless of whether such shortage is specific to ProdCo or industry-wide.', ARRAY['force majeure','include','shortage','personnel','equipment','facilities','needed','production','regardless','shortage','specific','ProdCo','industry-wide']::text[], '{"doc": "Counterparty_Proposal", "section": "Force Majeure", "note": "Resource shortage as FM", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Resource shortage as FM regardless of cause would excuse ProdCo for poor planning or resource management. FM must be external unforeseeable events, not resource allocation issues."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon waives any right to terminate for force majeure. During any FM Event, the Agreement shall be suspended but Amazon''s payment obligations shall continue, and the Agreement shall resume upon conclusion of the FM Event without any adjustment.', ARRAY['Amazon waives','right to terminate','force majeure','FM Event','Agreement','suspended','Amazon''s payment obligations','continue','Agreement','resume','conclusion','FM Event','without','adjustment']::text[], '{"doc": "Counterparty_Proposal", "section": "Force Majeure", "note": "No Amazon FM termination with continued payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Waiving Amazon''s FM termination right while requiring continued payment is completely one-sided. Amazon must retain FM termination rights, especially for extended events."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Pandemics and epidemics shall not constitute Force Majeure Events regardless of their severity, as such events are now foreseeable in the post-COVID environment.', ARRAY['pandemics','epidemics','not constitute','Force Majeure Events','regardless','severity','events','foreseeable','post-COVID environment']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "Pandemic exclusion from FM", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Categorical pandemic exclusion regardless of severity is too broad. Future pandemics may still be FM-qualifying events depending on circumstances and government response."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement, together with all exhibits and schedules hereto, constitutes the entire agreement between the parties with respect to the subject matter hereof and supersedes all prior and contemporaneous agreements, understandings, negotiations, and discussions, whether oral or written.', ARRAY['Agreement','exhibits','schedules','constitutes','entire agreement','parties','subject matter','supersedes','prior','contemporaneous','agreements','understandings','negotiations','discussions','oral','written']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Standard entire agreement clause", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard entire agreement clause with merger of prior discussions. Inclusion of exhibits and schedules ensures complete integration."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No amendment, modification, or supplement to this Agreement shall be valid or binding unless made in writing and signed by authorized representatives of both parties. Email and other electronic communications shall not constitute a writing for this purpose.', ARRAY['no amendment','modification','supplement','Agreement','valid','binding','unless','writing','signed','authorized representatives','both parties','email','electronic communications','not constitute','writing']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Written amendment requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Strict written amendment requirement with signature prevents informal modification claims. Email exclusion ensures formal process for changes."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No waiver of any provision of this Agreement shall be effective unless in writing and signed by the waiving party. No waiver shall operate as a waiver of any other provision, and no single waiver shall constitute a continuing or subsequent waiver.', ARRAY['no waiver','provision','Agreement','effective','unless','writing','signed','waiving party','waiver','not operate','waiver','other provision','single waiver','not constitute','continuing','subsequent waiver']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Waiver requirements and limitations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Written waiver requirement prevents implied waiver claims. Limitations on waiver scope and duration protect against waiver creep."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The failure of either party to enforce any provision of this Agreement shall not constitute a waiver of such provision or the right to enforce it at a later time. Delay in exercising any right shall not constitute waiver of such right.', ARRAY['failure','either party','enforce','provision','Agreement','not constitute','waiver','provision','right to enforce','later time','delay','exercising','right','not constitute','waiver']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Non-waiver for non-enforcement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Protects against waiver by inaction. Delay protection ensures parties can enforce rights even if not immediately asserted."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Each party acknowledges that it has not relied on any statement, representation, or warranty not expressly set forth in this Agreement. No party shall have any claim against the other for innocent or negligent misrepresentation based on any statement not contained herein.', ARRAY['acknowledges','not relied','statement','representation','warranty','not expressly set forth','Agreement','no party','claim','other','innocent','negligent misrepresentation','statement','not contained']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Non-reliance acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Non-reliance acknowledgment prevents claims based on pre-contractual statements. Limits misrepresentation claims to fraudulent misrepresentation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement may be executed in counterparts, each of which shall be deemed an original, and all of which together shall constitute one and the same instrument. Electronic signatures and PDF copies shall have the same legal effect as original signatures and documents.', ARRAY['Agreement','executed','counterparts','deemed','original','together','constitute','same instrument','electronic signatures','PDF copies','same legal effect','original signatures','documents']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Counterparts and electronic signatures", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Counterparts clause facilitates execution. Electronic signature and PDF recognition is essential for modern transactions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The terms of this Agreement shall control over any conflicting or additional terms in any purchase order, invoice, acknowledgment, or other document. No terms proposed by ProdCo in any other document shall be binding unless expressly agreed in writing by Amazon.', ARRAY['terms','Agreement','control','conflicting','additional terms','purchase order','invoice','acknowledgment','document','terms','proposed','ProdCo','other document','not binding','unless','expressly agreed','writing','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "No battle of forms", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Prevailing terms clause prevents ''battle of the forms'' issues. Agreement terms control over any conflicting terms in other documents."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'This Agreement is the entire agreement. The parties agree that Amazon''s standard operating procedures and production guidelines, as updated from time to time and provided to ProdCo, are incorporated by reference and shall be binding without formal amendment.', ARRAY['Agreement','entire agreement','Amazon''s standard operating procedures','production guidelines','updated','time to time','provided','ProdCo','incorporated by reference','binding','without','formal amendment']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Incorporated guidelines without amendment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Incorporation of Amazon''s SOPs and guidelines allows operational flexibility. Binding without formal amendment may be acceptable if procedures are administrative only."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amendments require writing signed by both parties. Notwithstanding, amendments to delivery schedules and production budgets may be made by email exchange between authorized production contacts, provided such amendments do not affect material economic terms.', ARRAY['amendments','require','writing','signed','both parties','notwithstanding','amendments','delivery schedules','production budgets','email exchange','authorized production contacts','not affect','material economic terms']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Email amendment for operational matters", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Email amendment exception for schedules and budgets is operationally practical. Material economic terms carveout preserves formal process for significant changes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'No waiver shall be effective unless in writing. The parties acknowledge that a course of dealing between them shall not constitute waiver or modification of Agreement terms, even if such course of dealing has continued for an extended period.', ARRAY['no waiver','effective','unless','writing','acknowledge','course of dealing','not constitute','waiver','modification','Agreement terms','course of dealing','continued','extended period']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Course of dealing exclusion", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Course of dealing exclusion prevents argument that practices modified the Agreement. Important for long-term relationships with evolving operations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'This is the entire agreement. The parties may establish a formal amendment process through a written protocol identifying authorized amendment signatories, required approvals, and documentation requirements. Such protocol shall itself require formal execution.', ARRAY['entire agreement','establish','formal amendment process','written protocol','identifying','authorized amendment signatories','required approvals','documentation requirements','protocol','require','formal execution']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Amendment protocol option", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Option to establish amendment protocol provides flexibility while requiring formal execution of the protocol itself. Useful for complex ongoing relationships."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Written amendment is required. For purposes of this provision, an amendment signed by Amazon''s VP of Content or above shall be binding on Amazon. ProdCo shall not be bound by amendments signed below the level of ProdCo''s CEO or authorized designee.', ARRAY['written amendment','required','amendment','signed','Amazon''s VP of Content','above','binding','Amazon','ProdCo','not bound','amendments','signed','below','ProdCo''s CEO','authorized designee']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Signing authority specification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Specification of signing authority levels provides clarity on who can bind each party. May be useful for larger organizations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The entire agreement clause applies. For clarification, the following prior agreements remain in effect and are not superseded: [list specific NDAs, development agreements, or other surviving agreements].', ARRAY['entire agreement','applies','clarification','prior agreements','remain in effect','not superseded','list','specific NDAs','development agreements','surviving agreements']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Carveout for specific prior agreements", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for specifically listed prior agreements is acceptable when needed to preserve valid prior arrangements. Must be specifically enumerated."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This Agreement may be amended by either party providing written notice of the amendment to the other party. If the other party does not object within thirty (30) days, the amendment shall become effective.', ARRAY['Agreement','amended','either party','written notice','amendment','other party','not object','thirty days','amendment','become effective']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Unilateral amendment with deemed consent", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Unilateral amendment with deemed consent for non-objection allows either party to modify the Agreement without actual agreement. Mutual signature is required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Oral amendments shall be binding if made by authorized representatives during production meetings and confirmed in meeting minutes distributed within five (5) business days.', ARRAY['oral amendments','binding','authorized representatives','production meetings','confirmed','meeting minutes','distributed','five business days']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Oral amendments via meeting minutes", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Oral amendments with meeting minute confirmation is too informal for binding contract changes. Signed written amendments are required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This Agreement is the entire agreement. However, any written communication from ProdCo setting forth additional terms or conditions shall be deemed an amendment if Amazon does not expressly reject such terms within ten (10) business days.', ARRAY['Agreement','entire agreement','written communication','ProdCo','additional terms','conditions','deemed','amendment','Amazon','not expressly reject','terms','ten business days']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "ProdCo deemed amendment by non-rejection", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo one-sided deemed amendment through non-rejection would allow ProdCo to modify Agreement unilaterally. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The entire agreement clause shall not apply to limit ProdCo''s right to recover damages based on pre-contractual representations made by Amazon during negotiations, regardless of whether such representations are reflected in this Agreement.', ARRAY['entire agreement','not apply','limit','ProdCo''s right','recover damages','pre-contractual representations','Amazon','negotiations','regardless','representations','reflected','Agreement']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Pre-contractual representation carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Carving out pre-contractual representations defeats the entire agreement clause''s purpose. Creates liability for statements outside the contract."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s failure to enforce any provision on three (3) or more occasions shall constitute a permanent waiver of such provision. ProdCo may rely on such waiver as a modification of the Agreement.', ARRAY['Amazon''s failure','enforce','provision','three','more occasions','constitute','permanent waiver','provision','ProdCo','rely','waiver','modification','Agreement']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Automatic waiver after repeated non-enforcement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Automatic permanent waiver after three non-enforcements would eliminate rights through inaction. No waiver without express written waiver."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Industry custom and practice shall supplement this Agreement. Where this Agreement is silent, industry customs applicable to productions of this type shall govern the parties'' relationship.', ARRAY['industry custom','practice','supplement','Agreement','Agreement','silent','industry customs','applicable','productions','type','govern','parties'' relationship']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Industry custom gap-filler", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Industry custom gap-filler introduces undefined and potentially disputed terms. The Agreement must be complete; gaps should not be filled by custom."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If any provision of this Agreement is held to be invalid, illegal, or unenforceable, such provision shall be modified to the minimum extent necessary to make it valid and enforceable, or if modification is not possible, such provision shall be severed, and the remaining provisions shall remain in full force and effect.', ARRAY['provision','Agreement','held','invalid','illegal','unenforceable','modified','minimum extent','necessary','valid','enforceable','modification','not possible','severed','remaining provisions','full force and effect']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Standard severability with modification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard severability clause with modification preference before severance. Preserves Agreement validity while addressing invalid provisions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Severability shall not apply if the invalid provision is so fundamental to this Agreement that the parties would not have entered into the Agreement without it. In such case, the entire Agreement shall be voidable at the option of either party.', ARRAY['severability','not apply','invalid provision','fundamental','Agreement','parties','not have entered','Agreement','without','entire Agreement','voidable','option','either party']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Fundamental provision exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Fundamental provision exception recognizes that some provisions are essential to the bargain. Voidability option provides appropriate exit when core terms fail."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The following provisions shall survive expiration or termination of this Agreement for any reason: ownership and grant of rights; indemnification; confidentiality; limitation of liability; representations and warranties; and any other provision that by its nature or express terms should survive.', ARRAY['provisions','survive','expiration','termination','Agreement','any reason','ownership','grant of rights','indemnification','confidentiality','limitation of liability','representations','warranties','provision','nature','express terms','survive']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Enumerated survival provisions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of surviving provisions ensures critical protections continue post-termination. Catch-all for nature-based survival addresses unenumerated provisions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Survival of obligations shall not be affected by whether termination was for cause, for convenience, by expiration, or by operation of law. Surviving obligations shall continue for the periods specified herein or, if no period is specified, indefinitely.', ARRAY['survival','obligations','not affected','termination','for cause','for convenience','expiration','operation of law','surviving obligations','continue','periods specified','no period','specified','indefinitely']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Survival regardless of termination reason", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Universal survival regardless of termination circumstances ensures protections aren''t lost based on termination type. Indefinite default for unspecified periods provides maximum protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification obligations shall survive in perpetuity with respect to any claim arising from the Program or Materials delivered hereunder. This survival applies regardless of any termination, expiration, or invalidity of any other provision.', ARRAY['ProdCo''s indemnification','survive','perpetuity','claim','arising from','Program','Materials','delivered','survival applies','regardless','termination','expiration','invalidity','other provision']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Perpetual indemnification survival", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Perpetual indemnification survival reflects that content claims can arise indefinitely after creation. Survival independent of other provisions ensures this critical protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s ownership of the Program and all rights therein shall survive any termination, expiration, or invalidity of this Agreement. Such ownership shall vest and remain with Amazon regardless of any claim by ProdCo arising from the Agreement''s termination.', ARRAY['Amazon''s ownership','Program','rights','survive','termination','expiration','invalidity','Agreement','ownership','vest','remain','Amazon','regardless','claim','ProdCo','arising from','Agreement''s termination']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Ownership survival", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Ownership survival ensures Amazon''s rights persist regardless of Agreement status. Critical protection given Amazon''s investment in content."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If any court or arbitrator reforms or limits any provision affecting Amazon''s rights, Amazon may, at its option, terminate this Agreement upon notice without liability, except for payment for work performed through the termination date.', ARRAY['court','arbitrator','reforms','limits','provision','affecting','Amazon''s rights','Amazon','option','terminate','Agreement','notice','without liability','except','payment','work performed','termination date']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Termination right for reformed provisions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Termination right when provisions affecting Amazon''s rights are reformed allows exit from unfavorably modified Agreement. Payment for work performed is fair."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Severability applies. If severance of a provision would materially alter the economic bargain, the parties shall negotiate in good faith to restore the economic balance through amendment. If no agreement is reached within thirty (30) days, either party may terminate.', ARRAY['severability','applies','severance','provision','materially alter','economic bargain','negotiate','good faith','restore','economic balance','amendment','no agreement','thirty days','either party','terminate']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Renegotiation for material severance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Renegotiation obligation for material economic impact with termination fallback is reasonable approach to significant severance situations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Surviving provisions shall remain effective. For purposes of clarity, the following provisions shall expressly survive: Sections [X] (Ownership), [Y] (Indemnification), [Z] (Confidentiality), [AA] (Limitation of Liability), [BB] (Dispute Resolution), and [CC] (Representations).', ARRAY['surviving provisions','remain effective','clarity','provisions','expressly survive','Sections','Ownership','Indemnification','Confidentiality','Limitation of Liability','Dispute Resolution','Representations']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Section-specific survival enumeration", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Section-specific enumeration provides clarity on exactly which provisions survive. Cross-referenced to specific sections for precision."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Confidentiality obligations shall survive for five (5) years after termination. Indemnification obligations shall survive for seven (7) years after termination. Ownership provisions shall survive indefinitely.', ARRAY['confidentiality obligations','survive','five years','after termination','indemnification obligations','survive','seven years','after termination','ownership provisions','survive','indefinitely']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Tiered survival periods", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Tiered survival periods by provision type may be acceptable. Five years for confidentiality is minimum; seven for indemnification addresses claim discovery periods; indefinite ownership is essential."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The rights and obligations of the parties with respect to completed episodes and deliverables shall survive termination. Rights and obligations with respect to uncommenced work shall terminate as of the termination date.', ARRAY['rights','obligations','parties','completed episodes','deliverables','survive','termination','rights','obligations','uncommenced work','terminate','termination date']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Completed versus uncommenced work distinction", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Distinction between completed and uncommenced work is practical approach. Completed work rights survive; uncommenced work obligations appropriately terminate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If any provision is held invalid in a particular jurisdiction, such invalidity shall not affect the validity of such provision in any other jurisdiction. Provisions shall be severed on a jurisdiction-by-jurisdiction basis to the extent possible.', ARRAY['provision','held invalid','particular jurisdiction','invalidity','not affect','validity','provision','other jurisdiction','provisions','severed','jurisdiction-by-jurisdiction basis','extent possible']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Jurisdiction-specific severability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Jurisdiction-specific severability prevents invalidity in one jurisdiction from affecting enforceability elsewhere. Practical for international productions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Survival provisions shall bind successors and assigns. If Amazon assigns this Agreement, the assignee shall have the benefit of all surviving provisions, and ProdCo''s surviving obligations shall extend to such assignee.', ARRAY['survival provisions','bind','successors','assigns','Amazon assigns','Agreement','assignee','benefit','surviving provisions','ProdCo''s surviving obligations','extend','assignee']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Survival extends to assignees", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extension of survival to assignees ensures continuing protections transfer with the Agreement. Essential for meaningful assignment rights."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If any provision is found invalid, the entire Agreement shall be void and unenforceable, and ProdCo shall have no further obligations to Amazon, including with respect to rights previously granted.', ARRAY['provision','found invalid','entire Agreement','void','unenforceable','ProdCo','no further obligations','Amazon','including','rights','previously granted']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Whole Agreement void for any invalidity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Voiding entire Agreement for any provision invalidity is completely unacceptable. Would allow ProdCo to escape obligations if any minor provision fails."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification obligations shall not survive termination for more than two (2) years. After such period, ProdCo shall have no further indemnification liability regardless of when claims arise.', ARRAY['ProdCo''s indemnification','not survive','termination','more than','two years','after period','no further','indemnification liability','regardless','when','claims arise']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Two-year indemnification survival limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Two-year indemnification survival is grossly inadequate. Content claims can arise decades after creation. Indemnification must survive indefinitely."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s ownership of the Program shall survive termination for cause by Amazon. If Amazon terminates for convenience or ProdCo terminates for Amazon''s breach, all rights shall revert to ProdCo.', ARRAY['Amazon''s ownership','Program','survive','termination for cause','Amazon','Amazon terminates','convenience','ProdCo terminates','Amazon''s breach','all rights','revert','ProdCo']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Conditional ownership survival with reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Conditional ownership survival with reversion for convenience termination or breach is completely unacceptable. Amazon''s ownership must be absolute and unconditional."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Survival provisions shall be mutual. Amazon''s obligations, including payment obligations, shall survive to the same extent and for the same periods as ProdCo''s obligations.', ARRAY['survival provisions','mutual','Amazon''s obligations','including','payment obligations','survive','same extent','same periods','ProdCo''s obligations']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Forced mutual survival", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Forced mutual survival ignores asymmetric nature of obligations. ProdCo''s content-related obligations appropriately have longer survival than Amazon''s payment obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Upon termination, all provisions shall terminate except those expressly designated as surviving in this Section. No provision shall survive by implication, nature, or prior course of dealing.', ARRAY['termination','all provisions','terminate','except','expressly designated','surviving','Section','no provision','survive','implication','nature','prior course of dealing']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "No implied survival", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Eliminating nature-based survival could exclude important provisions not expressly listed. Survival by nature is standard and necessary for comprehensive protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If any limitation of liability or exclusion of damages provision is found unenforceable, the corresponding provision limiting ProdCo''s liability or excluding damages for ProdCo''s benefit shall also be deemed unenforceable.', ARRAY['limitation of liability','exclusion of damages','provision','unenforceable','corresponding provision','limiting','ProdCo''s liability','excluding damages','ProdCo''s benefit','deemed unenforceable']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Linked unenforceability", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Linked unenforceability would void Amazon''s limitations if ProdCo''s fail. Severability should operate independently for each provision."}'::jsonb)
